    gap: 10px;
    color: #666;
    font-size: 13px;
  }
</style>
</head>
<body>

<div class="header">
  <h1>Cookie Import</h1>
  <span class="port">localhost:${serverPort}</span>
</div>

<p class="subtitle">Select the domains of cookies you want to import to GStack Browser. You'll be able to browse those sites with the same login as your other browser.</p>

<div id="banner" class="banner"></div>

<div class="container">
  <!-- Left Panel: Source Browser -->
  <div class="panel panel-left">
    <div class="panel-header">Source Browser</div>
    <div id="browser-pills" class="browser-pills"></div>
    <div id="profile-pills" class="profile-pills" style="display:none"></div>
    <div class="search-wrap">
      <input type="text" class="search-input" id="search" placeholder="Search domains..." />
    </div>
    <div class="domain-list" id="source-domains">
      <div class="loading-row"><span class="spinner"></span> Detecting browsers...</div>
    </div>
    <div class="panel-footer" id="source-footer"><span id="source-footer-text"></span><button class="btn-import-all" id="btn-import-all" style="display:none">Import All</button></div>
  </div>

  <!-- Right Panel: Imported -->
  <div class="panel panel-right">
    <div class="panel-header">Imported to Session</div>
    <div class="domain-list" id="imported-domains">
      <div class="imported-empty">No cookies imported yet</div>
    </div>
    <div class="panel-footer" id="imported-footer"></div>
  </div>
</div>

<script>
(function() {
  const BASE = '${baseUrl}';
  let activeBrowser = null;
  let activeProfile = 'Default';
  let allProfiles = [];
  let allDomains = [];
  let importedSet = {};  // domain → count
  let inflight = {};     // domain → true (prevents double-click)

  const $pills = document.getElementById('browser-pills');
  const $profilePills = document.getElementById('profile-pills');
  const $search = document.getElementById('search');
  const $sourceDomains = document.getElementById('source-domains');
  const $importedDomains = document.getElementById('imported-domains');
  const $sourceFooter = document.getElementById('source-footer-text');
  const $btnImportAll = document.getElementById('btn-import-all');
  const $importedFooter = document.getElementById('imported-footer');
  const $banner = document.getElementById('banner');

  // ─── Banner ────────────────────────────
  function showBanner(msg, type, retryFn) {
    $banner.className = 'banner ' + type;
    $banner.style.display = 'flex';
    let html = '<span class="banner-text">' + escHtml(msg) + '</span>';
    if (retryFn) {
      html += '<button class="banner-retry" id="banner-retry">Retry</button>';
    }
    html += '<button class="banner-close" id="banner-close">×</button>';
    $banner.innerHTML = html;
    document.getElementById('banner-close').onclick = () => { $banner.style.display = 'none'; };
    if (retryFn) {
      document.getElementById('banner-retry').onclick = () => {
        $banner.style.display = 'none';
        retryFn();
      };
    }
  }

  function escHtml(s) {
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  // ─── API ────────────────────────────────
  async function api(path, opts) {
    const res = await fetch(BASE + '/cookie-picker' + path, { ...opts, credentials: 'same-origin' });
    const data = await res.json();
    if (!res.ok) {
      const err = new Error(data.error || 'Request failed');
      err.code = data.code;
      err.action = data.action;
      throw err;
    }
    return data;
  }

  // ─── Init ───────────────────────────────
  async function init() {
    try {
      const [browserData, importedData] = await Promise.all([
        api('/browsers'),
        api('/imported'),
      ]);

      // Populate imported state
      for (const entry of importedData.domains) {
        importedSet[entry.domain] = entry.count;
      }
      renderImported();

      // Render browser pills
      const browsers = browserData.browsers;
      if (browsers.length === 0) {
        $sourceDomains.innerHTML = '<div class="imported-empty">No Chromium browsers detected</div>';
        return;
      }

      $pills.innerHTML = '';
      browsers.forEach(b => {
        const pill = document.createElement('button');
        pill.className = 'pill';
        pill.innerHTML = '<span class="dot"></span>' + escHtml(b.name);
        pill.onclick = () => selectBrowser(b.name);
        $pills.appendChild(pill);
      });

      // Auto-select first browser
      selectBrowser(browsers[0].name);
    } catch (err) {
      showBanner(err.message, 'error', init);
      $sourceDomains.innerHTML = '<div class="imported-empty">Failed to load</div>';
    }
  }

  // ─── Select Browser ────────────────────
  async function selectBrowser(name) {
    activeBrowser = name;
    activeProfile = 'Default';

    // Update pills
    $pills.querySelectorAll('.pill').forEach(p => {
      p.classList.toggle('active', p.textContent === name);
    });

    $sourceDomains.innerHTML = '<div class="loading-row"><span class="spinner"></span> Loading...</div>';
    $sourceFooter.textContent = '';
    $search.value = '';

    try {
      // Fetch profiles for this browser
      const profileData = await api('/profiles?browser=' + encodeURIComponent(name));
      allProfiles = profileData.profiles || [];

      if (allProfiles.length > 1) {
        // Show profile pills when multiple profiles exist
        $profilePills.style.display = 'flex';
        renderProfilePills();
        // Auto-select profile with the most recent/largest cookie DB, or Default
        activeProfile = allProfiles[0].name;
      } else {
        $profilePills.style.display = 'none';
        activeProfile = allProfiles.length === 1 ? allProfiles[0].name : 'Default';
      }

      await loadDomains();
    } catch (err) {
      showBanner(err.message, 'error', err.action === 'retry' ? () => selectBrowser(name) : null);
      $sourceDomains.innerHTML = '<div class="imported-empty">Failed to load</div>';
      $profilePills.style.display = 'none';
    }
  }

  // ─── Render Profile Pills ─────────────
  function renderProfilePills() {
    let html = '';
    for (const p of allProfiles) {
      const isActive = p.name === activeProfile;
      const label = p.displayName || p.name;
      html += '<button class="profile-pill' + (isActive ? ' active' : '') + '" data-profile="' + escHtml(p.name) + '">' + escHtml(label) + '</button>';
    }
    $profilePills.innerHTML = html;

    $profilePills.querySelectorAll('.profile-pill').forEach(btn => {
      btn.addEventListener('click', () => selectProfile(btn.dataset.profile));
    });
  }

  // ─── Select Profile ───────────────────
  async function selectProfile(profileName) {
    activeProfile = profileName;
    renderProfilePills();

    $sourceDomains.innerHTML = '<div class="loading-row"><span class="spinner"></span> Loading domains...</div>';
    $sourceFooter.textContent = '';
    $search.value = '';

    await loadDomains();
  }

  // ─── Load Domains ─────────────────────
  async function loadDomains() {
    try {
      const data = await api('/domains?browser=' + encodeURIComponent(activeBrowser) + '&profile=' + encodeURIComponent(activeProfile));
      allDomains = data.domains;
      renderSourceDomains();
    } catch (err) {
      showBanner(err.message, 'error', err.action === 'retry' ? () => loadDomains() : null);
      $sourceDomains.innerHTML = '<div class="imported-empty">Failed to load domains</div>';
    }
  }

  // ─── Render Source Domains ─────────────
  function renderSourceDomains() {
    const query = $search.value.toLowerCase();
    const filtered = query
      ? allDomains.filter(d => d.domain.toLowerCase().includes(query))
      : allDomains;

    if (filtered.length === 0) {
      $sourceDomains.innerHTML = '<div class="imported-empty">' +
        (query ? 'No matching domains' : 'No cookie domains found') + '</div>';
      $sourceFooter.textContent = '';
      return;
    }

    let html = '';
    for (const d of filtered) {
      const isImported = d.domain in importedSet;
      const isInflight = inflight[d.domain];
      html += '<div class="domain-row">';
      html += '<span class="domain-name">' + escHtml(d.domain) + '</span>';
      html += '<span class="domain-count">' + d.count + '</span>';
      if (isInflight) {
        html += '<span class="btn-add" disabled><span class="spinner" style="width:12px;height:12px;border-width:1.5px;"></span></span>';
      } else if (isImported) {
        html += '<span class="btn-add imported">&#10003;</span>';
      } else {
        html += '<button class="btn-add" data-domain="' + escHtml(d.domain) + '" title="Import">+</button>';
      }
      html += '</div>';
    }
    $sourceDomains.innerHTML = html;

    // Total counts
    const totalDomains = allDomains.length;
    const totalCookies = allDomains.reduce((s, d) => s + d.count, 0);
    $sourceFooter.textContent = totalDomains + ' domains · ' + totalCookies.toLocaleString() + ' cookies';

    // Show/hide Import All button
    const unimported = filtered.filter(d => !(d.domain in importedSet) && !inflight[d.domain]);
    if (unimported.length > 0) {
      $btnImportAll.style.display = '';
      $btnImportAll.disabled = false;
      $btnImportAll.textContent = 'Import All (' + unimported.length + ')';
    } else {
      $btnImportAll.style.display = 'none';
    }

    // Click handlers
    $sourceDomains.querySelectorAll('.btn-add[data-domain]').forEach(btn => {
      btn.addEventListener('click', () => importDomain(btn.dataset.domain));
    });
  }

  // ─── Import Domain ─────────────────────
  async function importDomain(domain) {
    if (inflight[domain] || domain in importedSet) return;
    inflight[domain] = true;
    renderSourceDomains();

    try {
      const data = await api('/import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ browser: activeBrowser, domains: [domain], profile: activeProfile }),
      });

      if (data.domainCounts) {
        for (const [d, count] of Object.entries(data.domainCounts)) {
          importedSet[d] = (importedSet[d] || 0) + count;
        }
      }
      renderImported();
    } catch (err) {
      showBanner('Import failed for ' + domain + ': ' + err.message, 'error',
        err.action === 'retry' ? () => importDomain(domain) : null);
    } finally {
      delete inflight[domain];
      renderSourceDomains();
    }
  }

  // ─── Import All ───────────────────────
  async function importAll() {
    const query = $search.value.toLowerCase();
    const filtered = query
      ? allDomains.filter(d => d.domain.toLowerCase().includes(query))
      : allDomains;
    const toImport = filtered.filter(d => !(d.domain in importedSet) && !inflight[d.domain]);
    if (toImport.length === 0) return;

    $btnImportAll.disabled = true;
    $btnImportAll.textContent = 'Importing...';

    const domains = toImport.map(d => d.domain);
    try {
      const data = await api('/import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ browser: activeBrowser, domains: domains, profile: activeProfile }),
      });

      if (data.domainCounts) {
        for (const [d, count] of Object.entries(data.domainCounts)) {
          importedSet[d] = (importedSet[d] || 0) + count;
        }
      }
      renderImported();
    } catch (err) {
      showBanner('Import all failed: ' + err.message, 'error',
        err.action === 'retry' ? () => importAll() : null);
    } finally {
      renderSourceDomains();
    }
  }

  $btnImportAll.addEventListener('click', importAll);

  // ─── Render Imported ───────────────────
  function renderImported() {
    const entries = Object.entries(importedSet).sort((a, b) => b[1] - a[1]);

    if (entries.length === 0) {
      $importedDomains.innerHTML = '<div class="imported-empty">No cookies imported yet</div>';
      $importedFooter.textContent = '';
      return;
    }

    let html = '';
    for (const [domain, count] of entries) {
      const isInflight = inflight['remove:' + domain];
      html += '<div class="domain-row">';
      html += '<span class="domain-name">' + escHtml(domain) + '</span>';
      html += '<span class="domain-count">' + count + '</span>';
      if (isInflight) {
        html += '<span class="btn-trash" disabled><span class="spinner" style="width:12px;height:12px;border-width:1.5px;border-top-color:#f87171;"></span></span>';
      } else {
        html += '<button class="btn-trash" data-domain="' + escHtml(domain) + '" title="Remove">&#128465;</button>';
      }
      html += '</div>';
    }
    $importedDomains.innerHTML = html;

    const totalCookies = entries.reduce((s, e) => s + e[1], 0);
    $importedFooter.textContent = entries.length + ' domains · ' + totalCookies.toLocaleString() + ' cookies imported';

    // Click handlers
    $importedDomains.querySelectorAll('.btn-trash[data-domain]').forEach(btn => {
      btn.addEventListener('click', () => removeDomain(btn.dataset.domain));
    });
  }

  // ─── Remove Domain ─────────────────────
  async function removeDomain(domain) {
    if (inflight['remove:' + domain]) return;
    inflight['remove:' + domain] = true;
    renderImported();

    try {
      await api('/remove', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ domains: [domain] }),
      });
      delete importedSet[domain];
      renderImported();
      renderSourceDomains(); // update checkmarks
    } catch (err) {
      showBanner('Remove failed for ' + domain + ': ' + err.message, 'error',
        err.action === 'retry' ? () => removeDomain(domain) : null);
    } finally {
      delete inflight['remove:' + domain];
      renderImported();
    }
  }

  // ─── Search ────────────────────────────
  $search.addEventListener('input', renderSourceDomains);

  // ─── Start ─────────────────────────────
  init();
})();
</script>
</body>
</html>`;
}

/**
 * $B domain-skill subcommands — CLI surface for the domain-skills storage layer.
 *
 * Subcommands:
 *   save                          — save a skill body (host derived from active tab, T3)
 *   list                          — list all skills (project + global) visible here
 *   show <host>                   — print the body of a skill
 *   edit <host>                   — round-trip through $EDITOR
 *   promote-to-global <host>      — promote active per-project skill to global
 *   rollback <host>               — restore prior version
 *   rm <host> [--global]          — tombstone a skill
 *
 * Design constraints:
 *   - host is ALWAYS derived from the active tab's top-level origin (T3
 *     confused-deputy fix). Never accepted as an arg.
 *   - Save-time security uses content-security.ts L1-L3 filters (importable
 *     from the compiled binary, unlike the L4 ML classifier). There is NO
 *     load-time L4 scan today — it died with the chat path; the
 *     classifier_score>0 promotion gate in domain-skills.ts compensates.
 *   - Output is structured: every success/error includes problem + cause +
 *     suggested-action. Matches the gstack house style.
 *
 * The body for `save` is supplied via stdin or --from-file, NOT inline argv,
 * so multi-line markdown bodies don't get mangled by shell quoting.
 */

import { promises as fs } from 'fs';
import * as path from 'path';
import * as os from 'os';
import { spawnSync } from 'child_process';
import type { BrowserManager } from './browser-manager';
import {
  deriveHostFromActiveTab,
  writeSkill,
  readSkill,
  listSkills,
  promoteToGlobal,
  rollbackSkill,
  deleteSkill,
  type DomainSkillRow,
  type SkillScope,
} from './domain-skills';
import { runContentFilters } from './content-security';
import { getCurrentProjectSlug } from './project-slug';
import { logTelemetry } from './telemetry';

// ─── Body input resolution ──────────────────────────────────────

/**
 * Read skill body from --from-file <path> or from stdin.
 * Body is NEVER taken from inline argv (shell quoting hazard for multi-line markdown).
 */
async function readBodyFromArgs(args: string[]): Promise<string> {
  const fromFileIdx = args.indexOf('--from-file');
  if (fromFileIdx >= 0 && fromFileIdx + 1 < args.length) {
    const filePath = args[fromFileIdx + 1]!;
    const body = await fs.readFile(filePath, 'utf8');
    return body;
  }
  // Read from stdin (the CLI may pipe content in)
  return new Promise((resolve) => {
    let data = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => (data += chunk));
    process.stdin.on('end', () => resolve(data));
    // If no stdin attached, end immediately with empty string
    if (process.stdin.isTTY) resolve('');
  });
}

// ─── Output formatting ──────────────────────────────────────────

function formatSavedOk(row: DomainSkillRow, slug: string): string {
  return [
    `Saved (state: ${row.state}, scope: ${row.scope}).`,
    `Host: ${row.host}`,
    `Bytes: ${row.body.length}`,
    `Version: ${row.version}`,
    `Stored at: ~/.gstack/projects/${slug}/learnings.jsonl`,
    '',
    `Next: skill is quarantined and won't fire in prompts until used 3 times`,
    `      without classifier flags. Run $B domain-skill list to see state.`,
  ].join('\n');
}

function formatSkillListing(list: { project: DomainSkillRow[]; global: DomainSkillRow[] }): string {
  if (list.project.length === 0 && list.global.length === 0) {
    return 'No domain-skills yet.\n\nNext: navigate to a site, then $B domain-skill save with a markdown body to begin.';
  }
  const lines: string[] = [];
  if (list.project.length > 0) {
    lines.push('Project (per-project):');
    for (const r of list.project) {
      lines.push(`  [${r.state}] ${r.host} — v${r.version}, ${r.body.length} bytes, used ${r.use_count}× (${r.flag_count} flags)`);
    }
  }
  if (list.global.length > 0) {
    if (lines.length > 0) lines.push('');
    lines.push('Global (cross-project):');
    for (const r of list.global) {
      lines.push(`  ${r.host} — v${r.version}, ${r.body.length} bytes`);
    }
  }
  return lines.join('\n');
}

// ─── Subcommand handlers ────────────────────────────────────────

async function handleSave(args: string[], bm: BrowserManager): Promise<string> {
  const page = bm.getPage();
  const host = await deriveHostFromActiveTab(page);
  const body = await readBodyFromArgs(args);
  if (!body || !body.trim()) {
    throw new Error(
      'Save failed: empty body.\n' +
        'Cause: no content provided via --from-file or stdin.\n' +
        'Action: pipe markdown into $B domain-skill save, or pass --from-file <path>.'
    );
  }
  // L1-L3 content filters (datamarking, hidden-element strip, ARIA regex,
  // URL blocklist). No L4 ML scan here — the classifier can't import in the
  // compiled binary, and the load-time scan path no longer exists.
  const filterResult = runContentFilters(body, page.url(), 'domain-skill-save');
  if (filterResult.blocked) {
    logTelemetry({ event: 'domain_skill_save_blocked', host, reason: filterResult.message });
    throw new Error(
      `Save blocked: ${filterResult.message}\n` +
        'Cause: skill body trips L1-L3 content filters (likely contains URL blocklist match or ARIA injection patterns).\n' +
        'Action: review the body for suspicious instruction-like content; rewrite and retry.'
    );
  }
  // L1-L3 score is binary (passed or not). The L4 score field stays 0
  // ("never ML-scanned") — nothing fills it in today, which is exactly why
  // the promotion gate in domain-skills.ts requires classifier_score > 0.
  const slug = getCurrentProjectSlug();
  const row = await writeSkill({
    host,
    body,
    projectSlug: slug,
    source: 'agent',
    classifierScore: 0, // L4 deferred to load-time
  });
  logTelemetry({ event: 'domain_skill_saved', host, scope: row.scope, state: row.state, bytes: body.length });
  return formatSavedOk(row, slug);
}

async function handleList(_args: string[]): Promise<string> {
  const slug = getCurrentProjectSlug();
  const list = await listSkills(slug);
  return formatSkillListing(list);
}

async function handleShow(args: string[]): Promise<string> {
  const host = args[0];
  if (!host) {
    throw new Error(
      'Usage: $B domain-skill show <host>\n' +
        'Cause: missing hostname argument.\n' +
        'Action: $B domain-skill list to see available hosts.'
    );
  }
  const slug = getCurrentProjectSlug();
  const result = await readSkill(host, slug);
  if (!result) {
    return `No active skill for ${host}.\n\nA quarantined skill may exist; run $B domain-skill list to see all states.`;
  }
  return [
    `# ${result.row.host} (${result.source} scope, ${result.row.state})`,
    `# version: ${result.row.version}, used: ${result.row.use_count}×, flags: ${result.row.flag_count}`,
    '',
    result.row.body,
  ].join('\n');
}

async function handleEdit(args: string[]): Promise<string> {
  const host = args[0];
  if (!host) {
    throw new Error('Usage: $B domain-skill edit <host>');
  }
  const slug = getCurrentProjectSlug();
  // Read current body to seed the editor
  const list = await listSkills(slug);
  const current = [...list.project, ...list.global].find((r) => r.host === host);
  if (!current) {
    throw new Error(
      `Cannot edit: no skill for ${host}.\n` +
        'Cause: skill does not exist in this project or global scope.\n' +
        'Action: $B domain-skill save to create one first.'
    );
  }
  const editor = process.env.EDITOR || 'vi';
  const tmpFile = path.join(os.tmpdir(), `gstack-domain-skill-${process.pid}-${Date.now()}.md`);
  await fs.writeFile(tmpFile, current.body, 'utf8');
  const result = spawnSync(editor, [tmpFile], { stdio: 'inherit' });
  if (result.status !== 0) {
    await fs.unlink(tmpFile).catch(() => {});
    throw new Error(`Editor exited with status ${result.status}; no changes saved.`);
  }
  const newBody = await fs.readFile(tmpFile, 'utf8');
  await fs.unlink(tmpFile).catch(() => {});
  if (newBody === current.body) {
    return `No changes for ${host}.`;
  }
  // Re-save (always per-project; promotion is explicit)
  const page = (global as any).__bm?.getPage?.();
  void page; // we're in the daemon — page available, but for edit we trust the existing host
  const row = await writeSkill({
    host: current.host,
    body: newBody,
    projectSlug: slug,
    source: 'human',
    classifierScore: 0,
  });
  return formatSavedOk(row, slug);
}

async function handlePromoteToGlobal(args: string[]): Promise<string> {
  const host = args[0];
  if (!host) {
    throw new Error('Usage: $B domain-skill promote-to-global <host>');
  }
  const slug = getCurrentProjectSlug();
  const row = await promoteToGlobal(host, slug);
  return [
    `Promoted ${row.host} to global scope (v${row.version}).`,
    `Stored at: ~/.gstack/global-domain-skills.jsonl`,
    '',
    `This skill now fires for all projects unless they have a per-project skill for the same host.`,
  ].join('\n');
}

async function handleRollback(args: string[]): Promise<string> {
  const host = args[0];
  if (!host) {
    throw new Error('Usage: $B domain-skill rollback <host>');
  }
  const scope: SkillScope = args.includes('--global') ? 'global' : 'project';
  const slug = getCurrentProjectSlug();
  const row = await rollbackSkill(host, slug, scope);
  return [
    `Rolled back ${row.host} (${scope} scope) to prior version.`,
    `New version: ${row.version} (content from earlier revision)`,
  ].join('\n');
}

async function handleRm(args: string[]): Promise<string> {
  const host = args[0];
  if (!host) {
    throw new Error('Usage: $B domain-skill rm <host> [--global]');
  }
  const scope: SkillScope = args.includes('--global') ? 'global' : 'project';
  const slug = getCurrentProjectSlug();
  await deleteSkill(host, slug, scope);
  return `Tombstoned ${host} (${scope} scope). Use $B domain-skill rollback to restore.`;
}

// ─── Top-level dispatcher ──────────────────────────────────────

export async function handleDomainSkillCommand(args: string[], bm: BrowserManager): Promise<string> {
  const sub = args[0];
  const rest = args.slice(1);
  switch (sub) {
    case 'save':
      return handleSave(rest, bm);
    case 'list':
      return handleList(rest);
    case 'show':
      return handleShow(rest);
    case 'edit':
      return handleEdit(rest);
    case 'promote-to-global':
      return handlePromoteToGlobal(rest);
    case 'rollback':
      return handleRollback(rest);
    case 'rm':
    case 'remove':
    case 'delete':
      return handleRm(rest);
    case undefined:
    case '':
    case 'help':
      return [
        '$B domain-skill — agent-authored per-site notes',
        '',
        'Subcommands:',
        '  save              save body from stdin or --from-file (host derived from active tab)',
        '  list              list all skills visible to current project',
        '  show <host>       print skill body',
        '  edit <host>       open in $EDITOR',
        '  promote-to-global <host>  promote active skill to global scope',
        '  rollback <host> [--global]  restore prior version',
        '  rm <host> [--global]  tombstone',
      ].join('\n');
    default:
      throw new Error(
        `Unknown subcommand: ${sub}\n` +
          'Cause: not one of save|list|show|edit|promote-to-global|rollback|rm.\n' +
          'Action: $B domain-skill help for the full list.'
      );
  }
}

/**
 * Domain skills — per-site notes the agent writes for itself, persisted
 * alongside /learn's per-project learnings as type:"domain" rows.
 *
 * Scope:
 *   - per-project: ~/.gstack/projects/<slug>/learnings.jsonl
 *   - global:      ~/.gstack/global-domain-skills.jsonl
 *
 * State machine (T6 — defense against persistent prompt poisoning):
 *
 *   ┌──────────────┐  N=3 successful uses     ┌────────┐  promote-to-global  ┌────────┐
 *   │ quarantined  │ ─────────────────────▶  │ active │ ──────────────────▶ │ global │
 *   │ (per-project)│  (no classifier flags)   │(project)│  (manual command)   │        │
 *   └──────────────┘                          └────────┘                     └────────┘
 *          ▲                                       │
 *          │  classifier flag during use           │  rollback (version log)
 *          └───────────────────────────────────────┘
 *
 *  - new save → quarantined (does NOT auto-fire in prompts)
 *  - active skills fire in prompts for their project (wrapped in UNTRUSTED)
 *  - global skills fire across all projects (cross-context, requires explicit promote)
 *  - rollback restores prior version by sha256
 *
 * Storage discipline (T5):
 *   - Append-only with O_APPEND (POSIX guarantees atomic appends < PIPE_BUF)
 *   - Tombstone for deletes; idle compactor rewrites file
 *   - Tolerant parser drops partial trailing line on read
 *
 * Hostname rules (T3, CEO-temporal):
 *   - Derived from active tab's top-level origin — NEVER agent-supplied
 *   - Lowercase, strip www., keep full subdomain (subdomain-exact match)
 *   - Punycode hostnames stored as-encoded
 */

import { promises as fs } from 'fs';
import { open as fsOpen, constants as fsConstants } from 'fs';
import * as path from 'path';
import * as os from 'os';
import { createHash } from 'crypto';
import type { Page } from 'playwright';

export type SkillState = 'quarantined' | 'active' | 'global';
export type SkillScope = 'project' | 'global';
export type SkillSource = 'agent' | 'human';

export interface DomainSkillRow {
  type: 'domain';
  host: string;
  scope: SkillScope;
  state: SkillState;
  body: string;
  version: number;
  classifier_score: number;
  source: SkillSource;
  sha256: string;
  use_count: number;
  flag_count: number;
  created_ts: string;
  updated_ts: string;
  tombstone?: boolean;
}

const PROMOTE_THRESHOLD = 3;

function gstackHome(): string {
  return process.env.GSTACK_HOME || path.join(os.homedir(), '.gstack');
}

function globalFile(): string {
  return path.join(gstackHome(), 'global-domain-skills.jsonl');
}

function projectFile(slug: string): string {
  return path.join(gstackHome(), 'projects', slug, 'learnings.jsonl');
}

// ─── Hostname normalization (T3) ──────────────────────────────

export function normalizeHost(input: string): string {
  let h = input.trim().toLowerCase();
  // strip protocol if present
  h = h.replace(/^https?:\/\//, '');
  // strip path/query
  h = h.split('/')[0]!.split('?')[0]!.split('#')[0]!;
  // strip port
  h = h.split(':')[0]!;
  // strip www. prefix
  h = h.replace(/^www\./, '');
  return h;
}

/**
 * Derive hostname from the active tab's top-level origin.
 * Closes the confused-deputy bug (Codex T3): agent cannot supply a wrong
 * hostname even if it tried — host is read from the page state we control.
 */
export async function deriveHostFromActiveTab(page: Page): Promise<string> {
  const url = page.url();
  if (!url || url === 'about:blank' || url.startsWith('chrome://')) {
    throw new Error(
      'Cannot save domain-skill: no top-level URL on active tab.\n' +
        'Cause: tab is empty or on chrome:// page.\n' +
        'Action: navigate to the target site first with $B goto <url>.'
    );
  }
  return normalizeHost(url);
}

// ─── File I/O (T5: append-only + flock-free atomic appends) ────

async function ensureDir(filePath: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
}

/**
 * Append a JSONL row atomically. POSIX guarantees atomicity for writes <
 * PIPE_BUF (typically 4KB) when O_APPEND is set. Each row is single-line JSON
 * well under that bound. fsync ensures durability before return.
 */
async function appendRow(filePath: string, row: DomainSkillRow): Promise<void> {
  await ensureDir(filePath);
  const line = JSON.stringify(row) + '\n';
  return new Promise((resolve, reject) => {
    fsOpen(filePath, fsConstants.O_WRONLY | fsConstants.O_CREAT | fsConstants.O_APPEND, 0o644, (err, fd) => {
      if (err) return reject(err);
      const buf = Buffer.from(line, 'utf8');
      const writeAndSync = () => {
        // Use fs.writeSync via fd to ensure single write call (atomic with O_APPEND).
        const fsSync = require('fs');
        try {
          fsSync.writeSync(fd, buf, 0, buf.length);
          fsSync.fsyncSync(fd);
          fsSync.closeSync(fd);
          resolve();
        } catch (e) {
          try {
            fsSync.closeSync(fd);
          } catch {
            // Ignore close errors after a write failure — original error wins.
          }
          reject(e);
        }
      };
      writeAndSync();
    });
  });
}

/**
 * Read all rows from a JSONL file. Tolerant of partial trailing line (drops it).
 * Returns rows in append order. Caller resolves latest-wins per (host, scope).
 */
async function readRows(filePath: string): Promise<DomainSkillRow[]> {
  let raw: string;
  try {
    raw = await fs.readFile(filePath, 'utf8');
  } catch (e) {
    const err = e as NodeJS.ErrnoException;
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  const rows: DomainSkillRow[] = [];
  const lines = raw.split('\n');
  // Last line is empty (trailing newline) OR partial. Drop unconditionally if no parse.
  for (const line of lines) {
    if (!line) continue;
    try {
      const parsed = JSON.parse(line);
      if (parsed && parsed.type === 'domain') rows.push(parsed as DomainSkillRow);
    } catch {
      // Partial-line corruption tolerated. Compactor will clean up.
    }
  }
  return rows;
}

// ─── Latest-wins resolution ────────────────────────────────────

interface SkillKey {
  host: string;
  scope: SkillScope;
}

function keyOf(row: DomainSkillRow): string {
  return `${row.scope}::${row.host}`;
}

/**
 * Reduce a row stream to latest-version-wins per (host, scope).
 * Tombstones win (deleted skill stays deleted).
 */
function resolveLatest(rows: DomainSkillRow[]): Map<string, DomainSkillRow> {
  const m = new Map<string, DomainSkillRow>();
  for (const row of rows) {
    const k = keyOf(row);
    const prior = m.get(k);
    if (!prior || row.version >= prior.version) {
      m.set(k, row);
    }
  }
  // Drop tombstoned entries from the result map for readers; rollback uses raw history.
  for (const [k, row] of m) {
    if (row.tombstone) m.delete(k);
  }
  return m;
}

// ─── Public API ────────────────────────────────────────────────

export interface ReadSkillResult {
  row: DomainSkillRow;
  source: 'project' | 'global';
}

/**
 * Read the active or global skill for a host visible to a given project.
 * Project-scoped active skills shadow global skills for the same host.
 * Quarantined skills are NEVER returned (they don't fire).
 */
export async function readSkill(host: string, projectSlug: string): Promise<ReadSkillResult | null> {
  const normalized = normalizeHost(host);
  // Project layer first
  const projectRows = await readRows(projectFile(projectSlug));
  const projectLatest = resolveLatest(projectRows);
  const projectHit = projectLatest.get(`project::${normalized}`);
  if (projectHit && projectHit.state === 'active') {
    return { row: projectHit, source: 'project' };
  }
  // Global layer fallback
  const globalRows = await readRows(globalFile());
  const globalLatest = resolveLatest(globalRows);
  const globalHit = globalLatest.get(`global::${normalized}`);
  if (globalHit && globalHit.state === 'global') {
    return { row: globalHit, source: 'global' };
  }
  return null;
}

export interface WriteSkillInput {
  host: string;
  body: string; // markdown frontmatter + content
  projectSlug: string;
  source: SkillSource;
  classifierScore: number; // 0..1; caller invokes classifier before calling this
}

/**
 * Save a new skill (always quarantined initially per T6).
 * Caller MUST run the classifier first and pass classifierScore.
 * Score >= 0.85 should fail-fast at caller, never reach here.
 */
export async function writeSkill(input: WriteSkillInput): Promise<DomainSkillRow> {
  if (input.classifierScore >= 0.85) {
    throw new Error(
      `Save blocked: classifier flagged content as potential injection (score: ${input.classifierScore.toFixed(2)}).\n` +
        'Cause: skill body contains patterns the L4 classifier marks as risky.\n' +
        'Action: rewrite the skill content removing instruction-like prose, retry.'
    );
  }
  const normalized = normalizeHost(input.host);
  const body = input.body;
  const now = new Date().toISOString();
  const sha = createHash('sha256').update(body, 'utf8').digest('hex');
  // Determine prior version for this (host, scope=project) so version counter increments.
  const projectRows = await readRows(projectFile(input.projectSlug));
  const projectLatest = resolveLatest(projectRows);
  const prior = projectLatest.get(`project::${normalized}`);
  const version = prior ? prior.version + 1 : 1;
  const row: DomainSkillRow = {
    type: 'domain',
    host: normalized,
    scope: 'project',
    state: 'quarantined',
    body,
    version,
    classifier_score: input.classifierScore,
    source: input.source,
    sha256: sha,
    use_count: 0,
    flag_count: 0,
    created_ts: prior?.created_ts ?? now,
    updated_ts: now,
  };
  await appendRow(projectFile(input.projectSlug), row);
  return row;
}

/**
 * Promote a quarantined skill to active in its project after N=3 uses without
 * classifier flagging. No production caller today — the chat-path agent that
 * invoked it on successful skill use was ripped with the chat queue.
 *
 * Auto-promote logic:
 *   - increment use_count
 *   - if use_count >= PROMOTE_THRESHOLD AND flag_count == 0 AND L4 has scored
 *     the body (classifier_score > 0) → state:active
 *   - else stay quarantined with updated counter; user must run
 *     `domain-skill promote-to-global` manually
 *
 * The classifier_score > 0 gate is load-bearing: handleSave writes
 * classifier_score=0 (meaning "never ML-scanned"), and NOTHING updates the
 * score today — the load-time L4 scan died with the chat path, so skills
 * authored via the production path never had their body scanned by L4.
 * Without this gate, three benign uses promote any quarantined skill — including
 * one written under the influence of a poisoned page — into the prompt context
 * for every subsequent visit. The gate re-opens automatically the day L4 is
 * rewired and writeSkill / recordSkillUse start receiving non-zero scores.
 */
export async function recordSkillUse(host: string, projectSlug: string, classifierFlagged: boolean): Promise<DomainSkillRow | null> {
  const normalized = normalizeHost(host);
  const rows = await readRows(projectFile(projectSlug));
  const latest = resolveLatest(rows);
  const current = latest.get(`project::${normalized}`);
  if (!current) return null;
  const useCount = current.use_count + 1;
  const flagCount = current.flag_count + (classifierFlagged ? 1 : 0);
  let state: SkillState = current.state;
  if (
    state === 'quarantined' &&
    useCount >= PROMOTE_THRESHOLD &&
    flagCount === 0 &&
    current.classifier_score > 0
  ) {
    state = 'active';
  }
  const updated: DomainSkillRow = {
    ...current,
    state,
    use_count: useCount,
    flag_count: flagCount,
    version: current.version + 1,
    updated_ts: new Date().toISOString(),
  };
  await appendRow(projectFile(projectSlug), updated);
  return updated;
}

/**
 * Promote an active per-project skill to global. Explicit operator call only —
 * never auto-promoted across project boundaries (T4).
 */
export async function promoteToGlobal(host: string, projectSlug: string): Promise<DomainSkillRow> {
  const normalized = normalizeHost(host);
  const rows = await readRows(projectFile(projectSlug));
  const latest = resolveLatest(rows);
  const current = latest.get(`project::${normalized}`);
  if (!current) {
    throw new Error(
      `Cannot promote: no skill for ${normalized} in project ${projectSlug}.\n` +
        'Cause: skill does not exist or is tombstoned.\n' +
        'Action: $B domain-skill list to see what exists in this project.'
    );
  }
  if (current.state !== 'active') {
    throw new Error(
      `Cannot promote: skill for ${normalized} is in state "${current.state}", expected "active".\n` +
        `Cause: skill must be active in this project (used ${PROMOTE_THRESHOLD}+ times without flag) before global promotion.\n` +
        'Action: use the skill in this project until it auto-promotes to active.'
    );
  }
  const now = new Date().toISOString();
  const globalRow: DomainSkillRow = {
    ...current,
    scope: 'global',
    state: 'global',
    version: 1, // global file has its own version line
    use_count: 0,
    flag_count: 0,
    updated_ts: now,
  };
  await appendRow(globalFile(), globalRow);
  return globalRow;
}

/**
 * Rollback to a prior version (by sha256 OR previous version number).
 * Re-emits the prior row as the latest, preserving the version counter monotonicity.
 */
export async function rollbackSkill(host: string, projectSlug: string, scope: SkillScope = 'project'): Promise<DomainSkillRow> {
  const normalized = normalizeHost(host);
  const file = scope === 'project' ? projectFile(projectSlug) : globalFile();
  const rows = await readRows(file);
  const matching = rows.filter((r) => r.host === normalized && r.scope === scope && !r.tombstone);
  if (matching.length < 2) {
    throw new Error(
      `Cannot rollback: ${normalized} has fewer than 2 versions in ${scope} scope.\n` +
        'Cause: no prior version to roll back to.\n' +
        'Action: $B domain-skill rm to delete instead, or wait for a future revision to roll back from.'
    );
  }
  // Sort by version desc; take second-latest as the rollback target.
  matching.sort((a, b) => b.version - a.version);
  const target = matching[1]!;
  const newVersion = matching[0]!.version + 1;
  const restored: DomainSkillRow = {
    ...target,
    version: newVersion,
    updated_ts: new Date().toISOString(),
  };
  await appendRow(file, restored);
  return restored;
}

/**
 * List all non-tombstoned skills visible to a project (active project + active global).
 */
export async function listSkills(projectSlug: string): Promise<{ project: DomainSkillRow[]; global: DomainSkillRow[] }> {
  const projectRows = await readRows(projectFile(projectSlug));
  const globalRows = await readRows(globalFile());
  const projectLatest = Array.from(resolveLatest(projectRows).values());
  const globalLatest = Array.from(resolveLatest(globalRows).values()).filter((r) => r.state === 'global');
  return { project: projectLatest, global: globalLatest };
}

/**
 * Tombstone a skill. Append a tombstone row; compactor cleans up later.
 */
export async function deleteSkill(host: string, projectSlug: string, scope: SkillScope = 'project'): Promise<void> {
  const normalized = normalizeHost(host);
  const file = scope === 'project' ? projectFile(projectSlug) : globalFile();
  const rows = await readRows(file);
  const latest = resolveLatest(rows);
  const current = latest.get(`${scope}::${normalized}`);
  if (!current) {
    throw new Error(
      `Cannot delete: no skill for ${normalized} in ${scope} scope.\n` +
        'Cause: skill does not exist or is already tombstoned.\n' +
        'Action: $B domain-skill list to see what exists.'
    );
  }
  const tombstone: DomainSkillRow = {
    ...current,
    version: current.version + 1,
    updated_ts: new Date().toISOString(),
    tombstone: true,
  };
  await appendRow(file, tombstone);
}

/**
 * Shared error-handling utilities for browse server and CLI.
 *
 * Each wrapper uses selective catches (checks err.code) to avoid masking
 * unexpected errors. Empty catches would be flagged by slop-scan.
 */

import * as fs from 'fs';

// ─── Filesystem ────────────────────────────────────────────────

/** Remove a file, ignoring ENOENT (already gone). Rethrows other errors. */
export function safeUnlink(filePath: string): void {
  try {
    fs.unlinkSync(filePath);
  } catch (err: any) {
    if (err?.code !== 'ENOENT') throw err;
  }
}

/** Remove a file, ignoring ALL errors. Use only in best-effort cleanup (shutdown, emergency). */
export function safeUnlinkQuiet(filePath: string): void {
  try { fs.unlinkSync(filePath); } catch {}
}

// ─── Process ───────────────────────────────────────────────────

/** Send a signal to a process, ignoring ESRCH (already dead). Rethrows other errors. */
export function safeKill(pid: number, signal: NodeJS.Signals | number): void {
  try {
    process.kill(pid, signal);
  } catch (err: any) {
    if (err?.code !== 'ESRCH') throw err;
  }
}

/**
 * Check if a PID is alive. Pure boolean probe — never throws.
 *
 * Signal 0 on EVERY platform (#1952). Node maps `process.kill(pid, 0)` to an
 * OpenProcess existence check on Windows — and on Windows the browse daemon
 * runs under Node (dist/server-node.mjs + bun-polyfill, the documented
 * fallback for oven-sh/bun#4253) — so the POSIX idiom is portable here.
 *
 * Windows used to shell out to `tasklist /FI "PID eq <pid>"` and
 * string-match the CSV. That was wrong in two ways, both hit in production:
 *
 *   1. FALSE NEGATIVES UNDER LOAD (#2414/#2295): tasklist takes ~700-1700ms
 *      on an idle box and far longer under memory pressure. A Bun.spawnSync
 *      that hits its `timeout` still RETURNS, carrying partial stdout — so
 *      the `.includes()` match came back false and a LIVE process was
 *      reported dead. Callers that validate liveness before killing
 *      (killAgentByRecord, the terminal-agent watchdog) then skipped the
 *      kill and respawned around the survivor — one leaked terminal-agent
 *      per tick, self-reinforcing (each orphan slows the next tasklist).
 *   2. A console window per probe (#1952): the watchdog blinked a conhost
 *      window into the foreground every 60s for the whole session.
 *
 * Signal 0 spawns nothing, cannot time out, and is orders of magnitude
 * faster (~0.004ms vs ~270ms measured in #2414).
 *
 * EPERM means the process EXISTS but we lack rights to signal it. That is
 * alive — returning false there would reintroduce failure mode 1.
 */
export function isProcessAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err: any) {
    return err?.code === 'EPERM';
  }
}

/**
 * Cross-platform file permission restriction for sensitive gstack state.
 *
 * Why this exists
 * ----------------
 * POSIX mode bits (`0o600` for files, `0o700` for dirs) are how gstack marks
 * sensitive state files — auth tokens, PTY session state, tab context. On
 * Linux and macOS,
 * `fs.chmodSync(path, 0o600)` and `fs.writeFileSync(path, data, { mode: 0o600 })`
 * do exactly what you'd hope: the file ends up readable and writable only
 * by the owning user, no access for group / other.
 *
 * On Windows, both calls are effectively no-ops. NTFS uses ACLs, not POSIX
 * mode bits, and Node's fs module doesn't translate. So on every Windows
 * install, sensitive gstack state files inherit whatever ACL the parent
 * directory grants — typically user-full + inherited admin-full. That's
 * fine on a single-user laptop but leaks on:
 *
 *   - Self-hosted CI runners (GitHub Actions / GitLab / Jenkins agents
 *     running as a different service account on the same box — they can
 *     read developer state)
 *   - Shared development machines (agencies, studios, lab machines)
 *   - Multi-tenant servers with shared home directories
 *   - Malware running as the same user (no in-user-account isolation)
 *
 * This module wraps the platform-correct call. POSIX: chmod. Windows:
 * icacls with inheritance break + explicit user grant. Failures on either
 * platform are best-effort — the filesystem is still functional if ACL
 * restriction fails; we just don't hit the intended hardening target.
 *
 * Warning behavior: to avoid spamming the console on a machine where
 * icacls is unavailable (rare — it ships in System32 on every Windows
 * version since 7), we log the first failure per process and stay silent
 * afterward. The warning includes the advice "sensitive files may be
 * readable by other accounts on this machine" so operators know to audit
 * their runner / share setup.
 */

import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';

let warnedOnce = false;

let cachedSid: string | null | undefined;

/**
 * Resolve the current user's SID, cached for the process lifetime.
 *
 * Returns null if `whoami` is unavailable or its output cannot be parsed,
 * in which case callers fall back to a domain-qualified account name.
 */
function currentUserSid(): string | null {
  if (cachedSid !== undefined) return cachedSid;
  try {
    // Pin to the System32 binary. A bare `whoami` resolves to the MSYS/Git
    // Bash build under a bash-flavoured PATH, which rejects `/user` — the
    // lookup would then silently fail on one of the most common Windows
    // setups for this tool.
    const systemRoot = process.env.SystemRoot || process.env.windir || 'C:\\Windows';
    const out = execFileSync(`${systemRoot}\\System32\\whoami.exe`, ['/user', '/fo', 'csv', '/nh'], {
      encoding: 'utf8',
      windowsHide: true,
    });
    const match = out.match(/S-1-[\d-]+/);
    cachedSid = match ? match[0] : null;
  } catch {
    cachedSid = null;
  }
  return cachedSid;
}

/**
 * The principal to hand icacls for "the current user".
 *
 * An unqualified username is ambiguous: on a machine whose hostname equals
 * the username, it fails to resolve to the user account and icacls silently
 * writes an ACE for the machine SID instead. Combined with `/inheritance:r`
 * that leaves a directory whose only ACE matches nobody — locking out the
 * process that just created it.
 *
 * `*<SID>` is icacls' literal-SID form and is immune to that ambiguity.
 * The domain-qualified name is the fallback.
 */
function currentUserPrincipal(): string {
  const sid = currentUserSid();
  if (sid) return `*${sid}`;
  const domain = process.env.USERDOMAIN || os.hostname();
  return `${domain}\\${os.userInfo().username}`;
}

function warnIcaclsFailure(fsPath: string, err: unknown): void {
  if (warnedOnce) return;
  warnedOnce = true;
  const msg = err instanceof Error ? err.message : String(err);
  // biome-ignore lint/suspicious/noConsole: intentional user-facing warning
  console.warn(
    `[gstack] Failed to restrict Windows ACL on ${fsPath}: ${msg}\n` +
    `  Sensitive files may be readable by other accounts on this machine.\n` +
    `  This warning appears once per process; subsequent failures are silent.`
  );
}

/**
 * Restrict a file to owner-only access (POSIX 0o600 equivalent).
 *
 * POSIX: `fs.chmodSync(path, 0o600)`. Idempotent if the file was already
 * written with `{ mode: 0o600 }`, so safe to call regardless.
 *
 * Windows: invokes `icacls /inheritance:r /grant:r <user>:(F)` to remove
 * any inherited ACLs and replace the ACL with a single entry granting the
 * current user full control.
 */
export function restrictFilePermissions(filePath: string): void {
  if (process.platform === 'win32') {
    try {
      const user = currentUserPrincipal();
      execFileSync(
        'icacls',
        [filePath, '/inheritance:r', '/grant:r', `${user}:(F)`],
        { stdio: 'ignore', windowsHide: true },
      );
    } catch (err) {
      warnIcaclsFailure(filePath, err);
    }
    return;
  }
  try { fs.chmodSync(filePath, 0o600); } catch { /* best-effort */ }
}

/**
 * Restrict a directory to owner-only access (POSIX 0o700 equivalent),
 * with new children inheriting the restricted ACL.
 *
 * POSIX: `fs.chmodSync(path, 0o700)`. Idempotent if the dir was already
 * created with `{ mode: 0o700 }`.
 *
 * Owner-only hardening is for directories gstack creates and owns. Two
 * pre-existing shapes must never be chmodded, so the POSIX branch refuses
 * them:
 *
 *   - A directory owned by another user. On most hosts the chmod just
 *     fails EPERM, but run as root (or with CAP_FOWNER — containers, CI
 *     sandboxes) it SUCCEEDS and takes the directory away from its owner.
 *   - A shared sticky world-writable directory (`/tmp`, `/var/tmp`).
 *     Callers land here when a state file is configured directly inside
 *     the system temp dir (`BROWSE_STATE_FILE=/tmp/foo.json` makes
 *     `path.dirname()` derive `/tmp` as the state dir). A 0o700 `/tmp`
 *     locks every other process on the machine out of it: access(2)-based
 *     checks (`fs.existsSync`) return EACCES→false machine-wide, even
 *     while stat keeps working for capability-holding processes.
 *
 * Windows: `icacls /inheritance:r /grant:r <user>:(OI)(CI)(F)`. The
 * `(OI)(CI)` flags make new files (OI = object inherit) and subdirs
 * (CI = container inherit) inherit the single-user-full ACL — important
 * because child creations in `fs.writeFileSync(...)` without explicit
 * `restrictFilePermissions` still end up owner-only.
 *
 * Symlinked dirs are warned about and SKIPPED, never followed: both
 * `chmod` and `icacls` dereference the link, so restricting through a
 * symlink hardens whatever the link points at — a target the caller never
 * vetted (and, with `/inheritance:r`, one we could lock its real owner out
 * of). Skipping is best-effort-consistent with the rest of this module:
 * the filesystem stays functional, we just don't hit the hardening target.
 */
export function restrictDirectoryPermissions(dirPath: string): void {
  try {
    if (fs.lstatSync(dirPath).isSymbolicLink()) {
      // biome-ignore lint/suspicious/noConsole: intentional user-facing warning
      console.warn(
        `[gstack] Refusing to restrict permissions through symlink ${dirPath} — skipping.\n` +
        `  Restricting through a symlink would alter the link target instead. ` +
        `Harden the real directory directly.`
      );
      return;
    }
  } catch {
    // Path doesn't exist (or lstat failed) — fall through; both platform
    // branches below already swallow failures on missing paths.
  }
  if (process.platform === 'win32') {
    try {
      const user = currentUserPrincipal();
      execFileSync(
        'icacls',
        [dirPath, '/inheritance:r', '/grant:r', `${user}:(OI)(CI)(F)`],
        { stdio: 'ignore', windowsHide: true },
      );
    } catch (err) {
      warnIcaclsFailure(dirPath, err);
    }
    return;
  }
  try {
    // fd-anchored check-then-act: statSync + chmodSync resolve the path twice,
    // so a symlink swapped in between would let the chmod land on a directory
    // the check never saw (exactly the CAP_FOWNER hosts this guard exists
    // for). O_NOFOLLOW refuses a symlinked state dir outright; fstat + fchmod
    // pin both the check and the act to the same inode.
    const fd = fs.openSync(
      dirPath,
      fs.constants.O_RDONLY | fs.constants.O_DIRECTORY | fs.constants.O_NOFOLLOW,
    );
    try {
      if (!shouldHardenDir(fs.fstatSync(fd))) {
        warnUnhardenedDirOnce(dirPath);
        return;
      }
      fs.fchmodSync(fd, 0o700);
    } finally {
      fs.closeSync(fd);
    }
  } catch (err: any) {
    // The fd path refuses two shapes the old chmodSync handled, and a silent
    // skip here would quietly lose hardening (the module's own rule is that
    // refusals are never silent):
    //   ELOOP/ENOTDIR — dirPath is a symlink (dotfiles-managed ~/.gstack via
    //     stow/chezmoi). Never follow it blind; warn so the operator knows.
    //   EACCES — an OWNED dir stuck without the read bit (mode 0300/0000)
    //     can't be opened but could always be repaired by plain chmod. Keep
    //     that self-repair: re-check ownership via lstat (no link follow) and
    //     chmod only a real, owned, non-shared directory.
    if (err?.code === 'EACCES') {
      try {
        const st = fs.lstatSync(dirPath);
        if (st.isDirectory() && shouldHardenDir(st)) {
          fs.chmodSync(dirPath, 0o700);
          return;
        }
      } catch { /* fall through to the warning */ }
    }
    if (err?.code === 'ELOOP' || err?.code === 'ENOTDIR' || err?.code === 'EACCES') {
      warnUnhardenedDirOnce(dirPath);
    }
    /* anything else: best-effort, matching the old behavior */
  }
}

/** Owner-only hardening applies to a real dir we own that isn't shared. */
function shouldHardenDir(st: fs.Stats): boolean {
  // chmod authorization is judged on the EFFECTIVE uid; fall back to the
  // real uid where geteuid is unavailable (Windows — unreachable here).
  const uid = process.geteuid?.() ?? process.getuid?.();
  if (st.uid !== uid) return false;
  // sticky + world-writable = shared temp dir (/tmp, /var/tmp) — never ours
  // to restrict. Running as root, treat ANY world-writable dir as shared:
  // root "owns" docker/CI volume mounts (0777, no sticky bit) that other
  // users depend on, and a 0700 there locks them all out.
  if ((st.mode & 0o1002) === 0o1002) return false;
  if (uid === 0 && (st.mode & 0o002) === 0o002) return false;
  return true;
}

// The POSIX refusal must not be silent (the Windows branch already warns when
// icacls misses its hardening target): an operator who points state at a
// shared or foreign-owned directory should learn it was left unhardened.
const unhardenedWarned = new Set<string>();
function warnUnhardenedDirOnce(dirPath: string): void {
  if (unhardenedWarned.has(dirPath)) return;
  unhardenedWarned.add(dirPath);
  // biome-ignore lint/suspicious/noConsole: intentional user-facing warning
  console.warn(
    `[gstack] directory ${dirPath} is shared, symlinked, or owned by another user; ` +
    'gstack left its permissions untouched — use a private, non-symlinked directory for owner-only hardening',
  );
}

/**
 * Write a file and restrict it to owner-only access, cross-platform.
 * Replaces `fs.writeFileSync(path, data, { mode: 0o600 })` + Windows ACL.
 */
export function writeSecureFile(
  filePath: string,
  data: string | NodeJS.ArrayBufferView,
): void {
  fs.writeFileSync(filePath, data, { mode: 0o600 });
  restrictFilePermissions(filePath);
}

/**
 * Append to a file with owner-only permissions, cross-platform.
 * Replaces `fs.appendFileSync(path, data, { mode: 0o600 })` + Windows ACL.
 *
 * ACL is applied only on first write — subsequent appends are fire-and-forget
 * (no need to re-run icacls on every log line).
 */
export function appendSecureFile(
  filePath: string,
  data: string | NodeJS.ArrayBufferView,
): void {
  const existed = fs.existsSync(filePath);
  fs.appendFileSync(filePath, data, { mode: 0o600 });
  if (!existed) restrictFilePermissions(filePath);
}

/**
 * Windows only: probe whether the current process can actually list the
 * directory. `fs.accessSync` doesn't consult NTFS ACLs on Windows, so a
 * real readdir is the only honest check.
 */
function canListDir(dirPath: string): boolean {
  try { fs.readdirSync(dirPath); return true; } catch { return false; }
}

/**
 * Windows only: repair a broken DACL on a state directory (#1605).
 *
 * `icacls /inheritance:r /grant:r <user>:(F)` is a single command, but the
 * two halves can partially fail: inheritance gets stripped while the user
 * grant doesn't resolve (localized account names, domain accounts, roaming
 * profiles). The result is a DACL with no usable ACE — often just a machine
 * SID — and the client can't read its own state files. `/reset` restores
 * inherited ACLs from the parent, making the directory functional again.
 * Functional-but-unhardened beats hardened-but-unusable.
 */
export function repairBrokenDacl(dirPath: string): void {
  if (process.platform !== 'win32') return;
  try {
    execFileSync('icacls', [dirPath, '/reset', '/T', '/C', '/Q'], { stdio: 'ignore', windowsHide: true });
  } catch (err) {
    warnIcaclsFailure(dirPath, err);
  }
}

/**
 * `mkdir -p` with owner-only directory permissions, cross-platform.
 * Replaces `fs.mkdirSync(path, { recursive: true, mode: 0o700 })` + Windows ACL.
 * Safe to call on an existing directory — re-applies the ACL idempotently,
 * except on directories gstack doesn't own (another user's dir, or a shared
 * sticky world-writable dir like `/tmp`), which are left untouched — see
 * `restrictDirectoryPermissions`.
 *
 * Windows: after applying the restricted ACL, verifies the directory is
 * still listable by this process and repairs a broken DACL (#1605) if not.
 */
export function mkdirSecure(dirPath: string): void {
  fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  restrictDirectoryPermissions(dirPath);
  if (process.platform === 'win32' && !canListDir(dirPath)) {
    repairBrokenDacl(dirPath);
    restrictDirectoryPermissions(dirPath);
    // If re-hardening broke access again, reset once more and leave the
    // directory with inherited ACLs — the client must be able to read
    // its own state.
    if (!canListDir(dirPath)) repairBrokenDacl(dirPath);
  }
}

/**
 * Reset the once-per-process warning gate. Test-only.
 */
export function __resetWarnedForTests(): void {
  warnedOnce = false;
}

/**
 * find-browse — locate the gstack browse binary.
 *
 * Compiled to browse/dist/find-browse (standalone binary, no bun runtime needed).
 * Outputs the absolute path to the browse binary on stdout, or exits 1 if not found.
 */

import { accessSync, constants } from 'fs';
import { join } from 'path';
import { homedir } from 'os';

// ─── Binary Discovery ───────────────────────────────────────────

function getGitRoot(): string | null {
  try {
    const proc = Bun.spawnSync(['git', 'rev-parse', '--show-toplevel'], {
    windowsHide: true,
      stdout: 'pipe',
      stderr: 'pipe',
    });
    if (proc.exitCode !== 0) return null;
    return proc.stdout.toString().trim();
  } catch {
    return null;
  }
}

// Probe a path for executability. accessSync(X_OK) checks the executable
// bit on Linux/macOS and degrades to an existence check on Windows (no
// true execute bit). Mirrors make-pdf/src/browseClient.ts:159 /
// make-pdf/src/pdftotext.ts:117.
function isExecutable(p: string): boolean {
  try {
    accessSync(p, constants.X_OK);
    return true;
  } catch {
    return false;
  }
}

// Resolve a bare binary path to the actual file on disk. On Windows, `bun
// build --compile` appends `.exe` to the output filename, so `browse` on
// disk is actually `browse.exe`. After a bare-path probe, try the Windows
// extensions. Linux/macOS behavior is unchanged. Mirrors the helper in
// make-pdf/src/browseClient.ts:89 and make-pdf/src/pdftotext.ts:52.
function findExecutable(base: string): string | null {
  if (isExecutable(base)) return base;
  if (process.platform === 'win32') {
    for (const ext of ['.exe', '.cmd', '.bat']) {
      const withExt = base + ext;
      if (isExecutable(withExt)) return withExt;
    }
  }
  return null;
}

export function locateBinary(): string | null {
  const root = getGitRoot();
  const home = homedir();
  const markers = ['.codex', '.agents', '.claude'];

  // Workspace-local takes priority (for development)
  if (root) {
    for (const m of markers) {
      const local = join(root, m, 'skills', 'gstack', 'browse', 'dist', 'browse');
      const found = findExecutable(local);
      if (found) return found;
    }

    // Source-checkout fallback (no installed skill layout — the binary
    // lives directly at <repo>/browse/dist/browse[.exe]). Hit by:
    // - gstack repo dev workflow before `./setup` runs
    // - the windows-setup-e2e.yml CI workflow which builds binaries
    //   in place but never installs them under a marker dir
    // - make-pdf consumers running from a sibling source checkout
    const sourceCheckout = join(root, 'browse', 'dist', 'browse');
    const sourceFound = findExecutable(sourceCheckout);
    if (sourceFound) return sourceFound;
  }

  // Global fallback
  for (const m of markers) {
    const global = join(home, m, 'skills', 'gstack', 'browse', 'dist', 'browse');
    const found = findExecutable(global);
    if (found) return found;
  }

  return null;
}

// ─── Main ───────────────────────────────────────────────────────

function main() {
  const bin = locateBinary();
  if (!bin) {
    process.stderr.write('ERROR: browse binary not found. Run: cd <skill-dir> && ./setup\n');
    process.exit(1);
  }

  console.log(bin);
}

// Only run main() when this module is the entry point. Without this guard,
// any test that imports `locateBinary` from this file would have main() fire
// at module-load time, calling process.exit(1) when no compiled binary
// exists — killing the test process before any test runs. Surfaced on the
// windows-free-tests CI lane where the runner has no compiled browse
// binary (intentional — that lane only builds server-node.mjs).
if (import.meta.main) {
  main();
}

/**
 * find-security-sidecar — resolve the Node entry that runs the L4 ML
 * classifier sidecar.
 *
 * The sidecar can't be bundled into the compiled browse binary because
 * onnxruntime-node fails to dlopen from Bun's compile extract dir. It runs
 * as a separate Node subprocess instead. This module resolves the right
 * path + interpreter on each platform:
 *
 *   1. Prefer node on PATH + a bundled JS entry at
 *      browse/dist/security-sidecar.js (built by package.json's
 *      build:security-sidecar script).
 *   2. Dev fallback: node + browse/src/security-sidecar-entry.ts via tsx
 *      (only available in the source checkout, not the compiled install).
 *   3. If Node is missing or no entry resolves, return null. The /pty-inject-scan
 *      endpoint then responds with l4 { available: false } and the extension
 *      degrades to WARN+confirm (D7).
 */

import { existsSync } from "fs";
import { join, dirname } from "path";
import { execFileSync } from "child_process";

export interface SidecarLocation {
  node: string;
  entry: string;
  /** "compiled" if running from browse/dist/, "dev" if running from src */
  mode: "compiled" | "dev";
}

function nodeOnPath(): string | null {
  try {
    execFileSync("node", ["--version"], { stdio: "ignore", timeout: 2000, windowsHide: true });
    return "node";
  } catch {
    return null;
  }
}

function browseRoot(): string {
  // When running compiled, __dirname (via import.meta.dir) points at the
  // Bun extract temp. Walk up until we find a directory containing
  // browse/dist/ or browse/src/.
  let candidate = dirname(import.meta.path || "");
  for (let i = 0; i < 6; i += 1) {
    if (existsSync(join(candidate, "browse", "dist", "security-sidecar.js"))) {
      return candidate;
    }
    if (existsSync(join(candidate, "src", "security-sidecar-entry.ts"))) {
      return candidate;
    }
    const next = dirname(candidate);
    if (next === candidate) break;
    candidate = next;
  }
  return process.cwd();
}

export function findSecuritySidecar(): SidecarLocation | null {
  const node = nodeOnPath();
  if (!node) return null;

  const root = browseRoot();

  const compiled = join(root, "browse", "dist", "security-sidecar.js");
  if (existsSync(compiled)) {
    return { node, entry: compiled, mode: "compiled" };
  }

  // Dev fallback. Compiled installs won't have src/ on disk so this only
  // resolves when running from the source checkout.
  const devEntry = join(root, "src", "security-sidecar-entry.ts");
  if (existsSync(devEntry)) {
    return { node, entry: devEntry, mode: "dev" };
  }

  return null;
}

/**
 * Media extraction helper — shared between `media` (read) and `scrape` (write) commands.
 *
 * Runs page.evaluate() to discover all media elements on the page:
 *   - <img> with src, srcset, currentSrc, alt, dimensions, loading, data-src
 *   - <video> with currentSrc, poster, duration, <source> children, HLS/DASH detection
 *   - <audio> with src, duration, type
 *   - CSS background-image (capped at 500 elements)
 */

import type { Page, Frame } from 'playwright';

export interface ImageInfo {
  index: number;
  src: string;
  srcset: string;
  currentSrc: string;
  alt: string;
  width: number;
  height: number;
  naturalWidth: number;
  naturalHeight: number;
  loading: string;
  dataSrc: string;
  visible: boolean;
}

export interface VideoSource {
  src: string;
  type: string;
}

export interface VideoInfo {
  index: number;
  src: string;
  currentSrc: string;
  poster: string;
  width: number;
  height: number;
  duration: number;
  type: string;
  sources: VideoSource[];
  isHLS: boolean;
  isDASH: boolean;
}

export interface AudioInfo {
  index: number;
  src: string;
  currentSrc: string;
  duration: number;
  type: string;
}

export interface BackgroundImageInfo {
  index: number;
  url: string;
  selector: string;
  element: string;
}

export interface MediaResult {
  images: ImageInfo[];
  videos: VideoInfo[];
  audio: AudioInfo[];
  backgroundImages: BackgroundImageInfo[];
  total: number;
}

/** Extract all media elements from the page or a scoped subtree. */
export async function extractMedia(
  target: Page | Frame,
  options?: { selector?: string; filter?: 'images' | 'videos' | 'audio' },
): Promise<MediaResult> {
  const result = await target.evaluate(({ scopeSelector, filter }) => {
    const root = scopeSelector
      ? document.querySelector(scopeSelector) || document
      : document;

    const images: any[] = [];
    const videos: any[] = [];
    const audio: any[] = [];
    const backgroundImages: any[] = [];

    // Images
    if (!filter || filter === 'images') {
      const imgs = root.querySelectorAll('img');
      imgs.forEach((img, i) => {
        const rect = img.getBoundingClientRect();
        images.push({
          index: i,
          src: img.src || '',
          srcset: img.srcset || '',
          currentSrc: img.currentSrc || '',
          alt: img.alt || '',
          width: img.width,
          height: img.height,
          naturalWidth: img.naturalWidth,
          naturalHeight: img.naturalHeight,
          loading: img.loading || '',
          dataSrc: img.getAttribute('data-src') || img.getAttribute('data-lazy-src') || img.getAttribute('data-original') || '',
          visible: rect.width > 0 && rect.height > 0 && rect.bottom > 0 && rect.right > 0,
        });
      });
    }

    // Videos
    if (!filter || filter === 'videos') {
      const vids = root.querySelectorAll('video');
      vids.forEach((vid, i) => {
        const sources = Array.from(vid.querySelectorAll('source')).map(s => ({
          src: s.src || '',
          type: s.type || '',
        }));
        const isHLS = sources.some(s => s.type.includes('mpegURL') || s.src.includes('.m3u8'));
        const isDASH = sources.some(s => s.type.includes('dash') || s.src.includes('.mpd'));
        videos.push({
          index: i,
          src: vid.src || '',
          currentSrc: vid.currentSrc || '',
          poster: vid.poster || '',
          width: vid.videoWidth || vid.width,
          height: vid.videoHeight || vid.height,
          duration: isFinite(vid.duration) ? vid.duration : 0,
          type: sources[0]?.type || '',
          sources,
          isHLS,
          isDASH,
        });
      });
    }

    // Audio
    if (!filter || filter === 'audio') {
      const auds = root.querySelectorAll('audio');
      auds.forEach((aud, i) => {
        const source = aud.querySelector('source');
        audio.push({
          index: i,
          src: aud.src || source?.src || '',
          currentSrc: aud.currentSrc || '',
          duration: isFinite(aud.duration) ? aud.duration : 0,
          type: source?.type || '',
        });
      });
    }

    // Background images (capped at 500 elements for performance)
    if (!filter || filter === 'images') {
      const allElements = root.querySelectorAll('*');
      let bgCount = 0;
      for (let i = 0; i < allElements.length && bgCount < 500; i++) {
        const el = allElements[i];
        const bg = getComputedStyle(el).backgroundImage;
        if (bg && bg !== 'none') {
          const urlMatch = bg.match(/url\(["']?([^"')]+)["']?\)/);
          if (urlMatch && urlMatch[1] && !urlMatch[1].startsWith('data:')) {
            backgroundImages.push({
              index: bgCount,
              url: urlMatch[1],
              selector: el.tagName.toLowerCase() + (el.id ? `#${el.id}` : '') + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\s+/).join('.') : ''),
              element: el.tagName.toLowerCase(),
            });
            bgCount++;
          }
        }
      }
    }

    return { images, videos, audio, backgroundImages };
  }, { scopeSelector: options?.selector || null, filter: options?.filter || null });

  return {
    ...result,
    total: result.images.length + result.videos.length + result.audio.length + result.backgroundImages.length,
  };
}

// `$B memory` — diagnostic snapshot of Bun heap + per-tab JS heap +
// Chromium process tree + bounded buffer sizes. Lives in its own file
// because the meta-commands dispatcher imports it lazily — projects
// that never run the diagnostic don't pay the import-graph cost (CDP
// bridge, memory-snapshot types, buffer accessors).

import type { BrowserManager } from './browser-manager';
import { formatBytes, type MemorySnapshot, type MemoryStructureStats } from './memory-snapshot';
import { getModificationHistoryStats } from './cdp-inspector';
import { getSubscriberCount as getActivitySubscriberCount } from './activity';
import { getInspectorSubscriberCount } from './server';
import { consoleBuffer, networkBuffer, dialogBuffer } from './buffers';
import { getCaptureBuffer } from './network-capture';

/**
 * Assemble the MemoryStructureStats from the modules that own each buffer.
 * Browser-manager doesn't take a hard dep on every buffer-owning module —
 * the snapshot caller passes them in.
 */
function collectStructureStats(): MemoryStructureStats {
  return {
    modificationHistory: getModificationHistoryStats(),
    activitySubscribers: getActivitySubscriberCount(),
    inspectorSubscribers: getInspectorSubscriberCount(),
    consoleBufferLen: consoleBuffer.length,
    networkBufferLen: networkBuffer.length,
    dialogBufferLen: dialogBuffer.length,
    captureBufferBytes: getCaptureBuffer().byteSize,
  };
}

/**
 * Pretty-print the snapshot for terminal output. JSON mode (--json) goes
 * straight through JSON.stringify so the extension footer and any test
 * harness can consume it programmatically.
 */
function formatSnapshotText(s: MemorySnapshot): string {
  const lines: string[] = [];
  lines.push(
    `Bun server:        RSS: ${formatBytes(s.bunServer.rss)}  ` +
    `heap: ${formatBytes(s.bunServer.heapUsed)} / ${formatBytes(s.bunServer.heapTotal)}  ` +
    `external: ${formatBytes(s.bunServer.external)}`,
  );

  if (s.processes && s.processes.length > 0) {
    // Group by type so the user sees "renderer: 12" vs listing 12 separate rows.
    const byType: Record<string, number> = {};
    for (const p of s.processes) byType[p.type] = (byType[p.type] ?? 0) + 1;
    const typeSummary = Object.entries(byType)
      .map(([t, n]) => `${t}=${n}`)
      .join(' ');
    lines.push(`Chromium processes: ${s.processes.length} total  (${typeSummary})`);
  } else if (s.processes === null) {
    lines.push('Chromium processes: (unavailable — see notes)');
  } else {
    lines.push('Chromium processes: 0');
  }

  if (s.tabs.length > 0) {
    // Sort by JS heap descending; show top 10 plus "...N more" tail.
    const sorted = [...s.tabs].sort((a, b) => b.jsHeapUsed - a.jsHeapUsed);
    const shown = sorted.slice(0, 10);
    lines.push(`Renderers:         ${s.tabs.length} tabs (top by JS heap):`);
    for (const t of shown) {
      const urlShort = t.url.length > 80 ? t.url.slice(0, 77) + '...' : t.url;
      lines.push(
        `  [${formatBytes(t.jsHeapUsed).padStart(8)} JS, ` +
        `${String(t.nodes).padStart(6)} nodes, ` +
        `${String(t.listeners).padStart(5)} listeners] ` +
        `tab #${t.id} — ${urlShort}`,
      );
    }
    if (sorted.length > shown.length) {
      lines.push(`  ...and ${sorted.length - shown.length} more`);
    }
  } else {
    lines.push('Renderers:         (no tabs tracked)');
  }

  lines.push('─────────────────────────────────────────────────');
  lines.push('In-memory structures (Bun side):');
  const m = s.structures.modificationHistory;
  lines.push(
    `  modificationHistory:    ${m.current} / ${m.cap} entries` +
    (m.evicted > 0 ? `  (${m.evicted} evicted since reset)` : ''),
  );
  lines.push(`  inspectorSubscribers:   ${s.structures.inspectorSubscribers}`);
  lines.push(`  activitySubscribers:    ${s.structures.activitySubscribers}`);
  lines.push(`  consoleBuffer:          ${s.structures.consoleBufferLen} entries`);
  lines.push(`  networkBuffer:          ${s.structures.networkBufferLen} entries`);
  lines.push(`  dialogBuffer:           ${s.structures.dialogBufferLen} entries`);
  lines.push(`  captureBuffer:          ${formatBytes(s.structures.captureBufferBytes)}`);

  if (s.notes.length > 0) {
    lines.push('');
    lines.push('Notes:');
    for (const n of s.notes) lines.push(`  - ${n}`);
  }

  return lines.join('\n');
}

export async function handleMemoryCommand(args: string[], bm: BrowserManager): Promise<string> {
  const jsonMode = args.includes('--json');
  const structures = collectStructureStats();
  const snapshot = await bm.getMemorySnapshot(structures);
  if (jsonMode) return JSON.stringify(snapshot);
  return formatSnapshotText(snapshot);
}

/** Entry point used by the /memory HTTP endpoint — same data, always JSON. */
export async function buildMemorySnapshotJson(bm: BrowserManager): Promise<MemorySnapshot> {
  const structures = collectStructureStats();
  return bm.getMemorySnapshot(structures);
}

// Shared types for the $B memory diagnostic command and the /memory
// endpoint. Lives in its own module so server.ts, read-commands.ts, and
// the extension footer poll can import without taking a circular dep on
// browser-manager.ts.
//
// Background: the gbrowser-OOM investigation (160 GB Activity Monitor
// reading on a friend's machine) needed a diagnostic that could land
// before the next incident — measurement comes first, fixes come after.
// $B memory is that diagnostic.

/** Counts/bytes for the bounded in-memory structures on the Bun side. */
export interface MemoryStructureStats {
  modificationHistory: { current: number; cap: number; evicted: number };
  activitySubscribers: number;
  inspectorSubscribers: number;
  consoleBufferLen: number;
  networkBufferLen: number;
  dialogBufferLen: number;
  captureBufferBytes: number;
}

/** Per-tab JS heap snapshot (CDP Performance.getMetrics). */
export interface MemoryTabSnapshot {
  id: number;
  url: string;
  title: string;
  jsHeapUsed: number;
  jsHeapTotal: number;
  documents: number;
  nodes: number;
  listeners: number;
}

/** Chromium process metadata via CDP SystemInfo.getProcessInfo. */
export interface MemoryProcess {
  /** Chromium-internal process id (not OS PID). */
  id: number;
  /** 'browser' | 'renderer' | 'gpu' | 'utility' | 'extension' | ... */
  type: string;
  /** CPU time accumulated since process start (seconds). */
  cpuTime: number;
}

export interface MemorySnapshot {
  bunServer: {
    rss: number;
    heapUsed: number;
    heapTotal: number;
    external: number;
  };
  tabs: MemoryTabSnapshot[];
  /**
   * Chromium process tree. `null` when no browser handle is available
   * (server in connection mode, or browser not yet launched).
   *
   * Per-process RSS is NOT included: SystemInfo.getProcessInfo returns
   * id+type+cpuTime but Chromium does not expose RSS via CDP. The
   * `notes[]` field tells the caller why — see the follow-up TODO
   * "native/GPU memory breakdown" for the deferred fix.
   */
  processes: MemoryProcess[] | null;
  structures: MemoryStructureStats;
  capturedAt: number;
  notes: string[];
}

/** Format bytes as a short human string ("1.4 GB", "312 MB", "84 KB"). */
export function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`;
}

