/** Which HTTP listener accepted this request. */
export type Surface = 'local' | 'tunnel';

/**
 * Factory contract for embedders (gbrowser phoenix overlay).
 *
 * Today the CLI calls `start()` which reads env vars and binds Bun.serve
 * itself. Embedders building on this server as a submodule (gbrowser's
 * fd-passing gbd architecture) need to inject auth + ports + a
 * BrowserManager they pre-launched, and own the listener themselves.
 *
 * Status: v1 surfaces this type as documentation. AUTH_TOKEN env-injection
 * is already live (see ~L70). `start()` is exported and the kickoff /
 * signal-handler registration is gated on `import.meta.main`, so phoenix
 * can `import { start } from '.../server'` without auto-starting. Full
 * `buildFetchHandler` extraction lands in a follow-up; see plan
 * `/Users/garrytan/.claude/plans/system-instruction-you-are-working-swirling-fountain.md`
 * Part 1.
 */
export interface ServerConfig {
  /** Bearer token clients must present. Today injected via AUTH_TOKEN env. */
  authToken: string;
  /** Local listener port. Used in /welcome URL + state-file. */
  browsePort: number;
  /** Result of resolveConfig() — stateDir, auditLog, stateFile. */
  config: ReturnType<typeof resolveConfig>;
  /** Pre-launched BrowserManager. Caller owns lifecycle. */
  browserManager: BrowserManager;
  // NOTE: per-factory idleTimeoutMs and chromiumProfile were deleted — they
  // were documented but never read (the idle timer, activity state, and
  // shutdown target are module-global, so per-factory wiring would lie for
  // any embedder running >1 handler). Real support belongs to the deferred
  // server.ts singleton/route-table refactor. Until then: BROWSE_IDLE_TIMEOUT
  // and CHROMIUM_PROFILE env are the honest knobs.
  /** Caller-owned. shutdown() does NOT call xvfb.stop(); caller is responsible. */
  xvfb?: XvfbHandle | null;
  /** Caller-owned. shutdown() does NOT call proxyBridge.close(); caller is responsible. */
  proxyBridge?: BridgeHandle | null;
  startTime: number;
  /**
   * Overlay hook. Runs AFTER gstack resolves auth and BEFORE route dispatch.
   * Invalid tokens are auto-rejected at the gstack layer (401 returned
   * before hook fires), so the hook only ever sees valid TokenInfo or null
   * (no token presented). Returning a Response short-circuits gstack
   * dispatch; returning null falls through.
   */
  beforeRoute?: (req: Request, surface: Surface, auth: TokenInfo | null) => Promise<Response | null>;
  /**
   * Whether gstack owns the lifecycle of the terminal-agent process and its
   * discovery files (`<stateDir>/terminal-port`, `<stateDir>/terminal-internal-token`,
   * `<stateDir>/terminal-agent-pid`).
   *
   * When true (default), shutdown() runs four side effects:
   *   1. Identity-based kill via `killAgentByRecord(readAgentRecord(stateDir))`
   *      (v1.44+). Only signals the PID recorded by THIS daemon's agent.
   *      Replaced the historical `pkill -f terminal-agent\.ts` regex that
   *      matched sibling gstack sessions on the same host — see
   *      terminal-agent-control.ts for rationale.
   *   2. `safeUnlinkQuiet(<stateDir>/terminal-port)`
   *   3. `safeUnlinkQuiet(<stateDir>/terminal-internal-token)`
   *   4. `safeUnlinkQuiet(<stateDir>/terminal-agent-pid)` (the v1.44 record)
   *
   * This is correct for gstack's CLI path, which spawns `terminal-agent.ts` as
   * the producer of those files (see cli.ts:1037-1063).
   *
   * Embedders (gbrowser phoenix overlay, future hosts) that run their own PTY
   * server and write those files themselves should pass `false`. When `false`,
   * the embedder owns BOTH the agent process AND all three discovery files.
   * Note that terminal-agent.ts's own SIGTERM cleanup removes `terminal-port`
   * and `terminal-agent-pid` (the agent writes both at boot), so embedders
   * that pre-launch their own agent must ensure their cleanup matches.
   *
   * Polarity note: this differs from `xvfb?` and `proxyBridge?`, which gate by
   * the *presence* of a caller-owned handle (presence ⇒ don't close). This
   * field gates by an explicit boolean because there is no handle object —
   * the terminal-agent is started elsewhere (cli.ts), and shutdown's only
   * reference is the PID record + the file paths.
   */
  ownsTerminalAgent?: boolean;
}

/**
 * Return shape of buildFetchHandler() — fetch handlers + lifecycle helpers
 * embedders need to drive their own Bun.serve binding. See ServerConfig.
 */
export interface ServerHandle {
  fetchLocal: (req: Request, server: any) => Promise<Response>;
  fetchTunnel: (req: Request, server: any) => Promise<Response>;
  /**
   * Drains buffers, kills terminal-agent, closes browser, clears intervals,
   * removes state files. Does NOT stop bound Bun.Server listeners — call
   * stopListeners() for that. CLI relies on process.exit() to drop sockets.
   */
  shutdown: (exitCode?: number) => Promise<void>;
  /**
   * Graceful listener stop for embedders. Calls server.stop(true) on each
   * passed Bun.Server. CLI doesn't need this (process.exit handles it).
   */
  stopListeners: (local: any, tunnel?: any) => Promise<void>;
}

/**
 * Build a ServerConfig-shaped object from process.env. Used by gstack's
 * own CLI when running `bun run dev` or the compiled binary directly.
 * Embedders construct their own ServerConfig explicitly.
 *
 * Reads env, calls resolveConfig(). Does NOT bind a listener or call
 * initAuditLog/initRegistry — those happen inside the buildFetchHandler
 * lifecycle.
 */
export function resolveConfigFromEnv(): Omit<ServerConfig, 'browserManager' | 'startTime'> & {
  config: ReturnType<typeof resolveConfig>;
} {
  return {
    // Same sanitizer as the module-level AUTH_TOKEN: strips ALL unicode
    // whitespace and rejects tokens shorter than 16 chars so a misconfigured
    // embedder can't ship a BOM/zero-width as the bearer secret.
    authToken: sanitizeAuthToken(process.env.AUTH_TOKEN) || crypto.randomUUID(),
    browsePort: parseInt(process.env.BROWSE_PORT || '0', 10),
    config: resolveConfig(),
  };
}

/**
 * Paths reachable over the tunnel surface. Everything else returns 404.
 *
 * `/connect` is the only unauthenticated tunnel endpoint — POST for setup-key
 * exchange, GET for an `{alive: true}` probe used by /pair and /tunnel/start
 * to detect dead ngrok tunnels. Other paths in this set require a scoped
 * token via Authorization: Bearer.
 *
 * Updating this set is a deliberate security decision. Every addition widens
 * the tunnel attack surface.
 */
const TUNNEL_PATHS = new Set<string>([
  '/connect',
  '/command',
]);

/**
 * The gstack sidebar extension's pinned Chrome extension ID. Derived from
 * the "key" field in extension/manifest.json (first 16 bytes of SHA-256 of
 * the DER public key, hex nibbles mapped 0-9a-f → a-p). Reproduce with:
 *   bun browse/scripts/extension-id.ts
 * POST /extension-token releases AUTH_TOKEN only to an Origin of exactly
 * `chrome-extension://<this id>`. If the manifest keypair is ever rotated,
 * this constant must be updated in the same commit.
 */
export const GSTACK_EXTENSION_ID = 'dgbkdbjebeiblbajiilljmhjdpmiglep';

/**
 * Commands reachable via POST /command over the tunnel surface. A paired
 * remote agent can drive the browser (goto, click, text, etc.) but cannot
 * configure the daemon, bootstrap new sessions, import cookies, or reach
 * extension-inspector state. This allowlist maps to the eng-review decision
 * logged in the CEO plan for sec-wave v1.6.0.0.
 */
export const TUNNEL_COMMANDS = new Set<string>([
  // Original 17
  'goto', 'click', 'text', 'screenshot',
  'html', 'links', 'forms', 'accessibility',
  'attrs', 'media', 'data',
  'scroll', 'press', 'type', 'select', 'wait', 'eval',
  // Tab + navigation primitives operator docs and CLI hints already promised
  'newtab', 'tabs', 'back', 'forward', 'reload',
  // Read/inspect/write operators paired agents need to be useful
  'snapshot', 'fill', 'url', 'closetab',
]);

/**
 * Pure gate: returns true iff the command is reachable over the tunnel surface.
 * Extracted from the inline /command handler so the gate logic is unit-testable
 * without standing up an HTTP listener. Behavior is identical to the inline
 * check; the function canonicalizes the command (so aliases hit the same set)
 * and returns false for null/undefined input.
 *
 * `args` is consulted so an `--out` invocation (e.g. `eval --out <file>`) is
 * NEVER tunnel-dispatchable: `--out` turns an otherwise-readable command into a
 * local-disk WRITE, and the tunnel surface never grants disk-write capability to
 * remote paired agents. Omitting `args` preserves the old command-only behavior.
 */
export function canDispatchOverTunnel(command: string | undefined | null, args?: string[]): boolean {
  if (typeof command !== 'string' || command.length === 0) return false;
  if (Array.isArray(args) && hasOutArg(args)) return false;
  const cmd = canonicalizeCommand(command);
  return TUNNEL_COMMANDS.has(cmd);
}

/**
 * Read ngrok authtoken from env var, ~/.gstack/ngrok.env, or ngrok's native
 * config files.  Returns null if nothing found.  Shared between the
 * /tunnel/start handler and the BROWSE_TUNNEL=1 auto-start flow.
 */
function resolveNgrokAuthtoken(): string | null {
  let authtoken = process.env.NGROK_AUTHTOKEN;
  if (authtoken) return authtoken;

  const home = process.env.HOME || '';
  const ngrokEnvPath = path.join(home, '.gstack', 'ngrok.env');
  if (fs.existsSync(ngrokEnvPath)) {
    try {
      const envContent = fs.readFileSync(ngrokEnvPath, 'utf-8');
      const match = envContent.match(/^NGROK_AUTHTOKEN=(.+)$/m);
      if (match) return match[1].trim();
    } catch {}
  }

  const ngrokConfigs = [
    path.join(home, 'Library', 'Application Support', 'ngrok', 'ngrok.yml'),
    path.join(home, '.config', 'ngrok', 'ngrok.yml'),
    path.join(home, '.ngrok2', 'ngrok.yml'),
  ];
  for (const conf of ngrokConfigs) {
    try {
      const content = fs.readFileSync(conf, 'utf-8');
      const match = content.match(/authtoken:\s*(.+)/);
      if (match) return match[1].trim();
    } catch {}
  }
  return null;
}

/**
 * Tear down the tunnel: close the ngrok listener and stop the tunnel-surface
 * Bun.serve listener.  Safe to call with nothing running.  Always clears
 * tunnel state regardless of individual close failures.
 */
async function closeTunnel(): Promise<void> {
  try { if (tunnelListener) await tunnelListener.close(); } catch {}
  try { if (tunnelServer) tunnelServer.stop(true); } catch {}
  tunnelListener = null;
  tunnelServer = null;
  tunnelUrl = null;
  tunnelActive = false;
}

/**
 * Result of startTunnel(). `stage` tells the caller which half failed so it
 * can keep its distinct error surface: 'bind' = the tunnel-surface Bun.serve
 * listener could not bind (nothing to clean up), 'ngrok' = anything after the
 * bind (ngrok forward, egress receipt, state-file write) — startTunnel has
 * already torn down both ngrok and the Bun listener by the time it returns.
 */
type StartTunnelResult =
  | { ok: true; url: string }
  | { ok: false; stage: 'bind' | 'ngrok'; error: Error };

/**
 * Start the ngrok tunnel using the dual-listener pattern: bind a dedicated
 * tunnel-surface listener on an ephemeral 127.0.0.1 port and point
 * ngrok.forward() at THAT port — the local listener (which serves
 * /extension-token, /cookie-picker, /inspector/*, welcome, etc.) is never
 * exposed to ngrok. Shared by the /tunnel/start route handler (which passes
 * its in-closure makeFetchHandler('tunnel')) and the BROWSE_TUNNEL=1
 * auto-start flow in start() (which passes handle.fetchTunnel from the
 * factory). The BROWSE_TUNNEL_LOCAL_ONLY=1 test path does NOT use this
 * helper — it binds the tunnel surface with no ngrok forwarding at all.
 *
 * Hard fail on listener bind (`stage: 'bind'`) — NEVER fall back to the
 * local port, which would silently defeat the whole security property.
 *
 * On success, sets the module tunnel state (tunnelListener / tunnelUrl /
 * tunnelServer / tunnelActive) and records the tunnel in the state file.
 */
async function startTunnel(opts: {
  fetchHandler: (req: Request, server: any) => Promise<Response>;
  authtoken: string;
  consent: string;
}): Promise<StartTunnelResult> {
  // Bind the tunnel listener on an ephemeral port.  HARD FAIL if this
  // errors — never fall back to the local port.
  let boundTunnel: ReturnType<typeof Bun.serve>;
  try {
    boundTunnel = Bun.serve({
      port: 0,
      hostname: '127.0.0.1',
      fetch: opts.fetchHandler,
    });
  } catch (err: any) {
    return { ok: false, stage: 'bind', error: err };
  }
  const tunnelPort = boundTunnel.port;

  // Point ngrok at the TUNNEL port (not the local port).  If this fails,
  // tear the listener back down so we don't leak sockets.
  try {
    const ngrok = await import('@ngrok/ngrok');
    const domain = process.env.NGROK_DOMAIN;
    const forwardOpts: any = { addr: tunnelPort, authtoken: opts.authtoken };
    if (domain) forwardOpts.domain = domain;

    // Egress receipt BEFORE the tunnel session opens, fail-closed: a
    // writeReceipt failure lands in this catch, which tears the tunnel
    // listener back down and refuses the start. One receipt per session
    // open; browse command behavior over the tunnel is unchanged.
    writeReceipt({
      sink: 'browse-tunnel',
      host: domain || 'connect.ngrok-agent.com',
      payloadClass: 'tunnel-session-open (scoped-token browser-command surface)',
      bytes: 0,
      sha256: null,
      consent: opts.consent,
    });

    tunnelListener = await ngrok.forward(forwardOpts);
    tunnelUrl = tunnelListener.url();
    tunnelServer = boundTunnel;
    tunnelActive = true;
    console.log(`[browse] Tunnel listener bound on 127.0.0.1:${tunnelPort}, ngrok → ${tunnelUrl}`);

    // Update state file
    const stateContent = JSON.parse(fs.readFileSync(config.stateFile, 'utf-8'));
    stateContent.tunnel = { url: tunnelUrl, domain: domain || null, startedAt: new Date().toISOString() };
    const tmpState = tmpStatePath();
    fs.writeFileSync(tmpState, JSON.stringify(stateContent, null, 2), { mode: 0o600 });
    fs.renameSync(tmpState, config.stateFile);

    return { ok: true, url: tunnelUrl! };
  } catch (err: any) {
    // Clean up BOTH ngrok and the Bun listener on failure.  If
    // ngrok.forward() succeeded but tunnelListener.url() or the
    // state-file write threw, we'd otherwise leak an active ngrok
    // session on the user's account.
    try { if (tunnelListener) await tunnelListener.close(); } catch {}
    try { boundTunnel.stop(true); } catch {}
    tunnelListener = null;
    return { ok: false, stage: 'ngrok', error: err };
  }
}

// Module-level validateAuth deleted in v1.35.0.0. Factory-scoped equivalent
// in buildFetchHandler closes over cfg.authToken so every internal auth check
// sees the same token the routes receive.

/**
 * Terminal-agent discovery. The non-compiled bun process at
 * `browse/src/terminal-agent.ts` writes its chosen port to
 * `<stateDir>/terminal-port` and the loopback handshake token to
 * `<stateDir>/terminal-internal-token` once it boots. Read on demand —
 * lazy so we don't break tests that don't spawn the agent.
 */
function readTerminalPort(): number | null {
  try {
    const f = path.join(path.dirname(config.stateFile), 'terminal-port');
    const v = parseInt(fs.readFileSync(f, 'utf-8').trim(), 10);
    return Number.isFinite(v) && v > 0 ? v : null;
  } catch { return null; }
}
function readTerminalInternalToken(): string | null {
  try {
    const f = path.join(path.dirname(config.stateFile), 'terminal-internal-token');
    const t = fs.readFileSync(f, 'utf-8').trim();
    return t.length > 16 ? t : null;
  } catch { return null; }
}

/**
 * Push a freshly-minted PTY cookie token to the terminal-agent so its
 * /ws upgrade can validate the cookie. v1.44+: also pushes the bound
 * sessionId so the agent can route /internal/restart and (Commit 3)
 * re-attach back to the same PtySession. Loopback POST authenticated
 * with the internal token written by the agent at startup. If the agent
 * isn't up yet, the extension just retries /pty-session.
 */
async function grantPtyToken(token: string, sessionId?: string): Promise<boolean> {
  const port = readTerminalPort();
  const internal = readTerminalInternalToken();
  if (!port || !internal) return false;
  try {
    const resp = await fetch(`http://127.0.0.1:${port}/internal/grant`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${internal}`,
      },
      body: JSON.stringify(sessionId ? { token, sessionId } : { token }),
      signal: AbortSignal.timeout(2000),
    });
    return resp.ok;
  } catch { return false; }
}

/**
 * Ask the terminal-agent to dispose the PtySession bound to `sessionId`.
 * Scoped to one caller's session — sibling tabs/agents untouched. Used by
 * /pty-restart and /pty-dispose. Returns true on agent ack.
 */
async function restartPtySession(sessionId: string): Promise<boolean> {
  const port = readTerminalPort();
  const internal = readTerminalInternalToken();
  if (!port || !internal) return false;
  try {
    const resp = await fetch(`http://127.0.0.1:${port}/internal/restart`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${internal}`,
      },
      body: JSON.stringify({ sessionId }),
      signal: AbortSignal.timeout(5000),
    });
    return resp.ok;
  } catch { return false; }
}

/** Extract bearer token from request. Returns the token string or null. */
function extractToken(req: Request): string | null {
  const header = req.headers.get('authorization');
  if (!header?.startsWith('Bearer ')) return null;
  return header.slice(7);
}

/** Validate token and return TokenInfo. Returns null if invalid/expired. */
function getTokenInfo(req: Request): TokenInfo | null {
  const token = extractToken(req);
  if (!token) return null;
  return validateScopedToken(token);
}

/** Check if request is from root token (local use). */
function isRootRequest(req: Request): boolean {
  const token = extractToken(req);
  return token !== null && isRootToken(token);
}

// ─── Help text (auto-generated from COMMAND_DESCRIPTIONS) ────────
function generateHelpText(): string {
  // Group commands by category
  const groups = new Map<string, string[]>();
  for (const [cmd, meta] of Object.entries(COMMAND_DESCRIPTIONS)) {
    const display = meta.usage || cmd;
    const list = groups.get(meta.category) || [];
    list.push(display);
    groups.set(meta.category, list);
  }

  const categoryOrder = [
    'Navigation', 'Reading', 'Interaction', 'Inspection',
    'Visual', 'Snapshot', 'Meta', 'Tabs', 'Server',
  ];

  const lines = ['gstack browse — headless browser for AI agents', '', 'Commands:'];
  for (const cat of categoryOrder) {
    const cmds = groups.get(cat);
    if (!cmds) continue;
    lines.push(`  ${(cat + ':').padEnd(15)}${cmds.join(', ')}`);
  }

  // Snapshot flags from source of truth
  lines.push('');
  lines.push('Snapshot flags:');
  const flagPairs: string[] = [];
  for (const flag of SNAPSHOT_FLAGS) {
    const label = flag.valueHint ? `${flag.short} ${flag.valueHint}` : flag.short;
    flagPairs.push(`${label}  ${flag.long}`);
  }
  // Print two flags per line for compact display
  for (let i = 0; i < flagPairs.length; i += 2) {
    const left = flagPairs[i].padEnd(28);
    const right = flagPairs[i + 1] || '';
    lines.push(`  ${left}${right}`);
  }

  return lines.join('\n');
}

// ─── Buffer (from buffers.ts) ────────────────────────────────────
import { consoleBuffer, networkBuffer, dialogBuffer, addConsoleEntry, addNetworkEntry, addDialogEntry, type LogEntry, type NetworkEntry, type DialogEntry } from './buffers';
export { consoleBuffer, networkBuffer, dialogBuffer, addConsoleEntry, addNetworkEntry, addDialogEntry, type LogEntry, type NetworkEntry, type DialogEntry };

const CONSOLE_LOG_PATH = config.consoleLog;
const NETWORK_LOG_PATH = config.networkLog;
const DIALOG_LOG_PATH = config.dialogLog;

/**
 * Per-process state-file temp path. The state-file write pattern is
 * `writeFileSync(tmp, ...) → renameSync(tmp, stateFile)` for atomicity,
 * but a shared `${stateFile}.tmp` filename means two concurrent writers
 * (cold-start race when N CLIs hit a fresh repo simultaneously, parallel
 * /tunnel/start handlers, or a combination) collide on the rename: the
 * first writer's renameSync moves the shared temp file out of the way,
 * the second writer's writeFileSync re-creates it, the second rename
 * then races with the first writer's already-renamed state. Worst case
 * the second renameSync throws ENOENT mid-air, killing one of the
 * spawning daemons during startup.
 *
 * Per-process suffix (pid + 4 random bytes) makes each writer's temp
 * path unique. The atomic rename still gives last-writer-wins semantics
 * for the final state.json content; the only behavior change is that
 * concurrent writers no longer kill each other on the rename.
 */
function tmpStatePath(): string {
  return `${config.stateFile}.tmp.${process.pid}.${crypto.randomBytes(4).toString('hex')}`;
}


// ─── Sidebar agent / chat state ripped ──────────────────────────────
let lastConsoleFlushed = 0;
let lastNetworkFlushed = 0;
let lastDialogFlushed = 0;
let flushInProgress = false;

async function flushBuffers() {
  if (flushInProgress) return; // Guard against concurrent flush
  flushInProgress = true;

  try {
    // Console buffer
    const newConsoleCount = consoleBuffer.totalAdded - lastConsoleFlushed;
    if (newConsoleCount > 0) {
      const entries = consoleBuffer.last(Math.min(newConsoleCount, consoleBuffer.length));
      const lines = entries.map(e =>
        `[${new Date(e.timestamp).toISOString()}] [${e.level}] ${e.text}`
      ).join('\n') + '\n';
      appendSecureFile(CONSOLE_LOG_PATH, lines);
      lastConsoleFlushed = consoleBuffer.totalAdded;
    }

    // Network buffer
    const newNetworkCount = networkBuffer.totalAdded - lastNetworkFlushed;
    if (newNetworkCount > 0) {
      const entries = networkBuffer.last(Math.min(newNetworkCount, networkBuffer.length));
      const lines = entries.map(e =>
        `[${new Date(e.timestamp).toISOString()}] ${e.method} ${e.url} → ${e.status || 'pending'} (${e.duration || '?'}ms, ${e.size || '?'}B)`
      ).join('\n') + '\n';
      appendSecureFile(NETWORK_LOG_PATH, lines);
      lastNetworkFlushed = networkBuffer.totalAdded;
    }

    // Dialog buffer
    const newDialogCount = dialogBuffer.totalAdded - lastDialogFlushed;
    if (newDialogCount > 0) {
      const entries = dialogBuffer.last(Math.min(newDialogCount, dialogBuffer.length));
      const lines = entries.map(e =>
        `[${new Date(e.timestamp).toISOString()}] [${e.type}] "${e.message}" → ${e.action}${e.response ? ` "${e.response}"` : ''}`
      ).join('\n') + '\n';
      appendSecureFile(DIALOG_LOG_PATH, lines);
      lastDialogFlushed = dialogBuffer.totalAdded;
    }
  } catch (err: any) {
    console.error('[browse] Buffer flush failed:', err.message);
  } finally {
    flushInProgress = false;
  }
}

// Flush every 1 second
const flushInterval = setInterval(flushBuffers, 1000);

// ─── Idle Timer ────────────────────────────────────────────────
let lastActivity = Date.now();

function resetIdleTimer() {
  lastActivity = Date.now();
}

// Named for behavioral testing via __testInternals__. The factory tests in
// server-factory.test.ts call this directly so the idle-shutdown path can be
// exercised without waiting 60s for the interval to fire.
function idleCheckTick() {
  // Headed mode: the user is looking at the browser. Never auto-die.
  // Only shut down when the user explicitly disconnects or closes the window.
  // Reads via the activeBrowserManager indirection so embedders that pass
  // their own BrowserManager into buildFetchHandler hit the right instance.
  if (activeBrowserManager.getConnectionMode() === 'headed') return;
  // Tunnel mode: remote agents may send commands sporadically. Never auto-die.
  if (tunnelActive) return;
  if (Date.now() - lastActivity > IDLE_TIMEOUT_MS) {
    console.log(`[browse] Idle for ${IDLE_TIMEOUT_MS / 1000}s, shutting down`);
    activeShutdown?.();
  }
}
const idleCheckInterval = setInterval(idleCheckTick, 60_000);

// Test-only surface for server-factory.test.ts. Lets the dual-instance
// idle-timer behavior be exercised deterministically without mutating
// Date.now (which would interact with the leaked module-level setInterval).
// Production code must never import this — see `idle timer + onDisconnect
// dual-instance fix` describe block for usage.
export const __testInternals__ = {
  idleCheckTick,
  // Watchdog seams (watchdog.test.ts): drive the 15s poll against an
  // arbitrary (dead) PID, trigger the handoff-promotion suppression exactly
  // as onHeadedPromotion does, and reset the latches between tests.
  parentWatchdogTick,
  suppressHeadedParentShutdown,
  resetParentWatchdogState: () => { headedParentShutdownSuppressed = false; parentGone = false; },
  setTunnelActive: (v: boolean) => { tunnelActive = v; },
  setLastActivity: (t: number) => { lastActivity = t; },
  formatExplicitPortUnavailableError,
  formatRandomPortUnavailableError,
  // Reset the module-level shutdown latch so tests that drive shutdown to
  // completion (process.exit-stubbed) can be followed by tests that also
  // need shutdown to fire. Without this, the second test's shutdown
  // returns early at the `if (isShuttingDown) return;` guard.
  resetShutdownState: () => { isShuttingDown = false; },
};

// ─── Parent-Process Watchdog ────────────────────────────────────────
// When the spawning CLI process (e.g. a Claude Code session) exits, this
// server can become an orphan — keeping chrome-headless-shell alive and
// causing console-window flicker on Windows. Poll the parent PID every 15s
// and self-terminate if it is gone.
//
// Headed mode (BROWSE_HEADED=1 or BROWSE_PARENT_PID=0): The user controls
// the browser window lifecycle. The CLI exits immediately after connect,
// so the watchdog would kill the server prematurely. Disabled in both cases
// as defense-in-depth — the CLI sets PID=0 for headed mode, and the server
// also checks BROWSE_HEADED in case a future launcher forgets.
// Cleanup happens via browser disconnect event or $B disconnect.
const BROWSE_PARENT_PID = parseInt(process.env.BROWSE_PARENT_PID || '0', 10);
// Outer gate: if the spawner explicitly marks this as headed (env var set at
// launch time), skip registering the watchdog entirely. Cheaper than entering
// the closure every 15s. The CLI's connect path sets BROWSE_HEADED=1 + PID=0,
// so this branch is the normal path for /open-gstack-browser.
const IS_HEADED_WATCHDOG = process.env.BROWSE_HEADED === '1';
// Runtime promotion to headed (`handoff`) must NOT clear this interval — the
// same tick is the tunnel-orphan reaper, and idle timeout is disabled in
// tunnel mode, so parent death is the ONLY thing that reaps an
// internet-exposed daemon after handoff → resume → /pair-agent. Promotion
// sets this suppress flag instead; the tick re-reads it (and tunnelActive)
// every pass. See suppressHeadedParentShutdown() below.
let headedParentShutdownSuppressed = false;
// Latch for the one-time "parent exited, staying alive" log line.
let parentGone = false;
// Named + parameterized (default: the boot-time env PID) so watchdog.test.ts
// can drive the tick deterministically via __testInternals__, mirroring
// idleCheckTick above. setInterval invokes it with no args in production.
function parentWatchdogTick(parentPid: number = BROWSE_PARENT_PID): void {
  try {
    process.kill(parentPid, 0); // signal 0 = existence check only, no signal sent
  } catch {
    // Parent exited. Resolution order:
    // 1. Active cookie picker (one-time code or session live)? Stay alive
    //    regardless of mode — tearing down the server mid-import leaves the
    //    picker UI with a stale "Failed to fetch" error.
    // 2. Headed (unless suppressed by a runtime promotion) / tunnel mode?
    //    Shutdown. The idle timeout doesn't apply in these modes (see
    //    idleCheckInterval above — both early-return), so ignoring parent
    //    death here would leak orphan daemons after /pair-agent or
    //    /open-gstack-browser sessions.
    // 3. Normal (headless) mode, or headed-by-promotion? Stay alive. Claude
    //    Code's Bash tool kills the parent shell between invocations, and a
    //    promoted daemon's user owns the window lifecycle. The idle timeout
    //    (30 min) handles eventual cleanup.
    if (hasActivePicker()) return;
    const headed = activeBrowserManager.getConnectionMode() === 'headed'
      && !headedParentShutdownSuppressed;
    if (headed || tunnelActive) {
      console.log(`[browse] Parent process ${parentPid} exited in ${headed ? 'headed' : 'tunnel'} mode, shutting down`);
      activeShutdown?.();
    } else if (!parentGone) {
      parentGone = true;
      console.log(`[browse] Parent process ${parentPid} exited (server stays alive, idle timeout will clean up)`);
    }
  }
}
// Poll cadence. Env-overridable as a test seam: watchdog.test.ts shrinks it
// (250ms) so a free-tier test can observe a real tick deciding on a dead
// parent instead of sleeping through the 15s production cadence. Production
// launchers never set this; unparsable or non-positive values fall back to 15s.
const rawWatchdogIntervalMs = parseInt(process.env.BROWSE_PARENT_WATCHDOG_INTERVAL_MS || '', 10);
const PARENT_WATCHDOG_INTERVAL_MS =
  Number.isFinite(rawWatchdogIntervalMs) && rawWatchdogIntervalMs > 0
    ? rawWatchdogIntervalMs
    : 15_000;
if (BROWSE_PARENT_PID > 0 && !IS_HEADED_WATCHDOG) {
  setInterval(parentWatchdogTick, PARENT_WATCHDOG_INTERVAL_MS);
} else if (IS_HEADED_WATCHDOG) {
  console.log('[browse] Parent-process watchdog disabled (headed mode)');
} else if (BROWSE_PARENT_PID === 0) {
  console.log('[browse] Parent-process watchdog disabled (BROWSE_PARENT_PID=0)');
}

/**
 * Suppress the headed-mode parent-death shutdown after a runtime promotion.
 *
 * The watchdog's contract is "headless daemons outlive their parent, headed ones
 * do not" — reasonable at boot, when mode is fixed by env. `handoff` breaks that
 * assumption: it swaps in a headed context on a RUNNING daemon
 * (browser-manager.ts, connectionMode = 'headed') without a restart, so a daemon
 * that legitimately registered a watchdog is suddenly on the fatal side of the
 * branch. The parent is typically a short-lived shell — Claude Code's Bash tool
 * kills one after every invocation — so the next 15s poll shuts the daemon down,
 * discarding whatever the user was handed off to do, such as a login.
 *
 * Once promoted, the user owns the window lifecycle exactly as if the daemon had
 * been started headed, which is the case the env guards already exempt.
 *
 * A flag, NOT clearInterval: the tick doubles as the tunnel-orphan reaper
 * (its `tunnelActive` branch), and idle timeout is disabled in tunnel mode —
 * clearing the whole interval here left handoff → resume → /pair-agent with
 * an internet-exposed daemon nothing could ever reap. After promotion, parent
 * death no longer kills the daemon for BEING HEADED, but still kills it when
 * a tunnel is active.
 */
function suppressHeadedParentShutdown(): void {
  if (headedParentShutdownSuppressed) return;
  headedParentShutdownSuppressed = true;
  console.log('[browse] Parent-death headed shutdown suppressed (promoted to headed at runtime); watchdog stays armed as the tunnel-orphan reaper');
}

// ─── Command Sets (from commands.ts — single source of truth) ───
import { READ_COMMANDS, WRITE_COMMANDS, META_COMMANDS } from './commands';
export { READ_COMMANDS, WRITE_COMMANDS, META_COMMANDS };

/**
 * Whether an invocation should be treated as a WRITE for capability gating
 * (scope, watch-mode block, tab ownership, tunnel). A command is a write if it
 * mutates state (`WRITE_COMMANDS`) OR it carries an `--out` flag — `js`/`eval
 * --out` writes the evaluate result to local disk, so the capability is
 * per-invocation, not per-command-name. This deliberately does NOT change
 * dispatch routing: `js`/`eval` still route to `handleReadCommand`; only the
 * security gates consult this.
 */
function isWriteInvocation(command: string, args: string[]): boolean {
  return WRITE_COMMANDS.has(command) || hasOutArg(args);
}

// ─── Inspector State (in-memory) ──────────────────────────────
let inspectorData: InspectorResult | null = null;
let inspectorTimestamp: number = 0;

// Inspector SSE subscribers
type InspectorSubscriber = (event: any) => void;
const inspectorSubscribers = new Set<InspectorSubscriber>();

/** Diagnostic accessor used by the $B memory snapshot. */
export function getInspectorSubscriberCount(): number {
  return inspectorSubscribers.size;
}

function emitInspectorEvent(event: any): void {
  for (const notify of inspectorSubscribers) {
    queueMicrotask(() => {
      try { notify(event); } catch (err: any) {
        console.error('[browse] Inspector event subscriber threw:', err.message);
      }
    });
  }
}

// ─── Server ────────────────────────────────────────────────────
const browserManager = new BrowserManager();
// Declared here rather than beside suppressHeadedParentShutdown: that function
// sits with the watchdog it gates, which is above this line, and binding it up
// there would touch `browserManager` in its temporal dead zone — aborting
// module evaluation and leaving every later const uninitialized.
browserManager.onHeadedPromotion = suppressHeadedParentShutdown;
// Indirection for embedders. Module-level handlers (idleCheckTick, parent
// watchdog, SIGTERM) read activeBrowserManager so that buildFetchHandler can
// retarget them at a caller-supplied BrowserManager. Symmetric with the
// existing `let activeShutdown` pattern at module scope (line ~113).
// Without this, embedders like gbrowser hit the dead module-level instance
// whose connectionMode never leaves 'launched' — and headed mode never
// short-circuits idle-shutdown.
let activeBrowserManager: BrowserManager = browserManager;
// When the user closes the headed browser window, run full cleanup
// (kill terminal agent, save session, remove profile locks, delete state file)
// before exiting. Exit code 0 means user-initiated clean quit (Cmd+Q on
// macOS) so process supervisors like gbrowser's gbd skip the restart loop;
// 2 means a real crash that should respawn. The fallback `?? 2` preserves
// legacy crash semantics for any caller that invokes onDisconnect without
// an explicit code. This is the safety-net default for the CLI flow before
// any buildFetchHandler call rebinds onDisconnect onto the cfg instance.
browserManager.onDisconnect = (code) => activeShutdown?.(code ?? 2);
let isShuttingDown = false;
// Session-persist ticker handle. Registered in start() (module scope so the
// factory's shutdown() can reach it), cleared by shutdown() BEFORE the final
// snapshot — a tick landing during browser teardown would otherwise overwrite
// the good final snapshot with a degraded one (zero tabs).
let sessionPersistInterval: ReturnType<typeof setInterval> | null = null;

// Port allocation lives in port-allocator.ts (#2314, decision 8) so the
// terminal-agent shares the SAME fixed 10000-60000 scan range instead of
// binding port:0 into the OS ephemeral range. The imports at the top of
// this file re-expose the pieces __testInternals__ pins.

// Find port: explicit BROWSE_PORT, or random in 10000-60000
function findPort(): Promise<number> {
  return findAvailablePort(BROWSE_PORT);
}

/**
 * Translate Playwright errors into actionable messages for AI agents.
 */
function wrapError(err: any): string {
  const msg = err.message || String(err);
  // Timeout errors
  if (err.name === 'TimeoutError' || msg.includes('Timeout') || msg.includes('timeout')) {
    if (msg.includes('locator.click') || msg.includes('locator.fill') || msg.includes('locator.hover')) {
      return `Element not found or not interactable within timeout. Check your selector or run 'snapshot' for fresh refs.`;
    }
    if (msg.includes('page.goto') || msg.includes('Navigation')) {
      return `Page navigation timed out. The URL may be unreachable or the page may be loading slowly.`;
    }
    return `Operation timed out: ${msg.split('\n')[0]}`;
  }
  // Multiple elements matched
  if (msg.includes('resolved to') && msg.includes('elements')) {
    return `Selector matched multiple elements. Be more specific or use @refs from 'snapshot'.`;
  }
  // Pass through other errors
  return msg;
}

/** Internal command result — used by handleCommand and chain subcommand routing */
interface CommandResult {
  status: number;
  result: string;
  headers?: Record<string, string>;
  json?: boolean; // true if result is JSON (errors), false for text/plain
}

/**
 * Core command execution logic. Returns a structured result instead of HTTP Response.
 * Used by both the HTTP handler (handleCommand) and chain subcommand routing.
 *
 * Options:
 *   skipRateCheck: true when called from chain (chain counts as 1 request)
 *   skipActivity: true when called from chain (chain emits 1 event for all subcommands)
 *   chainDepth: recursion guard — reject nested chains (depth > 0 means inside a chain)
 */
async function handleCommandInternalImpl(
  body: { command: string; args?: string[]; tabId?: number },
  tokenInfo?: TokenInfo | null,
  opts?: { skipRateCheck?: boolean; skipActivity?: boolean; chainDepth?: number },
): Promise<CommandResult> {
  const { args = [], tabId } = body;
  const rawCommand = body.command;

  if (!rawCommand) {
    return { status: 400, result: JSON.stringify({ error: 'Missing "command" field' }), json: true };
  }

  // ─── Alias canonicalization (before scope, watch, tab-ownership, dispatch) ─
  // Agent-friendly names like 'setcontent' route to canonical 'load-html'. Must
  // happen BEFORE scope check so a read-scoped token calling 'setcontent' is still
  // rejected (load-html lives in SCOPE_WRITE). Audit logging preserves rawCommand
  // so the trail records what the agent actually typed.
  const command = canonicalizeCommand(rawCommand);
  const isAliased = command !== rawCommand;

  // ─── Recursion guard: reject nested chains ──────────────────
  if (command === 'chain' && (opts?.chainDepth ?? 0) > 0) {
    return { status: 400, result: JSON.stringify({ error: 'Nested chain commands are not allowed' }), json: true };
  }

  // ─── Scope check (for scoped tokens) ──────────────────────────
  if (tokenInfo && tokenInfo.clientId !== 'root') {
    if (!checkScope(tokenInfo, command)) {
      return {
        status: 403, json: true,
        result: JSON.stringify({
          error: `Command "${command}" not allowed by your token scope`,
          hint: `Your scopes: ${tokenInfo.scopes.join(', ')}. Ask the user to re-pair without --restrict for full page access, or with --control for browser control commands.`,
        }),
      };
    }

    // `--out` writes the evaluate result to local disk, which is a WRITE
    // capability distinct from the JS-exec (admin) capability js/eval need.
    // Require write scope so an admin-but-not-write token can't write files.
    if (hasOutArg(args) && !tokenInfo.scopes.includes('write')) {
      return {
        status: 403, json: true,
        result: JSON.stringify({
          error: `"--out" writes to disk and requires the "write" scope`,
          hint: `Your scopes: ${tokenInfo.scopes.join(', ')}. Re-pair with write access to use --out.`,
        }),
      };
    }

    // Domain check for navigation commands
    if ((command === 'goto' || command === 'newtab') && args[0]) {
      if (!checkDomain(tokenInfo, args[0])) {
        return {
          status: 403, json: true,
          result: JSON.stringify({
            error: `Domain not allowed by your token scope`,
            hint: `Allowed domains: ${tokenInfo.domains?.join(', ') || 'none configured'}`,
          }),
        };
      }
    }

    // Rate check (skipped for chain subcommands — chain counts as 1 request)
    if (!opts?.skipRateCheck) {
      const rateResult = checkRate(tokenInfo);
      if (!rateResult.allowed) {
        return {
          status: 429, json: true,
          result: JSON.stringify({
            error: 'Rate limit exceeded',
            hint: `Max ${tokenInfo.rateLimit} requests/second. Retry after ${rateResult.retryAfterMs}ms.`,
          }),
          headers: { 'Retry-After': String(Math.ceil((rateResult.retryAfterMs || 1000) / 1000)) },
        };
      }
    }

    // Record command execution for idempotent key exchange tracking
    if (!opts?.skipRateCheck && tokenInfo.token) recordCommand(tokenInfo.token);
  }

  // Pin to a specific tab if requested (set by BROWSE_TAB env var, e.g. per-tab agent contexts).
  // This prevents parallel agents from interfering with each other's tab context.
  // Safe because Bun's event loop is single-threaded — no concurrent handleCommand.
  let savedTabId: number | null = null;
  if (tabId !== undefined && tabId !== null) {
    savedTabId = browserManager.getActiveTabId();
    // bringToFront: false — internal tab pinning must NOT steal window focus
    try { browserManager.switchTab(tabId, { bringToFront: false }); } catch (err: any) {
      console.warn('[browse] Failed to pin tab', tabId, ':', err.message);
    }
  }

  // ─── Tab ownership check (own-only tokens / pair-agent isolation) ──
  //
  // Only `own-only` tokens (pair-agent over tunnel) are bound to their own
  // tabs. `shared` tokens — the default for skill spawns and local scoped
  // clients — can drive any tab; the capability gate (scope checks above)
  // and rate limits already constrain what they can do.
  //
  // Skip for `newtab` — it creates a tab rather than accessing one.
  if (command !== 'newtab' && tokenInfo && tokenInfo.clientId !== 'root' && tokenInfo.tabPolicy === 'own-only') {
    const targetTab = tabId ?? browserManager.getActiveTabId();
    if (!browserManager.checkTabAccess(targetTab, tokenInfo.clientId, { isWrite: isWriteInvocation(command, args), ownOnly: true })) {
      return {
        status: 403, json: true,
        result: JSON.stringify({
          error: 'Tab not owned by your agent. Use newtab to create your own tab.',
          hint: `Tab ${targetTab} is owned by ${browserManager.getTabOwner(targetTab) || 'root'}. Your agent: ${tokenInfo.clientId}.`,
        }),
      };
    }
  }

  // ─── newtab with ownership for scoped tokens ──────────────
  if (command === 'newtab' && tokenInfo && tokenInfo.clientId !== 'root') {
    const newId = await browserManager.newTab(args[0] || undefined, tokenInfo.clientId);
    return {
      status: 200, json: true,
      result: JSON.stringify({
        tabId: newId,
        owner: tokenInfo.clientId,
        hint: 'Include "tabId": ' + newId + ' in subsequent commands to target this tab.',
      }),
    };
  }

  // Block mutation commands while watching (read-only observation mode).
  // `--out` invocations count as mutations (they write the result to disk).
  if (browserManager.isWatching() && isWriteInvocation(command, args)) {
    return {
      status: 400, json: true,
      result: JSON.stringify({ error: 'Cannot run mutation commands while watching. Run `$B watch stop` first.' }),
    };
  }

  // Activity: emit command_start (skipped for chain subcommands)
  const startTime = Date.now();
  if (!opts?.skipActivity) {
    emitActivity({
      type: 'command_start',
      command,
      args,
      url: browserManager.getCurrentUrl(),
      tabs: browserManager.getTabCount(),
      mode: browserManager.getConnectionMode(),
      clientId: tokenInfo?.clientId,
    });
  }

  try {
    let result: string;

    const session = browserManager.getActiveSession();

    // Per-request warnings collected during hidden-element detection,
    // surfaced into the envelope the LLM sees. Carries across the read
    // phase into the centralized wrap block below.
    let hiddenContentWarnings: string[] = [];

    if (READ_COMMANDS.has(command)) {
      const isScoped = tokenInfo && tokenInfo.clientId !== 'root';
      // Hidden-element / ARIA-injection detection for every scoped
      // DOM-reading channel (text, html, links, forms, accessibility,
      // attrs, data, media, ux-audit). Previously only `text` received
      // stripping; other channels let hidden injection payloads reach
      // the LLM despite the envelope wrap. Detections become CONTENT
      // WARNINGS on the outgoing envelope so the model can see what it
      // would have otherwise trusted silently.
      if (isScoped && DOM_CONTENT_COMMANDS.has(command)) {
        const page = session.getPage();
        try {
          const strippedDescs = await markHiddenElements(page);
          if (strippedDescs.length > 0) {
            console.warn(`[browse] Content security: ${strippedDescs.length} hidden elements flagged on ${command} for ${tokenInfo.clientId}`);
            hiddenContentWarnings = strippedDescs.slice(0, 8).map(d =>
              `hidden content: ${d.slice(0, 120)}`,
            );
            if (strippedDescs.length > 8) {
              hiddenContentWarnings.push(`hidden content: +${strippedDescs.length - 8} more flagged elements`);
            }
          }
          if (command === 'text') {
            const target = session.getActiveFrameOrPage();
            result = await getCleanTextWithStripping(target);
          } else {
            result = await handleReadCommand(command, args, session, browserManager);
          }
        } finally {
          await cleanupHiddenMarkers(page);
        }
      } else {
        result = await handleReadCommand(command, args, session, browserManager);
      }
    } else if (WRITE_COMMANDS.has(command)) {
      result = await handleWriteCommand(command, args, session, browserManager);
    } else if (META_COMMANDS.has(command)) {
      // Pass chain depth + executeCommand callback so chain routes subcommands
      // through the full security pipeline (scope, domain, tab, wrapping).
      const chainDepth = (opts?.chainDepth ?? 0);
      // shutdown is factory-scoped (deleted from module scope in v1.35.0.0);
      // route the call through activeShutdown which buildFetchHandler assigns.
      const shutdownFn = () => activeShutdown ? activeShutdown() : Promise.resolve();
      result = await handleMetaCommand(command, args, browserManager, shutdownFn, tokenInfo, {
        chainDepth,
        daemonPort: LOCAL_LISTEN_PORT,
        executeCommand: (body, ti) => handleCommandInternal(body, ti, {
          skipRateCheck: true,    // chain counts as 1 request
          skipActivity: true,     // chain emits 1 event for all subcommands
          chainDepth: chainDepth + 1,  // recursion guard
        }),
      });
      // Start periodic snapshot interval when watch mode begins
      if (command === 'watch' && args[0] !== 'stop' && browserManager.isWatching()) {
        const watchInterval = setInterval(async () => {
          if (!browserManager.isWatching()) {
            clearInterval(watchInterval);
            return;
          }
          try {
            const snapshot = await handleSnapshot(['-i'], browserManager.getActiveSession());
            browserManager.addWatchSnapshot(snapshot);
          } catch {
            // Page may be navigating — skip this snapshot
          }
        }, 5000);
        browserManager.watchInterval = watchInterval;
      }
    } else if (command === 'help') {
      const helpText = generateHelpText();
      return { status: 200, result: helpText };
    } else {
      // Use the rich unknown-command helper: names the input, suggests the closest
      // match via Levenshtein (≤ 2 distance, ≥ 4 chars input), and appends an upgrade
      // hint if the command is listed in NEW_IN_VERSION.
      return {
        status: 400, json: true,
        result: JSON.stringify({
          error: buildUnknownCommandError(rawCommand, ALL_COMMANDS),
          hint: `Available commands: ${[...READ_COMMANDS, ...WRITE_COMMANDS, ...META_COMMANDS].sort().join(', ')}`,
        }),
      };
    }

    // ─── Centralized content wrapping (single location for all commands) ───
    // Scoped tokens: content filter + enhanced envelope + datamarking
    // Root tokens: basic untrusted content wrapper (backward compat)
    // Chain exempt from top-level wrapping (each subcommand wrapped individually)
    if (PAGE_CONTENT_COMMANDS.has(command) && command !== 'chain') {
      const isScoped = tokenInfo && tokenInfo.clientId !== 'root';
      if (isScoped) {
        // Run content filters
        const filterResult: ContentFilterResult = runContentFilters(
          result, browserManager.getCurrentUrl(), command,
        );
        if (filterResult.blocked) {
          return { status: 403, json: true, result: JSON.stringify({ error: filterResult.message }) };
        }
        // Datamark text command output only (not html, forms, or structured data)
        if (command === 'text') {
          result = datamarkContent(result);
        }
        // Enhanced envelope wrapping for scoped tokens.
        // Merge per-request hidden-element warnings with content-filter
        // warnings so both reach the LLM through the same CONTENT
        // WARNINGS header.
        const combinedWarnings = [...filterResult.warnings, ...hiddenContentWarnings];
        result = wrapUntrustedPageContent(
          result, command,
          combinedWarnings.length > 0 ? combinedWarnings : undefined,
        );
      } else {
        // Root token: basic wrapping (backward compat, Decision 2)
        result = wrapUntrustedContent(result, browserManager.getCurrentUrl());
      }
    }

    // Activity: emit command_end (skipped for chain subcommands)
    const successDuration = Date.now() - startTime;
    if (!opts?.skipActivity) {
      emitActivity({
        type: 'command_end',
        command,
        args,
        url: browserManager.getCurrentUrl(),
        duration: successDuration,
        status: 'ok',
        result: result,
        tabs: browserManager.getTabCount(),
        mode: browserManager.getConnectionMode(),
        clientId: tokenInfo?.clientId,
      });
    }

    writeAuditEntry({
      ts: new Date().toISOString(),
      cmd: command,
      aliasOf: isAliased ? rawCommand : undefined,
      args: args.join(' '),
      origin: browserManager.getCurrentUrl(),
      durationMs: successDuration,
      status: 'ok',
      hasCookies: browserManager.hasCookieImports(),
      mode: browserManager.getConnectionMode(),
    });

    browserManager.resetFailures();
    // Restore original active tab if we pinned to a specific one
    if (savedTabId !== null) {
      try { browserManager.switchTab(savedTabId, { bringToFront: false }); } catch (restoreErr: any) {
        console.warn('[browse] Failed to restore tab after command:', restoreErr.message);
      }
    }
    return { status: 200, result };
  } catch (err: any) {
    // Restore original active tab even on error
    if (savedTabId !== null) {
      try { browserManager.switchTab(savedTabId, { bringToFront: false }); } catch (restoreErr: any) {
        console.warn('[browse] Failed to restore tab after error:', restoreErr.message);
      }
    }

    // Activity: emit command_end (error) — skipped for chain subcommands
    const errorDuration = Date.now() - startTime;
    if (!opts?.skipActivity) {
      emitActivity({
        type: 'command_end',
        command,
        args,
        url: browserManager.getCurrentUrl(),
        duration: errorDuration,
        status: 'error',
        error: err.message,
        tabs: browserManager.getTabCount(),
        mode: browserManager.getConnectionMode(),
        clientId: tokenInfo?.clientId,
      });
    }

    writeAuditEntry({
      ts: new Date().toISOString(),
      cmd: command,
      aliasOf: isAliased ? rawCommand : undefined,
      args: args.join(' '),
      origin: browserManager.getCurrentUrl(),
      durationMs: errorDuration,
      status: 'error',
      error: err.message,
      hasCookies: browserManager.hasCookieImports(),
      mode: browserManager.getConnectionMode(),
    });

    browserManager.incrementFailures();
    let errorMsg = wrapError(err);
    const hint = browserManager.getFailureHint();
    if (hint) errorMsg += '\n' + hint;
    return { status: 500, result: JSON.stringify({ error: errorMsg }), json: true };
  }
}

/**
 * Sanitizing wrapper around handleCommandInternalImpl. ALL callers (single-command
 * HTTP, batch loop, scoped-token dispatch) go through this so the lone-surrogate
 * sanitization happens once at the architectural choke point, not per-leaf.
 * Do not bypass this by calling handleCommandInternalImpl directly.
 */
async function handleCommandInternal(
  body: { command: string; args?: string[]; tabId?: number },
  tokenInfo?: TokenInfo | null,
  opts?: { skipRateCheck?: boolean; skipActivity?: boolean; chainDepth?: number },
): Promise<CommandResult> {
  const cr = await handleCommandInternalImpl(body, tokenInfo, opts);
  return { ...cr, result: stripLoneSurrogates(cr.result) };
}

/**
 * Build the HTTP response from a CommandResult. Pure function so it can be
 * unit-tested without spinning up the server (#1440). Defense in depth on top
 * of handleCommandInternal's choke-point sanitization: this catches any
 * \uXXXX JSON-escape surrogate forms that the raw-codepoint regex above
 * misses when the body has already been JSON-stringified.
 */
export function buildCommandResponse(cr: CommandResult): Response {
  const contentType = cr.json ? 'application/json' : 'text/plain';
  const safeBody = typeof cr.result === 'string' ? sanitizeBody(cr.result, !!cr.json) : cr.result;
  return new Response(safeBody, {
    status: cr.status,
    headers: { 'Content-Type': contentType, ...cr.headers },
  });
}

/** HTTP wrapper — converts CommandResult to Response. Used by the /command
 * route dispatcher (line ~2158). The wrapper layer exists so
 * `buildCommandResponse` is independently unit-testable (v1.38.1.0).
 */
async function handleCommand(body: any, tokenInfo?: TokenInfo | null): Promise<Response> {
  const cr = await handleCommandInternal(body, tokenInfo);
  return buildCommandResponse(cr);
}

// Module-level shutdown function deleted in v1.39.0.0; it now lives inside
// the buildFetchHandler closure so it closes the cfg-provided browserManager.
// Signal handlers below call activeShutdown which buildFetchHandler assigns.

// Handle signals
//
// Node passes the signal name (e.g. 'SIGTERM') as the first arg to listeners.
// Wrap calls so activeShutdown receives no args — otherwise the string gets
// passed as exitCode and process.exit() coerces it to NaN, exiting with code 1
// instead of 0. (Caught in v0.18.1.0 #1025.)
//
// Gated on `import.meta.main` so embedders (gbrowser phoenix) that import
// server.ts as a submodule can register their own signal handlers without
// fighting with gstack's. CLI path is unchanged.
if (import.meta.main) {
  // Standalone daemon: a Chromium crash must exit THIS process (its
  // supervisor/user notices); embedders and in-process test launches must
  // never be exited by browser-manager's disconnect handler.
  markDaemonProcess();
  // SIGINT (Ctrl+C): user intentionally stopping → shutdown.
  process.on('SIGINT', () => activeShutdown?.());
  // SIGHUP (terminal hangup): with handleSIGHUP:false at the three launch
  // sites (#2220), Playwright no longer closes Chromium when this process
  // gets hung up on — this handler is now the ONLY Chromium cleanup on
  // SIGHUP (ENG-OV4). Route to the same shutdown path as SIGINT:
  // activeShutdown closes the browser, releases ports, and removes the
  // state file. Without it, a hangup would leak a live Chromium.
  process.on('SIGHUP', () => activeShutdown?.());
  // SIGTERM behavior depends on mode:
  // - Normal (headless) mode: Claude Code's Bash sandbox fires SIGTERM when the
  //   parent shell exits between tool invocations. Ignoring it keeps the server
  //   alive across $B calls. Idle timeout (30 min) handles eventual cleanup.
  // - Headed / tunnel mode: idle timeout doesn't apply in these modes. Respect
  //   SIGTERM so external tooling (systemd, supervisord, CI) can shut cleanly
  //   without waiting forever. Ctrl+C and /stop still work either way.
  // - Active cookie picker: never tear down mid-import regardless of mode —
  //   would strand the picker UI with "Failed to fetch."
  process.on('SIGTERM', () => {
    if (hasActivePicker()) {
      console.log('[browse] Received SIGTERM but cookie picker is active, ignoring to avoid stranding the picker UI');
      return;
    }
    const headed = activeBrowserManager.getConnectionMode() === 'headed';
    if (headed || tunnelActive) {
      console.log(`[browse] Received SIGTERM in ${headed ? 'headed' : 'tunnel'} mode, shutting down`);
      activeShutdown?.();
    } else {
      console.log('[browse] Received SIGTERM (ignoring — use /stop or Ctrl+C for intentional shutdown)');
    }
  });
  // Windows: taskkill /F bypasses SIGTERM, but 'exit' fires for some shutdown paths.
  // Defense-in-depth — primary cleanup is the CLI's stale-state detection via health check.
  if (process.platform === 'win32') {
    process.on('exit', () => {
      safeUnlinkQuiet(config.stateFile);
    });
  }
}

// Emergency cleanup for crashes (OOM, uncaught exceptions, browser disconnect)
function emergencyCleanup() {
  if (isShuttingDown) return;
  isShuttingDown = true;
  // Xvfb cleanup MUST happen before state-file deletion. spawnXvfb detaches
  // the child, so without this, an uncaught exception leaves the Xvfb
  // running with no PID record — orphan accumulates and eventually
  // exhausts the :99-:120 display range. Read the state file FIRST,
  // call cleanupXvfb (validates cmdline + start-time before kill), THEN
  // delete the state file.
  try {
    if (fs.existsSync(config.stateFile)) {
      const raw = fs.readFileSync(config.stateFile, 'utf-8');
      const state = JSON.parse(raw);
      if (state.xvfbPid && state.xvfbStartTime) {
        // Lazy import — emergencyCleanup may run on platforms where
        // ./xvfb's Linux-specific helpers fail to load. Best effort.
        try {
          const { cleanupXvfb } = require('./xvfb');
          cleanupXvfb({
            pid: state.xvfbPid,
            startTime: state.xvfbStartTime,
            display: state.xvfbDisplay || ':99',
          });
        } catch { /* best effort */ }
      }
    }
  } catch { /* state file unparseable — fall through to lock + state cleanup */ }

  // Clean Chromium profile locks via the shared helper (defensive guard
  // refuses to operate on unrecognized profile dirs).
  cleanSingletonLocks(resolveChromiumProfile());
  safeUnlinkQuiet(config.stateFile);
}
// Same import.meta.main gate as SIGINT/SIGTERM — embedders register their
// own crash handlers.
if (import.meta.main) {
  process.on('uncaughtException', (err) => {
    console.error('[browse] FATAL uncaught exception:', err.message);
    emergencyCleanup();
    process.exit(1);
  });
  process.on('unhandledRejection', (err: any) => {
    console.error('[browse] FATAL unhandled rejection:', err?.message || err);
    emergencyCleanup();
    process.exit(1);
  });
}

// ─── Start ─────────────────────────────────────────────────────
/**
 * Entry point for `bun run dev` and the compiled binary.
 *
 * Exported so embedders (gbrowser phoenix overlay) can call it
 * directly with env vars set, bypassing the module-level `import.meta.main`
 * gate. Phoenix's eventual fd-passing path will use `buildFetchHandler`
 * directly; until that lands, calling `start()` from a non-main entry is
 * supported via env (AUTH_TOKEN, BROWSE_PORT, BROWSE_OWN_SIGNALS).
 */
/**
 * Build a request handler set for the browse daemon. Embedders (gbrowser
 * phoenix overlay) call this directly with their own cfg to compose overlay
 * routes via cfg.beforeRoute, pass a pre-launched cfg.browserManager, and
 * opt out of terminal-agent teardown via cfg.ownsTerminalAgent (default
 * true, set to false when the embedder runs its own PTY server). The CLI
 * path calls this through start() with env-derived defaults and explicit
 * cfg.ownsTerminalAgent: true — externally-observable behavior is identical.
 *
 * Auth state lives ENTIRELY inside the factory closure: cfg.authToken is the
 * single source of truth for the bearer secret, factory-scoped validateAuth
 * closes over it, and factory-scoped shutdown closes the cfg-provided
 * browserManager. Module-level lifecycle singletons (LOCAL_LISTEN_PORT,
 * tunnelActive, inspector state) intentionally STAY at module scope; see
 * the v1.35.0.0 CHANGELOG entry for the architectural rationale.
 *
 * The returned ServerHandle is callable directly. Bun.serve is the caller's
 * responsibility — embedders may fd-pass; CLI uses Bun.serve normally.
 */
export function buildFetchHandler(cfg: ServerConfig): ServerHandle {
  if (!cfg.authToken || cfg.authToken.length < 16) {
    throw new Error('buildFetchHandler: cfg.authToken must be a non-empty string >= 16 chars');
  }
  if (!cfg.browserManager) {
    throw new Error('buildFetchHandler: cfg.browserManager is required');
  }

  // Re-run init with cfg-provided values. ensureStateDir is idempotent
  // (mkdir -p); initAuditLog is idempotent (sets a module string);
  // initRegistry is idempotent for same-token, throws for different-token.
  // Owning init here (instead of at module load) means cfg.authToken is the
  // single source of truth for the registry root token.
  ensureStateDir(cfg.config);
  initAuditLog(cfg.config.auditLog);
  initRegistry(cfg.authToken);

  const { authToken, browserManager: cfgBrowserManager, startTime, beforeRoute, browsePort } = cfg;
  // Strict opt-out: only explicit `false` flips the gate. Any other value
  // (undefined, truthy non-bool from a JS caller bypassing TS, etc.) defaults
  // to gstack-owns. Matches the "default-true preserves CLI bit-for-bit"
  // premise even under malformed cfg.
  const ownsTerminalAgent = cfg.ownsTerminalAgent === false ? false : true;

  // ─── Terminal-Agent Watchdog (v1.44+) ─────────────────────────────
  //
  // The terminal-agent process can die independently of the server: SIGKILL
  // from the OS OOM killer, an uncaught exception under load, an external
  // `pkill` from a sibling debugging session. Pre-v1.44 the sidebar would
  // see the broken connection and stay broken until the user reloaded.
  // Now: 60s ticker checks the recorded agent PID, respawns via the shared
  // spawnTerminalAgent helper if dead.
  //
  // Identity-based — uses readAgentRecord + isProcessAlive, NOT a process
  // name probe. Critical: prevents respawning around a slow-but-alive agent
  // (which would create split-brain — two agents writing the port file,
  // tokens diverging between them, mystery PTY upgrade failures).
  //
  // Crash-loop guard: 3 respawn attempts inside 60s → stop trying and emit
  // a one-line error. Manual `forceRestart` from the sidebar clears the
  // history (the user is the explicit signal to retry).
  //
  // Only active when ownsTerminalAgent === true. Embedders that pre-launch
  // their own PTY server (gbrowser phoenix overlay) must not be auto-respawned
  // by us — their lifecycle is their concern.
  let agentWatchdogInterval: ReturnType<typeof setInterval> | null = null;
  const respawnHistory: number[] = [];
  const AGENT_WATCHDOG_TICK_MS = parseInt(
    process.env.GSTACK_AGENT_WATCHDOG_TICK_MS || '60000',
    10,
  );
  const RESPAWN_GUARD_MAX = 3;
  // The guard window MUST span enough ticks for RESPAWN_GUARD_MAX respawns to
  // land inside it. This was a fixed 60_000 against a 60_000 tick, so at most
  // ONE respawn could ever be in the window and `respawnHistory.length >= 3`
  // was unreachable — the guard could not fire at the default tick rate, and a
  // steady one-per-tick leak ran unbounded instead of stopping after 3. Scale
  // with the tick so the intent ("3 crashes in quick succession → stop") holds
  // at any tick value: 3 respawns within 5 ticks trips it.
  const RESPAWN_GUARD_WINDOW_MS = Math.max(
    60_000,
    AGENT_WATCHDOG_TICK_MS * (RESPAWN_GUARD_MAX + 2),
  );
  let agentRespawnGuardTripped = false;

  if (ownsTerminalAgent) {
    agentWatchdogInterval = setInterval(() => {
      if (isShuttingDown) return;
      if (agentRespawnGuardTripped) return;
      const stateDir = path.dirname(cfg.config.stateFile);
      const record = readAgentRecord(stateDir);
      // If the record exists and the PID is alive, the agent is healthy
      // (or at least still answering signal 0). Slow-but-alive agents
      // intentionally fall through here — split-brain is worse than
      // unresponsiveness, and slow recovery is handled by the user via
      // restart.
      if (record && isProcessAlive(record.pid)) return;
      // Either no record (never spawned, or cleaned up after crash) or
      // PID is dead. Try to respawn.
      const now = Date.now();
      while (respawnHistory.length && now - respawnHistory[0] > RESPAWN_GUARD_WINDOW_MS) {
        respawnHistory.shift();
      }
      if (respawnHistory.length >= RESPAWN_GUARD_MAX) {
        agentRespawnGuardTripped = true;
        console.error(
          `[browse] terminal-agent respawn guard tripped (${RESPAWN_GUARD_MAX} crashes in ${RESPAWN_GUARD_WINDOW_MS / 1000}s) — manual restart required`,
        );
        return;
      }
      respawnHistory.push(now);
      try {
        const pid = spawnTerminalAgent({
          stateFile: cfg.config.stateFile,
          serverPort: cfg.browsePort,
          ownerPid: process.pid,
          cwd: cfg.config.projectDir,
        });
        if (pid) {
          console.log(`[browse] terminal-agent respawned by watchdog (PID: ${pid})`);
        } else {
          console.warn('[browse] terminal-agent respawn skipped — script not found on disk');
        }
      } catch (err: any) {
        console.warn('[browse] terminal-agent respawn failed:', err?.message || err);
      }
    }, AGENT_WATCHDOG_TICK_MS);
    // Detach the watchdog timer from Node's event-loop ref count so a
    // healthy idle process can still exit cleanly if everything else is
    // also unref'd. Bun's setInterval returns a Timer with unref().
    (agentWatchdogInterval as any)?.unref?.();
  }

  // Factory-scoped validateAuth. Closes over cfg.authToken so every internal
  // auth check sees the same token the routes receive. Module-level
  // validateAuth was deleted in v1.35.0.0.
  function validateAuth(req: Request): boolean {
    const header = req.headers.get('authorization');
    if (header === null) return false;
    // Constant-time compare so a byte-by-byte early-exit can't leak the token
    // prefix via response timing. timingSafeEqual requires equal-length inputs,
    // so the length check gates it (the length itself is not secret).
    const got = Buffer.from(header);
    const want = Buffer.from(`Bearer ${authToken}`);
    return got.length === want.length && crypto.timingSafeEqual(got, want);
  }

  // Factory-scoped shutdown. Closes the cfg-provided browserManager so
  // embedders that pass their own BrowserManager get correct teardown.
  // Module-level shutdown was deleted in v1.35.0.0.
  async function shutdown(exitCode: number = 0) {
    if (isShuttingDown) return;
    isShuttingDown = true;

    console.log('[browse] Shutting down...');
    if (ownsTerminalAgent) {
      // Identity-based kill (v1.44+). Replaces the v1.43- `pkill -f
      // terminal-agent\.ts` regex teardown which matched sibling gstack
      // sessions on the same host. Only the PID recorded in
      // `<stateDir>/terminal-agent-pid` by THIS daemon's agent is signaled.
      try {
        const stateDir = path.dirname(config.stateFile);
        const record = readAgentRecord(stateDir);
        if (record) killAgentByRecord(record, 'SIGTERM');
      } catch (err: any) {
        console.warn('[browse] Failed to kill terminal-agent:', err.message);
      }
      safeUnlinkQuiet(path.join(path.dirname(config.stateFile), 'terminal-port'));
      safeUnlinkQuiet(path.join(path.dirname(config.stateFile), 'terminal-internal-token'));
      safeUnlinkQuiet(agentRecordPath(path.dirname(config.stateFile)));
    }
    try { detachSession(); } catch (err: any) {
      console.warn('[browse] Failed to detach CDP session:', err.message);
    }
    inspectorSubscribers.clear();
    if (cfgBrowserManager.isWatching()) cfgBrowserManager.stopWatch();
    clearInterval(flushInterval);
    clearInterval(idleCheckInterval);
    if (agentWatchdogInterval) clearInterval(agentWatchdogInterval);
    // Stop the session-persist ticker BEFORE the final snapshot below —
    // paired with the isShuttingDown gate inside the tick, this guarantees
    // no interval snapshot can race the final one during teardown.
    if (sessionPersistInterval) {
      clearInterval(sessionPersistInterval);
      sessionPersistInterval = null;
    }
    await flushBuffers();

    // Final session snapshot before the browser goes away (#778). Best
    // effort with a hard 2s deadline: shutdown must never hang on a wedged
    // page.evaluate — after the deadline we proceed to browser close and let
    // the previous interval snapshot stand (atomic writes guarantee it's
    // intact). The .catch is attached to the persist promise itself so a
    // late rejection after losing the race can't become an unhandled
    // rejection.
    if (isSessionPersistEnabled()) {
      const finalSnapshot = persistSessionState(cfgBrowserManager, path.join(config.stateDir, SESSION_STATE_FILE))
        .catch((err: any) => {
          console.warn(`[browse] SESSION_PERSIST_FAILED at shutdown: ${err?.message ?? err}`);
        });
      await Promise.race([
        finalSnapshot,
        new Promise<void>((resolve) => setTimeout(resolve, 2_000)),
      ]);
    }

    await cfgBrowserManager.close();

    cleanSingletonLocks(resolveChromiumProfile());
    safeUnlinkQuiet(config.stateFile);
    process.exit(exitCode);
  }

  // Named lifecycle helper (matches closeTunnel style). Logs failures so
  // future debugging isn't blind to a stuck listener.
  async function stopListeners(local: any, tunnel?: any) {
    try { if (local?.stop) local.stop(true); }
    catch (err: any) { console.warn('[browse] local listener stop failed:', err?.message || err); }
    try { if (tunnel?.stop) tunnel.stop(true); }
    catch (err: any) { console.warn('[browse] tunnel listener stop failed:', err?.message || err); }
  }

  // Register this handle's shutdown as the active one. Module-level
  // handlers (idleCheckInterval, parent watchdog, onDisconnect, signal
  // handlers) call activeShutdown so they reach THIS shutdown, not a stale
  // module reference. Critical for embedders whose cfg.browserManager
  // differs from the module-level instance.
  activeShutdown = shutdown;

  // Retarget the BrowserManager indirection at the cfg-instance so the
  // module-level idleCheckTick + parent watchdog + SIGTERM handler all read
  // the right connectionMode. Without this, headed embedders auto-shutdown
  // after 30 min of HTTP idle because the dead module-level instance still
  // reports connectionMode === 'launched'.
  activeBrowserManager = cfgBrowserManager;
  // Same reason as above: the watchdog reads activeBrowserManager, so the
  // instance that can promote itself to headed must be the one that can
  // suppress the headed parent-death branch. An embedder-supplied manager
  // otherwise promotes silently and the watchdog keeps shutting down on a
  // promotion it can no longer see.
  cfgBrowserManager.onHeadedPromotion = suppressHeadedParentShutdown;

  // Wire the cfg-instance's onDisconnect to run shutdown when the user
  // closes the headed browser window. CHAIN any caller-provided handler
  // instead of overwriting it: gbrowser may have set its own onDisconnect
  // before calling buildFetchHandler (e.g. for snapshot/log work that needs
  // to run before the process exits). Caller errors are logged but never
  // block gstack shutdown — defensive symmetry with the safeUnlinkQuiet /
  // safeKill philosophy in error-handling.ts.
  const callerOnDisconnect = cfgBrowserManager.onDisconnect;
  cfgBrowserManager.onDisconnect = async (code) => {
    if (callerOnDisconnect) {
      try { await callerOnDisconnect(code); }
      catch (err: any) {
        console.warn('[browse] caller onDisconnect threw:', err?.message ?? err);
      }
    }
    await activeShutdown?.(code ?? 2);
  };

  // Substitute cfgBrowserManager for module-level browserManager in the
  // dispatcher body so all browser-state reads/writes go through the cfg
  // instance. Other module-level references (handleCommand, getTokenInfo,
  // isRootRequest, etc.) take the token as a parameter and are passed
  // `authToken` (the cfg-derived value) explicitly.
  const browserManager = cfgBrowserManager;


  const makeFetchHandler = (surface: Surface) => async (req: Request): Promise<Response> => {
    const url = new URL(req.url);

    // ─── Tunnel surface filter (runs before any route dispatch) ──
    if (surface === 'tunnel') {
      const isGetConnect = req.method === 'GET' && url.pathname === '/connect';
      const allowed = TUNNEL_PATHS.has(url.pathname);
      if (!allowed && !isGetConnect) {
        logTunnelDenial(req, url, 'path_not_on_tunnel');
        return new Response(JSON.stringify({ error: 'Not found' }), {
          status: 404, headers: { 'Content-Type': 'application/json' },
        });
      }
      if (isRootRequest(req)) {
        logTunnelDenial(req, url, 'root_token_on_tunnel');
        return new Response(JSON.stringify({
          error: 'Root token rejected on tunnel surface',
          hint: 'Remote agents must pair via /connect to receive a scoped token.',
        }), { status: 403, headers: { 'Content-Type': 'application/json' } });
      }
      if (url.pathname !== '/connect' && !getTokenInfo(req)) {
        logTunnelDenial(req, url, 'missing_scoped_token');
        return new Response(JSON.stringify({ error: 'Unauthorized' }), {
          status: 401, headers: { 'Content-Type': 'application/json' },
        });
      }
    }

    // beforeRoute overlay hook (v1.35.0.0). Runs AFTER the tunnel surface
    // filter and BEFORE per-route dispatch. Pre-resolves bearer auth once
    // so the hook receives TokenInfo | null. Note: getTokenInfo returns null
    // for both missing AND invalid bearer — see the ServerConfig.beforeRoute
    // JSDoc for the security implications.
    if (beforeRoute) {
      const auth = getTokenInfo(req);
      const overlayResp = await beforeRoute(req, surface, auth);
      if (overlayResp) return overlayResp;
    }

    // GET /connect — alive probe.  Unauth on both surfaces.  Used by /pair
    // and /tunnel/start to detect dead ngrok tunnels via the tunnel URL,
    // since /health is not tunnel-reachable under the dual-listener design.
    //
    // Shares the same rate limit as POST /connect — otherwise a tunnel
    // caller can probe unlimited GETs and lock out nothing, which makes
    // the endpoint a free daemon-enumeration surface.
    if (url.pathname === '/connect' && req.method === 'GET') {
      if (!checkConnectRateLimit()) {
        return new Response(JSON.stringify({ error: 'Rate limited' }), {
          status: 429, headers: { 'Content-Type': 'application/json' },
        });
      }
      return new Response(JSON.stringify({ alive: true }), {
        status: 200, headers: { 'Content-Type': 'application/json' },
      });
    }

      // Cookie picker routes — HTML page unauthenticated, data/action routes require auth
      if (url.pathname.startsWith('/cookie-picker')) {
        return handleCookiePickerRoute(url, req, browserManager, authToken);
      }

      // Welcome page — served when GStack Browser launches in headed mode
      if (url.pathname === '/welcome') {
        const welcomePath = (() => {
          // Gate GSTACK_SLUG on a strict regex BEFORE interpolating it into
          // the filesystem path. Without this, a slug like "../../etc/passwd"
          // would resolve to ~/.gstack/projects/../../etc/passwd/... — path
          // traversal.  Not exploitable today (attacker needs local env-var
          // access), but the gate is one regex and buys us defense-in-depth.
          const rawSlug = process.env.GSTACK_SLUG || 'unknown';
          const slug = /^[a-z0-9_-]+$/.test(rawSlug) ? rawSlug : 'unknown';
          const homeDir = process.env.HOME || process.env.USERPROFILE || '/tmp';
          const projectWelcome = `${homeDir}/.gstack/projects/${slug}/designs/welcome-page-20260331/finalized.html`;
          if (fs.existsSync(projectWelcome)) return projectWelcome;
          // Fallback: built-in welcome page from gstack install.  Reject
          // SKILL_ROOT values containing '..' for the same defense-in-depth
          // reason as the GSTACK_SLUG regex above.  Not exploitable today
          // (env set at install time), but the gate is one check.
          const rawSkillRoot = process.env.GSTACK_SKILL_ROOT || `${homeDir}/.claude/skills/gstack`;
          if (rawSkillRoot.includes('..')) return null;
          const builtinWelcome = `${rawSkillRoot}/browse/src/welcome.html`;
          if (fs.existsSync(builtinWelcome)) return builtinWelcome;
          return null;
        })();
        if (welcomePath) {
          try {
            const html = require('fs').readFileSync(welcomePath, 'utf-8');
            return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
          } catch (err: any) {
            console.error('[browse] Failed to read welcome page:', welcomePath, err.message);
          }
        }
        // No welcome page found — serve a simple fallback (avoid ERR_UNSAFE_REDIRECT on Windows)
        return new Response(
          `<!DOCTYPE html><html><head><title>GStack Browser</title>
          <style>body{background:#111;color:#fff;font-family:system-ui;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;}
          .msg{text-align:center;opacity:.7;}.gold{color:#f5a623;font-size:2em;margin-bottom:12px;}</style></head>
          <body><div class="msg"><div class="gold">◈</div><p>GStack Browser ready.</p><p style="font-size:.85em">Waiting for commands from Claude Code.</p></div></body></html>`,
          { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8' } }
        );
      }

      // ─── POST /extension-token — pinned-origin token bootstrap ──────
      //
      // The ONLY endpoint that hands out AUTH_TOKEN. GET /health used to
      // carry the token (headed mode + any chrome-extension:// Origin),
      // which meant ANY extension — or any localhost caller in headed
      // mode — could read the root token. Now the token is released only
      // to the one extension identity we ship: the Origin header must be
      // exactly `chrome-extension://<GSTACK_EXTENSION_ID>`, where the ID
      // is pinned by the "key" field in extension/manifest.json (derive
      // it with `bun browse/scripts/extension-id.ts`). Chrome sets Origin
      // on cross-origin POSTs from extension contexts and web pages
      // cannot forge a chrome-extension:// Origin.
      //
      // Local listener only: NEVER added to TUNNEL_PATHS, so the tunnel
      // surface 404s it by default-deny.
      if (url.pathname === '/extension-token' && req.method === 'POST') {
        // Defense-in-depth alongside the 127.0.0.1 bind: a DNS-rebinding
        // page can't present a localhost Host header. Host arrives as
        // '127.0.0.1:34567', so parse out the hostname — never compare
        // the raw header (which carries the port) against a literal.
        let hostname: string | null = null;
        try {
          hostname = new URL(`http://${req.headers.get('host') ?? ''}`).hostname;
        } catch (err) {
          if (!(err instanceof TypeError)) throw err;  // TypeError = malformed Host
        }
        const originOk =
          req.headers.get('origin') === `chrome-extension://${GSTACK_EXTENSION_ID}`;
        const hostOk = hostname === '127.0.0.1' || hostname === 'localhost';
        if (!originOk || !hostOk) {
          // No detail in the body — don't teach a probing caller which
          // check failed.
          return new Response(JSON.stringify({ error: 'Forbidden' }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        return new Response(JSON.stringify({ token: authToken }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // Health check — no auth required, does NOT reset idle timer.
      // NEVER carries a token in any mode: token bootstrap is
      // POST /extension-token (pinned extension Origin) and shell auth
      // is POST /pty-session. Liveness/status only.
      if (url.pathname === '/health') {
        const healthy = await browserManager.isHealthy();
        return new Response(JSON.stringify({
          status: healthy ? 'healthy' : 'unhealthy',
          mode: browserManager.getConnectionMode(),
          uptime: Math.floor((Date.now() - startTime) / 1000),
          tabs: browserManager.getTabCount(),
          // No `security` field (#2557): the only writer of the status it
          // reported (sidebar-agent.ts's session-state file) went away with
          // the chat path, so it read from a file nothing wrote — reporting
          // a permanent 'inactive', or a stale false-green 'protected'
          // wherever an old state file survived on disk. The live defenses
          // (content-security L1-L3, the L4 sidecar on /pty-inject-scan)
          // report through their own call sites, not through /health.
          // Terminal-agent discovery. ONLY a port number — never a token.
          // Tokens flow via the /pty-session HttpOnly cookie path. See
          // `pty-session-cookie.ts` for the rationale (codex outside-voice
          // finding #2: don't reuse this endpoint for shell auth).
          terminalPort: readTerminalPort(),
        }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── /pty-session — mint sessionId + lease + attachToken ─────────
      //
      // v1.44+ four-tuple shape:
      //   { terminalPort, sessionId, attachToken, leaseExpiresAt }
      //
      //  - sessionId    : stable, non-secret. Safe to log. Identifies "this
      //                   terminal" across re-attaches.
      //  - attachToken  : short-lived (30 min wall, single attach in practice
      //                   since the agent revokes on WS close). Bearer for
      //                   the /ws upgrade.
      //  - leaseExpiresAt: client-visible deadline for the lease. Re-attach
      //                   only works inside this window.
      //
      // The lease + attachToken are minted together so a successful
      // /pty-session is one round trip. Re-attach mints a fresh attachToken
      // for the SAME sessionId via /pty-session/reattach.
      //
      // NEVER added to TUNNEL_PATHS — the tunnel surface 404s any
      // /pty-session attempt by default-deny.
      if (url.pathname === '/pty-session' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const port = readTerminalPort();
        if (!port) {
          return new Response(JSON.stringify({
            error: 'terminal-agent not ready',
          }), { status: 503, headers: { 'Content-Type': 'application/json' } });
        }
        const lease = mintLease();
        const minted = mintPtySessionToken();
        const granted = await grantPtyToken(minted.token, lease.sessionId);
        if (!granted) {
          revokePtySessionToken(minted.token);
          revokeLease(lease.sessionId);
          return new Response(JSON.stringify({
            error: 'failed to grant terminal session',
          }), { status: 503, headers: { 'Content-Type': 'application/json' } });
        }
        return new Response(JSON.stringify({
          terminalPort: port,
          sessionId: lease.sessionId,
          attachToken: minted.token,
          leaseExpiresAt: lease.expiresAt,
          // Legacy alias — extensions still on the v1.43 wire shape keep
          // working. Drop after one minor release once dogfood confirms.
          ptySessionToken: minted.token,
          expiresAt: minted.expiresAt,
        }), {
          status: 200,
          headers: {
            'Content-Type': 'application/json',
            'Set-Cookie': buildPtySetCookie(minted.token),
          },
        });
      }

      // ─── /pty-session/reattach — mint fresh attachToken for existing sessionId
      //
      // Used by Commit 3's re-attach loop on the client. Validates the
      // lease (rejects unknown/expired sessionId with 410 Gone), mints a
      // fresh short-lived attachToken bound to the same sessionId, and
      // pushes it to the agent. The client opens a new WS with the new
      // token; the agent matches the sessionId binding and re-attaches
      // to the existing PtySession (kept alive for the 60s detach
      // window — Commit 3 wires that side).
      if (url.pathname === '/pty-session/reattach' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const port = readTerminalPort();
        if (!port) {
          return new Response(JSON.stringify({ error: 'terminal-agent not ready' }), {
            status: 503, headers: { 'Content-Type': 'application/json' },
          });
        }
        let body: any;
        try { body = await req.json(); } catch { body = null; }
        const sessionId = typeof body?.sessionId === 'string' ? body.sessionId : null;
        const v = sessionId ? validateLease(sessionId) : { ok: false };
        if (!v.ok) {
          // 410 Gone — session window has closed (lease expired or never
          // existed). Client must fall back to /pty-session for a brand-new
          // session.
          return new Response(JSON.stringify({ error: 'lease expired or unknown' }), {
            status: 410, headers: { 'Content-Type': 'application/json' },
          });
        }
        const minted = mintPtySessionToken();
        const granted = await grantPtyToken(minted.token, sessionId!);
        if (!granted) {
          revokePtySessionToken(minted.token);
          return new Response(JSON.stringify({ error: 'failed to grant attach token' }), {
            status: 503, headers: { 'Content-Type': 'application/json' },
          });
        }
        return new Response(JSON.stringify({
          terminalPort: port,
          sessionId,
          attachToken: minted.token,
          leaseExpiresAt: v.ok ? v.expiresAt : 0,
        }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      }

      // ─── /pty-restart — one-transaction kill + fresh mint ────────────
      //
      // The Restart button. Synchronously disposes the caller's existing
      // PtySession on the agent, revokes the old lease, mints a fresh
      // sessionId + lease + attachToken, and returns the new 4-tuple in
      // one response. Zero race window between kill and mint (codex T2
      // + D8 of the eng review).
      if (url.pathname === '/pty-restart' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const port = readTerminalPort();
        if (!port) {
          return new Response(JSON.stringify({ error: 'terminal-agent not ready' }), {
            status: 503, headers: { 'Content-Type': 'application/json' },
          });
        }
        let body: any;
        try { body = await req.json(); } catch { body = null; }
        const oldSessionId = typeof body?.sessionId === 'string' ? body.sessionId : null;
        // Best-effort dispose. Missing/unknown sessionId is non-fatal —
        // the client may be doing a "restart from scratch" with no prior
        // session (e.g. ENDED state). The fresh mint always proceeds.
        if (oldSessionId) {
          await restartPtySession(oldSessionId);
          revokeLease(oldSessionId);
        }
        const lease = mintLease();
        const minted = mintPtySessionToken();
        const granted = await grantPtyToken(minted.token, lease.sessionId);
        if (!granted) {
          revokePtySessionToken(minted.token);
          revokeLease(lease.sessionId);
          return new Response(JSON.stringify({ error: 'failed to grant terminal session' }), {
            status: 503, headers: { 'Content-Type': 'application/json' },
          });
        }
        return new Response(JSON.stringify({
          terminalPort: port,
          sessionId: lease.sessionId,
          attachToken: minted.token,
          leaseExpiresAt: lease.expiresAt,
        }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      }

      // ─── /pty-dispose — explicit teardown (pagehide / browser quit) ──
      //
      // sendBeacon-compatible: accepts the auth token in the BODY so the
      // extension's pagehide handler can fire it without setting headers
      // (sendBeacon doesn't support custom headers). Codex T3 fix —
      // without this, every browser quit + sidebar close leaves a zombie
      // PTY alive for the 60s detach window (Commit 3).
      if (url.pathname === '/pty-dispose' && req.method === 'POST') {
        let body: any;
        try { body = await req.json(); } catch { body = null; }
        const authTokenFromBody = typeof body?.authToken === 'string' ? body.authToken : null;
        // Accept either header bearer OR body authToken. Both must match
        // the root auth token; otherwise reject.
        const headerToken = extractToken(req);
        const authedByHeader = headerToken !== null && headerToken === authToken;
        const authedByBody = authTokenFromBody !== null && authTokenFromBody === authToken;
        if (!authedByHeader && !authedByBody) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const sessionId = typeof body?.sessionId === 'string' ? body.sessionId : null;
        if (sessionId) {
          await restartPtySession(sessionId);
          revokeLease(sessionId);
        }
        return new Response(JSON.stringify({ ok: true }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── /internal/lease-refresh — loopback from terminal-agent on keepalive
      //
      // T6 PTY-only idle reset (codex outside-voice fix): the headless
      // daemon's idle timer must reset only on active PTY usage, not on
      // every passive SSE consumer. Terminal-agent calls this endpoint
      // (lazily, only when its cached lease is within 5 min of expiry)
      // on its 25s keepalive cycle. Refreshing the lease here also bumps
      // lastActivity so the daemon stays alive while a sidebar terminal
      // is actively in use.
      //
      // INTERNAL endpoint — bound to the root authToken so an external
      // caller can't refresh another user's lease. Body: {sessionId}.
      if (url.pathname === '/internal/lease-refresh' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        let body: any;
        try { body = await req.json(); } catch { body = null; }
        const sessionId = typeof body?.sessionId === 'string' ? body.sessionId : null;
        const r = sessionId ? refreshLease(sessionId) : { ok: false };
        if (!r.ok) {
          return new Response(JSON.stringify({ error: 'lease expired or unknown' }), {
            status: 410, headers: { 'Content-Type': 'application/json' },
          });
        }
        // T6: PTY activity resets the daemon idle timer.
        resetIdleTimer();
        return new Response(JSON.stringify({ ok: true, expiresAt: r.expiresAt }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── /pty-inject-scan — pre-inject prompt-injection scan for the
      // extension's gstackInjectToTerminal callers. The extension routes
      // every page-derived text through this endpoint BEFORE writing to
      // the PTY (#1370). Local-only by intent: not added to the tunnel
      // allowlist; root-token auth required. Sidecar absence degrades to
      // L4 unavailable (extension shows WARN + user confirm per D7).
      if (url.pathname === '/pty-inject-scan' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(
            JSON.stringify({ error: 'Unauthorized' }, sanitizeReplacer),
            { status: 401, headers: { 'Content-Type': 'application/json' } },
          );
        }
        // 64KB request cap. Defense against accidentally posting an
        // entire page DOM into the PTY path.
        const contentLength = Number(req.headers.get('content-length') || '0');
        if (contentLength > 64 * 1024) {
          return new Response(
            JSON.stringify({ error: 'payload-too-large', limit: 65536 }, sanitizeReplacer),
            { status: 413, headers: { 'Content-Type': 'application/json' } },
          );
        }
        let body: { text?: unknown; origin?: unknown } = {};
        try {
          body = (await req.json()) as { text?: unknown; origin?: unknown };
        } catch {
          return new Response(
            JSON.stringify({ error: 'malformed-json' }, sanitizeReplacer),
            { status: 400, headers: { 'Content-Type': 'application/json' } },
          );
        }
        const text = typeof body.text === 'string' ? body.text : '';
        const origin = typeof body.origin === 'string' ? body.origin : 'unknown';
        if (text.length === 0) {
          return new Response(
            JSON.stringify({ error: 'missing-text' }, sanitizeReplacer),
            { status: 400, headers: { 'Content-Type': 'application/json' } },
          );
        }

        // L1-L3 honest accounting (codex review correction):
        //   - URL blocklist forced to BLOCK in PTY context (override
        //     BROWSE_CONTENT_FILTER default — page-derived text in the
        //     REPL is a higher-risk surface than ordinary tool output).
        //   - L4 ML classifier via the sidecar when available.
        //   - L1-L3 envelope/datamarking is INFORMATIONAL only; the
        //     verdict is driven by the URL blocklist + L4.
        // See CLAUDE.md "Sidebar security stack" + plan §"L1-L3 honest
        // accounting".
        let verdict: 'PASS' | 'WARN' | 'BLOCK' = 'PASS';
        const reasons: string[] = [];

        // Quick URL-blocklist check (re-uses the security module's
        // pure-string helpers — no @huggingface/transformers dep).
        // Pattern: text containing a known bad-actor domain → BLOCK.
        if (/(\bbit\.ly|\btinyurl\.com|\bdiscord\.gg)/i.test(text)) {
          verdict = 'BLOCK';
          reasons.push('url-blocklist');
        }

        // L4 sidecar scan if available.
        const sidecarAvail = isSidecarAvailable();
        let l4: { available: boolean; verdict?: unknown; error?: string } = {
          available: sidecarAvail.available,
        };
        if (sidecarAvail.available && verdict !== 'BLOCK') {
          try {
            const { verdict: layerVerdict } = await scanWithSidecar(text, {
              timeoutMs: 5000,
            });
            l4 = { available: true, verdict: layerVerdict };
            // LayerSignal shape: { verdict: 'safe'|'suspicious'|'unsafe', ... }
            const lv = (layerVerdict as { verdict?: string })?.verdict;
            if (lv === 'unsafe') {
              verdict = 'BLOCK';
              reasons.push('l4-unsafe');
            } else if (lv === 'suspicious') {
              verdict = 'WARN';
              reasons.push('l4-suspicious');
            }
          } catch (err) {
            l4 = {
              available: false,
              error: err instanceof Error ? err.message : String(err),
            };
            // L4 failure during scan: degrade to WARN per D7.
            if (verdict === 'PASS') {
              verdict = 'WARN';
              reasons.push('l4-unavailable');
            }
          }
        } else if (!sidecarAvail.available && verdict === 'PASS') {
          verdict = 'WARN';
          reasons.push(`l4-unavailable:${sidecarAvail.reason ?? 'unknown'}`);
        }

        // BLOCK decisions are surfaced in the response shape; the
        // existing writeDecision audit log is tab-scoped (per-page) and
        // doesn't fit the PTY surface. The extension logs the BLOCK
        // event into its own activity feed on receipt, which keeps the
        // audit signal observable without bolting a new attempts.jsonl
        // onto the server.

        return new Response(
          JSON.stringify(
            { verdict, reasons, l4, datamark: '<untrusted-page-content>' },
            sanitizeReplacer,
          ),
          { status: 200, headers: { 'Content-Type': 'application/json' } },
        );
      }

      // ─── /connect — setup key exchange for /pair-agent ceremony ────
      if (url.pathname === '/connect' && req.method === 'POST') {
        if (!checkConnectRateLimit()) {
          return new Response(JSON.stringify({
            error: 'Too many connection attempts. Wait 1 minute.',
          }), { status: 429, headers: { 'Content-Type': 'application/json' } });
        }
        try {
          const connectBody = await req.json() as { setup_key?: string };
          if (!connectBody.setup_key) {
            return new Response(JSON.stringify({ error: 'Missing setup_key' }), {
              status: 400, headers: { 'Content-Type': 'application/json' },
            });
          }
          const session = exchangeSetupKey(connectBody.setup_key);
          if (!session) {
            return new Response(JSON.stringify({
              error: 'Invalid, expired, or already-used setup key',
            }), { status: 401, headers: { 'Content-Type': 'application/json' } });
          }
          console.log(`[browse] Remote agent connected: ${session.clientId} (scopes: ${session.scopes.join(',')})`);
          return new Response(JSON.stringify({
            token: session.token,
            expires: session.expiresAt,
            scopes: session.scopes,
            agent: session.clientId,
          }), { status: 200, headers: { 'Content-Type': 'application/json' } });
        } catch {
          return new Response(JSON.stringify({ error: 'Invalid request body' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // ─── /token — mint scoped tokens (root-only) ──────────────────
      if (url.pathname === '/token' && req.method === 'POST') {
        if (!isRootRequest(req)) {
          return new Response(JSON.stringify({
            error: 'Only the root token can mint sub-tokens',
          }), { status: 403, headers: { 'Content-Type': 'application/json' } });
        }
        try {
          const tokenBody = await req.json() as any;
          if (!tokenBody.clientId) {
            return new Response(JSON.stringify({ error: 'Missing clientId' }), {
              status: 400, headers: { 'Content-Type': 'application/json' },
            });
          }
          const session = createToken({
            clientId: tokenBody.clientId,
            scopes: tokenBody.scopes,
            domains: tokenBody.domains,
            tabPolicy: tokenBody.tabPolicy,
            rateLimit: tokenBody.rateLimit,
            expiresSeconds: tokenBody.expiresSeconds,
          });
          return new Response(JSON.stringify({
            token: session.token,
            expires: session.expiresAt,
            scopes: session.scopes,
            agent: session.clientId,
          }), { status: 200, headers: { 'Content-Type': 'application/json' } });
        } catch (err) {
          // Name the caller's typo (bad scope, negative rateLimit, reserved
          // clientId) instead of hiding it behind the generic body error.
          if (err instanceof InvalidScopeError || err instanceof ReservedClientIdError) {
            return new Response(JSON.stringify({ error: err.message }), {
              status: 400, headers: { 'Content-Type': 'application/json' },
            });
          }
          return new Response(JSON.stringify({ error: 'Invalid request body' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // ─── /token/:clientId — revoke a scoped token (root-only) ─────
      if (url.pathname.startsWith('/token/') && req.method === 'DELETE') {
        if (!isRootRequest(req)) {
          return new Response(JSON.stringify({ error: 'Root token required' }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        // decodeURIComponent so CLI-encoded names (spaces, UTF-8) round-trip.
        let clientId: string;
        try {
          clientId = decodeURIComponent(url.pathname.slice('/token/'.length));
        } catch {
          return new Response(JSON.stringify({ error: 'Malformed client ID encoding' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
        const revoked = revokeToken(clientId);
        // Release tabs UNCONDITIONALLY: ownership outlives the token (it clears
        // only on tab close), so a client whose token already expired can still
        // own tabs. Gating release on a revoke hit would orphan that ownership
        // and let a same-name re-pair inherit an authenticated tab.
        const tabsReleased = browserManager.releaseClientTabs(clientId).length;
        if (!revoked && tabsReleased === 0) {
          return new Response(JSON.stringify({ error: `Agent "${clientId}" not found` }), {
            status: 404, headers: { 'Content-Type': 'application/json' },
          });
        }
        console.log(`[browse] Revoked ${revoked} token(s), released ${tabsReleased} tab(s) for: ${clientId}`);
        return new Response(JSON.stringify({ revoked: clientId, tokens_deleted: revoked, tabs_released: tabsReleased }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── /agents — list connected agents (root-only) ──────────────
      if (url.pathname === '/agents' && req.method === 'GET') {
        if (!isRootRequest(req)) {
          return new Response(JSON.stringify({ error: 'Root token required' }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        // includeSetup: pending (unexchanged) setup keys are live grants the
        // operator must be able to see — without them, revoking a paired-but-
        // never-connected agent "works" while the list shows nothing.
        const agents = listTokens({ includeSetup: true }).map(t => ({
          clientId: t.clientId,
          scopes: t.scopes,
          domains: t.domains,
          expiresAt: t.expiresAt,
          commandCount: t.commandCount,
          createdAt: t.createdAt,
          pending: t.type === 'setup',
        }));
        return new Response(JSON.stringify({ agents }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── /pair — create setup key for pair-agent ceremony (root-only) ───
      if (url.pathname === '/pair' && req.method === 'POST') {
        if (!isRootRequest(req)) {
          return new Response(JSON.stringify({ error: 'Root token required' }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        try {
          const pairBody = await req.json() as any;
          // Reject a reserved/invalid clientId up front (createSetupKey enforces
          // it too, but this makes the 400 unambiguous and skips the teardown).
          if (pairBody.clientId !== undefined) assertValidClientId(pairBody.clientId);
          // Default: DEFAULT_PAIR_SCOPES (full page access). The trust boundary
          // is the pairing ceremony itself, not the scope. --control adds
          // browser-wide destructive commands (stop, restart, disconnect).
          // --restrict limits scope — but can never grant control: that scope
          // stays behind the explicit control flag.
          if (!pairBody.control && !pairBody.admin
              && Array.isArray(pairBody.scopes) && pairBody.scopes.includes('control')) {
            return new Response(JSON.stringify({
              error: 'The control scope requires the control flag (--control); it cannot be granted via a scopes list.',
            }), { status: 400, headers: { 'Content-Type': 'application/json' } });
          }
          const scopes = pairBody.control || pairBody.admin
            ? [...DEFAULT_PAIR_SCOPES, 'control' as const]
            : ((pairBody.scopes || [...DEFAULT_PAIR_SCOPES]) as ScopeCategory[]);
          // D1: a re-pair supersedes prior grants. ALWAYS drop stale setup keys
          // so a superseded broad key can never be exchanged — this closes the
          // shadow-key hole where a narrowing re-pair before the agent connects
          // would otherwise leave the old broad key live. Revoke the live
          // SESSION only when the new grant actually reduces access, so a
          // broaden/refresh never strands a working agent mid-task. Compare
          // against the resolved grant (not raw pairBody) so dropping 'control'
          // or a default re-pair is classified correctly. Revoke runs BEFORE
          // createSetupKey — revokeToken deletes all of a clientId's tokens, so
          // minting first would nuke the fresh key.
          const grant = {
            scopes: [...scopes] as ScopeCategory[],
            domains: pairBody.domains as string[] | undefined,
            rateLimit: pairBody.rateLimit ?? 10,
            tabPolicy: 'own-only' as const,
          };
          // Validate BEFORE any revoke (createSetupKey validates too, but that
          // runs after the teardown below). A bad scope or negative rateLimit
          // must 400 without knocking a live session offline — otherwise a
          // reducing re-pair with a typo (--restrict red) destroys the session
          // and mints no replacement.
          assertValidTokenOptions(grant.scopes, grant.rateLimit);
          const priorSession = pairBody.clientId ? getClientSession(pairBody.clientId) : null;
          let superseded: { tokens_deleted: number; tabs_released: number } | undefined;
          if (priorSession && grantReducesAccess(priorSession, grant)) {
            const tokensDeleted = revokeToken(pairBody.clientId);
            const tabsReleased = browserManager.releaseClientTabs(pairBody.clientId).length;
            superseded = { tokens_deleted: tokensDeleted, tabs_released: tabsReleased };
            console.log(`[browse] Superseded ${tokensDeleted} token(s), released ${tabsReleased} tab(s) for reducing re-pair: ${pairBody.clientId}`);
          } else if (pairBody.clientId) {
            revokeSetupKeys(pairBody.clientId);
            // No live session, but tab ownership outlives token expiry: free any
            // tabs orphaned by an expired session so this re-pair can't inherit
            // an earlier incarnation's authenticated pages (mirrors DELETE
            // /token's unconditional release). A live-session broaden keeps its
            // tabs — the working agent still owns them.
            if (!priorSession) browserManager.releaseClientTabs(pairBody.clientId);
          }
          const setupKey = createSetupKey({
            clientId: pairBody.clientId,
            scopes: [...scopes],
            domains: pairBody.domains,
            rateLimit: pairBody.rateLimit,
          });
          // Verify tunnel is actually alive before reporting it (ngrok may have died externally).
          // Probe via GET /connect — under dual-listener /health is NOT on the tunnel allowlist,
          // so the old probe would return 404 and always mark the tunnel as dead.
          let verifiedTunnelUrl: string | null = null;
          if (tunnelActive && tunnelUrl) {
            try {
              const probe = await fetch(`${tunnelUrl}/connect`, {
                method: 'GET',
                headers: { 'ngrok-skip-browser-warning': 'true' },
                signal: AbortSignal.timeout(5000),
              });
              if (probe.ok) {
                verifiedTunnelUrl = tunnelUrl;
              } else {
                console.warn(`[browse] Tunnel probe failed (HTTP ${probe.status}), marking tunnel as dead`);
                await closeTunnel();
              }
            } catch {
              console.warn('[browse] Tunnel probe timed out or unreachable, marking tunnel as dead');
              await closeTunnel();
            }
          }
          return new Response(JSON.stringify({
            setup_key: setupKey.token,
            expires_at: setupKey.expiresAt,
            scopes: setupKey.scopes,
            tunnel_url: verifiedTunnelUrl,
            server_url: `http://127.0.0.1:${browsePort}`,
            ...(superseded ? { superseded } : {}),
          }), { status: 200, headers: { 'Content-Type': 'application/json' } });
        } catch (err) {
          // Name the caller's typo (bad scope, negative rateLimit, reserved
          // clientId) instead of hiding it behind the generic body error.
          if (err instanceof InvalidScopeError || err instanceof ReservedClientIdError) {
            return new Response(JSON.stringify({ error: err.message }), {
              status: 400, headers: { 'Content-Type': 'application/json' },
            });
          }
          return new Response(JSON.stringify({ error: 'Invalid request body' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // ─── /tunnel/start — start ngrok tunnel on demand (root-only) ──
      //
      // Dual-listener model: binds a SECOND Bun.serve listener on an
      // ephemeral 127.0.0.1 port dedicated to tunnel traffic, then points
      // ngrok.forward() at THAT port.  The existing local listener (which
      // serves /extension-token, /cookie-picker, /inspector/*, welcome, etc.)
      // is never exposed to ngrok.
      //
      // Hard fail if the tunnel listener bind fails — NEVER fall back to
      // the local port, which would silently defeat the whole security
      // property.
      if (url.pathname === '/tunnel/start' && req.method === 'POST') {
        if (!isRootRequest(req)) {
          return new Response(JSON.stringify({ error: 'Root token required' }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        if (!isPairAgentEnabled()) {
          // Consent-on-first-use: the /pair-agent skill asks once and sets the
          // key; a direct API caller gets the same hint instead of a tunnel.
          return new Response(JSON.stringify({
            error: 'pair-agent is off (tunnel exposes this browser beyond the machine)',
            hint: 'enable once with: gstack-config set pair_agent on — or run /pair-agent, which asks for consent and sets it',
          }), { status: 403, headers: { 'Content-Type': 'application/json' } });
        }
        if (tunnelActive && tunnelUrl && tunnelServer) {
          // Verify tunnel is still alive before returning cached URL.
          // Probe GET /connect (the only unauth-reachable path on the tunnel
          // surface); /health is NOT tunnel-reachable under dual-listener.
          try {
            const probe = await fetch(`${tunnelUrl}/connect`, {
              method: 'GET',
              headers: { 'ngrok-skip-browser-warning': 'true' },
              signal: AbortSignal.timeout(5000),
            });
            if (probe.ok) {
              return new Response(JSON.stringify({ url: tunnelUrl, already_active: true }), {
                status: 200, headers: { 'Content-Type': 'application/json' },
              });
            }
          } catch {}
          // Tunnel is dead — tear down cleanly before restarting
          console.warn('[browse] Cached tunnel is dead, restarting...');
          await closeTunnel();
        }

        // 1) Resolve ngrok authtoken from env / .gstack / native config
        const authtoken = resolveNgrokAuthtoken();
        if (!authtoken) {
          return new Response(JSON.stringify({
            error: 'No ngrok authtoken found',
            hint: 'Run: ngrok config add-authtoken YOUR_TOKEN',
          }), { status: 400, headers: { 'Content-Type': 'application/json' } });
        }

        // 2) Bind the tunnel listener + open ngrok via the shared helper
        //    (see startTunnel — hard-fails the bind, cleans up both ngrok
        //    and the Bun listener on any post-bind failure).
        const started = await startTunnel({
          fetchHandler: makeFetchHandler('tunnel'),
          authtoken,
          consent: 'pair_agent=on (isPairAgentEnabled gate at /tunnel/start)',
        });
        if (!started.ok) {
          return new Response(JSON.stringify({
            error: started.stage === 'bind'
              ? `Failed to bind tunnel listener: ${started.error.message}`
              : `Failed to open ngrok tunnel: ${started.error.message}`,
          }), { status: 500, headers: { 'Content-Type': 'application/json' } });
        }
        return new Response(JSON.stringify({ url: started.url }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── SSE session cookie mint (auth required) ──────────────────
      //
      // Issues a short-lived view-only token in an HttpOnly SameSite=Strict
      // cookie so EventSource calls can authenticate without putting the
      // root token in a URL. The returned cookie is valid ONLY on the SSE
      // endpoints (/activity/stream, /inspector/events); it is not a
      // scoped token and cannot be used against /command.
      //
      // The extension calls this once at bootstrap with the root Bearer
      // header, then opens EventSource with `withCredentials: true` which
      // sends the cookie back automatically.
      if (url.pathname === '/sse-session' && req.method === 'POST') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        const minted = mintSseSessionToken();
        return new Response(JSON.stringify({
          expiresAt: minted.expiresAt,
          cookie: SSE_COOKIE_NAME,
        }), {
          status: 200,
          headers: {
            'Content-Type': 'application/json',
            'Set-Cookie': buildSseSetCookie(minted.token),
          },
        });
      }

      // Refs endpoint — auth required, does NOT reset idle timer
      if (url.pathname === '/refs') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        const refs = browserManager.getRefMap();
        return new Response(JSON.stringify({
          refs,
          url: browserManager.getCurrentUrl(),
          mode: browserManager.getConnectionMode(),
        }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // Activity stream — SSE, auth required, does NOT reset idle timer
      if (url.pathname === '/activity/stream') {
        // Auth: Bearer header OR view-only SSE session cookie (EventSource
        // can't send Authorization headers, so the extension fetches a cookie
        // via POST /sse-session first, then opens EventSource with
        // withCredentials: true). The ?token= query param is NO LONGER
        // accepted — URLs leak to logs/referer/history. See N1 in the
        // v1.6.0.0 security wave plan.
        const cookieToken = extractSseCookie(req);
        if (!validateAuth(req) && !validateSseSessionToken(cookieToken)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        const afterId = parseInt(url.searchParams.get('after') || '0', 10);
        // Cleanup contract (abort + enqueue-fail + heartbeat-fail, all
        // idempotent) lives in createSseEndpoint; sanitizeReplacer is
        // applied to every JSON.stringify inside the helper, so
        // page-content-derived fields (URLs, command args, errors)
        // stay surrogate-safe per CLAUDE.md egress invariant.
        return createSseEndpoint(req, {
          initialReplay: (send) => {
            const { entries, gap, gapFrom, availableFrom } = getActivityAfter(afterId);
            if (gap) send('gap', { gapFrom, availableFrom });
            for (const entry of entries) send('activity', entry);
          },
          subscribe,
          liveEventName: 'activity',
        });
      }

      // Activity history — REST, auth required, does NOT reset idle timer
      if (url.pathname === '/activity/history') {
        if (!validateAuth(req)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        const limit = parseInt(url.searchParams.get('limit') || '50', 10);
        const { entries, totalAdded } = getActivityHistory(limit);
        return new Response(JSON.stringify({ entries, totalAdded, subscribers: getSubscriberCount() }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }


      // ─── Batch endpoint — N commands, 1 HTTP round-trip ─────────────
      // Accepts both root AND scoped tokens (same as /command).
      // Executes commands sequentially through the full security pipeline.
      // Designed for remote agents where tunnel latency dominates.
      if (url.pathname === '/batch' && req.method === 'POST') {
        const tokenInfo = getTokenInfo(req);
        if (!tokenInfo) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        resetIdleTimer();
        const body = await req.json();
        const { commands } = body;

        if (!Array.isArray(commands) || commands.length === 0) {
          return new Response(JSON.stringify({ error: '"commands" must be a non-empty array' }), {
            status: 400,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        if (commands.length > 50) {
          return new Response(JSON.stringify({ error: 'Max 50 commands per batch' }), {
            status: 400,
            headers: { 'Content-Type': 'application/json' },
          });
        }

        const startTime = Date.now();
        emitActivity({
          type: 'command_start',
          command: 'batch',
          args: [`${commands.length} commands`],
          url: browserManager.getCurrentUrl(),
          tabs: browserManager.getTabCount(),
          mode: browserManager.getConnectionMode(),
          clientId: tokenInfo?.clientId,
        });

        const results: Array<{ index: number; status: number; result: string; command: string; tabId?: number }> = [];
        for (let i = 0; i < commands.length; i++) {
          const cmd = commands[i];
          if (!cmd || typeof cmd.command !== 'string') {
            results.push({ index: i, status: 400, result: JSON.stringify({ error: 'Missing "command" field' }), command: '' });
            continue;
          }
          // Reject nested batches
          if (cmd.command === 'batch') {
            results.push({ index: i, status: 400, result: JSON.stringify({ error: 'Nested batch commands are not allowed' }), command: 'batch' });
            continue;
          }
          const cr = await handleCommandInternal(
            { command: cmd.command, args: cmd.args, tabId: cmd.tabId },
            tokenInfo,
            { skipRateCheck: true, skipActivity: true },
          );
          // Sanitize lone surrogates per-result (#1440 — /batch bypasses the
          // handleCommand chokepoint, so it needs its own sanitization).
          const safeResult = typeof cr.result === 'string' ? sanitizeBody(cr.result, !!cr.json) : cr.result;
          results.push({
            index: i,
            status: cr.status,
            result: safeResult,
            command: cmd.command,
            tabId: cmd.tabId,
          });
        }

        const duration = Date.now() - startTime;
        emitActivity({
          type: 'command_end',
          command: 'batch',
          args: [`${commands.length} commands`],
          url: browserManager.getCurrentUrl(),
          duration,
          status: 'ok',
          result: `${results.filter(r => r.status === 200).length}/${commands.length} succeeded`,
          tabs: browserManager.getTabCount(),
          mode: browserManager.getConnectionMode(),
          clientId: tokenInfo?.clientId,
        });

        // Sanitize the JSON envelope a second time (defense in depth) — catches
        // any \uXXXX escape sequences for lone surrogates that survived the
        // per-result pass.
        const batchBody = stripLoneSurrogateEscapes(JSON.stringify({
          results,
          duration,
          total: commands.length,
          succeeded: results.filter(r => r.status === 200).length,
          failed: results.filter(r => r.status !== 200).length,
        }));
        return new Response(batchBody, {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── File serving endpoint (for remote agents to retrieve downloaded files) ────
      if (url.pathname === '/file' && req.method === 'GET') {
        const tokenInfo = getTokenInfo(req);
        if (!tokenInfo) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const filePath = url.searchParams.get('path');
        if (!filePath) {
          return new Response(JSON.stringify({ error: 'Missing "path" query parameter' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
        try {
          validateTempPath(filePath);
        } catch (err: any) {
          return new Response(JSON.stringify({ error: err.message }), {
            status: 403, headers: { 'Content-Type': 'application/json' },
          });
        }
        if (!fs.existsSync(filePath)) {
          return new Response(JSON.stringify({ error: 'File not found' }), {
            status: 404, headers: { 'Content-Type': 'application/json' },
          });
        }
        const stat = fs.statSync(filePath);
        if (stat.size > 200 * 1024 * 1024) {
          return new Response(JSON.stringify({ error: 'File too large (max 200MB)' }), {
            status: 413, headers: { 'Content-Type': 'application/json' },
          });
        }
        const ext = path.extname(filePath).toLowerCase();
        const MIME_MAP: Record<string, string> = {
          '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
          '.gif': 'image/gif', '.webp': 'image/webp', '.svg': 'image/svg+xml',
          '.avif': 'image/avif',
          '.mp4': 'video/mp4', '.webm': 'video/webm', '.mov': 'video/quicktime',
          '.mp3': 'audio/mpeg', '.wav': 'audio/wav', '.ogg': 'audio/ogg',
          '.pdf': 'application/pdf', '.json': 'application/json',
          '.html': 'text/html', '.txt': 'text/plain', '.mhtml': 'message/rfc822',
        };
        const contentType = MIME_MAP[ext] || 'application/octet-stream';
        resetIdleTimer();
        return new Response(Bun.file(filePath), {
          headers: {
            'Content-Type': contentType,
            'Content-Length': String(stat.size),
            'Content-Disposition': `inline; filename="${path.basename(filePath)}"`,
            'Cache-Control': 'no-cache',
          },
        });
      }

      // ─── Command endpoint (accepts both root AND scoped tokens) ────
      // Must be checked BEFORE the blanket root-only auth gate below,
      // because scoped tokens from /connect are valid for /command.
      if (url.pathname === '/command' && req.method === 'POST') {
        const tokenInfo = getTokenInfo(req);
        if (!tokenInfo) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401,
            headers: { 'Content-Type': 'application/json' },
          });
        }
        resetIdleTimer();
        const body = await req.json() as any;
        // Tunnel surface: only commands in TUNNEL_COMMANDS are allowed.
        // Paired remote agents drive the browser but cannot configure the
        // daemon, launch new browsers, import cookies, or rotate tokens.
        if (surface === 'tunnel') {
          if (!canDispatchOverTunnel(body?.command, body?.args)) {
            logTunnelDenial(req, url, `disallowed_command:${body?.command}`);
            return new Response(JSON.stringify({
              error: `Command '${body?.command}' is not allowed over the tunnel surface`,
              hint: `Tunnel commands: ${[...TUNNEL_COMMANDS].sort().join(', ')}. Note: --out (disk write) is never allowed over the tunnel.`,
            }), { status: 403, headers: { 'Content-Type': 'application/json' } });
          }
        }
        return handleCommand(body, tokenInfo);
      }

      // ─── Auth-required endpoints (root token only) ─────────────────

      if (!validateAuth(req)) {
        return new Response(JSON.stringify({ error: 'Unauthorized' }), {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // ─── Inspector endpoints ──────────────────────────────────────

      // POST /inspector/pick — receive element pick from extension, run CDP inspection
      if (url.pathname === '/inspector/pick' && req.method === 'POST') {
        const body = await req.json();
        const { selector, activeTabUrl } = body;
        if (!selector) {
          return new Response(JSON.stringify({ error: 'Missing selector' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
        try {
          const page = browserManager.getPage();
          const result = await inspectElement(page, selector);
          inspectorData = result;
          inspectorTimestamp = Date.now();
          // Also store on browserManager for CLI access
          (browserManager as any)._inspectorData = result;
          (browserManager as any)._inspectorTimestamp = inspectorTimestamp;
          emitInspectorEvent({ type: 'pick', selector, timestamp: inspectorTimestamp });
          return new Response(JSON.stringify(result), {
            status: 200, headers: { 'Content-Type': 'application/json' },
          });
        } catch (err: any) {
          return new Response(JSON.stringify({ error: err.message }), {
            status: 500, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // GET /inspector — return latest inspector data
      if (url.pathname === '/inspector' && req.method === 'GET') {
        if (!inspectorData) {
          return new Response(JSON.stringify({ data: null }), {
            status: 200, headers: { 'Content-Type': 'application/json' },
          });
        }
        const stale = inspectorTimestamp > 0 && (Date.now() - inspectorTimestamp > 60000);
        return new Response(JSON.stringify({ data: inspectorData, timestamp: inspectorTimestamp, stale }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // POST /inspector/apply — apply a CSS modification
      if (url.pathname === '/inspector/apply' && req.method === 'POST') {
        const body = await req.json();
        const { selector, property, value } = body;
        if (!selector || !property || value === undefined) {
          return new Response(JSON.stringify({ error: 'Missing selector, property, or value' }), {
            status: 400, headers: { 'Content-Type': 'application/json' },
          });
        }
        try {
          const page = browserManager.getPage();
          const mod = await modifyStyle(page, selector, property, value);
          emitInspectorEvent({ type: 'apply', modification: mod, timestamp: Date.now() });
          return new Response(JSON.stringify(mod), {
            status: 200, headers: { 'Content-Type': 'application/json' },
          });
        } catch (err: any) {
          return new Response(JSON.stringify({ error: err.message }), {
            status: 500, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // POST /inspector/reset — clear all modifications
      if (url.pathname === '/inspector/reset' && req.method === 'POST') {
        try {
          const page = browserManager.getPage();
          await resetModifications(page);
          emitInspectorEvent({ type: 'reset', timestamp: Date.now() });
          return new Response(JSON.stringify({ ok: true }), {
            status: 200, headers: { 'Content-Type': 'application/json' },
          });
        } catch (err: any) {
          return new Response(JSON.stringify({ error: err.message }), {
            status: 500, headers: { 'Content-Type': 'application/json' },
          });
        }
      }

      // GET /inspector/history — return modification list
      if (url.pathname === '/inspector/history' && req.method === 'GET') {
        return new Response(JSON.stringify({ history: getModificationHistory() }), {
          status: 200, headers: { 'Content-Type': 'application/json' },
        });
      }

      // GET /memory — diagnostic snapshot (auth required, does NOT reset idle).
      // Same auth model as /activity/stream and /inspector/events: Bearer header
      // OR view-only SSE-session cookie. Does NOT extend /health (which is
      // unauthenticated liveness-only — token bootstrap moved to the pinned
      // POST /extension-token); a separate endpoint with the standard SSE auth
      // keeps /health free of anything worth stealing.
      if (url.pathname === '/memory' && req.method === 'GET') {
        const cookieToken = extractSseCookie(req);
        if (!validateAuth(req) && !validateSseSessionToken(cookieToken)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        const { buildMemorySnapshotJson } = await import('./memory-command');
        const snapshot = await buildMemorySnapshotJson(cfgBrowserManager);
        // sanitizeReplacer is required at every SSE/JSON egress that ships
        // page-content-derived strings — tab.url and tab.title come from
        // page content, so lone-surrogate bytes from broken emoji or
        // mid-emoji splits could otherwise reach the sidebar / Claude API.
        return new Response(JSON.stringify(snapshot, sanitizeReplacer), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // GET /inspector/events — SSE for inspector state changes (auth required)
      if (url.pathname === '/inspector/events' && req.method === 'GET') {
        // Same auth model as /activity/stream: Bearer OR view-only cookie.
        // ?token= query param dropped (see N1 in the v1.6.0.0 security plan).
        const cookieToken = extractSseCookie(req);
        if (!validateAuth(req) && !validateSseSessionToken(cookieToken)) {
          return new Response(JSON.stringify({ error: 'Unauthorized' }), {
            status: 401, headers: { 'Content-Type': 'application/json' },
          });
        }
        // Cleanup contract (abort + enqueue-fail + heartbeat-fail,
        // idempotent) lives in createSseEndpoint; sanitizeReplacer is
        // applied to every JSON.stringify inside the helper. The
        // inspector subscriber set stays here because it's also written
        // to by emitInspectorEvent above.
        return createSseEndpoint(req, {
          initialReplay: inspectorData
            ? (send) => send('state', { data: inspectorData, timestamp: inspectorTimestamp })
            : undefined,
          subscribe: (notify) => {
            inspectorSubscribers.add(notify);
            return () => inspectorSubscribers.delete(notify);
          },
          liveEventName: 'inspector',
        });
      }

      return new Response('Not found', { status: 404 });
  };

  return {
    fetchLocal: makeFetchHandler('local'),
    fetchTunnel: makeFetchHandler('tunnel'),
    shutdown,
    stopListeners,
  };
}

export async function start() {
  // Clear old log files
  safeUnlink(CONSOLE_LOG_PATH);
  safeUnlink(NETWORK_LOG_PATH);
  safeUnlink(DIALOG_LOG_PATH);

  const port = await findPort();
  LOCAL_LISTEN_PORT = port;

  // ─── Proxy config (D8 + codex F5) ──────────────────────────────
  // BROWSE_PROXY_URL is set by the CLI when --proxy was passed. For SOCKS5
  // with auth, we run a local 127.0.0.1 bridge that relays to the
  // authenticated upstream (Chromium can't do SOCKS5 auth itself). For
  // HTTP/HTTPS or unauthenticated SOCKS5, we pass the URL directly to
  // Chromium's proxy.server option.
  let proxyBridge: BridgeHandle | null = null;
  const proxyUrl = process.env.BROWSE_PROXY_URL;
  if (proxyUrl) {
    let parsed;
    try {
      parsed = parseProxyConfig({
        proxyUrl,
        envUser: process.env.BROWSE_PROXY_USER,
        envPass: process.env.BROWSE_PROXY_PASS,
      });
    } catch (err) {
      if (err instanceof ProxyConfigError) {
        console.error(`[browse] error: ${err.message} (${err.hint})`);
        process.exit(1);
      }
      throw err;
    }

    if (parsed.scheme === 'socks5' && parsed.hasAuth) {
      // Pre-flight: verify upstream accepts our creds before launching
      // Chromium. 5s budget, 3 retries with 500ms backoff (D4: handles VPN
      // warm-up race). On failure, exit with redacted error.
      console.log(`[browse] Testing SOCKS5 upstream ${redactProxyUrl(proxyUrl)}...`);
      try {
        const test = await testUpstream({
          upstream: toUpstreamConfig(parsed),
          budgetMs: 5000,
          retries: 3,
          backoffMs: 500,
        });
        console.log(`[browse] [proxy] upstream test ok in ${test.ms}ms (${test.attempts} attempt${test.attempts === 1 ? '' : 's'})`);
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        console.error(`[browse] [proxy] FAIL upstream ${redactProxyUrl(proxyUrl)}: ${msg}`);
        process.exit(1);
      }

      proxyBridge = await startSocksBridge({ upstream: toUpstreamConfig(parsed) });
      console.log(`[browse] [proxy] bridge listening on 127.0.0.1:${proxyBridge.port}`);
      browserManager.setProxyConfig({ server: `socks5://127.0.0.1:${proxyBridge.port}` });
    } else {
      // HTTP/HTTPS or unauth SOCKS5 — pass through to Chromium directly.
      browserManager.setProxyConfig({
        server: `${parsed.scheme}://${parsed.host}:${parsed.port}`,
        ...(parsed.userId ? { username: parsed.userId } : {}),
        ...(parsed.password ? { password: parsed.password } : {}),
      });
      console.log(`[browse] [proxy] using ${redactProxyUrl(proxyUrl)} (pass-through to Chromium)`);
    }

    // Tear down bridge on shutdown.
    process.on('exit', () => {
      if (proxyBridge) {
        proxyBridge.close().catch(() => { /* shutting down anyway */ });
      }
    });
  }

  // ─── Xvfb auto-spawn (Linux + headed + no DISPLAY) ─────────────
  // codex F2: walk display range to pick a free one (never hardcode :99);
  // record start-time alongside PID so cleanup can validate ownership and
  // not kill a recycled PID.
  let xvfb: XvfbHandle | null = null;
  const xvfbDecision = shouldSpawnXvfb(process.env, process.platform);
  if (xvfbDecision.spawn) {
    const displayNum = pickFreeDisplay();
    if (displayNum == null) {
      console.error('[browse] no free X display in range :99-:120 — refusing to clobber existing X servers');
      process.exit(1);
    }
    try {
      xvfb = await spawnXvfb(displayNum);
      process.env.DISPLAY = xvfb.display;
      console.log(`[browse] [xvfb] spawned on ${xvfb.display} (pid ${xvfb.pid})`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`[browse] [xvfb] FAILED: ${msg}`);
      console.error(`[browse] [xvfb] hint: ${xvfbInstallHint()}`);
      process.exit(1);
    }
    process.on('exit', () => { try { xvfb?.close(); } catch { /* shutting down */ } });
  } else if (process.env.BROWSE_HEADED === '1') {
    console.log(`[browse] [xvfb] skipped: ${xvfbDecision.reason}`);
  }

  // Read env once — single source of truth for authToken (and other env).
  // Threaded through launchHeaded, buildFetchHandler, and the state file
  // write so all consumers see the same value. v1.34.x's module-level
  // AUTH_TOKEN const was deleted in v1.35.0.0.
  const envCfg = resolveConfigFromEnv();

  // Launch browser (headless or headed with extension)
  // BROWSE_HEADLESS_SKIP=1 skips browser launch entirely (for HTTP-only testing)
  const skipBrowser = process.env.BROWSE_HEADLESS_SKIP === '1';
  if (!skipBrowser) {
    const headed = process.env.BROWSE_HEADED === '1';
    if (headed) {
      await browserManager.launchHeaded(envCfg.authToken);
      console.log(`[browse] Launched headed Chromium with extension`);
    } else {
      await browserManager.launch();
    }
  }

  const startTime = Date.now();

  // ─── Build the request handlers via buildFetchHandler factory ───
  // CLI path passes env-derived values; no beforeRoute hook. Phoenix uses
  // the same factory with its own cfg + overlay hook.
  const handle = buildFetchHandler({
    ...envCfg,
    browsePort: port,        // actual bound port (resolveConfigFromEnv default is 0)
    browserManager,          // module-level instance, same as today
    xvfb,
    proxyBridge,
    startTime,
    ownsTerminalAgent: true, // CLI spawns terminal-agent.ts itself (see cli.ts:1037-1063)
  });

  const server = Bun.serve({
    port,
    hostname: '127.0.0.1',
    fetch: handle.fetchLocal,
  });

  // Write state file (atomic: write .tmp then rename)
  const state: Record<string, unknown> = {
    pid: process.pid,
    port,
    token: envCfg.authToken,
    startedAt: new Date().toISOString(),
    serverPath: path.resolve(import.meta.dir, 'server.ts'),
    binaryVersion: readVersionHash() || undefined,
    mode: browserManager.getConnectionMode(),
    // D2 daemon-mismatch detection: CLI computes the same hash from its
    // resolved flags and refuses if it differs from this stored value.
    ...(process.env.BROWSE_CONFIG_HASH ? { configHash: process.env.BROWSE_CONFIG_HASH } : {}),
    // Xvfb child PID + start-time + display so disconnect (or a future
    // daemon launch on this state file) can validate-then-cleanup orphans
    // without clobbering a recycled PID.
    ...(xvfb ? { xvfbPid: xvfb.pid, xvfbStartTime: xvfb.startTime, xvfbDisplay: xvfb.display } : {}),
  };
  const tmpFile = tmpStatePath();
  fs.writeFileSync(tmpFile, JSON.stringify(state, null, 2), { mode: 0o600 });
  fs.renameSync(tmpFile, config.stateFile);

  browserManager.serverPort = port;

  // ─── Opt-in session persistence (#778 class) ─────────────────
  // BROWSE_PERSIST_STATE=1: restore cookies/storage/tabs from the last
  // snapshot, then keep snapshotting on an interval. Launched mode only —
  // the headed persistent profile owns its own state. The final snapshot at
  // clean shutdown lives in buildFetchHandler's shutdown().
  //
  // Runs AFTER Bun.serve() + the state-file write, in the BACKGROUND:
  // restore re-creates tabs sequentially with up-to-15s goto timeouts while
  // the CLI's readiness probe gives up at 8s — one slow/unreachable saved
  // URL must never make every `$B` command report "Server failed to start".
  // Fire-and-forget: a restore failure is logged and never affects the
  // daemon.
  if (!skipBrowser && isSessionPersistEnabled() && browserManager.getConnectionMode() === 'launched') {
    const sessionStatePath = path.join(config.stateDir, SESSION_STATE_FILE);
    restoreSessionState(browserManager, sessionStatePath)
      .then((restored) => {
        if (restored) {
          // Counts come from the deserialized snapshot itself — no extra
          // saveState() round-trip against pages that may still be loading.
          console.log(`[browse] Session state restored: ${restored.cookies.length} cookies / ${restored.pages.length} tabs (BROWSE_PERSIST_STATE=1)`);
        } else {
          console.log('[browse] Session persistence on; no prior state — fresh session (BROWSE_PERSIST_STATE=1)');
        }
      })
      .catch((err: any) => {
        console.warn(`[browse] SESSION_RESTORE_FAILED: ${err?.message ?? err}`);
      });
    let persistWarned = false;
    // In-flight guard: never start a new snapshot while the previous one is
    // still pending (a slow page.evaluate would otherwise pile up ticks).
    let persistInFlight = false;
    sessionPersistInterval = setInterval(() => {
      // Shutdown gate (belt; shutdown()'s clearInterval is the suspenders):
      // a tick that fires during browser teardown snapshots a degraded state
      // (zero tabs) over the good final snapshot.
      if (isShuttingDown) return;
      if (persistInFlight) return; // skip the tick
      persistInFlight = true;
      persistSessionState(browserManager, sessionStatePath)
        .catch((err: any) => {
          // Warn once — a full disk must not spam the log every 30s, and a
          // snapshot failure must never kill the daemon (R3).
          if (!persistWarned) {
            persistWarned = true;
            console.warn(`[browse] SESSION_PERSIST_FAILED: ${err?.message ?? err} (further failures suppressed)`);
          }
        })
        .finally(() => { persistInFlight = false; });
    }, sessionPersistIntervalMs());
    (sessionPersistInterval as any)?.unref?.();
  }

  // Navigate to welcome page if in headed mode and still on about:blank
  if (browserManager.getConnectionMode() === 'headed') {
    try {
      const currentUrl = browserManager.getCurrentUrl();
      if (currentUrl === 'about:blank' || currentUrl === '') {
        const page = browserManager.getPage();
        page.goto(`http://127.0.0.1:${port}/welcome`, { timeout: 3000 }).catch((err: any) => {
          console.warn('[browse] Failed to navigate to welcome page:', err.message);
        });
      }
    } catch (err: any) {
      console.warn('[browse] Welcome page navigation setup failed:', err.message);
    }
  }

  // Clean up stale state files (older than 7 days)
  try {
    const stateDir = path.join(config.stateDir, 'browse-states');
    if (fs.existsSync(stateDir)) {
      const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
      for (const file of fs.readdirSync(stateDir)) {
        const filePath = path.join(stateDir, file);
        const stat = fs.statSync(filePath);
        if (Date.now() - stat.mtimeMs > SEVEN_DAYS) {
          fs.unlinkSync(filePath);
          console.log(`[browse] Deleted stale state file: ${file}`);
        }
      }
    }
  } catch (err: any) {
    console.warn('[browse] Failed to clean stale state files:', err.message);
  }

  console.log(`[browse] Server running on http://127.0.0.1:${port} (PID: ${process.pid})`);
  console.log(`[browse] State file: ${config.stateFile}`);
  console.log(`[browse] Idle timeout: ${IDLE_TIMEOUT_MS / 1000}s`);

  // ─── Tunnel startup (optional) ────────────────────────────────
  // Start ngrok tunnel if BROWSE_TUNNEL=1 is set.  Uses the dual-listener
  // pattern: bind a dedicated tunnel listener on an ephemeral port and
  // point ngrok.forward() at IT, not the local daemon port.
  if (process.env.BROWSE_TUNNEL === '1' && !isPairAgentEnabled()) {
    console.error('[browse] BROWSE_TUNNEL=1 ignored: pair-agent is off. Enable once with: gstack-config set pair_agent on');
  } else if (process.env.BROWSE_TUNNEL === '1') {
    const authtoken = resolveNgrokAuthtoken();
    if (!authtoken) {
      console.error('[browse] BROWSE_TUNNEL=1 but no NGROK_AUTHTOKEN found. Set it via env var or ~/.gstack/ngrok.env');
    } else {
      // Shared startTunnel helper: binds the tunnel listener, opens ngrok,
      // and on any failure tears down BOTH ngrok and the Bun listener so we
      // don't leak an ngrok session if the error happened after
      // ngrok.forward() resolved.
      const started = await startTunnel({
        fetchHandler: handle.fetchTunnel,
        authtoken,
        consent: 'pair_agent=on (isPairAgentEnabled gate, BROWSE_TUNNEL=1)',
      });
      if (!started.ok) {
        console.error(`[browse] Failed to start tunnel: ${started.error.message}`);
      }
    }
  } else if (process.env.BROWSE_TUNNEL_LOCAL_ONLY === '1') {
    // Test-only: bind the dual-listener tunnel surface on 127.0.0.1 with NO
    // ngrok forwarding. Lets paid evals exercise the surface==='tunnel' gate
    // without an ngrok authtoken or live network. Production tunneling still
    // requires BROWSE_TUNNEL=1 + a valid authtoken above.
    try {
      const boundTunnel = Bun.serve({
        port: 0,
        hostname: '127.0.0.1',
        fetch: handle.fetchTunnel,
      });
      tunnelServer = boundTunnel;
      tunnelActive = true;
      const tunnelPort = boundTunnel.port;
      console.log(`[browse] Tunnel listener bound (local-only test mode) on 127.0.0.1:${tunnelPort}`);
      const stateContent = JSON.parse(fs.readFileSync(config.stateFile, 'utf-8'));
      stateContent.tunnelLocalPort = tunnelPort;
      const tmpState = tmpStatePath();
      fs.writeFileSync(tmpState, JSON.stringify(stateContent, null, 2), { mode: 0o600 });
      fs.renameSync(tmpState, config.stateFile);
    } catch (err: any) {
      console.error(`[browse] BROWSE_TUNNEL_LOCAL_ONLY=1 listener bind failed: ${err.message}`);
    }
  }
}

/**
 * Test-only. Resets the module-level shutdown latch so a second test case
 * can exercise shutdown() in the same process. Mirrors __resetRegistry in
 * token-registry.ts. shutdown() short-circuits when isShuttingDown is true
 * (see line near the start of shutdown), so without this, tests that call
 * shutdown() more than once silently no-op after the first call.
 *
 * DO NOT call from production code. Defeats the shutdown re-entry guard,
 * which can race process.exit with cfgBrowserManager.close() and the pkill /
 * safeUnlinkQuiet side effects. The `__` prefix is the convention; nothing
 * enforces it. If you find yourself reaching for this outside a test file,
 * the right fix is to make isShuttingDown factory-scoped instead.
 */
export function __resetShuttingDown(): void {
  isShuttingDown = false;
}

// Auto-kickoff only when this module is the entry point. Embedders
// (gbrowser phoenix overlay) import { start, buildFetchHandler, ... }
// without triggering the listener-binding side effects.
if (import.meta.main) {
  start().catch((err) => {
    console.error(`[browse] Failed to start: ${err.message}`);
    // Write error to disk for the CLI to read — on Windows, the CLI can't capture
    // stderr because the server is launched with detached: true, stdio: 'ignore'.
    try {
      const errorLogPath = path.join(config.stateDir, 'browse-startup-error.log');
      mkdirSecure(config.stateDir);
      writeSecureFile(errorLogPath, `${new Date().toISOString()} ${err.message}\n${err.stack || ''}\n`);
    } catch {
      // stateDir may not exist — nothing more we can do
    }
    process.exit(1);
  });
}

/**
 * Factory for expiring session-cookie registries.
 *
 * pty-session-cookie.ts and sse-session-cookie.ts were byte-identical modulo
 * the cookie name — a security-critical parser/TTL/prune implementation that
 * had to be fixed in two places (and a third hand-rolled copy of the cookie
 * parse had already diverged in terminal-agent.ts). One implementation now;
 * the two modules are thin instantiations that keep their names and their
 * distinct threat-model docstrings.
 *
 * Deliberately NOT unified here: pty-session-lease.ts — that's a different
 * contract (sessionId/secret separation, refresh, env-overridable TTL).
 *
 * SECURITY INVARIANT: this module must never import token-registry — cookie
 * session tokens must not be valid as scoped tokens (the
 * cookie-picker-auth-isolation pattern). Pinned by sse-session-cookie.test.ts.
 */
import * as crypto from 'crypto';

interface Session {
  createdAt: number;
  expiresAt: number;
}

export interface SessionCookieStore {
  mint(): { token: string; expiresAt: number };
  validate(token: string | null | undefined): boolean;
  revoke(token: string | null | undefined): void;
  extract(req: Request): string | null;
  buildSetCookie(token: string): string;
  /** Test-only reset. */
  __reset(): void;
}

export function createSessionCookieStore(opts: {
  cookieName: string;
  ttlMs: number;
  maxSessions?: number;
}): SessionCookieStore {
  const { cookieName, ttlMs } = opts;
  const maxSessions = opts.maxSessions ?? 10_000;
  const sessions = new Map<string, Session>();

  function pruneExpired(now: number): void {
    // Opportunistic cleanup: check up to 20 entries per call so we don't
    // stall on a massive registry. O(1) amortized. Runs on every mint AND
    // on every validate so a steady reconnect flow can't outpace it.
    let checked = 0;
    for (const [token, session] of sessions) {
      if (checked++ >= 20) break;
      if (session.expiresAt <= now) sessions.delete(token);
    }
    // Hard cap as a backstop — if something still gets past opportunistic
    // cleanup (e.g., all unexpired but registry enormous), drop the oldest.
    while (sessions.size > maxSessions) {
      const first = sessions.keys().next().value;
      if (!first) break;
      sessions.delete(first);
    }
  }

  return {
    mint() {
      // 32 random bytes → 43-char URL-safe base64 (no padding). 256 bits.
      const token = crypto.randomBytes(32).toString('base64url');
      const now = Date.now();
      const expiresAt = now + ttlMs;
      sessions.set(token, { createdAt: now, expiresAt });
      pruneExpired(now);
      return { token, expiresAt };
    },

    validate(token) {
      if (!token) return false;
      const s = sessions.get(token);
      if (!s) {
        pruneExpired(Date.now());
        return false;
      }
      if (Date.now() > s.expiresAt) {
        sessions.delete(token);
        pruneExpired(Date.now());
        return false;
      }
      return true;
    },

    revoke(token) {
      if (!token) return;
      sessions.delete(token);
    },

    extract(req) {
      const cookieHeader = req.headers.get('cookie');
      if (!cookieHeader) return null;
      for (const part of cookieHeader.split(';')) {
        const [name, ...valueParts] = part.trim().split('=');
        if (name === cookieName) {
          return valueParts.join('=') || null;
        }
      }
      return null;
    },

    /**
     * Set-Cookie value:
     * - HttpOnly: not readable from JS (mitigates XSS exfiltration).
     * - SameSite=Strict: not sent on cross-site requests (mitigates
     *   CSRF/CSWSH).
     * - Path=/: scope to the whole origin.
     * - Max-Age matches the TTL.
     * Secure is intentionally omitted: the daemon binds 127.0.0.1 over plain
     * HTTP; Secure would prevent the browser from ever sending it back.
     */
    buildSetCookie(token) {
      const maxAge = Math.floor(ttlMs / 1000);
      return `${cookieName}=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${maxAge}`;
    },

    __reset() {
      sessions.clear();
    },
  };
}

/**
 * Opt-in session-state persistence (#778, #2193, #1128, #1129).
 *
 * Portions copyright (c) 2026 Sina Matian, time-attack/gstack (GStack 2), MIT.
 *
 * With BROWSE_PERSIST_STATE=1, the headless daemon snapshots cookies +
 * per-tab URL/localStorage/sessionStorage to <stateDir>/session-state.json
 * on an interval and at clean shutdown, and restores it on the next launch.
 * Kills the auth-lost-on-restart class: a crash or binary-version
 * auto-restart no longer silently logs the user out of everything.
 *
 * Default OFF: cookies on disk (0600) are a real cost the user must opt
 * into. Headed mode is excluded — the persistent Chromium profile already
 * owns that state, and replaying tabs would clobber the user's window.
 *
 * Disk shape (version 1): { version, savedAt, cookies, pages[{url,
 * isActive, storage}] }. loadedHtml and owner are NEVER persisted — same
 * in-memory-only invariant as `state save|load` (meta-commands.ts): a
 * tampered file must not smuggle HTML past load-html's checks or forge tab
 * ownership.
 */

import * as fs from 'fs';
import type { BrowserManager, BrowserState } from './browser-manager';
import { writeSecureFile } from './file-permissions';
import { safeUnlinkQuiet } from './error-handling';

/** Rename a corrupt state file to .corrupt (forensic artifact) — best effort. */
function quarantineCorrupt(filePath: string): void {
  try {
    fs.renameSync(filePath, `${filePath}.corrupt`);
  } catch {
    safeUnlinkQuiet(filePath);
  }
}

export const SESSION_STATE_FILE = 'session-state.json';
export const SESSION_STATE_VERSION = 1;

/** Config gate. Documented in browse/SKILL.md ("Session persistence"). */
export function isSessionPersistEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
  return env.BROWSE_PERSIST_STATE === '1';
}

/** Persist interval (ms). Env override exists for tests. */
export function sessionPersistIntervalMs(env: NodeJS.ProcessEnv = process.env): number {
  const parsed = parseInt(env.BROWSE_PERSIST_INTERVAL_MS || '', 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 30_000;
}

/**
 * Serialize a BrowserState to the on-disk v1 shape. Strips loadedHtml,
 * loadedHtmlWaitUntil, and owner (in-memory-only invariants).
 */
export function serializeSessionState(state: BrowserState): string {
  return JSON.stringify({
    version: SESSION_STATE_VERSION,
    savedAt: new Date().toISOString(),
    cookies: state.cookies,
    pages: state.pages.map((p) => ({
      url: p.url,
      isActive: p.isActive,
      storage: p.storage,
    })),
  }, null, 2);
}

/**
 * True when a cookie domain points at an internal-network target a tampered
 * state file could use to reach localhost services, *.internal hosts, or
 * cloud metadata: `localhost`, `*.internal`, IPv4 loopback literals
 * (127.0.0.0/8), IPv6 loopback (`::1`, `[::1]`), and link-local/metadata
 * (169.254.0.0/16, which covers 169.254.169.254). Leading-dot domain
 * variants (`.127.0.0.1`) are normalized before matching. Single source of
 * truth for the persistence restore path here AND `state load`
 * (meta-commands.ts).
 */
export function isInternalCookieDomain(domain: string): boolean {
  const d = domain.startsWith('.') ? domain.slice(1) : domain;
  if (d === 'localhost' || d.endsWith('.internal')) return true;
  if (d === '::1' || d === '[::1]') return true; // IPv6 loopback
  if (/^127\./.test(d)) return true; // IPv4 loopback block
  if (/^169\.254\./.test(d)) return true; // link-local incl. cloud metadata
  return false;
}

/**
 * Cookie hygiene shared with `state load` (meta-commands.ts): drop malformed
 * cookies and internal-network domains (see isInternalCookieDomain).
 */
export function filterSessionCookies(cookies: unknown[]): BrowserState['cookies'] {
  return cookies.filter((c: any) => {
    if (typeof c !== 'object' || !c) return false;
    if (typeof c.name !== 'string' || typeof c.value !== 'string') return false;
    if (typeof c.domain !== 'string' || !c.domain) return false;
    return !isInternalCookieDomain(c.domain);
  }) as BrowserState['cookies'];
}

/**
 * Parse + validate the on-disk shape into a BrowserState. Returns null for
 * anything malformed (corrupt JSON, wrong version, missing arrays).
 * loadedHtml/owner are stripped unconditionally even if present on disk.
 */
export function deserializeSessionState(raw: string): BrowserState | null {
  let data: any;
  try {
    data = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!data || data.version !== SESSION_STATE_VERSION) return null;
  if (!Array.isArray(data.cookies) || !Array.isArray(data.pages)) return null;
  return {
    cookies: filterSessionCookies(data.cookies),
    pages: data.pages.map((p: any) => ({
      url: typeof p?.url === 'string' ? p.url : '',
      isActive: Boolean(p?.isActive),
      storage: p?.storage && typeof p.storage === 'object'
        ? {
            localStorage: typeof p.storage.localStorage === 'object' && p.storage.localStorage ? p.storage.localStorage : {},
            sessionStorage: typeof p.storage.sessionStorage === 'object' && p.storage.sessionStorage ? p.storage.sessionStorage : {},
          }
        : null,
      // NEVER accept loadedHtml / loadedHtmlWaitUntil / owner from disk.
    })),
  };
}

/**
 * Snapshot the live session to disk (0600). No-op outside launched
 * (headless) mode — the headed persistent profile owns its own state.
 */
export async function persistSessionState(bm: BrowserManager, filePath: string): Promise<void> {
  if (bm.getConnectionMode() !== 'launched') return;
  const state = await bm.saveState();
  // Atomic replace: stage the new snapshot beside the target, then rename
  // over it. A crash mid-write must never destroy the previous good
  // snapshot — surviving crashes is the point of this feature.
  const tmpPath = `${filePath}.tmp`;
  writeSecureFile(tmpPath, serializeSessionState(state));
  try {
    fs.renameSync(tmpPath, filePath);
  } catch (err) {
    safeUnlinkQuiet(tmpPath);
    throw err;
  }
}

/**
 * Restore a persisted session into a freshly launched manager. Returns the
 * restored (already-filtered) state so callers can log counts without an
 * extra saveState() round-trip, or null when there was nothing to restore
 * (missing file, or corrupt data — which is warned, quarantined, and skipped
 * rather than blocking launch). restoreState re-validates every URL before
 * navigating.
 */
export async function restoreSessionState(bm: BrowserManager, filePath: string): Promise<BrowserState | null> {
  let raw: string;
  try {
    raw = fs.readFileSync(filePath, 'utf-8');
  } catch (err: any) {
    if (err?.code === 'ENOENT') return null;
    throw err;
  }
  const state = deserializeSessionState(raw);
  if (!state) {
    // Boot fresh, keep the evidence: the corrupt file moves to .corrupt so a
    // 3-week-later bug report is reconstructable from the artifact.
    console.warn(`[browse] SESSION_STATE_INVALID: corrupt ${filePath} moved to .corrupt; starting fresh`);
    quarantineCorrupt(filePath);
    return null;
  }
  // launch() opens one blank tab; replace it rather than restoring alongside.
  await bm.closeAllPages();
  await bm.restoreState(state);
  return state;
}

/**
 * Skill-token — scoped tokens minted per `$B skill run` invocation.
 *
 * Why this exists:
 *   When `$B skill run <name>` spawns a browser-skill script, the script needs
 *   to call back into the daemon over loopback HTTP. It MUST NOT receive the
 *   daemon root token — a script that gets the root token can call any endpoint
 *   with full authority, defeating the trusted/untrusted distinction.
 *
 *   This module wraps `token-registry.ts` to mint per-spawn session tokens
 *   bound to read+write scope (the 17-cmd browser-driving surface, minus the
 *   `eval`/`js`/admin commands that live in the admin scope). The token's
 *   clientId encodes the skill name and spawn id, so revocation is
 *   deterministic when the script exits or times out.
 *
 * Lifecycle:
 *   spawn start → mintSkillToken() → set GSTACK_SKILL_TOKEN in child env
 *                                  ↓
 *   script makes HTTP calls       /command with Bearer <skill-token>
 *                                  ↓
 *   spawn exit / timeout         → revokeSkillToken() → token invalidated
 *
 * Why scopes = ['read', 'write']:
 *   These map to SCOPE_READ + SCOPE_WRITE in token-registry.ts and cover
 *   navigation, reading, and interaction commands the bulk of skills need.
 *   Excludes admin (eval/js/cookies/storage) deliberately — agent-authored
 *   skills should not get arbitrary JS execution. Phase 2 may add an opt-in
 *   `admin: true` frontmatter flag for cases that genuinely need it, gated
 *   by stronger review at skillify time.
 *
 * Zero side effects on import. Safe to import from tests.
 */

import * as crypto from 'crypto';
import { createToken, revokeToken, type ScopeCategory, type TokenInfo } from './token-registry';

/** Length of TTL slack (in seconds) past the spawn timeout. */
const TOKEN_TTL_SLACK = 30;

/** Default scopes for skill tokens. Excludes `admin` (eval/js) and `control`. */
const DEFAULT_SKILL_SCOPES: ScopeCategory[] = ['read', 'write'];

/** Generate a fresh spawn id. Caller passes this to spawn AND revoke. */
export function generateSpawnId(): string {
  return crypto.randomBytes(8).toString('hex');
}

/** Build the canonical clientId for a skill spawn. */
export function skillClientId(skillName: string, spawnId: string): string {
  return `skill:${skillName}:${spawnId}`;
}

export interface MintSkillTokenOptions {
  skillName: string;
  spawnId: string;
  /** Spawn timeout in seconds. Token TTL = timeout + 30s slack. */
  spawnTimeoutSeconds: number;
  /**
   * Override the default scopes. Phase 1 callers should not pass this; reserved
   * for future opt-in flags (e.g. an `admin: true` frontmatter for trusted
   * human-authored skills that need eval/js).
   */
  scopes?: ScopeCategory[];
}

/**
 * Mint a fresh scoped token for a skill spawn.
 *
 * Returns the token info; the caller passes `info.token` to the child via the
 * GSTACK_SKILL_TOKEN env var. The clientId is deterministic from skillName +
 * spawnId so the corresponding `revokeSkillToken()` always finds the right
 * record.
 */
export function mintSkillToken(opts: MintSkillTokenOptions): TokenInfo {
  const clientId = skillClientId(opts.skillName, opts.spawnId);
  return createToken({
    clientId,
    scopes: opts.scopes ?? DEFAULT_SKILL_SCOPES,
    tabPolicy: 'shared',          // skill scripts may switch tabs as needed
    rateLimit: 0,                  // skill scripts can run as fast as the daemon allows
    expiresSeconds: opts.spawnTimeoutSeconds + TOKEN_TTL_SLACK,
  });
}

/**
 * Revoke the token for a finished spawn. Idempotent — revoking an already-revoked
 * token returns false but is not an error.
 */
export function revokeSkillToken(skillName: string, spawnId: string): boolean {
  return Boolean(revokeToken(skillClientId(skillName, spawnId)));
}

/**
 * Snapshot command — accessibility tree with ref-based element selection
 *
 * Architecture (Locator map — no DOM mutation):
 *   1. page.locator(scope).ariaSnapshot() → YAML-like accessibility tree
 *   2. Parse tree, assign refs @e1, @e2, ...
 *   3. Build Playwright Locator for each ref (getByRole + nth)
 *   4. Store Map<string, Locator> on BrowserManager
 *   5. Return compact text output with refs prepended
 *
 * Extended features:
 *   --diff / -D:       Compare against last snapshot, return unified diff
 *   --annotate / -a:   Screenshot with overlay boxes at each @ref
 *   --output / -o:     Output path for annotated screenshot
 *   -C / --cursor-interactive: Scan for cursor:pointer/onclick/tabindex elements
 *
 * Later: "click @e3" → look up Locator → locator.click()
 */

import type { Page, Frame, Locator } from 'playwright';
import type { TabSession, RefEntry } from './tab-session';
import * as Diff from 'diff';
import { TEMP_DIR, isPathWithin } from './platform';
import { escapeEnvelopeSentinels } from './content-security';
import { stripLoneSurrogates } from './sanitize';
import { guardScreenshotPath } from './screenshot-size-guard';

// Roles considered "interactive" for the -i flag
const INTERACTIVE_ROLES = new Set([
  'button', 'link', 'textbox', 'checkbox', 'radio', 'combobox',
  'listbox', 'menuitem', 'menuitemcheckbox', 'menuitemradio',
  'option', 'searchbox', 'slider', 'spinbutton', 'switch', 'tab',
  'treeitem',
]);

interface SnapshotOptions {
  interactive?: boolean;       // -i: only interactive elements
  compact?: boolean;           // -c: remove empty structural elements
  depth?: number;              // -d N: limit tree depth
  selector?: string;           // -s SEL: scope to CSS selector
  diff?: boolean;              // -D / --diff: diff against last snapshot
  annotate?: boolean;          // -a / --annotate: annotated screenshot
  outputPath?: string;         // -o / --output: path for annotated screenshot
  cursorInteractive?: boolean; // -C / --cursor-interactive: scan cursor:pointer etc.
  heatmap?: string;            // -H / --heatmap: JSON color map for ref overlays
}

/**
 * Snapshot flag metadata — single source of truth for CLI parsing and doc generation.
 *
 * Imported by:
 *   - gen-skill-docs.ts (generates {{SNAPSHOT_FLAGS}} tables)
 *   - skill-parser.ts (validates flags in SKILL.md examples)
 */
export const SNAPSHOT_FLAGS: Array<{
  short: string;
  long: string;
  description: string;
  takesValue?: boolean;
  valueHint?: string;
  optionKey: keyof SnapshotOptions;
}> = [
  { short: '-i', long: '--interactive', description: 'Interactive elements only (buttons, links, inputs) with @e refs. Also auto-enables cursor-interactive scan (-C) to capture dropdowns and popovers.', optionKey: 'interactive' },
  { short: '-c', long: '--compact', description: 'Compact (no empty structural nodes)', optionKey: 'compact' },
  { short: '-d', long: '--depth', description: 'Limit tree depth (0 = root only, default: unlimited)', takesValue: true, valueHint: '<N>', optionKey: 'depth' },
  { short: '-s', long: '--selector', description: 'Scope to CSS selector', takesValue: true, valueHint: '<sel>', optionKey: 'selector' },
  { short: '-D', long: '--diff', description: 'Unified diff against previous snapshot (first call stores baseline)', optionKey: 'diff' },
  { short: '-a', long: '--annotate', description: 'Annotated screenshot with red overlay boxes and ref labels', optionKey: 'annotate' },
  { short: '-o', long: '--output', description: 'Output path for annotated screenshot (default: <temp>/browse-annotated.png)', takesValue: true, valueHint: '<path>', optionKey: 'outputPath' },
  { short: '-C', long: '--cursor-interactive', description: 'Cursor-interactive elements (@c refs — divs with pointer, onclick). Auto-enabled when -i is used.', optionKey: 'cursorInteractive' },
  { short: '-H', long: '--heatmap', description: 'Color-coded overlay screenshot from JSON map: \'{"@e1":"green","@e3":"red"}\'. Valid colors: green, yellow, red, blue, orange, gray.', takesValue: true, valueHint: '<json>', optionKey: 'heatmap' },
];

interface ParsedNode {
  indent: number;
  role: string;
  name: string | null;
  props: string;      // e.g., "[level=1]"
  children: string;   // inline text content after ":"
  rawLine: string;
}

/**
 * Parse CLI args into SnapshotOptions — driven by SNAPSHOT_FLAGS metadata.
 */
export function parseSnapshotArgs(args: string[]): SnapshotOptions {
  const opts: SnapshotOptions = {};
  for (let i = 0; i < args.length; i++) {
    const flag = SNAPSHOT_FLAGS.find(f => f.short === args[i] || f.long === args[i]);
    if (!flag) throw new Error(`Unknown snapshot flag: ${args[i]}`);
    if (flag.takesValue) {
      const value = args[++i];
      if (!value) throw new Error(`Usage: snapshot ${flag.short} <value>`);
      if (flag.optionKey === 'depth') {
        (opts as any)[flag.optionKey] = parseInt(value, 10);
        if (isNaN(opts.depth!)) throw new Error('Usage: snapshot -d <number>');
      } else {
        (opts as any)[flag.optionKey] = value;
      }
    } else {
      (opts as any)[flag.optionKey] = true;
    }
  }
  return opts;
}

/**
 * Parse one line of ariaSnapshot output.
 *
 * Format examples:
 *   - heading "Test" [level=1]
 *   - link "Link A":
 *     - /url: /a
 *   - textbox "Name"
 *   - paragraph: Some text
 *   - combobox "Role":
 */
function parseLine(line: string): ParsedNode | null {
  // Match: (indent)(- )(role)( "name")?( [props])?(: inline)?
  const match = line.match(/^(\s*)-\s+(\w+)(?:\s+"([^"]*)")?(?:\s+(\[.*?\]))?\s*(?::\s*(.*))?$/);
  if (!match) {
    // Skip metadata lines like "- /url: /a"
    return null;
  }
  return {
    indent: match[1].length,
    role: match[2],
    name: match[3] ?? null,
    props: match[4] || '',
    children: match[5]?.trim() || '',
    rawLine: line,
  };
}

/**
 * Take an accessibility snapshot and build the ref map.
 */
export async function handleSnapshot(
  args: string[],
  session: TabSession,
  securityOpts?: { splitForScoped?: boolean },
): Promise<string> {
  const opts = parseSnapshotArgs(args);
  const page = session.getPage();
  // Frame-aware target for accessibility tree
  const target = session.getActiveFrameOrPage();
  const inFrame = session.getFrame() !== null;

  // Get accessibility tree via ariaSnapshot
  let rootLocator: Locator;
  if (opts.selector) {
    rootLocator = target.locator(opts.selector);
    const count = await rootLocator.count();
    if (count === 0) throw new Error(`Selector not found: ${opts.selector}`);
  } else {
    rootLocator = target.locator('body');
  }

  const ariaText = await rootLocator.ariaSnapshot();
  if (!ariaText || ariaText.trim().length === 0) {
    session.setRefMap(new Map());
    return '(no accessible elements found)';
  }

  // Parse the ariaSnapshot output
  const lines = ariaText.split('\n');
  const refMap = new Map<string, RefEntry>();
  const output: string[] = [];
  let refCounter = 1;

  // Track role+name occurrences for nth() disambiguation
  const roleNameCounts = new Map<string, number>();
  const roleNameSeen = new Map<string, number>();

  // First pass: count role+name pairs for disambiguation
  for (const line of lines) {
    const node = parseLine(line);
    if (!node) continue;
    const key = `${node.role}:${node.name || ''}`;
    roleNameCounts.set(key, (roleNameCounts.get(key) || 0) + 1);
  }

  // Second pass: assign refs and build locators
  for (const line of lines) {
    const node = parseLine(line);
    if (!node) continue;

    const depth = Math.floor(node.indent / 2);
    const isInteractive = INTERACTIVE_ROLES.has(node.role);

    // Depth filter
    if (opts.depth !== undefined && depth > opts.depth) continue;

    // Interactive filter: skip non-interactive but still count for locator indices
    if (opts.interactive && !isInteractive) {
      // Still track for nth() counts
      const key = `${node.role}:${node.name || ''}`;
      roleNameSeen.set(key, (roleNameSeen.get(key) || 0) + 1);
      continue;
    }

    // Compact filter: skip elements with no name and no inline content that aren't interactive
    if (opts.compact && !isInteractive && !node.name && !node.children) continue;

    // Assign ref
    const ref = `e${refCounter++}`;
    const indent = '  '.repeat(depth);

    // Build Playwright locator
    const key = `${node.role}:${node.name || ''}`;
    const seenIndex = roleNameSeen.get(key) || 0;
    roleNameSeen.set(key, seenIndex + 1);
    const totalCount = roleNameCounts.get(key) || 1;

    let locator: Locator;
    if (opts.selector) {
      locator = target.locator(opts.selector).getByRole(node.role as any, {
        name: node.name || undefined,
      });
    } else {
      locator = target.getByRole(node.role as any, {
        name: node.name || undefined,
      });
    }

    // Disambiguate with nth() if multiple elements share role+name
    if (totalCount > 1) {
      locator = locator.nth(seenIndex);
    }

    refMap.set(ref, { locator, role: node.role, name: node.name || '' });

    // Format output line
    let outputLine = `${indent}@${ref} [${node.role}]`;
    if (node.name) outputLine += ` "${node.name}"`;
    if (node.props) outputLine += ` ${node.props}`;
    if (node.children) outputLine += `: ${node.children}`;

    output.push(outputLine);
  }

  // ─── Cursor-interactive scan (-C, or auto with -i) ────────
  // Auto-enable cursor scan when interactive mode is on — agents asking for
  // interactive elements should always see clickable non-ARIA items too.
  if (opts.interactive && !opts.cursorInteractive) {
    opts.cursorInteractive = true;
  }
  if (opts.cursorInteractive) {
    try {
      const cursorElements = await target.evaluate(() => {
        const STANDARD_INTERACTIVE = new Set([
          'A', 'BUTTON', 'INPUT', 'SELECT', 'TEXTAREA', 'SUMMARY', 'DETAILS',
        ]);

        const results: Array<{ selector: string; text: string; reason: string }> = [];
        const allElements = document.querySelectorAll('*');

        for (const el of allElements) {
          // Skip standard interactive elements (already in ARIA tree)
          if (STANDARD_INTERACTIVE.has(el.tagName)) continue;
          // Skip hidden elements
          if (!(el as HTMLElement).offsetParent && el.tagName !== 'BODY') continue;

          const style = getComputedStyle(el);
          const hasCursorPointer = style.cursor === 'pointer';
          const hasOnclick = el.hasAttribute('onclick');
          const hasTabindex = el.hasAttribute('tabindex') && parseInt(el.getAttribute('tabindex')!, 10) >= 0;
          const hasRole = el.hasAttribute('role');

          // Check if element is inside a floating container (portal/popover/dropdown)
          const isInFloating = (() => {
            let parent: Element | null = el;
            while (parent && parent !== document.documentElement) {
              const pStyle = getComputedStyle(parent);
              const isFloating = (pStyle.position === 'fixed' || pStyle.position === 'absolute') &&
                parseInt(pStyle.zIndex || '0', 10) >= 10;
              const hasPortalAttr = parent.hasAttribute('data-floating-ui-portal') ||
                parent.hasAttribute('data-radix-popper-content-wrapper') ||
                parent.hasAttribute('data-radix-portal') ||
                parent.hasAttribute('data-popper-placement') ||
                parent.getAttribute('role') === 'listbox' ||
                parent.getAttribute('role') === 'menu';
              if (isFloating || hasPortalAttr) return true;
              parent = parent.parentElement;
            }
            return false;
          })();

          if (!hasCursorPointer && !hasOnclick && !hasTabindex) {
            // For elements inside floating containers, also check for role="option"/"menuitem"
            if (isInFloating && hasRole) {
              const role = el.getAttribute('role');
              if (role !== 'option' && role !== 'menuitem' && role !== 'menuitemcheckbox' && role !== 'menuitemradio') continue;
            } else {
              continue;
            }
          }
          // Skip elements with ARIA roles UNLESS they're inside a floating container
          // (floating container items may be missed by the accessibility tree)
          if (hasRole && !isInFloating) continue;

          // Build deterministic nth-child CSS path
          const parts: string[] = [];
          let current: Element | null = el;
          while (current && current !== document.documentElement) {
            const parent = current.parentElement;
            if (!parent) break;
            const siblings = [...parent.children];
            const index = siblings.indexOf(current) + 1;
            parts.unshift(`${current.tagName.toLowerCase()}:nth-child(${index})`);
            current = parent;
          }
          const selector = parts.join(' > ');

          const text = (el as HTMLElement).innerText?.trim().slice(0, 80) || el.tagName.toLowerCase();
          const reasons: string[] = [];
          if (isInFloating) reasons.push('popover-child');
          if (hasCursorPointer) reasons.push('cursor:pointer');
          if (hasOnclick) reasons.push('onclick');
          if (hasTabindex) reasons.push(`tabindex=${el.getAttribute('tabindex')}`);
          if (hasRole) reasons.push(`role=${el.getAttribute('role')}`);

          results.push({ selector, text, reason: reasons.join(', ') });
        }
        return results;
      });

      if (cursorElements.length > 0) {
        output.push('');
        output.push('── cursor-interactive (not in ARIA tree) ──');
        let cRefCounter = 1;
        for (const elem of cursorElements) {
          const ref = `c${cRefCounter++}`;
          const locator = target.locator(elem.selector);
          refMap.set(ref, { locator, role: 'cursor-interactive', name: elem.text });
          output.push(`@${ref} [${elem.reason}] "${elem.text}"`);
        }
      }
    } catch (err: any) {
      // Cursor scan fails on pages with strict CSP or when page has navigated
      if (!err?.message?.includes('Execution context') && !err?.message?.includes('closed') && !err?.message?.includes('Target') && !err?.message?.includes('Content Security')) throw err;
      output.push('');
      output.push('(cursor scan failed — CSP restriction)');
    }
  }

  // Store ref map on BrowserManager
  session.setRefMap(refMap);

  if (output.length === 0) {
    return '(no interactive elements found)';
  }

  const snapshotText = output.join('\n');

  // `-o` only means something to the two modes that PRODUCE an image. Passed
  // alone it used to be silently ignored: exit 0, no file, no explanation —
  // which reads as "the screenshot feature is broken" rather than "you forgot a
  // flag", and cost a real debugging session before anyone noticed. Kept as a
  // variable so the diff-mode returns below (which bypass `output`) can carry
  // it too — diff mode must not regress to the silent-ignore behavior.
  const outputIgnoredWarning = (opts.outputPath && !opts.annotate && !opts.heatmap)
    ? `[warning] -o/--output was ignored: it names the output file for an annotated (-a/--annotate) or heatmap (-H/--heatmap) screenshot. For a plain screenshot use: browse screenshot ${opts.outputPath}`
    : '';
  if (outputIgnoredWarning) {
    output.push(outputIgnoredWarning);
  }

  // ─── Annotated screenshot (-a) ────────────────────────────
  if (opts.annotate) {
    const screenshotPath = opts.outputPath || `${TEMP_DIR}/browse-annotated.png`;
    // Validate output path — resolve symlinks to prevent symlink traversal attacks
    {
      const nodePath = require('path') as typeof import('path');
      const nodeFs = require('fs') as typeof import('fs');
      const absolute = nodePath.resolve(screenshotPath);
      const safeDirs = [TEMP_DIR, process.cwd()].map((d: string) => {
        try { return nodeFs.realpathSync(d); } catch (err: any) { if (err?.code !== 'ENOENT') throw err; return d; }
      });
      let realPath: string;
      try {
        realPath = nodeFs.realpathSync(absolute);
      } catch (err: any) {
        if (err.code === 'ENOENT') {
          try {
            const dir = nodeFs.realpathSync(nodePath.dirname(absolute));
            realPath = nodePath.join(dir, nodePath.basename(absolute));
          } catch (err2: any) {
            if (err2?.code !== 'ENOENT') throw err2;
            realPath = absolute;
          }
        } else {
          throw new Error(`Cannot resolve real path: ${screenshotPath} (${err.code})`);
        }
      }
      if (!safeDirs.some((dir: string) => isPathWithin(realPath, dir))) {
        throw new Error(`Path must be within: ${safeDirs.join(', ')}`);
      }
    }
    try {
      // Inject overlay divs at each ref's bounding box
      const boxes: Array<{ ref: string; box: { x: number; y: number; width: number; height: number } }> = [];
      const ambiguousRefs: string[] = [];
      const skippedRefs: string[] = [];
      for (const [ref, entry] of refMap) {
        try {
          // A ref's locator can resolve to MORE than one element, and Playwright
          // strict mode throws on that. It happens whenever a node has no
          // accessible name: the locator degrades to `getByRole(role)` with no
          // name filter, and the `.nth()` disambiguation above cannot help
          // because its count comes from the FILTERED aria snapshot while
          // getByRole matches the unfiltered DOM. Measured on a real page: the
          // tree surfaced 2 unnamed paragraphs, the DOM had 9. Landmarks
          // (banner/main/contentinfo) and paragraphs are correctly unnamed per
          // ARIA, so this is the common case, not an edge.
          //
          // The exact nth-resolved locator stays the primary path; `.first()`
          // is the AMBIGUITY FALLBACK only, and every fallback use is counted
          // so first-match annotation is never silent. Before this, ONE such
          // ref aborted the entire annotated screenshot (see the catch below) —
          // which silently cost /qa, /canary and /land-and-deploy the
          // screenshots their reports reference.
          let locator = entry.locator;
          const matchCount = await locator.count();
          if (matchCount > 1) {
            ambiguousRefs.push(`@${ref}`);
            locator = locator.first();
          }
          const box = await locator.boundingBox({ timeout: 1000 });
          if (box) {
            boxes.push({ ref: `@${ref}`, box });
          } else {
            skippedRefs.push(`@${ref}`);
          }
        } catch (err: any) {
          // Element may be offscreen, hidden, or page navigated — skip.
          //
          // The allowlist is deliberately not exhaustive-by-message any more: a
          // box we cannot measure is a box we do not draw, never a reason to
          // lose every other annotation on the page. The heatmap path below has
          // always used a bare `catch {}` for exactly this reason; annotate was
          // the only path that could be killed by a single unmeasurable ref.
          skippedRefs.push(`@${ref}`);
          if (process.env.BROWSE_DEBUG) console.error(`[annotate] skipped @${ref}: ${err?.message?.split('\n')[0]}`);
        }
      }

      await page.evaluate((boxes) => {
        for (const { ref, box } of boxes) {
          const overlay = document.createElement('div');
          overlay.className = '__browse_annotation__';
          overlay.style.cssText = `
            position: absolute; top: ${box.y}px; left: ${box.x}px;
            width: ${box.width}px; height: ${box.height}px;
            border: 2px solid red; background: rgba(255,0,0,0.1);
            pointer-events: none; z-index: 99999;
            font-size: 10px; color: red; font-weight: bold;
          `;
          const label = document.createElement('span');
          label.textContent = ref;
          label.style.cssText = 'position: absolute; top: -14px; left: 0; background: red; color: white; padding: 0 3px; font-size: 10px;';
          overlay.appendChild(label);
          document.body.appendChild(overlay);
        }
      }, boxes);

      await page.screenshot({ path: screenshotPath, fullPage: true });
      await guardScreenshotPath(screenshotPath);

      // Always remove overlays
      await page.evaluate(() => {
        document.querySelectorAll('.__browse_annotation__').forEach(el => el.remove());
      });

      output.push('');
      output.push(`[annotated screenshot: ${screenshotPath}]`);
      // Ambiguity and skips are visible, not buried behind BROWSE_DEBUG: a
      // first-match box or a missing box changes what the screenshot claims.
      if (ambiguousRefs.length || skippedRefs.length) {
        const cap = (arr: string[]) => arr.slice(0, 8).join(', ') + (arr.length > 8 ? `, +${arr.length - 8} more` : '');
        const parts: string[] = [];
        if (ambiguousRefs.length) parts.push(`${ambiguousRefs.length} ambiguous (first-match): ${cap(ambiguousRefs)}`);
        if (skippedRefs.length) parts.push(`${skippedRefs.length} skipped: ${cap(skippedRefs)}`);
        output.push(`[annotated: ${parts.join(' | ')}]`);
      }
    } catch (err: any) {
      // Remove overlays even on screenshot failure — but only swallow page/browser errors
      if (!err?.message?.includes('closed') && !err?.message?.includes('Target') && !err?.message?.includes('Execution context') && !err?.message?.includes('screenshot')) throw err;
      try {
        await page.evaluate(() => {
          document.querySelectorAll('.__browse_annotation__').forEach(el => el.remove());
        });
      } catch (err2: any) {
        if (!err2?.message?.includes('closed') && !err2?.message?.includes('Target') && !err2?.message?.includes('Execution context')) throw err2;
      }
    }
  }

  // ─── Heatmap mode (-H) ──────────────────────────────────────
  if (opts.heatmap) {
    const heatmapPath = opts.outputPath || `${TEMP_DIR}/browse-heatmap.png`;
    // Validate output path
    {
      const nodePath = require('path') as typeof import('path');
      const nodeFs = require('fs') as typeof import('fs');
      const absolute = nodePath.resolve(heatmapPath);
      const safeDirs = [TEMP_DIR, process.cwd()].map((d: string) => {
        try { return nodeFs.realpathSync(d); } catch (err: any) { if (err?.code !== 'ENOENT') throw err; return d; }
      });
      let realPath: string;
      try {
        realPath = nodeFs.realpathSync(absolute);
      } catch (err: any) {
        if (err.code === 'ENOENT') {
          try {
            const dir = nodeFs.realpathSync(nodePath.dirname(absolute));
            realPath = nodePath.join(dir, nodePath.basename(absolute));
          } catch (err2: any) {
            if (err2?.code !== 'ENOENT') throw err2;
            realPath = absolute;
          }
        } else {
          throw new Error(`Cannot resolve real path: ${heatmapPath} (${err.code})`);
        }
      }
      if (!safeDirs.some((dir: string) => isPathWithin(realPath, dir))) {
        throw new Error(`Path must be within: ${safeDirs.join(', ')}`);
      }
    }

    // Parse and validate color map
    const VALID_COLORS = new Set(['green', 'yellow', 'red', 'blue', 'orange', 'gray']);
    const COLOR_MAP: Record<string, { border: string; bg: string }> = {
      green:  { border: '#00b400', bg: 'rgba(0,180,0,0.15)' },
      yellow: { border: '#ffb400', bg: 'rgba(255,180,0,0.15)' },
      red:    { border: '#ff0000', bg: 'rgba(255,0,0,0.15)' },
      blue:   { border: '#0066ff', bg: 'rgba(0,102,255,0.15)' },
      orange: { border: '#ff6600', bg: 'rgba(255,102,0,0.15)' },
      gray:   { border: '#888888', bg: 'rgba(136,136,136,0.15)' },
    };

    let colorAssignments: Record<string, string>;
    try {
      const parsed = JSON.parse(opts.heatmap);
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        throw new Error('not an object');
      }
      colorAssignments = parsed;
    } catch {
      throw new Error('Invalid heatmap JSON. Expected object: \'{"@e1":"green","@e3":"red"}\'');
    }

    // Validate colors
    for (const [ref, color] of Object.entries(colorAssignments)) {
      if (!VALID_COLORS.has(color)) {
        throw new Error(`Invalid heatmap color "${color}" for ${ref}. Valid: ${[...VALID_COLORS].join(', ')}`);
      }
    }

    try {
      const boxes: Array<{ ref: string; box: { x: number; y: number; width: number; height: number }; color: string }> = [];
      for (const [refKey, color] of Object.entries(colorAssignments)) {
        const cleanRef = refKey.startsWith('@') ? refKey.slice(1) : refKey;
        const entry = refMap.get(cleanRef);
        if (!entry) continue; // Skip refs not found on page
        try {
          const box = await entry.locator.boundingBox({ timeout: 1000 });
          if (box) {
            const colors = COLOR_MAP[color] || COLOR_MAP.gray;
            boxes.push({ ref: `@${cleanRef}`, box, color: JSON.stringify(colors) });
          }
        } catch {
          // Element may be offscreen or hidden — skip
        }
      }

      await page.evaluate((boxes) => {
        for (const { ref, box, color } of boxes) {
          const colors = JSON.parse(color);
          const overlay = document.createElement('div');
          overlay.className = '__browse_heatmap__';
          overlay.style.cssText = `
            position: absolute; top: ${box.y}px; left: ${box.x}px;
            width: ${box.width}px; height: ${box.height}px;
            border: 2px solid ${colors.border}; background: ${colors.bg};
            pointer-events: none; z-index: 99999;
            font-size: 10px; color: ${colors.border}; font-weight: bold;
          `;
          const label = document.createElement('span');
          label.textContent = ref;
          label.style.cssText = `position: absolute; top: -14px; left: 0; background: ${colors.border}; color: white; padding: 0 3px; font-size: 10px;`;
          overlay.appendChild(label);
          document.body.appendChild(overlay);
        }
      }, boxes);

      await page.screenshot({ path: heatmapPath, fullPage: true });
      await guardScreenshotPath(heatmapPath);

      // Remove heatmap overlays
      await page.evaluate(() => {
        document.querySelectorAll('.__browse_heatmap__').forEach(el => el.remove());
      });

      output.push('');
      output.push(`[heatmap screenshot: ${heatmapPath}]`);
    } catch (err: any) {
      // Cleanup on failure
      try {
        await page.evaluate(() => {
          document.querySelectorAll('.__browse_heatmap__').forEach(el => el.remove());
        });
      } catch {}
      if (!err?.message?.includes('closed') && !err?.message?.includes('Target') && !err?.message?.includes('Execution context') && !err?.message?.includes('screenshot')) throw err;
    }
  }

  // ─── Diff mode (-D) ───────────────────────────────────────
  if (opts.diff) {
    const lastSnapshot = session.getLastSnapshot();
    if (!lastSnapshot) {
      session.setLastSnapshot(snapshotText);
      return snapshotText + '\n\n(no previous snapshot to diff against — this snapshot stored as baseline)'
        + (outputIgnoredWarning ? '\n' + outputIgnoredWarning : '');
    }

    const changes = Diff.diffLines(lastSnapshot, snapshotText);
    const diffOutput: string[] = ['--- previous snapshot', '+++ current snapshot', ''];

    for (const part of changes) {
      const prefix = part.added ? '+' : part.removed ? '-' : ' ';
      const diffLines = part.value.split('\n').filter(l => l.length > 0);
      for (const line of diffLines) {
        diffOutput.push(`${prefix} ${line}`);
      }
    }

    session.setLastSnapshot(snapshotText);
    return stripLoneSurrogates(diffOutput.join('\n')
      + (outputIgnoredWarning ? '\n' + outputIgnoredWarning : ''));
  }

  // Store for future diffs
  session.setLastSnapshot(snapshotText);

  // Add frame context header when operating inside an iframe
  if (inFrame) {
    const frameUrl = session.getFrame()?.url() ?? 'unknown';
    output.unshift(`[Context: iframe src="${frameUrl}"]`);
  }

  // Split output for scoped tokens: trusted refs + untrusted text
  if (securityOpts?.splitForScoped) {
    const trustedRefs: string[] = [];
    const untrustedLines: string[] = [];

    for (const line of output) {
      // Lines starting with @ref are interactive elements (trusted metadata)
      const refMatch = line.match(/^(\s*)@(e\d+|c\d+)\s+\[([^\]]+)\]\s*(.*)/);
      if (refMatch) {
        const [, indent, ref, role, rest] = refMatch;
        // Truncate element name/content to 50 chars for trusted section
        const nameMatch = rest.match(/^"(.+?)"/);
        let truncName = nameMatch ? nameMatch[1] : rest.trim();
        if (truncName.length > 50) truncName = truncName.slice(0, 47) + '...';
        trustedRefs.push(`${indent}@${ref} [${role}] "${truncName}"`);
      }
      // All lines go to untrusted section (full content)
      untrustedLines.push(line);
    }

    const parts: string[] = [];
    if (trustedRefs.length > 0) {
      parts.push('INTERACTIVE ELEMENTS (trusted — use these @refs for click/fill):');
      parts.push(...trustedRefs);
      parts.push('');
    }
    // Defuse any envelope sentinel that appears inside the page's own
    // accessibility text. Without this, a page whose rendered content
    // contains the literal `═══ END UNTRUSTED WEB CONTENT ═══` string
    // can close the envelope early and forge a fake "trusted" block
    // for the LLM. Same escape that wrapUntrustedPageContent applies.
    const safeUntrusted = untrustedLines.map(escapeEnvelopeSentinels);
    parts.push('═══ BEGIN UNTRUSTED WEB CONTENT ═══');
    parts.push(...safeUntrusted);
    parts.push('═══ END UNTRUSTED WEB CONTENT ═══');
    return stripLoneSurrogates(parts.join('\n'));
  }

  return stripLoneSurrogates(output.join('\n'));
}

/**
 * Local SOCKS5 bridge — accepts unauthenticated connections on 127.0.0.1:<ephemeral>
 * and relays them through an authenticated upstream SOCKS5 proxy.
 *
 * Why this exists: Chromium does not prompt for SOCKS5 auth at launch. To use
 * an auth-required upstream (residential SOCKS5 from a VPN provider, for
 * example), we run a no-auth listener locally that the browser talks to, and
 * the bridge handles the auth handshake with upstream.
 *
 * Architecture:
 *   Chromium  →  socks5://127.0.0.1:<ephemeral>  (this bridge, no auth)
 *                  └→ authenticated SOCKS5 to upstream  →  destination
 *
 * Ported from wintermute's scripts/socks-bridge.mjs with TS types, ephemeral
 * port (no hardcoded 1090), 127.0.0.1-only bind, and a stream-error policy
 * that closes the affected client connection without transport retries (a
 * SOCKS bridge is transport, not request-aware — retries can corrupt browser
 * traffic mid-stream).
 */

import * as net from 'net';
import { SocksClient, type SocksProxy } from 'socks';

export interface UpstreamConfig {
  host: string;
  port: number;
  userId?: string;
  password?: string;
}

export interface BridgeHandle {
  /** Local port the bridge is listening on (ephemeral). */
  port: number;
  /** Underlying server. Exposed for tests; production code uses close(). */
  server: net.Server;
  /** Close the listener and all in-flight client sockets. */
  close: () => Promise<void>;
}

const SOCKS5_VERSION = 0x05;
const NO_AUTH_METHOD = 0x00;
const CMD_CONNECT = 0x01;
const ATYP_IPV4 = 0x01;
const ATYP_DOMAINNAME = 0x03;
const ATYP_IPV6 = 0x04;
const REPLY_SUCCESS = 0x00;
const REPLY_GENERAL_FAILURE = 0x01;
const REPLY_HOST_UNREACHABLE = 0x04;
const UPSTREAM_CONNECT_TIMEOUT_MS = 15000;

function buildUpstream(upstream: UpstreamConfig): SocksProxy {
  return {
    host: upstream.host,
    port: upstream.port,
    type: 5,
    ...(upstream.userId ? { userId: upstream.userId } : {}),
    ...(upstream.password ? { password: upstream.password } : {}),
  };
}

function parseConnectRequest(reqData: Buffer): { host: string; port: number } | null {
  if (reqData.length < 7 || reqData[0] !== SOCKS5_VERSION || reqData[1] !== CMD_CONNECT) {
    return null;
  }
  const atyp = reqData[3];
  if (atyp === ATYP_IPV4) {
    if (reqData.length < 10) return null;
    const host = `${reqData[4]}.${reqData[5]}.${reqData[6]}.${reqData[7]}`;
    const port = reqData.readUInt16BE(8);
    return { host, port };
  }
  if (atyp === ATYP_DOMAINNAME) {
    const len = reqData[4];
    if (reqData.length < 5 + len + 2) return null;
    const host = reqData.subarray(5, 5 + len).toString('utf8');
    const port = reqData.readUInt16BE(5 + len);
    return { host, port };
  }
  if (atyp === ATYP_IPV6) {
    if (reqData.length < 22) return null;
    const parts: string[] = [];
    for (let i = 4; i < 20; i += 2) parts.push(reqData.readUInt16BE(i).toString(16));
    const host = parts.join(':');
    const port = reqData.readUInt16BE(20);
    return { host, port };
  }
  return null;
}

function writeReply(sock: net.Socket, code: number): void {
  // SOCKS5 reply: VER REP RSV ATYP BND.ADDR(0.0.0.0) BND.PORT(0)
  const reply = Buffer.from([SOCKS5_VERSION, code, 0x00, ATYP_IPV4, 0, 0, 0, 0, 0, 0]);
  try { sock.write(reply); } catch { /* peer already gone */ }
}

/**
 * Start a local SOCKS5 bridge that relays to an authenticated upstream.
 * Listens on 127.0.0.1 only (never 0.0.0.0). port: 0 picks an ephemeral port.
 *
 * Stream-error policy: on any error during a relayed connection, the affected
 * client socket and its upstream pair are destroyed. No transport retries.
 * Browser sees a proxy/connection error and surfaces it as such.
 */
export async function startSocksBridge(opts: {
  upstream: UpstreamConfig;
  port?: number;
}): Promise<BridgeHandle> {
  const upstreamProxy = buildUpstream(opts.upstream);
  const requestedPort = opts.port ?? 0;
  const inFlight = new Set<net.Socket>();

  // Frame-size predicates for the two SOCKS5 messages we read from the
  // client. Both return null when we don't yet have enough bytes to know
  // the frame size, or a positive integer when we do.
  function greetingSize(buf: Buffer): number | null {
    if (buf.length < 2) return null;
    return 2 + buf[1]; // VER NMETHODS + N method bytes
  }
  function connectSize(buf: Buffer): number | null {
    if (buf.length < 5) return null;
    const atyp = buf[3];
    if (atyp === ATYP_IPV4) return 10;        // VER CMD RSV ATYP + 4 + 2
    if (atyp === ATYP_IPV6) return 22;        // VER CMD RSV ATYP + 16 + 2
    if (atyp === ATYP_DOMAINNAME) return 7 + buf[4]; // VER CMD RSV ATYP LEN + N + 2
    return null;
  }

  type State = 'greeting' | 'connect' | 'connecting' | 'piped' | 'closed';

  const server = net.createServer((clientSocket) => {
    inFlight.add(clientSocket);
    clientSocket.once('close', () => inFlight.delete(clientSocket));

    let state: State = 'greeting';
    let buf = Buffer.alloc(0);
    let upstreamSocket: net.Socket | null = null;

    const killBoth = (reason?: string) => {
      void reason;
      state = 'closed';
      try { clientSocket.destroy(); } catch { /* already gone */ }
      if (upstreamSocket) {
        try { upstreamSocket.destroy(); } catch { /* already gone */ }
      }
    };

    const handshakeTimeout = setTimeout(() => {
      if (state === 'greeting' || state === 'connect' || state === 'connecting') {
        killBoth('handshake timeout');
      }
    }, 30000);
    clientSocket.once('close', () => clearTimeout(handshakeTimeout));

    const onData = (chunk: Buffer) => {
      if (state === 'closed' || state === 'piped') return;
      buf = buf.length === 0 ? chunk : Buffer.concat([buf, chunk]);

      if (state === 'greeting') {
        const sz = greetingSize(buf);
        if (sz == null || buf.length < sz) return;
        const greeting = buf.subarray(0, sz);
        buf = buf.subarray(sz);
        if (greeting[0] !== SOCKS5_VERSION) { killBoth('bad version'); return; }
        try { clientSocket.write(Buffer.from([SOCKS5_VERSION, NO_AUTH_METHOD])); }
        catch { killBoth('write greeting reply failed'); return; }
        state = 'connect';
        // Fall through — buf may already contain CONNECT bytes (coalesced).
      }

      if (state === 'connect') {
        const sz = connectSize(buf);
        if (sz == null || buf.length < sz) return;
        const reqData = buf.subarray(0, sz);
        const remainder = buf.subarray(sz);
        const dest = parseConnectRequest(reqData);
        if (!dest) {
          writeReply(clientSocket, REPLY_GENERAL_FAILURE);
          killBoth('bad connect request');
          return;
        }
        state = 'connecting';
        // Pause client reads so any post-handshake bytes don't get dropped.
        // We replay `remainder` after upstream is established.
        clientSocket.pause();
        SocksClient.createConnection({
          proxy: upstreamProxy,
          command: 'connect',
          destination: { host: dest.host, port: dest.port },
          timeout: UPSTREAM_CONNECT_TIMEOUT_MS,
        }).then((result) => {
          if (state === 'closed') {
            try { result.socket.destroy(); } catch { /* shutdown */ }
            return;
          }
          upstreamSocket = result.socket;
          writeReply(clientSocket, REPLY_SUCCESS);
          // Replay any pre-buffered post-handshake bytes BEFORE we pipe.
          if (remainder.length > 0) {
            try { upstreamSocket.write(remainder); } catch { killBoth('replay write failed'); return; }
          }
          // Wire the rest of the connection through the pipe.
          upstreamSocket.on('error', () => killBoth('upstream error'));
          upstreamSocket.on('close', () => { try { clientSocket.destroy(); } catch { /* already gone */ } });
          clientSocket.removeListener('data', onData);
          clientSocket.pipe(upstreamSocket);
          upstreamSocket.pipe(clientSocket);
          clientSocket.resume();
          state = 'piped';
        }).catch(() => {
          writeReply(clientSocket, REPLY_HOST_UNREACHABLE);
          killBoth('upstream connect failed');
        });
        return;
      }
    };

    clientSocket.on('data', onData);
    clientSocket.on('error', () => killBoth('client error'));
  });

  await new Promise<void>((resolve, reject) => {
    const onErr = (e: unknown) => { server.off('listening', onListen); reject(e); };
    const onListen = () => { server.off('error', onErr); resolve(); };
    server.once('error', onErr);
    server.once('listening', onListen);
    server.listen(requestedPort, '127.0.0.1');
  });

  const address = server.address();
  if (!address || typeof address === 'string') {
    throw new Error('socks-bridge: unexpected listener address');
  }

  return {
    port: address.port,
    server,
    close: async () => {
      for (const sock of inFlight) {
        try { sock.destroy(); } catch { /* already gone */ }
      }
      inFlight.clear();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

export interface UpstreamTestOpts {
  upstream: UpstreamConfig;
  /** Hostname to test connectivity to through the upstream. Default 1.1.1.1. */
  testHost?: string;
  /** Port. Default 443. */
  testPort?: number;
  /** Total time budget across all retries. Default 5000ms. */
  budgetMs?: number;
  /** Number of attempts. Default 3. */
  retries?: number;
  /** Backoff between attempts. Default 500ms. */
  backoffMs?: number;
}

/**
 * Pre-flight: verify the upstream proxy actually accepts our credentials and
 * can reach a known endpoint. Called before chromium.launch so failures
 * surface as a clear startup error instead of a confusing 'connection
 * refused' on first navigation.
 *
 * Retries a few times with backoff because residential VPNs can take a
 * second to fully establish on first connect.
 *
 * Throws on final failure. Caller is responsible for redacting any error
 * that may leak credentials.
 */
export async function testUpstream(opts: UpstreamTestOpts): Promise<{ ok: true; attempts: number; ms: number }> {
  const upstreamProxy = buildUpstream(opts.upstream);
  const testHost = opts.testHost ?? '1.1.1.1';
  const testPort = opts.testPort ?? 443;
  const budgetMs = opts.budgetMs ?? 5000;
  const retries = opts.retries ?? 3;
  const backoffMs = opts.backoffMs ?? 500;

  const start = Date.now();
  let lastErr: unknown;

  for (let attempt = 1; attempt <= retries; attempt++) {
    const elapsed = Date.now() - start;
    const remaining = budgetMs - elapsed;
    if (remaining <= 0) break;
    const perAttempt = Math.min(remaining, Math.max(500, Math.floor(budgetMs / retries)));

    try {
      const result = await SocksClient.createConnection({
        proxy: upstreamProxy,
        command: 'connect',
        destination: { host: testHost, port: testPort },
        timeout: perAttempt,
      });
      try { result.socket.destroy(); } catch { /* test connection done */ }
      return { ok: true, attempts: attempt, ms: Date.now() - start };
    } catch (err) {
      lastErr = err;
      if (attempt < retries) {
        const elapsedAfter = Date.now() - start;
        if (elapsedAfter + backoffMs >= budgetMs) break;
        await new Promise<void>((r) => setTimeout(r, backoffMs));
      }
    }
  }

  const reason = lastErr instanceof Error ? lastErr.message : String(lastErr);
  const err = new Error(`SOCKS5 upstream rejected or unreachable after ${retries} attempts (${Date.now() - start}ms): ${reason}`);
  (err as Error & { upstreamHost?: string; upstreamPort?: number }).upstreamHost = opts.upstream.host;
  (err as Error & { upstreamHost?: string; upstreamPort?: number }).upstreamPort = opts.upstream.port;
  throw err;
}

// SSE endpoint helper — shared cleanup contract for stream endpoints.
//
// Pre-helper, /activity/stream and /inspector/events implemented the same
// pattern in parallel and both leaked subscribers when enqueue failed
// without a corresponding abort signal (e.g. Chromium MV3 service-worker
// suspend dropped the TCP without an abort edge). The subscriber closure
// stayed in the Set, capturing the ReadableStreamDefaultController plus
// any payloads queued behind it. Over a multi-day sidebar session this
// compounded into multi-MB of retained controllers per dead connection.
//
// Centralizing the cleanup contract here means any future SSE endpoint
// inherits the invariant — cleanup runs on abort, enqueue failure, AND
// heartbeat failure, exactly once, regardless of which edge fires first.

// sanitizeReplacer strips lone UTF-16 surrogates from string values before
// they get escape-encoded — required at every SSE egress that ships
// page-content-derived fields. See CLAUDE.md "Unicode sanitization at
// server egress" and the canonical implementation in sanitize.ts.
import { sanitizeReplacer } from './sanitize';

/** Send an SSE event. Handles JSON encoding + lone-surrogate sanitization. */
export type SseSender = (event: string, data: unknown) => void;

export interface SseEndpointConfig<T> {
  /**
   * Optional. Runs once after the stream opens, before subscribing for live
   * events. Use for initial event replay (activity gap detection, history
   * burst) or a current-state snapshot (inspector). The `send` helper
   * handles JSON encoding with sanitizeReplacer and SSE framing; pass
   * any event name and any payload object.
   */
  initialReplay?: (send: SseSender) => void;

  /**
   * Subscribe to the live event source. Receives a `notify` callback;
   * returns an unsubscribe function. The callback routes through the
   * helper's safeEnqueue + cleanup-on-throw, so a dead consumer ends up
   * removed from the subscriber set on the very next event (instead of
   * waiting for an abort that may never fire).
   */
  subscribe: (notify: (entry: T) => void) => () => void;

  /**
   * SSE event name for live events. `data: <JSON.stringify(entry)>\n\n`
   * is wrapped automatically. /activity/stream uses 'activity';
   * /inspector/events uses 'inspector'.
   */
  liveEventName: string;

  /** Heartbeat interval in ms. Default: 15000. */
  heartbeatMs?: number;
}

/**
 * Build a streaming Response that owns the cleanup contract:
 *   - safeEnqueue catches enqueue throws → cleanup
 *   - 15s heartbeat catches dead peers; failure → cleanup
 *   - req.signal abort → cleanup
 *   - cleanup is idempotent (clearInterval + unsubscribe + try close)
 */
export function createSseEndpoint<T>(
  req: Request,
  config: SseEndpointConfig<T>,
): Response {
  const heartbeatMs = config.heartbeatMs ?? 15000;
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    start(controller) {
      let cleanedUp = false;
      let heartbeat: ReturnType<typeof setInterval> | null = null;
      let unsubscribe: (() => void) | null = null;

      const cleanup = (): void => {
        if (cleanedUp) return;
        cleanedUp = true;
        if (heartbeat !== null) {
          clearInterval(heartbeat);
          heartbeat = null;
        }
        if (unsubscribe !== null) {
          unsubscribe();
          unsubscribe = null;
        }
        try {
          controller.close();
        } catch {
          // Expected: stream already closed by the consumer.
        }
      };

      const send: SseSender = (event, data) => {
        if (cleanedUp) return;
        try {
          controller.enqueue(
            encoder.encode(
              `event: ${event}\ndata: ${JSON.stringify(data, sanitizeReplacer)}\n\n`,
            ),
          );
        } catch {
          // Consumer disconnected mid-write. Tear down so this subscriber
          // doesn't sit in the set forever.
          cleanup();
        }
      };

      // Initial replay (caller-provided).
      if (config.initialReplay) {
        try {
          config.initialReplay(send);
        } catch {
          cleanup();
          return;
        }
        if (cleanedUp) return;
      }

      // Subscribe for live events.
      unsubscribe = config.subscribe((entry) => {
        send(config.liveEventName, entry);
      });

      // Heartbeat keeps NAT boxes and proxies from dropping idle SSE,
      // and serves as a liveness probe: an enqueue failure here is the
      // cheapest way to learn the consumer is gone without waiting for
      // an abort signal that may never arrive.
      heartbeat = setInterval(() => {
        if (cleanedUp) return;
        try {
          controller.enqueue(encoder.encode(`: heartbeat\n\n`));
        } catch {
          cleanup();
        }
      }, heartbeatMs);

      req.signal.addEventListener('abort', cleanup);
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    },
  });
}

/**
 * View-only session cookie registry for SSE endpoints.
 *
 * Why this exists: EventSource cannot send Authorization headers, so
 * /activity/stream and /inspector/events historically took a `?token=`
 * query param with the root AUTH_TOKEN. URLs leak through browser history,
 * referer headers, server logs, crash reports, and refactoring accidents
 * (Codex's plan-review outside voice called this out). This module issues
 * a separate short-lived token, scoped to SSE reads only, delivered via
 * an HttpOnly SameSite=Strict cookie that EventSource can pick up with
 * `withCredentials: true`.
 *
 * Design notes:
 * - TTL 30 minutes. Long enough for a normal coding session; short enough
 *   that a leaked cookie expires quickly.
 * - Scope is implicit: validating a cookie only grants read access to
 *   /activity/stream and /inspector/events. The cookie is NEVER valid on
 *   /command, /token, or any mutating endpoint. Matches the
 *   cookie-picker-auth-isolation pattern (prior learning, 10/10 confidence):
 *   cookie-based session tokens must not be valid as scoped tokens.
 * - In-memory only. No persistence across daemon restarts — extension
 *   re-mints on reconnect.
 * - Tokens are 32 random bytes (URL-safe base64). 256 bits, unbruteforceable.
 *
 * Shares the registry implementation with pty-session-cookie.ts via
 * createSessionCookieStore; separate INSTANCE so the token spaces never
 * overlap.
 */
import { createSessionCookieStore } from './session-cookie-store';

const TTL_MS = 30 * 60 * 1000; // 30 minutes

export const SSE_COOKIE_NAME = 'gstack_sse';

const store = createSessionCookieStore({ cookieName: SSE_COOKIE_NAME, ttlMs: TTL_MS });

/** Mint a fresh view-only SSE session token. */
export function mintSseSessionToken(): { token: string; expiresAt: number } {
  return store.mint();
}

/**
 * Validate a token. Returns true only if the token exists AND is not expired.
 * Expired tokens are lazily removed, and we opportunistically prune a few
 * additional expired entries on every validate so the registry can't grow
 * unboundedly under sustained mint + reconnect pressure.
 */
export function validateSseSessionToken(token: string | null | undefined): boolean {
  return store.validate(token);
}

/** Parse the SSE session token from a Cookie header. */
export function extractSseCookie(req: Request): string | null {
  return store.extract(req);
}

/** Build the Set-Cookie header value for the SSE session cookie. */
export function buildSseSetCookie(token: string): string {
  return store.buildSetCookie(token);
}

// Test-only reset.
export function __resetSseSessions(): void {
  store.__reset();
}

/**
 * Stealth init script — Layer C of GBrowser's anti-detection plan.
 *
 * D7 (codex correction, kept): Layer C (the always-on default built by
 * buildStealthScript) does NOT fake navigator.plugins or
 * navigator.languages — modern fingerprinters cross-check those against
 * userAgent / platform / OS, and synthesizing fixed values flags MORE
 * bot-like, not less. Plugins and languages surface their native
 * Chromium values. The opt-in EXTENDED_STEALTH_SCRIPT below (gated on
 * GSTACK_STEALTH=extended, off by default) DOES fake plugins — that mode
 * is the documented "actively lies, may break sites" escape hatch, not
 * the default posture.
 *
 * What this script DOES do (the new additions for Phase 1):
 *   1. Mask navigator.webdriver (the canonical headless tell).
 *   2. Restore window.chrome.runtime / app / csi / loadTimes — real
 *      Chrome ships them; their absence in headless/automation is a
 *      universally-checked tell. (Vendor research: Cloudflare + DataDome
 *      check chrome.runtime presence + enum shape.)
 *   3. Align Notification.permission with the Permissions API spoof
 *      that the inline addInitScript already applies — `denied` while
 *      Permissions returns `prompt` is a cross-source inconsistency
 *      detectors flag.
 *   4. Report per-install hardware values via GSTACK_HW_CONCURRENCY /
 *      GSTACK_DEVICE_MEMORY env vars (set by gbd at startup via
 *      system_profiler + sysctl). Per-install honesty avoids the
 *      cross-user fingerprint cluster a hardcoded default would create.
 *   5. Install a Function.prototype.toString Proxy that makes every
 *      patched getter report `function ... { [native code] }` at every
 *      recursion depth — defeats the well-known depth-3 detection trick
 *      (`fn.toString.toString.toString().includes('[native code]')`)
 *      that breaks naive stealth tooling.
 *
 * Codex caveat (acknowledged): a Proxy on Function.prototype.toString
 * still has detection surfaces (descriptors, Reflect.ownKeys, cross-
 * realm identity). Phase 2's C++ patches make this layer obsolete by
 * pushing the spoofs to native code where toString is truly native.
 * Until then, this is the best JS-only approach.
 */

import type { BrowserContext } from 'playwright';

/**
 * Host hardware values resolved at browser-manager startup. Values come
 * from the gbd `host_profile.go` detection (system_profiler + sysctl
 * on macOS), passed through the GSTACK_* env vars. Each field falls
 * back to a documented default if the env var is missing or unparseable.
 */
interface HostProfile {
  hwConcurrency: number;
  deviceMemory: number;
}

// Exported for the clamp/fallback unit test. The platform spoof is owned by
// the UA-CH cmdline switch in buildGStackLaunchArgs (which reads GSTACK_PLATFORM
// directly), so this profile only carries the values buildStealthScript bakes
// into the page-world script.
export function readHostProfile(): HostProfile {
  const env = (globalThis as any).process?.env ?? {};
  const concurrency = Number(env.GSTACK_HW_CONCURRENCY);
  const memory = Number(env.GSTACK_DEVICE_MEMORY);
  return {
    // Clamp to a plausible default: 0/NaN/negative/missing all fall back to 8.
    // deviceMemory=0 or NaN would be a glaring bot tell, so never report it.
    hwConcurrency: Number.isFinite(concurrency) && concurrency > 0 ? concurrency : 8,
    deviceMemory: Number.isFinite(memory) && memory > 0 ? memory : 8,
  };
}

/**
 * Build the full Layer C stealth init script. The function template-
 * literal-interpolates the host values so they bake into the script the
 * page sees — process.env is not accessible from a page-world init script,
 * so values must be resolved by the browser-manager process before
 * injection.
 *
 * The script is one big self-invoking function so all the patches
 * happen atomically before any page code runs. Order matters: the
 * Function.prototype.toString Proxy installs FIRST so all subsequent
 * defineProperty getters are covered by its native-code lie.
 */
export function buildStealthScript(hw: HostProfile): string {
  return `(() => {
  // ──── Function.prototype.toString Proxy (must run first) ────
  // Make every patched getter / function below report
  // 'function NAME() { [native code] }' at every recursion depth.
  // Defeats fn.toString.toString.toString() integrity checks.
  const patchedFns = new WeakSet();
  const nativeToString = Function.prototype.toString;
  const toStringProxy = new Proxy(nativeToString, {
    apply(target, thisArg, args) {
      if (patchedFns.has(thisArg)) {
        const name = (thisArg && thisArg.name) || '';
        return 'function ' + name + '() { [native code] }';
      }
      return Reflect.apply(target, thisArg, args);
    },
  });
  Object.defineProperty(Function.prototype, 'toString', {
    value: toStringProxy, writable: true, configurable: true,
  });
  const markNative = (fn, name) => {
    if (name) {
      try { Object.defineProperty(fn, 'name', { value: name }); } catch {}
    }
    patchedFns.add(fn);
    return fn;
  };

  // ──── navigator.webdriver (canonical mask, kept from D7) ────
  try {
    const webdriverGetter = markNative(function() { return false; }, 'get webdriver');
    Object.defineProperty(navigator, 'webdriver', { get: webdriverGetter, configurable: true });
  } catch {}

  // ──── window.chrome.* restoration ────
  // Real Chrome ships these objects with rich enum / method shape.
  // Headless Chromium / Playwright's launch strips them. Their absence
  // is a universally-checked tell (verified in Cloudflare + DataDome
  // RE catalogs). We don't try to perfectly mimic — we ship plausible
  // shape with native-code-looking methods.
  try {
    if (!('chrome' in window)) {
      window.chrome = {};
    }
    const chrome = window.chrome;
    if (!chrome.runtime) {
      chrome.runtime = {
        OnInstalledReason: { CHROME_UPDATE: 'chrome_update', INSTALL: 'install',
                            SHARED_MODULE_UPDATE: 'shared_module_update', UPDATE: 'update' },
        OnRestartRequiredReason: { APP_UPDATE: 'app_update', OS_UPDATE: 'os_update', PERIODIC: 'periodic' },
        PlatformArch: { ARM: 'arm', ARM64: 'arm64', MIPS: 'mips', MIPS64: 'mips64',
                       X86_32: 'x86-32', X86_64: 'x86-64' },
        PlatformNaclArch: { ARM: 'arm', MIPS: 'mips', MIPS64: 'mips64',
                           X86_32: 'x86-32', X86_64: 'x86-64' },
        PlatformOs: { ANDROID: 'android', CROS: 'cros', LINUX: 'linux',
                     MAC: 'mac', OPENBSD: 'openbsd', WIN: 'win' },
        RequestUpdateCheckStatus: { NO_UPDATE: 'no_update', THROTTLED: 'throttled',
                                   UPDATE_AVAILABLE: 'update_available' },
        connect: markNative(function connect() {
          throw new TypeError('Error in invocation of runtime.connect: No matching signature.');
        }, 'connect'),
        sendMessage: markNative(function sendMessage() {
          throw new TypeError('Error in invocation of runtime.sendMessage: No matching signature.');
        }, 'sendMessage'),
        id: undefined,
      };
    }
    if (!chrome.app) {
      chrome.app = {
        isInstalled: false,
        InstallState: { DISABLED: 'disabled', INSTALLED: 'installed', NOT_INSTALLED: 'not_installed' },
        RunningState: { CANNOT_RUN: 'cannot_run', READY_TO_RUN: 'ready_to_run', RUNNING: 'running' },
      };
    }
    if (typeof chrome.csi !== 'function') {
      chrome.csi = markNative(function csi() {
        return {
          onloadT: Date.now(),
          pageT: performance.now(),
          startE: Date.now() - 1000,
          tran: 15,
        };
      }, 'csi');
    }
    if (typeof chrome.loadTimes !== 'function') {
      chrome.loadTimes = markNative(function loadTimes() {
        const t = performance.timing;
        return {
          requestTime: t.requestStart / 1000,
          startLoadTime: t.requestStart / 1000,
          commitLoadTime: t.responseStart / 1000,
          finishDocumentLoadTime: t.domContentLoadedEventEnd / 1000,
          finishLoadTime: t.loadEventEnd / 1000,
          firstPaintTime: t.responseEnd / 1000,
          firstPaintAfterLoadTime: 0,
          navigationType: 'Other',
          wasFetchedViaSpdy: true,
          wasNpnNegotiated: true,
          npnNegotiatedProtocol: 'h2',
          wasAlternateProtocolAvailable: false,
          connectionInfo: 'h2',
        };
      }, 'loadTimes');
    }
  } catch (err) {
    // Non-fatal — page might have a stricter Content Security Policy
    // that blocks property mutation on window. Leave chrome.* whatever
    // shape it was; navigator.webdriver mask still applies.
  }

  // ──── Notification.permission align with Permissions API ────
  // The inline addInitScript already overrides permissions.query for
  // notifications → 'prompt'. Notification.permission must match
  // ('default' in real Chrome on pages that haven't asked yet).
  try {
    if (typeof Notification !== 'undefined') {
      const notificationPermissionGetter = markNative(function() { return 'default'; }, 'get permission');
      Object.defineProperty(Notification, 'permission', {
        get: notificationPermissionGetter,
        configurable: true,
      });
    }
  } catch {}

  // ──── Per-install hardware values from GSTACK_* env (T2) ────
  // gbd's host_profile.go fed real host values via cmdline env. Reporting
  // those (not hardcoded defaults) avoids the cross-user GBrowser
  // fingerprint cluster.
  try {
    const hwConcurrencyGetter = markNative(function() { return ${hw.hwConcurrency}; }, 'get hardwareConcurrency');
    Object.defineProperty(navigator, 'hardwareConcurrency', {
      get: hwConcurrencyGetter,
      configurable: true,
    });
  } catch {}
  try {
    const deviceMemoryGetter = markNative(function() { return ${hw.deviceMemory}; }, 'get deviceMemory');
    Object.defineProperty(navigator, 'deviceMemory', {
      get: deviceMemoryGetter,
      configurable: true,
    });
  } catch {}

  // ──── Selenium / Phantom / Nightmare / Playwright global cleanup ────
  // Static known-name list of Selenium / Playwright / PhantomJS / Nightmare
  // globals. AUTOMATION_ARTIFACT_CLEANUP_SCRIPT (applied right after this on
  // every path) covers the cdc_/__webdriver dynamic prefixes; this list is the
  // fixed-name complement.
  try {
    const auto = [
      '__driver_evaluate', '__webdriver_evaluate', '__selenium_evaluate', '__fxdriver_evaluate',
      '__driver_unwrapped', '__webdriver_unwrapped', '__selenium_unwrapped', '__fxdriver_unwrapped',
      '_Selenium_IDE_Recorder', '_selenium', 'calledSelenium',
      '$chrome_asyncScriptInfo',
      '__$webdriverAsyncExecutor', '__webdriverFunc',
      'domAutomation', 'domAutomationController',
      '__lastWatirAlert', '__lastWatirConfirm', '__lastWatirPrompt',
      '__webdriver_script_fn', '_WEBDRIVER_ELEM_CACHE',
      'callPhantom', '_phantom', 'phantom', '__nightmare',
      '__pwInitScripts', '__playwright__binding__',
    ];
    for (const k of auto) {
      try { delete window[k]; } catch {}
    }
    try { delete document.__webdriver_script_fn; } catch {}
  } catch {}
})();`;
}

/**
 * Extended-mode init script — six detection-vector patches. Applied
 * AFTER the default mask, so the property-getter version remains in
 * place if any of the deletion paths fail.
 *
 * Self-contained string so it can be passed to addInitScript({ content })
 * without bundling concerns.
 */
export const EXTENDED_STEALTH_SCRIPT = `
(() => {
  try {
    // 1. Fully delete navigator.webdriver from the prototype so
    //    \`"webdriver" in navigator\` returns false (not just falsy).
    delete Object.getPrototypeOf(navigator).webdriver;
  } catch {}

  try {
    // 2. WebGL renderer spoof — SwiftShader is the canonical software-GPU
    //    tell. Spoof to a plausible Apple M1 Pro string.
    const getParameter = WebGLRenderingContext.prototype.getParameter;
    WebGLRenderingContext.prototype.getParameter = function (parameter) {
      // UNMASKED_VENDOR_WEBGL (37445) → 'Apple Inc.'
      if (parameter === 37445) return 'Apple Inc.';
      // UNMASKED_RENDERER_WEBGL (37446) → realistic Apple silicon string
      if (parameter === 37446) return 'Apple M1 Pro, OpenGL 4.1';
      return getParameter.call(this, parameter);
    };
  } catch {}

  try {
    // 3. navigator.plugins: real PluginArray with MimeType objects.
    const makePlugin = (name, filename, desc, mimes) => {
      const p = Object.create(Plugin.prototype);
      Object.defineProperties(p, {
        name: { get: () => name },
        filename: { get: () => filename },
        description: { get: () => desc },
        length: { get: () => mimes.length },
      });
      mimes.forEach((m, i) => { p[i] = m; });
      p.item = (i) => mimes[i];
      p.namedItem = (n) => mimes.find((m) => m.type === n);
      return p;
    };
    const makeMime = (type, suffixes, desc) => {
      const m = Object.create(MimeType.prototype);
      Object.defineProperties(m, {
        type: { get: () => type },
        suffixes: { get: () => suffixes },
        description: { get: () => desc },
      });
      return m;
    };
    const pdfMime = makeMime('application/pdf', 'pdf', '');
    const cpdfMime = makeMime('application/x-google-chrome-pdf', 'pdf', 'Portable Document Format');
    const plugins = [
      makePlugin('PDF Viewer', 'internal-pdf-viewer', '', [pdfMime]),
      makePlugin('Chrome PDF Viewer', 'internal-pdf-viewer', '', [cpdfMime]),
      makePlugin('Chromium PDF Viewer', 'internal-pdf-viewer', '', [cpdfMime]),
    ];
    Object.defineProperty(navigator, 'plugins', {
      get: () => {
        const arr = Object.create(PluginArray.prototype);
        Object.defineProperty(arr, 'length', { get: () => plugins.length });
        plugins.forEach((p, i) => { arr[i] = p; });
        arr.item = (i) => plugins[i];
        arr.namedItem = (n) => plugins.find((p) => p.name === n);
        arr.refresh = () => {};
        return arr;
      },
    });
  } catch {}

  try {
    // 4. window.chrome shape — chrome.app + chrome.runtime + loadTimes/csi.
    if (!window.chrome) {
      window.chrome = {};
    }
    if (!window.chrome.runtime) {
      window.chrome.runtime = { OnInstalledReason: {}, OnRestartRequiredReason: {} };
    }
    if (!window.chrome.app) {
      window.chrome.app = {
        isInstalled: false,
        InstallState: { DISABLED: 'disabled', INSTALLED: 'installed', NOT_INSTALLED: 'not_installed' },
        RunningState: { CANNOT_RUN: 'cannot_run', READY_TO_RUN: 'ready_to_run', RUNNING: 'running' },
      };
    }
    if (!window.chrome.loadTimes) {
      window.chrome.loadTimes = function () {
        return { commitLoadTime: Date.now() / 1000, finishLoadTime: Date.now() / 1000 };
      };
    }
    if (!window.chrome.csi) {
      window.chrome.csi = function () {
        return { startE: Date.now(), onloadT: Date.now(), pageT: 0, tran: 15 };
      };
    }
  } catch {}

  try {
    // 5. mediaDevices — some headless builds drop it entirely.
    if (!navigator.mediaDevices) {
      Object.defineProperty(navigator, 'mediaDevices', {
        get: () => ({ enumerateDevices: () => Promise.resolve([]) }),
      });
    }
  } catch {}

  try {
    // 6. CDP cdc_* property cleanup. Chromium under CDP sets cdc_*-prefixed
    //    globals (driver injection markers); a bot detector finds them by
    //    iterating window keys. Strip all matching keys.
    //    Note: via applyStealth this is redundant with AUTOMATION_ARTIFACT_
    //    CLEANUP_SCRIPT (which runs first on every path). Kept so this script
    //    is self-sufficient if ever applied standalone.
    for (const k of Object.keys(window)) {
      if (k.startsWith('cdc_')) {
        try { delete window[k]; } catch {}
      }
    }
  } catch {}
})();
`;

function extendedModeEnabled(): boolean {
  const v = process.env.GSTACK_STEALTH;
  return v === 'extended' || v === '1' || v === 'true';
}

/**
 * Strip automation runtime artifacts that don't belong in a real browser
 * and that no fingerprint-synthesis layer can mask: ChromeDriver/CDP window
 * globals (cdc_*, __webdriver*) and the Permissions API quirk where an
 * automated Chromium reports notifications as 'denied' instead of real
 * Chrome's 'prompt'. The 'prompt' answer is aligned with Layer C's
 * Notification.permission = 'default' so the two surfaces stay consistent.
 *
 * Runs on EVERY launch path via applyStealth (headless launch(),
 * launchHeaded(), handoff()) so the Notification/Permissions pairing never
 * diverges by mode. Previously this lived inline in launchHeaded() only,
 * which left headless and handoff with the Notification value but not the
 * matching Permissions answer.
 */
export const AUTOMATION_ARTIFACT_CLEANUP_SCRIPT = `(() => {
  // cdc_/__webdriver globals are injected by ChromeDriver/CDP. A detector
  // finds them by iterating window keys. Strip immediately and again after a
  // tick in case they are injected late.
  const cleanup = () => {
    for (const key of Object.keys(window)) {
      if (key.startsWith('cdc_') || key.startsWith('__webdriver')) {
        try { delete window[key]; } catch (e) { if (!(e instanceof TypeError)) throw e; }
      }
    }
  };
  cleanup();
  setTimeout(cleanup, 0);

  // Permissions API: automated Chromium returns 'denied' for notifications,
  // a known tell. Return 'prompt' to match real Chrome (and Layer C's
  // Notification.permission = 'default'). Tradeoff: this pins the
  // notifications state to fresh-Chrome values for the whole session, so a
  // site that actually grants/denies notifications would see a stale value.
  // Acceptable for the automation/anti-detection use case (which does not
  // drive real notification grants); only notifications is overridden.
  const originalQuery = window.navigator.permissions && window.navigator.permissions.query;
  if (originalQuery) {
    window.navigator.permissions.query = (params) => {
      if (params && params.name === 'notifications') {
        return Promise.resolve({ state: 'prompt', onchange: null });
      }
      return originalQuery.call(window.navigator.permissions, params);
    };
  }
})();`;

/**
 * Apply stealth patches to a fresh BrowserContext (or persistent context).
 * Called by EVERY context-creation path in browser-manager — launch(),
 * launchHeaded(), handoff(), AND recreateContext() (the useragent /
 * viewport --scale rebuild) — so a context can never reach a page un-stealthed.
 *
 * Injection order (Playwright evaluates init scripts in registration order):
 *   1. Layer C (buildStealthScript) — the always-on consistency-first default.
 *   2. Automation-artifact cleanup (cdc_/__webdriver + Permissions shim),
 *      kept consistent with Layer C's Notification.permission alignment.
 *   3. EXTENDED_STEALTH_SCRIPT — only when GSTACK_STEALTH=extended (off by
 *      default). Its window.chrome.* patches are `if (!...)`-guarded, so
 *      Layer C's richer shapes win; the extended-only additions (WebGL spoof,
 *      faked navigator.plugins, mediaDevices) apply on top.
 *
 * KNOWN LIMITATION (extended mode only, opt-in): extended's functions are NOT
 * wrapped by Layer C's Function.prototype.toString proxy, so they stringify
 * as injected code; its prototype-level navigator.webdriver delete is shadowed
 * by Layer C's own-property getter (net behavior still matches real Chrome:
 * webdriver present and false); and its hardcoded Apple-M1 WebGL string can
 * disagree with the env-driven GPU spoof in buildGStackLaunchArgs on non-Apple
 * hosts. This is acceptable for the documented "actively lies, may break sites"
 * escape hatch; the consistency-first default (Layer C alone) has none of these.
 *
 * Host profile is resolved from process.env at call time so per-install
 * values bake into the script before Playwright sends it to Chromium via
 * Page.addScriptToEvaluateOnNewDocument.
 */
export async function applyStealth(context: BrowserContext): Promise<void> {
  const hw = readHostProfile();
  await context.addInitScript({ content: buildStealthScript(hw) });
  await context.addInitScript({ content: AUTOMATION_ARTIFACT_CLEANUP_SCRIPT });
  if (extendedModeEnabled()) {
    await context.addInitScript({ content: EXTENDED_STEALTH_SCRIPT });
  }
}

/**
 * Args added to chromium.launch's `args` to suppress the
 * AutomationControlled blink feature. This is independent of the init
 * script — it changes how Chromium identifies itself in the protocol layer.
 */
export const STEALTH_LAUNCH_ARGS = [
  '--disable-blink-features=AutomationControlled',
];

/**
 * Build the `--gstack-*=` cmdline switches that the Pack 1 Chromium
 * patches read (webgl-vendor-spoof, ua-client-hints-stealth, worker-
 * navigator-stealth). Values come from the GSTACK_* env vars that
 * gbd populates from host_profile.go at startup.
 *
 * Each switch is only emitted when its env var is non-empty — empty
 * env values fall through to the patch's "no override" path, which
 * returns the real Chromium native value. This keeps the helper safe
 * on builds that DO NOT have the C++ patches applied (gbrowser
 * pre-Pack-1) and on hosts where gbd hasn't yet populated some
 * fields (legacy installs).
 *
 * TRUSTED-SOURCE ONLY. These GSTACK_* values are populated by gbd from
 * host_profile.go (system_profiler / sysctl) and become page-visible WebGL /
 * UA-CH surface data. They are NOT sanitized here (passed verbatim into the
 * argv array, which is injection-safe because Playwright spawns Chromium with
 * an argv array, not a shell). NEVER route page content, HTTP headers, or any
 * remote/untrusted input into these env vars — that would turn this into an
 * argv-injection sink. readHostProfile() applies the same trust assumption.
 *
 * Mapping (gbd env → Chromium cmdline switch → C++ patch consumer):
 *   GSTACK_GPU_VENDOR        → --gstack-gpu-vendor        → webgl-vendor-spoof.patch
 *   GSTACK_GPU_RENDERER      → --gstack-gpu-renderer      → webgl-vendor-spoof.patch
 *   GSTACK_PLATFORM          → --gstack-ua-platform       → ua-client-hints-stealth.patch
 *                              (maps MacARM/MacIntel → "macOS")
 *   GSTACK_GPU_CHIPSET       → --gstack-ua-model          → ua-client-hints-stealth.patch
 *   GSTACK_HW_CONCURRENCY    → --gstack-hw-concurrency    → worker-navigator-stealth.patch
 *   GSTACK_DEVICE_MEMORY     → --gstack-device-memory     → worker-navigator-stealth.patch
 */
export function buildGStackLaunchArgs(): string[] {
  const env = (globalThis as any).process?.env ?? {};
  const args: string[] = [];

  const vendor = env.GSTACK_GPU_VENDOR;
  if (vendor) args.push(`--gstack-gpu-vendor=${vendor}`);

  const renderer = env.GSTACK_GPU_RENDERER;
  if (renderer) args.push(`--gstack-gpu-renderer=${renderer}`);

  // Map gbd's "MacARM"/"MacIntel" classification to the UA-CH "macOS"
  // platform string Chromium emits natively. Other future platforms
  // would map similarly (Win32 → "Windows", Linux → "Linux").
  const platform = env.GSTACK_PLATFORM;
  if (platform === 'MacARM' || platform === 'MacIntel') {
    args.push('--gstack-ua-platform=macOS');
  } else if (platform === 'Win32') {
    args.push('--gstack-ua-platform=Windows');
  } else if (platform && platform.startsWith('Linux')) {
    args.push('--gstack-ua-platform=Linux');
  }

  const chipset = env.GSTACK_GPU_CHIPSET;
  if (chipset) args.push(`--gstack-ua-model=${chipset}`);

  const hw = env.GSTACK_HW_CONCURRENCY;
  if (hw) args.push(`--gstack-hw-concurrency=${hw}`);

  const memory = env.GSTACK_DEVICE_MEMORY;
  if (memory) args.push(`--gstack-device-memory=${memory}`);

  // Pack 2 / B11: suppress user-defined Error.prepareStackTrace during
  // V8 stack-trace formatting. Closes the Cloudflare Bot Management canary
  // trick where a page sets prepareStackTrace and watches for it to fire
  // during CDP serialization.
  //
  // OPT-IN (off by default): only emitted when GSTACK_CDP_STEALTH is
  // on/1/true. This switch is read by a C++ patch that only exists in
  // gbrowser builds; gbd opts in by exporting GSTACK_CDP_STEALTH=on. Stock
  // Playwright Chromium leaves it unset, so the flag never reaches a
  // Chromium that wouldn't understand it. (Previously this was on-by-default
  // unless GSTACK_CDP_STEALTH=off, which contradicted this very comment.)
  const cdpStealth = env.GSTACK_CDP_STEALTH;
  if (cdpStealth === 'on' || cdpStealth === '1' || cdpStealth === 'true') {
    args.push('--gstack-suppress-prepare-stack-trace');
  }

  return args;
}

/**
 * Playwright default args to strip via ignoreDefaultArgs.
 *
 * Playwright passes these by default. Each one is a visible automation
 * tell at some layer:
 *   --enable-automation                              → infobar + chrome shape
 *   --disable-extensions                             → blocks our extension
 *   --disable-component-extensions-with-background-pages → blocks component ext
 *   --disable-popup-blocking                         → automation default
 *   --disable-component-update                       → automation default
 *   --disable-default-apps                           → affects plugin enum
 *
 * Used by browser-manager via spread into ignoreDefaultArgs to keep
 * the list in one place across launchHeaded() and handoff().
 */
export const STEALTH_IGNORE_DEFAULT_ARGS = [
  '--enable-automation',
  '--disable-extensions',
  '--disable-component-extensions-with-background-pages',
  '--disable-popup-blocking',
  '--disable-component-update',
  '--disable-default-apps',
];

/** Test-only helper: report whether extended mode is currently active. */
export function isExtendedStealthEnabled(): boolean {
  return extendedModeEnabled();
}

/**
 * Per-tab session state.
 *
 * Extracted from BrowserManager to enable parallel tab execution in /batch.
 * Each TabSession holds the state that is scoped to a single browser tab:
 * page reference, element refs, snapshot baseline, and frame context.
 *
 *   BrowserManager (global)
 *     └── tabSessions: Map<number, TabSession>
 *           ├── TabSession(page1)  ←  refMap, lastSnapshot, frame
 *           ├── TabSession(page2)  ←  refMap, lastSnapshot, frame
 *           └── TabSession(page3)  ←  refMap, lastSnapshot, frame
 *
 * The /command path gets the active session via bm.getActiveSession().
 * The /batch path gets specific sessions via bm.getSession(tabId).
 * Both paths pass TabSession to the same handler functions.
 */

import type { Page, Locator, Frame } from 'playwright';

export interface RefEntry {
  locator: Locator;
  role: string;
  name: string;
}

export type SetContentWaitUntil = 'load' | 'domcontentloaded' | 'networkidle';

export class TabSession {
  readonly page: Page;

  // ─── Ref Map (snapshot → @e1, @e2, @c1, @c2, ...) ────────
  private refMap: Map<string, RefEntry> = new Map();

  // ─── Snapshot Diffing ─────────────────────────────────────
  // NOT cleared on navigation — it's a text baseline for diffing
  private lastSnapshot: string | null = null;

  // ─── Frame context ─────────────────────────────────────────
  private activeFrame: Frame | null = null;

  // ─── Loaded HTML (for load-html replay across context recreation) ─
  //
  // loadedHtml lifecycle:
  //
  //   load-html cmd ──▶ session.setTabContent(html, opts)
  //                          ├─▶ page.setContent(html, opts)
  //                          └─▶ this.loadedHtml = html
  //                              this.loadedHtmlWaitUntil = opts.waitUntil
  //
  //   goto/back/forward/reload ──▶ session.clearLoadedHtml()
  //                                     (BEFORE Playwright call, so timeouts
  //                                      don't leave stale state)
  //
  //   viewport --scale ──▶ recreateContext()
  //                             ├─▶ saveState() captures { url, loadedHtml } per tab
  //                             │        (in-memory only, never to disk)
  //                             └─▶ restoreState():
  //                                    for each tab with loadedHtml:
  //                                       newSession.setTabContent(html, opts)
  //                                    (NOT page.setContent — must rehydrate
  //                                     TabSession.loadedHtml too)
  private loadedHtml: string | null = null;
  private loadedHtmlWaitUntil: SetContentWaitUntil | undefined;

  constructor(page: Page) {
    this.page = page;
  }

  // ─── Page Access ───────────────────────────────────────────
  getPage(): Page {
    return this.page;
  }

  // ─── Ref Map ──────────────────────────────────────────────
  setRefMap(refs: Map<string, RefEntry>) {
    this.refMap = refs;
  }

  clearRefs() {
    this.refMap.clear();
  }

  /**
   * Resolve a selector that may be a @ref (e.g., "@e3", "@c1") or a CSS selector.
   * Returns { locator } for refs or { selector } for CSS selectors.
   */
  async resolveRef(selector: string): Promise<{ locator: Locator } | { selector: string }> {
    if (selector.startsWith('@e') || selector.startsWith('@c')) {
      const ref = selector.slice(1); // "e3" or "c1"
      const entry = this.refMap.get(ref);
      if (!entry) {
        throw new Error(
          `Ref ${selector} not found. Run 'snapshot' to get fresh refs.`
        );
      }
      const count = await entry.locator.count();
      if (count === 0) {
        throw new Error(
          `Ref ${selector} (${entry.role} "${entry.name}") is stale — element no longer exists. ` +
          `Run 'snapshot' for fresh refs.`
        );
      }
      return { locator: entry.locator };
    }
    return { selector };
  }

  /** Get the ARIA role for a ref selector, or null for CSS selectors / unknown refs. */
  getRefRole(selector: string): string | null {
    if (selector.startsWith('@e') || selector.startsWith('@c')) {
      const entry = this.refMap.get(selector.slice(1));
      return entry?.role ?? null;
    }
    return null;
  }

  getRefCount(): number {
    return this.refMap.size;
  }

  /** Get all ref entries for the /refs endpoint. */
  getRefEntries(): Array<{ ref: string; role: string; name: string }> {
    return Array.from(this.refMap.entries()).map(([ref, entry]) => ({
      ref, role: entry.role, name: entry.name,
    }));
  }

  // ─── Snapshot Diffing ─────────────────────────────────────
  setLastSnapshot(text: string | null) {
    this.lastSnapshot = text;
  }

  getLastSnapshot(): string | null {
    return this.lastSnapshot;
  }

  // ─── Frame context ─────────────────────────────────────────
  setFrame(frame: Frame | null): void {
    this.activeFrame = frame;
  }

  getFrame(): Frame | null {
    return this.activeFrame;
  }

  /**
   * Returns the active frame if set, otherwise the current page.
   * Use this for operations that work on both Page and Frame (locator, evaluate, etc.).
   */
  getActiveFrameOrPage(): Page | Frame {
    // Auto-recover from detached frames (iframe removed/navigated). Clear
    // refs alongside the activeFrame — same staleness condition as
    // onMainFrameNavigated() below: refs were captured against a frame
    // that no longer exists. Without this, refMap entries linger against
    // a dead frame after silently falling back to the main page; the
    // next snapshot's role+name keys collide with stale entries and the
    // resolver picks one at random.
    if (this.activeFrame?.isDetached()) {
      this.activeFrame = null;
      this.clearRefs();
    }
    return this.activeFrame ?? this.page;
  }

  /**
   * Called on main-frame navigation to clear stale refs, frame context, and any
   * load-html replay metadata. Runs for every main-frame nav — explicit goto/back/
   * forward/reload AND browser-emitted navigations (link clicks, form submits, JS
   * redirects, OAuth). Without clearing loadedHtml here, a user who load-html'd and
   * then clicked a link would silently revert to the original HTML on the next
   * viewport --scale.
   */
  onMainFrameNavigated(): void {
    this.clearRefs();
    this.activeFrame = null;
    this.loadedHtml = null;
    this.loadedHtmlWaitUntil = undefined;
  }

  // ─── Loaded HTML (load-html replay) ───────────────────────

  /**
   * Load HTML content into the tab AND store it for replay after context recreation
   * (e.g. viewport --scale). Unlike page.setContent() alone, this rehydrates
   * TabSession.loadedHtml so the next saveState()/restoreState() round-trip preserves
   * the content.
   */
  async setTabContent(html: string, opts: { waitUntil?: SetContentWaitUntil } = {}): Promise<void> {
    const waitUntil = opts.waitUntil ?? 'domcontentloaded';
    // Call setContent FIRST — only record the replay metadata after a successful load.
    // If setContent throws (timeout, crash), we must not leave phantom HTML that a
    // later viewport --scale would replay.
    await this.page.setContent(html, { waitUntil, timeout: 15000 });
    this.loadedHtml = html;
    this.loadedHtmlWaitUntil = waitUntil;
  }

  /** Get stored HTML + waitUntil for state replay. Returns null if no load-html happened. */
  getLoadedHtml(): { html: string; waitUntil?: SetContentWaitUntil } | null {
    if (this.loadedHtml === null) return null;
    return { html: this.loadedHtml, waitUntil: this.loadedHtmlWaitUntil };
  }

  /** Clear stored HTML. Called BEFORE goto/back/forward/reload navigation. */
  clearLoadedHtml(): void {
    this.loadedHtml = null;
    this.loadedHtmlWaitUntil = undefined;
  }
}

/**
 * Lightweight telemetry — DX D9 from /plan-devex-review.
 *
 * Piggybacks on ~/.gstack/analytics/skill-usage.jsonl pattern (existing
 * gstack telemetry). Hostname + aggregate counters only; no body content,
 * no agent text, no command args. Respects the user's telemetry tier
 * setting (off | anonymous | community) via gstack-config.
 *
 * Fire-and-forget: never blocks the calling path. Errors swallowed.
 *
 * Events:
 *   domain_skill_saved          {host, scope, state, bytes}
 *   domain_skill_state_changed  {host, from_state, to_state}
 *   domain_skill_save_blocked   {host, reason}
 *   domain_skill_fired          {host, source, version}
 *   cdp_method_called           {domain, method, allowed, scope}
 *   cdp_method_denied           {domain, method}    ← drives next allow-list growth
 *   cdp_method_lock_acquire_ms  {domain, method, ms}
 */

import { promises as fs } from 'fs';
import * as path from 'path';
import * as os from 'os';
import { readGstackConfigYamlKey } from './config';

function gstackHome(): string {
  return process.env.GSTACK_HOME || path.join(os.homedir(), '.gstack');
}

function analyticsDir(): string {
  return path.join(gstackHome(), 'analytics');
}

function telemetryFile(): string {
  return path.join(analyticsDir(), 'browse-telemetry.jsonl');
}

let lastEnsuredDir: string | null = null;
async function ensureDir(): Promise<void> {
  const dir = analyticsDir();
  if (lastEnsuredDir === dir) return;
  await fs.mkdir(dir, { recursive: true });
  lastEnsuredDir = dir;
}

let telemetryDisabled: boolean | null = null;
/**
 * Is telemetry disabled for this process? Telemetry is OPT-IN: the consent
 * prompt writes a granted tier ('community' | 'anonymous') to
 * ~/.gstack/config.yaml, and only a granted tier enables emission. Tiers,
 * checked in order:
 *
 *   1. Env hint GSTACK_TELEMETRY_OFF=1 (set by preambles and test
 *      harnesses): always disabled, even over a granted config tier.
 *   2. Persistent tier via the shared flat-YAML helper in config.ts (same
 *      parser as the pair-agent gate, so the two consent gates never drift):
 *      explicit `telemetry: off` disables; 'community'/'anonymous' enable.
 *   3. Default: DISABLED. An absent key, absent file, or unrecognized value
 *      means consent was never granted — matching bin/gstack-config's
 *      DEFAULTS table, which reports 'off' for an unset telemetry key.
 *      Anything else would be a split-brain where `gstack-config get
 *      telemetry` tells the user 'off' while a direct-$B daemon emits.
 *      One escape hatch: GSTACK_TELEMETRY_OFF=0 is a harness-side consent
 *      assertion that flips this DEFAULT only (test harnesses exercising the
 *      write path against a scratch GSTACK_HOME) — it never overrides an
 *      explicit `telemetry: off` the user wrote.
 *
 * Exported so tests can pin the consent gate directly; the cached verdict
 * resets via _resetTelemetryCache.
 */
export function isTelemetryDisabled(): boolean {
  if (telemetryDisabled !== null) return telemetryDisabled;
  // Env kill switch (set by preamble or test harnesses): beats everything.
  if (process.env.GSTACK_TELEMETRY_OFF === '1') {
    telemetryDisabled = true;
    return true;
  }
  // Persistent tier: an explicit user-written value always wins next.
  const tier = readGstackConfigYamlKey('telemetry');
  if (tier === 'off') {
    telemetryDisabled = true;
    return true;
  }
  if (tier === 'community' || tier === 'anonymous') {
    telemetryDisabled = false;
    return false;
  }
  // No granted consent on record (absent key/file, unrecognized value):
  // disabled — unless the harness asserted consent via the env seam.
  telemetryDisabled = process.env.GSTACK_TELEMETRY_OFF !== '0';
  return telemetryDisabled;
}

export interface TelemetryEvent {
  event: string;
  [key: string]: unknown;
}

/** Fire-and-forget log. Never throws. */
export function logTelemetry(payload: TelemetryEvent): void {
  if (isTelemetryDisabled()) return;
  const enriched = { ...payload, ts: new Date().toISOString() };
  ensureDir()
    .then(() => fs.appendFile(telemetryFile(), JSON.stringify(enriched) + '\n', 'utf8'))
    .catch(() => {
      // Telemetry must never crash the caller. If the disk is full or perms
      // are wrong, swallow silently — there's nothing useful to do here.
    });
}

/** Test-only: reset cached state. */
export function _resetTelemetryCache(): void {
  telemetryDisabled = null;
  lastEnsuredDir = null;
}

/**
 * terminal-agent process-control primitives shared by cli.ts spawn site,
 * server.ts shutdown teardown, and the v1.44 watchdog/respawn loop.
 *
 * Why this exists: pre-v1.44 used `pkill -f terminal-agent\.ts`, which
 * matches any process whose argv contains the string and would kill
 * sibling gstack sessions on the same host. The agent now writes a
 * structured `terminal-agent-pid` record (`{pid, gen, startedAt}`) and
 * every kill site routes through `killAgentByRecord` here — identity-based,
 * no regex.
 *
 * The `gen` field is a per-boot generation counter. Loopback /internal/*
 * calls from the parent server include `X-Browse-Gen` so a slow agent that
 * the watchdog respawned around can't accidentally service a stale grant
 * from the old generation.
 */
import * as fs from 'fs';
import * as path from 'path';
import { safeUnlink, safeKill, isProcessAlive } from './error-handling';
import { restrictFilePermissions, mkdirSecure } from './file-permissions';
import { atomicWriteSync } from '../../lib/fs-atomic';

/**
 * Locate the terminal-agent script on disk. In dev (cli.ts running via
 * `bun run`), it lives next to this file in browse/src. In a compiled
 * binary, Bun's --compile bakes the source into the executable and
 * exposes it relative to process.execPath. Either path must work or
 * the agent can't be spawned at all.
 */
export function resolveTerminalAgentScript(searchHints: { metaDir?: string; execPath?: string } = {}): string | null {
  const meta = searchHints.metaDir || __dirname;
  const exec = searchHints.execPath || process.execPath;
  const candidates = [
    path.resolve(meta, 'terminal-agent.ts'),
    path.resolve(path.dirname(exec), '..', 'src', 'terminal-agent.ts'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return null;
}

/**
 * Spawn a fresh terminal-agent as a detached child. Handles the standard
 * three steps: kill any prior agent recorded at `<stateDir>/terminal-agent-pid`,
 * clear the stale record, then `Bun.spawn(['bun', 'run', script], ...)` with
 * env wiring. Returns the PID of the new agent on success, null when the
 * agent script can't be located.
 *
 * Used by both the CLI cold-start path (cli.ts) and the v1.44 watchdog in
 * server.ts. Centralizing here removes a copy-paste between them and means
 * spawn-env additions (BROWSE_OWNER_PID being the first) land in one place.
 */
export function spawnTerminalAgent(opts: {
  stateFile: string;
  serverPort: number;
  /** PID of the browse server that owns this agent. */
  ownerPid: number;
  cwd?: string;
  /** Optional extra env vars to add to the agent's process env. */
  extraEnv?: Record<string, string>;
  /** Override script lookup for tests. */
  scriptPath?: string;
}): number | null {
  const stateDir = path.dirname(opts.stateFile);
  const prior = readAgentRecord(stateDir);
  if (prior) {
    killAgentByRecord(prior, 'SIGTERM');
    clearAgentRecord(stateDir);
  }
  const script = opts.scriptPath || resolveTerminalAgentScript();
  if (!script || !fs.existsSync(script)) return null;
  const proc = (Bun as any).spawn(['bun', 'run', script], {
    cwd: opts.cwd || process.cwd(),
    env: {
      ...process.env,
      BROWSE_STATE_FILE: opts.stateFile,
      BROWSE_SERVER_PORT: String(opts.serverPort),
      BROWSE_OWNER_PID: String(opts.ownerPid),
      ...(opts.extraEnv || {}),
    },
    stdio: ['ignore', 'ignore', 'ignore'],
    // Explicit for the Node fallback path (dist/bun-polyfill.cjs), where the
    // host default is the opposite of Bun's. A visible console window on every
    // watchdog respawn is the symptom when this is missing.
    windowsHide: true,
  });
  proc.unref?.();
  return proc.pid ?? null;
}

export interface AgentRecord {
  pid: number;
  /** Random per-boot identifier. Loopback /internal/* sees X-Browse-Gen: <gen>. */
  gen: string;
  /** ms since epoch. Reserved for future PID-reuse guards. */
  startedAt: number;
}

export function agentRecordPath(stateDir: string): string {
  return path.join(stateDir, 'terminal-agent-pid');
}

/** Read the current record. Returns null on missing/malformed file. */
export function readAgentRecord(stateDir: string): AgentRecord | null {
  try {
    const raw = fs.readFileSync(agentRecordPath(stateDir), 'utf-8');
    const j = JSON.parse(raw);
    if (typeof j?.pid === 'number' && typeof j?.gen === 'string' && typeof j?.startedAt === 'number') {
      return j as AgentRecord;
    }
    return null;
  } catch {
    return null;
  }
}

/** Atomic write (throws on failure — boot must not proceed on a bad record). */
export function writeAgentRecord(stateDir: string, record: AgentRecord): void {
  try { mkdirSecure(stateDir); } catch {}
  const target = agentRecordPath(stateDir);
  atomicWriteSync(target, JSON.stringify(record), { mode: 0o600 });
  // Windows ACL hardening (POSIX chmod is redundant with mode above).
  restrictFilePermissions(target);
}

export function clearAgentRecord(stateDir: string): void {
  safeUnlink(agentRecordPath(stateDir));
}

/**
 * Kill the agent identified by `record`. Signal defaults to SIGTERM (give
 * the agent a chance to run its own SIGTERM cleanup). Returns true if a
 * signal was actually sent to a live PID; false if the PID was already
 * dead (no-op). Never throws — ESRCH is swallowed by safeKill.
 *
 * Validates liveness BEFORE signaling so a PID-reuse race (the recorded
 * PID was reaped and a brand-new unrelated process now holds it) can't
 * cause us to kill the wrong process. This is a best-effort defense:
 * Linux/macOS don't expose process-start-time cheaply, and the gap
 * between record-write and watchdog-tick is small (60s max).
 */
export function killAgentByRecord(
  record: AgentRecord,
  signal: NodeJS.Signals = 'SIGTERM',
): boolean {
  if (!isProcessAlive(record.pid)) return false;
  safeKill(record.pid, signal);
  return true;
}

/**
 * Terminal Agent — PTY-backed Claude Code terminal for the gstack browser
 * sidebar. Translates the phoenix gbrowser PTY (cmd/gbd/terminal.go) into
 * Bun, with a few changes informed by codex's outside-voice review:
 *
 *  - Lives in a separate non-compiled bun process from the browse daemon so
 *    a bug in WS framing or PTY cleanup can't take down the command surface.
 *  - Binds 127.0.0.1 only — never on the dual-listener tunnel surface.
 *  - Origin validation on the WS upgrade is REQUIRED (not defense-in-depth)
 *    because a localhost shell WS is a real cross-site WebSocket-hijacking
 *    target.
 *  - Cookie-based auth via /internal/grant from the parent server, not a
 *    token in /health.
 *  - Lazy spawn: claude PTY is not spawned until the WS receives its first
 *    data frame. Sidebar opens that never type don't burn a claude session.
 *  - PTY dies with WS close (one PTY per WS). v1.1 may add session
 *    survival; for v1 we match phoenix's lifecycle.
 *
 * The PTY uses Bun's `terminal:` spawn option (verified at impl time on
 * Bun 1.3.10): pass cols/rows + a data callback; write input via
 * `proc.terminal.write(buf)`; resize via `proc.terminal.resize(cols, rows)`.
 */
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { writeSecureFile, restrictFilePermissions, mkdirSecure } from './file-permissions';
import { atomicWriteSync, atomicWriteQuiet } from '../../lib/fs-atomic';
import { safeUnlink } from './error-handling';
import { writeAgentRecord, clearAgentRecord } from './terminal-agent-control';
import { findAvailablePort } from './port-allocator';
import { extractPtyCookie } from './pty-session-cookie';

const STATE_FILE = process.env.BROWSE_STATE_FILE || path.join(process.env.HOME || '/tmp', '.gstack', 'browse.json');
const PORT_FILE = path.join(path.dirname(STATE_FILE), 'terminal-port');
const BROWSE_SERVER_PORT = parseInt(process.env.BROWSE_SERVER_PORT || '0', 10);
const BROWSE_OWNER_PID = parseInt(process.env.BROWSE_OWNER_PID || '0', 10);
const OWNER_WATCHDOG_MS = parseInt(
  process.env.GSTACK_TERMINAL_OWNER_WATCHDOG_MS || '15000',
  10,
);
const EXTENSION_ID = process.env.BROWSE_EXTENSION_ID || ''; // optional: tighten Origin check
const INTERNAL_TOKEN = crypto.randomBytes(32).toString('base64url'); // shared with parent server via env at spawn
/**
 * Per-boot generation identifier. Loopback /internal/* callers include
 * `X-Browse-Gen: <CURRENT_GEN>` so a slow agent the watchdog respawned
 * around can't service a stale grant from the prior generation. Absent
 * header means "legacy caller" and is accepted (backward compat); a
 * present-but-mismatched header returns 409 stale generation.
 */
const CURRENT_GEN = crypto.randomBytes(16).toString('base64url');

// In-memory attach-token registry. Parent posts /internal/grant after
// /pty-session; we validate WS upgrades against this map.
//
// v1.44+: each token is bound to a v1.44 sessionId (the stable, non-secret
// identifier from browse/src/pty-session-lease.ts). The token grants ONE
// attach for ONE session — re-attach within the lease window comes through
// /pty-session/reattach, which mints a fresh token for the same sessionId.
//
// Legacy callers can still pass `{token}` without sessionId (the value
// stays null and the WS upgrade still works); those callers don't get
// re-attach because there's no stable identifier to match against.
const validTokens = new Map<string, string | null>(); // token → sessionId

/**
 * Reverse index for re-attach lookups: sessionId → live PtySession.
 * Populated when a WS first attaches with a known sessionId; cleared when
 * the session is disposed or the lease expires. Used by:
 *   - /ws upgrade: if the incoming attachToken maps to a sessionId that
 *     already has a live session, REPLACE its ws ref instead of spawning.
 *   - /internal/restart: enumerate by sessionId, dispose that one session.
 *
 * Kept separate from the WeakMap<ws,PtySession> so re-attach can find the
 * session by id even after the original ws has gone.
 */
const sessionsById = new Map<string, PtySession>();

// Active PTY session per WS. One terminal per connection. Codex finding #4:
// uncaught handlers below catch bugs in framing/cleanup so they don't kill
// the listener loop.
process.on('uncaughtException', (err) => {
  console.error('[terminal-agent] uncaughtException:', err);
});
process.on('unhandledRejection', (reason) => {
  console.error('[terminal-agent] unhandledRejection:', reason);
});

export interface PtySession {
  proc: any | null;        // Bun.Subprocess once spawned
  cols: number;
  rows: number;
  cookie: string;
  /**
   * Current attached websocket. Swapped on re-attach (Commit 3): when a new
   * WS upgrade matches this session's sessionId, the old liveWs is gone
   * and the new ws takes its place. The PTY on-data callback closes over
   * `session`, not the original `ws`, so it always writes to the current
   * liveWs (or skips the write when detached and liveWs is null).
   */
  liveWs: any | null;
  /**
   * v1.44+ stable session identifier (from pty-session-lease). Null for
   * legacy /internal/grant callers that didn't pass one. Used for
   * targeted /internal/restart and Commit 3 re-attach lookups.
   */
  sessionId: string | null;
  spawned: boolean;
  /**
   * 25s server-side WS keepalive interval (v1.44+). Set in the WS `open`
   * handler, cleared in `close`. We send `{type:"ping",ts}` text frames so
   * NAT boxes, proxies, and Chrome's MV3 panel-suspend heuristics see the
   * connection as active; the client either replies with `{type:"pong"}`
   * or fires its own 25s `{type:"keepalive"}` cycle. Either path keeps
   * the underlying TCP from being silently dropped.
   */
  pingInterval: ReturnType<typeof setInterval> | null;
  /**
   * Commit 3 scrollback ring buffer. Each PTY write appends a frame; the
   * total byte count is capped at RING_BUFFER_MAX_BYTES with oldest frames
   * evicted first. On re-attach, the surviving frames are replayed as a
   * single binary frame (prefixed with the v1.44 reset sequence) so the
   * user sees their last screen of output. Frame boundaries preserve UTF-8
   * + ANSI-CSI boundaries because each frame is the exact buffer that
   * spawnClaude's on-data callback emitted.
   */
  ringBuffer: Buffer[];
  ringBufferBytes: number;
  /**
   * Tracks whether the PTY is currently in xterm alt-screen mode. claude's
   * TUI enters alt-screen (CSI ?1049h) during tool calls and exits (CSI
   * ?1049l) when returning to the main prompt. On re-attach, the replay
   * prelude must re-enter alt-screen if the original PTY left it active,
   * otherwise the replay renders against the main screen and the cursor
   * + colors end up in the wrong place.
   */
  altScreenActive: boolean;
  /**
   * Detach state machine (Commit 3). When the WS closes for a reason OTHER
   * than the v1.44 intentional-restart code (4001), we keep the PtySession
   * alive for the detach window (default 60s) so a re-attach within the
   * window can resume the same PTY and replay the ring buffer. The timer
   * disposes the session if no re-attach arrives in time.
   */
  detached: boolean;
  detachTimer: ReturnType<typeof setTimeout> | null;
}

/**
 * WS keepalive interval. 25s is comfortably under the lowest common NAT
 * idle timeout (typically 30-60s) and shorter than Chromium's WebSocket
 * dead-peer threshold. Test-overridable via env so the v1.44 e2e tests
 * can compress idle-window assertions to <1s without waiting half a
 * minute per assertion.
 */
const KEEPALIVE_INTERVAL_MS = parseInt(
  process.env.GSTACK_PTY_KEEPALIVE_INTERVAL_MS || '25000',
  10,
);

/**
 * Commit 3 scrollback ring buffer cap. 1 MB is enough for a full screen
 * of dense claude output (including a recent tool result), small enough
 * that a worst-case 10 detached sessions only cost ~10 MB of RSS.
 * Env-overridable so e2e tests can verify eviction without writing 1 MB
 * of fixture data per assertion.
 */
const RING_BUFFER_MAX_BYTES = parseInt(
  process.env.GSTACK_PTY_RING_BUFFER_BYTES || `${1024 * 1024}`,
  10,
);

/**
 * Commit 3 detach window — how long to keep a session alive after WS
 * close (with any code other than 4001 intentional-restart) so a
 * re-attach can resume the same PTY. 60s is long enough to cover a
 * Chrome MV3 service-worker suspend cycle, a wifi blip, or a brief
 * laptop sleep; short enough that genuinely-closed sessions don't
 * stack up unbounded.
 */
const DETACH_WINDOW_MS = parseInt(
  process.env.GSTACK_PTY_DETACH_WINDOW_MS || '60000',
  10,
);

/**
 * Append a frame to a session's ring buffer, evicting oldest frames if
 * the total byte count exceeds RING_BUFFER_MAX_BYTES. Eviction is at
 * frame boundaries (one PTY write = one frame), so we never cut a
 * multi-byte UTF-8 sequence or a partial ANSI CSI in half — claude's
 * on-data callback emits coherent frames.
 *
 * Side effect: scans the appended chunk for alt-screen enter/exit
 * sequences (CSI ?1049h / CSI ?1049l) and updates session.altScreenActive
 * so the re-attach prelude knows whether to re-enter alt-screen.
 */
export function appendToRingBuffer(session: PtySession, frame: Buffer): void {
  session.ringBuffer.push(frame);
  session.ringBufferBytes += frame.length;
  while (session.ringBufferBytes > RING_BUFFER_MAX_BYTES && session.ringBuffer.length > 1) {
    const evicted = session.ringBuffer.shift()!;
    session.ringBufferBytes -= evicted.length;
  }
  // Alt-screen tracking. Scan for the canonical xterm enter/exit pairs.
  // We do this on every append (not just on attach) so the state is
  // correct even if many frames have flowed since the last attach.
  const ascii = frame.toString('latin1'); // single-byte view is enough — the codes are 7-bit ASCII
  // Use lastIndexOf so trailing state wins when both appear in one frame
  // (e.g., a quick tool-call open+close inside one render pass).
  const enterIdx = ascii.lastIndexOf('\x1b[?1049h');
  const exitIdx = ascii.lastIndexOf('\x1b[?1049l');
  if (enterIdx >= 0 && enterIdx > exitIdx) session.altScreenActive = true;
  else if (exitIdx >= 0 && exitIdx > enterIdx) session.altScreenActive = false;
}

/**
 * Build the re-attach replay payload: server-side reset prelude + the
 * accumulated ring buffer. The client side writes RIS (`\x1bc`) to xterm
 * BEFORE feeding this payload in, so the layout is:
 *
 *   1. Client: `\x1bc` (RIS — full reset, clears pre-blip xterm content)
 *   2. Server: `\x1b[!p` (DECSTR soft reset — re-defaults char attributes)
 *   3. Server: optional `\x1b[?1049h` if we were in alt-screen at detach
 *   4. Server: ring buffer contents, in append order
 *
 * The client coordinates the order by waiting for a `{type:"reattach-begin"}`
 * text frame before treating the next binary frame as replay. That separation
 * is what lets us prepend reset codes without clobbering the live stream
 * that resumes immediately after.
 */
export function buildReplayPayload(session: PtySession): Buffer {
  const parts: Buffer[] = [];
  parts.push(Buffer.from('\x1b[!p'));
  if (session.altScreenActive) parts.push(Buffer.from('\x1b[?1049h'));
  for (const frame of session.ringBuffer) parts.push(frame);
  return Buffer.concat(parts);
}

const sessions = new WeakMap<any, PtySession>(); // ws -> session

/** Find claude on PATH. */
function findClaude(): string | null {
  // Test-only override. Lets the integration tests spawn /bin/bash instead
  // of requiring claude to be installed on every CI runner. NEVER read in
  // production (sidebar UI). Documented in browse/test/terminal-agent-integration.test.ts.
  const override = process.env.BROWSE_TERMINAL_BINARY;
  if (override && fs.existsSync(override)) return override;
  // Bun.which is sync and respects PATH. Falls back to a small list of
  // common install locations if PATH is stripped (e.g., launched from
  // Conductor with a minimal env).
  const which = (Bun as any).which?.('claude');
  if (which) return which;
  const candidates = [
    '/opt/homebrew/bin/claude',
    '/usr/local/bin/claude',
    `${process.env.HOME}/.local/bin/claude`,
    `${process.env.HOME}/.bun/bin/claude`,
    `${process.env.HOME}/.npm-global/bin/claude`,
  ];
  for (const c of candidates) {
    try { fs.accessSync(c, fs.constants.X_OK); return c; } catch {}
  }
  return null;
}

/** Probe + persist claude availability for the bootstrap card. */
function writeClaudeAvailable(): void {
  const stateDir = path.dirname(STATE_FILE);
  try { mkdirSecure(stateDir); } catch {}
  const found = findClaude();
  const status = {
    available: !!found,
    path: found || undefined,
    install_url: 'https://docs.anthropic.com/en/docs/claude-code',
    checked_at: new Date().toISOString(),
  };
  const target = path.join(stateDir, 'claude-available.json');
  // Fire-and-forget state file: a failed write must not break boot.
  if (atomicWriteQuiet(target, JSON.stringify(status, null, 2), { mode: 0o600 })) {
    restrictFilePermissions(target); // Windows ACL hardening
  }
}

/**
 * System-prompt hint passed to claude via --append-system-prompt. Tells
 * claude what tab-awareness affordances exist in this session so it
 * doesn't have to discover them by trial. The user can override anything
 * here just by saying so — system prompt is a soft hint, not a contract.
 *
 * Two paths claude has:
 *   1. Read live state from <stateDir>/tabs.json + active-tab.json
 *      (updated continuously by the gstack browser extension).
 *   2. Run $B tab, $B tabs, $B tab-each <command> to act on tabs. The
 *      tab-each helper fans a single command across every open tab and
 *      returns per-tab results as JSON.
 */
function buildTabAwarenessHint(stateDir: string): string {
  const tabsFile = path.join(stateDir, 'tabs.json');
  const activeFile = path.join(stateDir, 'active-tab.json');
  return [
    'You are running inside the gstack browser sidebar with live access to the user\'s browser tabs.',
    '',
    'Tab state files (kept fresh automatically by the extension):',
    `  ${tabsFile}        — all open tabs (id, url, title, active, pinned)`,
    `  ${activeFile}    — the currently active tab`,
    'Read these any time the user asks about "tabs", "the current page", or anything multi-tab. Do NOT shell out to $B tabs just to learn what\'s open — read the file.',
    '',
    'Tab manipulation commands (via $B):',
    '  $B tab <id>                 — switch to a tab',
    '  $B newtab [url]             — open a new tab',
    '  $B closetab [id]            — close a tab (current if no id)',
    '  $B tab-each <command>       — fan out a command across every tab; returns JSON results',
    '',
    'When the user asks for multi-tab work, prefer $B tab-each. Examples:',
    '  $B tab-each snapshot -i     — grab a snapshot from every tab',
    '  $B tab-each text            — pull clean text from every tab',
    '  $B tab-each title           — list every tab\'s title',
    '',
    'You\'re in a real terminal with a real PTY — slash commands, /resume, ANSI colors all work as in a normal claude session.',
  ].join('\n');
}

/** Spawn claude in a PTY. Returns null if claude not on PATH. */
function spawnClaude(cols: number, rows: number, onData: (chunk: Buffer) => void) {
  const claudePath = findClaude();
  if (!claudePath) return null;

  // Match phoenix env so claude knows which browse server to talk to and
  // doesn't try to autostart its own. BROWSE_HEADED=1 keeps the existing
  // headed-mode browser; BROWSE_NO_AUTOSTART prevents claude's gstack
  // tooling from racing to spawn another server.
  const env: Record<string, string> = {
    ...process.env as any,
    BROWSE_PORT: String(BROWSE_SERVER_PORT),
    BROWSE_STATE_FILE: STATE_FILE,
    BROWSE_NO_AUTOSTART: '1',
    BROWSE_HEADED: '1',
    TERM: 'xterm-256color',
    COLORTERM: 'truecolor',
  };

  // --append-system-prompt is the right injection surface (per `claude --help`):
  // it gets appended to the model's system prompt, so claude treats this as
  // contextual guidance, not a user message. Don't use a leading PTY write
  // for this — that would show up as if the user typed the hint, polluting
  // the visible transcript.
  const stateDir = path.dirname(STATE_FILE);
  const tabHint = buildTabAwarenessHint(stateDir);

  const proc = (Bun as any).spawn([claudePath, '--append-system-prompt', tabHint], {
    windowsHide: true,
    terminal: {
      rows,
      cols,
      data(_terminal: any, chunk: Buffer) { onData(chunk); },
    },
    env,
  });
  return proc;
}

/** Cleanup a PTY session: SIGINT, then SIGKILL after 3s. */
function disposeSession(session: PtySession): void {
  try { session.proc?.terminal?.close?.(); } catch {}
  if (session.proc?.pid) {
    try { session.proc.kill?.('SIGINT'); } catch {}
    setTimeout(() => {
      try {
        if (session.proc && !session.proc.killed) session.proc.kill?.('SIGKILL');
      } catch {}
    }, 3000);
  }
  session.proc = null;
  session.spawned = false;
}

/**
 * Build the HTTP server. Two routes:
 *   POST /internal/grant — parent server pushes a fresh cookie token
 *   GET  /ws             — extension upgrades to WebSocket (PTY transport)
 *
 * Everything else returns 404. The listener binds 127.0.0.1 only.
 */
/**
 * Validate a loopback /internal/* request. Returns null when the request
 * is allowed; otherwise returns the Response to send back. Centralizes
 * bearer auth + the v1.44 X-Browse-Gen generation check so adding a new
 * /internal/* route is a one-liner.
 */
function checkInternalAuth(req: Request): Response | null {
  const auth = req.headers.get('authorization');
  if (auth !== `Bearer ${INTERNAL_TOKEN}`) {
    return new Response('forbidden', { status: 403 });
  }
  const headerGen = req.headers.get('x-browse-gen');
  if (headerGen && headerGen !== CURRENT_GEN) {
    return new Response('stale generation', { status: 409 });
  }
  return null;
}

/**
 * Wrap a JSON-bodied /internal/* handler with the standard bearer-auth +
 * generation-check + json-parse + error-response boilerplate. The handler
 * `fn` is called with the parsed body; whatever it returns is JSON-stringified
 * into a 200 Response, or the handler can return a Response directly to
 * customize status / headers. Throwing from `fn` collapses to a 400 "bad".
 *
 * Centralizing the dance kills the copy-paste pattern of bearer + gen check
 * + req.json().then(...).catch(...) that every /internal/* route needs.
 * New routes become a single call to internalHandler.
 */
async function internalHandler<T>(
  req: Request,
  fn: (body: any) => T | Promise<T> | Response | Promise<Response>,
): Promise<Response> {
  const denied = checkInternalAuth(req);
  if (denied) return denied;
  let body: any;
  try {
    body = await req.json();
  } catch {
    return new Response('bad', { status: 400 });
  }
  try {
    const result = await fn(body);
    if (result instanceof Response) return result;
    if (result === undefined || result === null) return new Response('ok');
    return new Response(JSON.stringify(result), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch {
    return new Response('bad', { status: 400 });
  }
}

/**
 * Spawn the claude PTY for a session if it hasn't been spawned yet.
 * Used by both the legacy binary-frame spawn trigger and the v1.44 explicit
 * `{type:"start"}` text-frame trigger. Idempotent on `session.spawned`.
 *
 * Returns true if claude is now running, false if spawn failed (e.g. claude
 * binary not on PATH). On failure, the caller is expected to have already
 * surfaced the error to the client (or will via the next frame).
 */
function maybeSpawnPty(ws: any, session: PtySession): boolean {
  if (session.spawned) return true;
  session.spawned = true;
  let leftover = Buffer.alloc(0);
  const proc = spawnClaude(session.cols, session.rows, (chunk) => {
    const combined = Buffer.concat([leftover, Buffer.from(chunk)]);
    // UTF-8 boundary detection (issue #1272). Look back at most 3 bytes
    // for the start of an incomplete multibyte sequence and defer it.
    let safeEnd = combined.length;
    for (let i = combined.length - 1; i >= Math.max(0, combined.length - 3); i--) {
      const b = combined[i];
      if ((b & 0x80) === 0) { safeEnd = i + 1; break; }
      if ((b & 0xC0) === 0x80) continue;
      const expected = (b & 0xE0) === 0xC0 ? 2 : (b & 0xF0) === 0xE0 ? 3 : 4;
      safeEnd = (combined.length - i >= expected) ? combined.length : i;
      break;
    }
    const flush = combined.slice(0, safeEnd);
    leftover = combined.slice(safeEnd);
    if (flush.length) {
      // Always record into the ring buffer (Commit 3) so re-attach can
      // replay. session.liveWs is what changes across re-attaches — we
      // close over `session`, not the original `ws`, so the write always
      // goes to whichever ws is currently attached (or is skipped when
      // detached and liveWs is null).
      appendToRingBuffer(session, flush);
      if (session.liveWs) {
        try { session.liveWs.sendBinary(flush); } catch {}
      }
    }
  });
  if (!proc) {
    try {
      ws.send(JSON.stringify({
        type: 'error',
        code: 'CLAUDE_NOT_FOUND',
        message: 'claude CLI not on PATH. Install: https://docs.anthropic.com/en/docs/claude-code',
      }));
      ws.close(4404, 'claude not found');
    } catch {}
    return false;
  }
  session.proc = proc;
  proc.exited?.then?.(() => {
    try { session.liveWs?.close(1000, 'pty exited'); } catch {}
  });
  return true;
}

function buildServer(port: number) {
  return Bun.serve({
    hostname: '127.0.0.1',
    // #2314: allocated from the SAME fixed 10000-60000 scan range the main
    // server uses (port-allocator.ts, decision 8) — never `port: 0`. Binding
    // 0 drew from the OS EPHEMERAL range (49152-65535 on macOS), where this
    // weeks-lived agent squatted ports that short-lived `app.listen(0)` test
    // servers expected to receive, absorbing their traffic as phantom 404s.
    port,
    idleTimeout: 0, // PTY connections are long-lived; default idleTimeout would kill them

    fetch(req, server) {
      const url = new URL(req.url);

      // /internal/grant — loopback-only handshake from parent server.
      // v1.44+: accepts `{token, sessionId?}`. The sessionId binding lets
      // the agent route re-attach attempts (same sessionId, fresh token)
      // back to the same PtySession. Legacy callers passing just `{token}`
      // still work — sessionId becomes null and re-attach is unavailable
      // for that grant.
      if (url.pathname === '/internal/grant' && req.method === 'POST') {
        return internalHandler(req, (body) => {
          if (typeof body?.token === 'string' && body.token.length > 16) {
            const sid = typeof body?.sessionId === 'string' && body.sessionId.length > 0
              ? body.sessionId
              : null;
            validTokens.set(body.token, sid);
          }
        });
      }

      // /internal/revoke — drop a token (called on WS close or bootstrap reload)
      if (url.pathname === '/internal/revoke' && req.method === 'POST') {
        return internalHandler(req, (body) => {
          if (typeof body?.token === 'string') validTokens.delete(body.token);
        });
      }

      // /internal/restart — dispose the PtySession for a specific sessionId.
      // Scoped to one caller (not enumerate-all). Server.ts /pty-restart
      // posts here with the caller's sessionId; we kill ONLY that PTY,
      // leaving any other live sidebar tabs untouched. Codex T2 of the
      // eng review caught this gap — pre-spec the route would have
      // disposed all sessions.
      if (url.pathname === '/internal/restart' && req.method === 'POST') {
        return internalHandler(req, (body) => {
          const sid = typeof body?.sessionId === 'string' ? body.sessionId : null;
          if (!sid) return { killed: 0 };
          const session = sessionsById.get(sid);
          if (!session) return { killed: 0 };
          // Cancel any pending detach timer before disposal — otherwise it
          // would fire later against an already-disposed session.
          if (session.detachTimer) {
            clearTimeout(session.detachTimer);
            session.detachTimer = null;
          }
          disposeSession(session);
          sessionsById.delete(sid);
          return { killed: 1 };
        });
      }

      // /internal/healthz — liveness probe used by the v1.44 watchdog.
      // Returns this agent's pid + gen + active session count without
      // touching claude binary lookup (which can fail for non-process
      // reasons and isn't a useful liveness signal). GET — no body to parse,
      // so it stays on the bare checkInternalAuth gate.
      if (url.pathname === '/internal/healthz' && req.method === 'GET') {
        const denied = checkInternalAuth(req);
        if (denied) return denied;
        return new Response(JSON.stringify({
          pid: process.pid,
          gen: CURRENT_GEN,
          sessions: validTokens.size,
        }), { status: 200, headers: { 'Content-Type': 'application/json' } });
      }

      // /claude-available — bootstrap card hits this when user clicks "I installed it".
      if (url.pathname === '/claude-available' && req.method === 'GET') {
        writeClaudeAvailable();
        const found = findClaude();
        return new Response(JSON.stringify({ available: !!found, path: found }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // /ws — WebSocket upgrade. CRITICAL gates:
      //   (1) Origin must be chrome-extension://<id>. Cross-site WS hijacking
      //       defense — required, not optional.
      //   (2) Token must be in validTokens. We accept the token via two
      //       transports for compatibility:
      //         - Sec-WebSocket-Protocol (preferred for browsers — the only
      //           auth header settable from the browser WebSocket API)
      //         - Cookie gstack_pty (works for non-browser callers and
      //           same-port browser callers; doesn't survive the cross-port
      //           jump from server.ts:34567 to the agent's random port
      //           when SameSite=Strict is set)
      //       Either path works; both verify against the same in-memory
      //       validTokens Set, populated by the parent server's
      //       authenticated /pty-session → /internal/grant chain.
      if (url.pathname === '/ws') {
        const origin = req.headers.get('origin') || '';
        const isExtensionOrigin = origin.startsWith('chrome-extension://');
        if (!isExtensionOrigin) {
          return new Response('forbidden origin', { status: 403 });
        }
        if (EXTENSION_ID && origin !== `chrome-extension://${EXTENSION_ID}`) {
          return new Response('forbidden origin', { status: 403 });
        }

        // Try Sec-WebSocket-Protocol first. Format: a single token, possibly
        // with a `gstack-pty.` prefix (which we strip). Browsers send a
        // comma-separated list when multiple were requested; we pick the
        // first that matches a known token.
        const protoHeader = req.headers.get('sec-websocket-protocol') || '';
        let token: string | null = null;
        for (const raw of protoHeader.split(',').map(s => s.trim()).filter(Boolean)) {
          const candidate = raw.startsWith('gstack-pty.') ? raw.slice('gstack-pty.'.length) : raw;
          if (validTokens.has(candidate)) {
            token = candidate;
            break;
          }
        }

        // Fallback: Cookie gstack_pty (legacy / non-browser callers).
        // Parsing is shared with the server via extractPtyCookie; VALIDATION
        // deliberately stays against the agent's own validTokens map — the
        // server's registry lives in a different process.
        if (!token) {
          const candidate = extractPtyCookie(req);
          if (candidate && validTokens.has(candidate)) {
            token = candidate;
          }
        }

        if (!token) {
          return new Response('unauthorized', { status: 401 });
        }

        // v1.44+: surface the token's sessionId binding to the upgraded ws.
        // open() reads it via ws.data and registers the session in
        // sessionsById so /internal/restart and (Commit 3) re-attach
        // lookups can find it.
        const sessionId = validTokens.get(token) ?? null;
        // No explicit Sec-WebSocket-Protocol echo: Bun >= 1.3 auto-echoes the
        // first offered protocol in the 101 response, so setting the header
        // here produced a DUPLICATE header — strict clients (Chromium, python
        // websockets) reject the handshake per RFC 6455 and the sidebar
        // terminal could never connect. Verified on Bun 1.3.6.
        const upgraded = server.upgrade(req, {
          data: { cookie: token, sessionId },
        });
        return upgraded ? undefined : new Response('upgrade failed', { status: 500 });
      }

      return new Response('not found', { status: 404 });
    },

    websocket: {
      /**
       * Spawn the claude PTY for `session` if it hasn't been spawned yet.
       * Called from both message paths: the legacy binary-frame trigger
       * (any keystroke) AND the v1.44 explicit `{type:"start"}` trigger
       * (forceRestart sends this on every fresh WS to get an eager prompt
       * without requiring the user to type). Idempotent — a second call
       * after `spawned: true` is a no-op.
       */
      open(ws) {
        const sessionId = (ws.data as any)?.sessionId ?? null;
        const cookie = (ws.data as any)?.cookie || '';

        // Commit 3 re-attach: if this sessionId already has a detached
        // PtySession in sessionsById, REPLACE its liveWs ref and replay
        // the ring buffer. The PTY process is unchanged — claude keeps
        // running through the wifi blip / panel-suspend cycle.
        if (sessionId) {
          const existing = sessionsById.get(sessionId);
          if (existing) {
            if (existing.detachTimer) {
              clearTimeout(existing.detachTimer);
              existing.detachTimer = null;
            }
            existing.detached = false;
            existing.liveWs = ws;
            existing.cookie = cookie;
            // Re-bind the WS-keyed map so resize/close/message handlers
            // can still find this session via the new ws.
            sessions.set(ws, existing);
            // Restart keepalive on the new ws.
            if (existing.pingInterval) clearInterval(existing.pingInterval);
            existing.pingInterval = setInterval(() => {
              try { ws.send(JSON.stringify({ type: 'ping', ts: Date.now() })); } catch {}
            }, KEEPALIVE_INTERVAL_MS);
            // Tell the client to prep its xterm (write RIS) before the
            // replay binary arrives. Order matters — the binary frame
            // immediately after this text frame IS the replay.
            try { ws.send(JSON.stringify({ type: 'reattach-begin', sessionId })); } catch {}
            try { ws.sendBinary(buildReplayPayload(existing)); } catch {}
            return;
          }
        }

        const session: PtySession = {
          proc: null,
          cols: 80,
          rows: 24,
          cookie,
          liveWs: ws,
          sessionId,
          spawned: false,
          pingInterval: null,
          ringBuffer: [],
          ringBufferBytes: 0,
          altScreenActive: false,
          detached: false,
          detachTimer: null,
        };
        session.pingInterval = setInterval(() => {
          try {
            ws.send(JSON.stringify({ type: 'ping', ts: Date.now() }));
          } catch {
            // ws likely closed mid-tick; close handler clears the interval.
          }
        }, KEEPALIVE_INTERVAL_MS);
        sessions.set(ws, session);
        // Index by sessionId for /internal/restart + Commit 3 re-attach.
        if (sessionId) sessionsById.set(sessionId, session);
      },

      message(ws, raw) {
        let session = sessions.get(ws);
        if (!session) {
          // Fallback for any path where open() didn't fire (shouldn't happen
          // in Bun.serve but keeps the spawn path safe). No keepalive on
          // this branch — open() is the supported entry point.
          session = {
            proc: null,
            cols: 80,
            rows: 24,
            cookie: (ws.data as any)?.cookie || '',
            liveWs: ws,
            sessionId: (ws.data as any)?.sessionId ?? null,
            spawned: false,
            pingInterval: null,
            ringBuffer: [],
            ringBufferBytes: 0,
            altScreenActive: false,
            detached: false,
            detachTimer: null,
          };
          sessions.set(ws, session);
          if (session.sessionId) sessionsById.set(session.sessionId, session);
        }

        // Text frames are control messages: {type: "resize", cols, rows},
        // {type: "tabSwitch", tabId, url, title}, {type: "tabState", ...},
        // or v1.44 keepalive frames: {type: "pong", ts}, {type: "keepalive"}.
        // Binary frames are raw input bytes destined for the PTY stdin.
        if (typeof raw === 'string') {
          let msg: any;
          try { msg = JSON.parse(raw); } catch { return; }
          if (msg?.type === 'resize') {
            const cols = Math.max(2, Math.floor(Number(msg.cols) || 80));
            const rows = Math.max(2, Math.floor(Number(msg.rows) || 24));
            session.cols = cols;
            session.rows = rows;
            try { session.proc?.terminal?.resize?.(cols, rows); } catch {}
            return;
          }
          if (msg?.type === 'tabSwitch') {
            handleTabSwitch(msg);
            return;
          }
          if (msg?.type === 'tabState') {
            handleTabState(msg);
            return;
          }
          if (msg?.type === 'pong' || msg?.type === 'keepalive' || msg?.type === 'ping') {
            // Keepalive frames — accepted and silently dropped. The mere
            // fact that the WS carried this frame is the liveness signal;
            // there's no application-level state to update at this layer.
            // `ping` is acknowledged here too in case the client (or a
            // future agent peer) mirrors our server-side ping shape.
            return;
          }
          if (msg?.type === 'start') {
            // v1.44 explicit spawn trigger. forceRestart sends this
            // immediately on every fresh WS so claude boots without the
            // user having to type a keystroke (pre-v1.44, the lazy-binary
            // spawn made restart look stuck until the user typed). No-op
            // if already spawned.
            maybeSpawnPty(ws, session);
            return;
          }
          // Unknown text frame — ignore.
          return;
        }

        // Binary input. Lazy-spawn claude on the first byte if `start`
        // wasn't sent first. Both paths land in the same maybeSpawnPty
        // helper for behavior parity.
        if (!session.spawned) {
          if (!maybeSpawnPty(ws, session)) return;
        }
        try {
          // raw is a Uint8Array; Bun.Terminal.write accepts string|Buffer.
          // Convert to Buffer for safety.
          session.proc?.terminal?.write?.(Buffer.from(raw as Uint8Array));
        } catch (err) {
          console.error('[terminal-agent] terminal.write failed:', err);
        }
      },

      close(ws, code, _reason) {
        const session = sessions.get(ws);
        if (!session) return;
        // Always drop the WS-keyed map entry and the per-attach
        // attachToken — the attach grant was single-use.
        sessions.delete(ws);
        if (session.cookie) validTokens.delete(session.cookie);
        // Keepalive lives with the WS — every attach starts a fresh one.
        if (session.pingInterval) {
          clearInterval(session.pingInterval);
          session.pingInterval = null;
        }

        // Commit 3 detach state machine. If the close was intentional
        // (code 4001 = restart, 4404 = no-claude error), dispose
        // immediately — there's no value in keeping the PTY alive.
        // Otherwise enter the detach window: claude keeps running, the
        // ring buffer keeps accumulating, and a re-attach with the same
        // sessionId within DETACH_WINDOW_MS picks back up. If the timer
        // fires without a re-attach, the session is disposed normally.
        //
        // Sessions without a sessionId (legacy single-shot grants) can't
        // re-attach by definition — fall through to immediate dispose.
        const intentional = code === 4001 || code === 4404 || code === 1000;
        if (intentional || !session.sessionId) {
          disposeSession(session);
          if (session.sessionId) sessionsById.delete(session.sessionId);
          return;
        }

        // Mark detached and start the disposal timer. The session stays
        // in sessionsById so the next /ws upgrade with the same
        // sessionId can find and reattach to it.
        session.detached = true;
        session.liveWs = null;
        session.detachTimer = setTimeout(() => {
          if (!session.detached) return; // re-attached in the meantime
          disposeSession(session);
          if (session.sessionId) sessionsById.delete(session.sessionId);
        }, DETACH_WINDOW_MS);
        // setTimeout returns a Bun Timer; unref so the detach window
        // doesn't keep the process alive past natural shutdown.
        (session.detachTimer as any)?.unref?.();
      },
    },
  });
}

/**
 * Tab-switch helper: write the active tab to a state file (claude reads it)
 * and notify the parent server so its activeTabId stays synced. Skips
 * chrome:// and chrome-extension:// internal pages.
 */
/**
 * Live tab snapshot. Writes <stateDir>/tabs.json (full list) and updates
 * <stateDir>/active-tab.json (current active). claude can read these any
 * time without invoking $B tabs — saves a round-trip when the model just
 * needs to check the landscape before deciding what to do.
 */
function handleTabState(msg: {
  active?: { tabId?: number; url?: string; title?: string } | null;
  tabs?: Array<{ tabId?: number; url?: string; title?: string; active?: boolean; windowId?: number; pinned?: boolean; audible?: boolean }>;
  reason?: string;
}): void {
  const stateDir = path.dirname(STATE_FILE);
  try { mkdirSecure(stateDir); } catch {}

  // tabs.json — full list
  if (Array.isArray(msg.tabs)) {
    const payload = {
      updatedAt: new Date().toISOString(),
      reason: msg.reason || 'unknown',
      tabs: msg.tabs.map(t => ({
        tabId: t.tabId ?? null,
        url: t.url || '',
        title: t.title || '',
        active: !!t.active,
        windowId: t.windowId ?? null,
        pinned: !!t.pinned,
        audible: !!t.audible,
      })),
    };
    const target = path.join(stateDir, 'tabs.json');
    // Fire-and-forget state file: atomic write (via lib/fs-atomic) so
    // claude never reads a half-written JSON document; failures swallowed.
    if (atomicWriteQuiet(target, JSON.stringify(payload, null, 2), { mode: 0o600 })) {
      restrictFilePermissions(target); // Windows ACL hardening
    }
  }

  // active-tab.json — single active tab. Skip chrome-internal pages so
  // claude doesn't see chrome:// or chrome-extension:// URLs as
  // "current target."
  const active = msg.active;
  if (active && active.url && !active.url.startsWith('chrome://') && !active.url.startsWith('chrome-extension://')) {
    const ctxFile = path.join(stateDir, 'active-tab.json');
    const ok = atomicWriteQuiet(ctxFile, JSON.stringify({
      tabId: active.tabId ?? null,
      url: active.url,
      title: active.title ?? '',
    }), { mode: 0o600 });
    if (ok) restrictFilePermissions(ctxFile); // Windows ACL hardening
  }
}

function handleTabSwitch(msg: { tabId?: number; url?: string; title?: string }): void {
  const url = msg.url || '';
  if (!url || url.startsWith('chrome://') || url.startsWith('chrome-extension://')) return;

  const stateDir = path.dirname(STATE_FILE);
  const ctxFile = path.join(stateDir, 'active-tab.json');
  // Fire-and-forget: atomic write via lib/fs-atomic, failures swallowed.
  const ok = atomicWriteQuiet(ctxFile, JSON.stringify({
    tabId: msg.tabId ?? null,
    url,
    title: msg.title ?? '',
  }), { mode: 0o600 });
  if (ok) restrictFilePermissions(ctxFile); // Windows ACL hardening

  // Best-effort sync to parent server so its activeTabId tracking matches.
  // No await; this is fire-and-forget.
  if (BROWSE_SERVER_PORT > 0) {
    fetch(`http://127.0.0.1:${BROWSE_SERVER_PORT}/command`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${readBrowseToken()}`,
      },
      body: JSON.stringify({
        command: 'tab',
        args: [String(msg.tabId ?? ''), '--no-focus'],
      }),
    }).catch(() => {});
  }
}

function readBrowseToken(): string {
  try {
    const raw = fs.readFileSync(STATE_FILE, 'utf-8');
    const j = JSON.parse(raw);
    return j.token || '';
  } catch { return ''; }
}

// Boot.
async function main() {
  writeClaudeAvailable();
  // #2314: allocate from the shared fixed scan range, then bind. Probe-then-
  // bind has a TOCTOU window — a concurrent process can take the port between
  // the probe and Bun.serve, which throws and would kill the boot with no
  // retry (main().catch → exit 1). Re-allocate and retry a few times; each
  // iteration probes fresh, so only a genuine race lands here.
  let server: ReturnType<typeof buildServer> | undefined;
  let lastBindErr: unknown;
  for (let attempt = 0; attempt < 5 && !server; attempt++) {
    const allocatedPort = await findAvailablePort();
    try {
      server = buildServer(allocatedPort);
    } catch (err) {
      lastBindErr = err;
    }
  }
  if (!server) {
    console.error(`[terminal-agent] failed to bind after 5 attempts: ${lastBindErr}`);
    process.exit(1);
  }
  const port = (server as any).port || (server as any).address?.port;
  if (!port) {
    console.error('[terminal-agent] failed to bind: no port');
    process.exit(1);
  }

  // Write port file atomically so the parent server can pick it up.
  // Throws on failure — a boot without a discoverable port file is broken.
  const dir = path.dirname(PORT_FILE);
  try { mkdirSecure(dir); } catch {}
  atomicWriteSync(PORT_FILE, String(port), { mode: 0o600 });
  restrictFilePermissions(PORT_FILE); // Windows ACL hardening

  // Write identity-based agent record (pid + per-boot gen). Replaces the
  // v1.43- `pkill -f terminal-agent\.ts` regex teardown that could kill
  // sibling gstack sessions. Callers (cli.ts spawn site, server.ts
  // shutdown, the v1.44 watchdog) now route through killAgentByRecord in
  // terminal-agent-control.ts.
  writeAgentRecord(dir, { pid: process.pid, gen: CURRENT_GEN, startedAt: Date.now() });

  // Hand the parent the internal token so it can call /internal/grant.
  // Parent learns INTERNAL_TOKEN via env (TERMINAL_AGENT_INTERNAL_TOKEN below).
  // We just print it on stdout for the supervising process to pick up if it's
  // not already in env. Defense against env races at spawn time.
  console.log(`[terminal-agent] listening on 127.0.0.1:${port} pid=${process.pid} gen=${CURRENT_GEN}`);

  // Cleanup port file + agent record on exit.
  let cleaningUp = false;
  const cleanup = () => {
    if (cleaningUp) return;
    cleaningUp = true;
    safeUnlink(PORT_FILE);
    safeUnlink(INTERNAL_TOKEN_FILE);
    clearAgentRecord(dir);
    process.exit(0);
  };
  process.on('SIGTERM', cleanup);
  process.on('SIGINT', cleanup);

  // The terminal agent is intentionally detached so it survives the short-lived
  // CLI launcher, but its real owner is the persistent browse server. If that
  // server crashes or is killed before running normal shutdown, the agent would
  // otherwise be adopted by PID 1 and live forever. Poll the server PID and use
  // the same cleanup path as an intentional shutdown when it disappears.
  if (BROWSE_OWNER_PID > 0) {
    const ownerWatchdog = setInterval(() => {
      try {
        process.kill(BROWSE_OWNER_PID, 0);
      } catch {
        cleanup();
      }
    }, OWNER_WATCHDOG_MS);
    (ownerWatchdog as any)?.unref?.();
  }
}

// Export the internal token so cli.ts can pass the SAME value to the parent
// server via env. Parent reads BROWSE_TERMINAL_INTERNAL_TOKEN and uses it
// for /internal/grant calls.
//
// In practice, the agent generates INTERNAL_TOKEN once at boot and writes it
// to a state file the parent reads. This avoids env-passing races. See main().
const INTERNAL_TOKEN_FILE = path.join(path.dirname(STATE_FILE), 'terminal-internal-token');
try {
  mkdirSecure(path.dirname(INTERNAL_TOKEN_FILE));
  writeSecureFile(INTERNAL_TOKEN_FILE, INTERNAL_TOKEN);
} catch {}

main().catch((err) => {
  console.error(`[terminal-agent] boot failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
});

/**
 * Token registry — per-agent scoped tokens for multi-agent browser access.
 *
 * Architecture:
 *   Root token (from server startup) → POST /token → scoped sub-tokens
 *   POST /connect (setup key exchange) → session token
 *
 *   Token lifecycle:
 *     createSetupKey() → exchangeSetupKey() → session token (24h default)
 *     createToken()    → direct session token (for CLI/local use)
 *     revokeToken()    → immediate invalidation
 *     rotateRoot()     → new root, all scoped tokens invalidated
 *
 *   Scope categories (derived from commands.ts READ/WRITE/META sets):
 *     read  — snapshot, text, html, links, forms, console, etc.
 *     write — goto, click, fill, scroll, newtab, etc.
 *     admin — eval, js, cookies, storage, useragent, state (destructive)
 *     meta  — tab, diff, chain, frame, responsive
 *
 *   Security invariants:
 *     1. Only root token can mint sub-tokens (POST /token, POST /connect)
 *     2. control scope denied by default — must be explicitly flagged.
 *        Registry API defaults (createToken/createSetupKey with no scopes)
 *        stay ['read','write']; the /pair ceremony explicitly grants
 *        DEFAULT_PAIR_SCOPES (read+write+admin+meta — the pairing ceremony
 *        is the trust boundary; --restrict narrows, --control must be
 *        explicit and never rides in via a scopes list)
 *     3. chain command scope-checks each subcommand individually
 *     4. Root token never in connection strings or pasted instructions
 *
 * Zero side effects on import. Safe to import from tests.
 */

import * as crypto from 'crypto';
import { READ_COMMANDS, WRITE_COMMANDS, META_COMMANDS } from './commands';

// ─── Scope Definitions ─────────────────────────────────────────
// Derived from commands.ts, but reclassified by actual side effects.
// The key insight (from Codex adversarial review): commands.ts READ_COMMANDS
// includes js/eval/cookies/storage which are actually dangerous. The scope
// model here overrides the commands.ts classification.

/** Commands safe for read-only agents */
export const SCOPE_READ = new Set([
  'snapshot', 'text', 'html', 'links', 'forms', 'accessibility',
  'console', 'network', 'perf', 'dialog', 'is', 'inspect',
  'url', 'tabs', 'status', 'screenshot', 'pdf', 'css', 'attrs',
  'media', 'data',
]);

/** Commands that modify page state or navigate */
export const SCOPE_WRITE = new Set([
  'goto', 'back', 'forward', 'reload',
  'load-html',
  'click', 'fill', 'select', 'hover', 'type', 'press', 'scroll', 'wait',
  'upload', 'viewport', 'newtab', 'closetab',
  'dialog-accept', 'dialog-dismiss',
  'download', 'scrape', 'archive',
]);

/** Page-level power tools — JS execution, credential access, page mutations */
export const SCOPE_ADMIN = new Set([
  'eval', 'js', 'cookies', 'storage',
  'cookie', 'cookie-import', 'cookie-import-browser',
  'header', 'useragent',
  'style', 'cleanup', 'prettyscreenshot',
]);

/** Browser-wide destructive commands — can kill the server, disconnect headed mode */
export const SCOPE_CONTROL = new Set([
  'state', 'handoff', 'resume', 'stop', 'restart', 'connect', 'disconnect',
]);

/** Meta commands — generally safe but some need scope checking */
export const SCOPE_META = new Set([
  'tab', 'diff', 'frame', 'responsive', 'snapshot',
  'watch', 'inbox', 'focus',
]);

export type ScopeCategory = 'read' | 'write' | 'admin' | 'meta' | 'control';

const SCOPE_MAP: Record<ScopeCategory, Set<string>> = {
  read: SCOPE_READ,
  write: SCOPE_WRITE,
  admin: SCOPE_ADMIN,
  control: SCOPE_CONTROL,
  meta: SCOPE_META,
};

/**
 * Scopes granted by POST /pair when nothing narrower is requested.
 * Deliberately full page access (b73f3644 / #907): the trust boundary is the
 * pairing ceremony, not the scope. 'control' (browser-wide destructive ops)
 * is the only scope that stays opt-in via the control flag. Referenced by
 * BOTH server.ts (/pair default) and cli.ts (explicit send) so the two
 * defaults cannot silently drift apart again.
 */
export const DEFAULT_PAIR_SCOPES: readonly ScopeCategory[] = ['read', 'write', 'admin', 'meta'];

/**
 * Typed error for caller-supplied token options (unknown scope, negative
 * rateLimit). HTTP handlers catch it to 400 with the message at the endpoint
 * where the typo happened — pre-fix, a bad scope sailed through /pair into a
 * poisoned setup key and surfaced as a misleading "Invalid request body" to
 * the remote agent at /connect.
 */
export class InvalidScopeError extends Error {}

export function assertValidTokenOptions(scopes: readonly string[], rateLimit: number): void {
  const validScopes: ScopeCategory[] = ['read', 'write', 'admin', 'meta', 'control'];
  for (const s of scopes) {
    if (!validScopes.includes(s as ScopeCategory)) {
      throw new InvalidScopeError(`Invalid scope: ${s}. Valid: ${validScopes.join(', ')}`);
    }
  }
  if (rateLimit < 0) throw new InvalidScopeError('rateLimit must be >= 0');
}

/**
 * Typed error for a reserved or malformed clientId. `root` is the sentinel that
 * checkScope/checkDomain/checkRate and the server command gate use to mean "the
 * omnipotent root caller" (validateToken:360), so a scoped token carrying it
 * would bypass every enforcement path. Empty/non-string ids collapse distinct
 * agents together and break revoke-by-clientId. Request-path writers throw;
 * restoreRegistry skips-and-logs so one bad state-file entry can't drop later
 * sessions or brick boot.
 */
export class ReservedClientIdError extends Error {}

export function assertValidClientId(clientId: unknown): asserts clientId is string {
  if (typeof clientId !== 'string' || clientId.trim() === '') {
    throw new ReservedClientIdError('clientId must be a non-empty string');
  }
  if (clientId.trim().toLowerCase() === 'root') {
    throw new ReservedClientIdError("clientId 'root' is reserved");
  }
}

// ─── Types ──────────────────────────────────────────────────────

export interface TokenInfo {
  token: string;
  clientId: string;
  type: 'session' | 'setup';
  scopes: ScopeCategory[];
  domains?: string[];          // glob patterns, e.g. ['*.myapp.com']
  tabPolicy: 'own-only' | 'shared';
  rateLimit: number;           // requests per second (0 = unlimited)
  expiresAt: string | null;    // ISO8601, null = never
  createdAt: string;
  usesRemaining?: number;      // for setup keys only
  issuedSessionToken?: string; // for setup keys: the session token that was issued
  commandCount: number;        // how many commands have been executed
}

export interface CreateTokenOptions {
  clientId: string;
  scopes?: ScopeCategory[];
  domains?: string[];
  tabPolicy?: 'own-only' | 'shared';
  rateLimit?: number;
  expiresSeconds?: number | null; // null = never, default = 86400 (24h)
}

export interface TokenRegistryState {
  agents: Record<string, Omit<TokenInfo, 'commandCount'>>;
}

// ─── Rate Limiter ───────────────────────────────────────────────

interface RateBucket {
  count: number;
  windowStart: number;
}

const rateBuckets = new Map<string, RateBucket>();

function checkRateLimit(clientId: string, limit: number): { allowed: boolean; retryAfterMs?: number } {
  if (limit <= 0) return { allowed: true };

  const now = Date.now();
  const bucket = rateBuckets.get(clientId);

  if (!bucket || now - bucket.windowStart >= 1000) {
    rateBuckets.set(clientId, { count: 1, windowStart: now });
    return { allowed: true };
  }

  if (bucket.count >= limit) {
    const retryAfterMs = 1000 - (now - bucket.windowStart);
    return { allowed: false, retryAfterMs: Math.max(retryAfterMs, 100) };
  }

  bucket.count++;
  return { allowed: true };
}

// ─── Token Registry ─────────────────────────────────────────────

const tokens = new Map<string, TokenInfo>();
let rootToken: string = '';

export function initRegistry(root: string): void {
  // Idempotent re-init: same token is a no-op so embedders can call this
  // alongside any prior call without fighting. Different token after init
  // means a misconfigured caller — throw clearly rather than silently
  // invalidate every scoped token already issued.
  if (rootToken !== '' && rootToken !== root) {
    throw new Error(
      'token-registry already initialized with a different token; ' +
      'embedders must call buildFetchHandler before any registry-mutating code path'
    );
  }
  rootToken = root;
}

export function getRootToken(): string {
  return rootToken;
}

export function isRootToken(token: string): boolean {
  // Constant-time compare so a tunnel-reachable caller who can provoke an
  // isRootToken() call (e.g., via the 403 "root over tunnel" rejection path)
  // can't measure byte-by-byte string-compare timing to recover the token.
  // Compare UTF-8 byte lengths (not JS string length) before timingSafeEqual,
  // which throws on length-mismatched buffers. A multibyte input whose JS
  // string length matches rootToken but whose UTF-8 byte length differs must
  // return false on the auth path, not error out.
  if (!rootToken) return false;
  const tokenBytes = Buffer.byteLength(token, 'utf8');
  const rootBytes = Buffer.byteLength(rootToken, 'utf8');
  if (tokenBytes !== rootBytes) return false;
  const a = Buffer.from(token, 'utf8');
  const b = Buffer.from(rootToken, 'utf8');
  return crypto.timingSafeEqual(a, b);
}

function generateToken(prefix: string): string {
  return `${prefix}${crypto.randomBytes(24).toString('hex')}`;
}

/**
 * Create a scoped session token (for direct minting via CLI or /token endpoint).
 * Only callable by root token holder.
 */
export function createToken(opts: CreateTokenOptions): TokenInfo {
  const {
    clientId,
    scopes = ['read', 'write'],
    domains,
    tabPolicy = 'own-only',
    rateLimit = 10,
    expiresSeconds = 86400, // 24h default
  } = opts;

  // Validate inputs
  assertValidClientId(clientId);
  assertValidTokenOptions(scopes, rateLimit);
  if (expiresSeconds !== null && expiresSeconds !== undefined && expiresSeconds < 0) {
    throw new Error('expiresSeconds must be >= 0 or null');
  }

  const token = generateToken('gsk_sess_');
  const now = new Date();
  const expiresAt = expiresSeconds === null
    ? null
    : new Date(now.getTime() + expiresSeconds * 1000).toISOString();

  const info: TokenInfo = {
    token,
    clientId,
    type: 'session',
    scopes,
    domains,
    tabPolicy,
    rateLimit,
    expiresAt,
    createdAt: now.toISOString(),
    commandCount: 0,
  };

  // Overwrite if clientId already exists (re-pairing)
  // First revoke the old session token (but NOT setup keys — they track their issued session)
  for (const [t, existing] of tokens) {
    if (existing.clientId === clientId && existing.type === 'session') {
      tokens.delete(t);
      break;
    }
  }

  tokens.set(token, info);
  return info;
}

/**
 * Create a one-time setup key for the /pair-agent ceremony.
 * Setup keys expire in 5 minutes and can only be exchanged once.
 */
export function createSetupKey(opts: Omit<CreateTokenOptions, 'clientId'> & { clientId?: string }): TokenInfo {
  // Only validate when a clientId is supplied; an omitted one gets a safe
  // generated `remote-<ts>` default below.
  if (opts.clientId !== undefined) assertValidClientId(opts.clientId);
  const scopes = opts.scopes || ['read', 'write'];
  // ?? not ||: rateLimit 0 is documented as "unlimited" and must survive.
  const rateLimit = opts.rateLimit ?? 10;
  // Validate HERE, not only at exchange time in createToken — otherwise a
  // typo mints a poisoned setup key whose failure surfaces to the wrong
  // party (the remote agent, at /connect, as "Invalid request body").
  assertValidTokenOptions(scopes, rateLimit);
  const token = generateToken('gsk_setup_');
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 5 * 60 * 1000).toISOString(); // 5 min

  const info: TokenInfo = {
    token,
    clientId: opts.clientId || `remote-${Date.now()}`,
    type: 'setup',
    scopes,
    domains: opts.domains,
    tabPolicy: opts.tabPolicy || 'own-only',
    rateLimit,
    expiresAt,
    createdAt: now.toISOString(),
    usesRemaining: 1,
    commandCount: 0,
  };

  tokens.set(token, info);
  return info;
}

/**
 * Exchange a setup key for a session token.
 * Idempotent: if the same key is presented again and the prior session
 * has 0 commands, returns the same session token (handles tunnel drops).
 */
export function exchangeSetupKey(setupKey: string, sessionExpiresSeconds?: number | null): TokenInfo | null {
  const setup = tokens.get(setupKey);
  if (!setup) return null;
  if (setup.type !== 'setup') return null;

  // Check expiry
  if (setup.expiresAt && new Date(setup.expiresAt) < new Date()) {
    tokens.delete(setupKey);
    return null;
  }

  // Idempotent: if already exchanged but session has 0 commands, return existing
  if (setup.usesRemaining === 0) {
    if (setup.issuedSessionToken) {
      const existing = tokens.get(setup.issuedSessionToken);
      if (existing && existing.commandCount === 0) {
        return existing;
      }
    }
    return null; // Session used or gone — can't re-issue
  }

  // Consume the setup key
  setup.usesRemaining = 0;

  // Create the session token
  const session = createToken({
    clientId: setup.clientId,
    scopes: setup.scopes,
    domains: setup.domains,
    tabPolicy: setup.tabPolicy,
    rateLimit: setup.rateLimit,
    expiresSeconds: sessionExpiresSeconds ?? 86400,
  });

  // Track which session token was issued from this setup key
  setup.issuedSessionToken = session.token;

  return session;
}

/**
 * Validate a token and return its info if valid.
 * Returns null for expired, revoked, or unknown tokens.
 * Root token returns a special root info object.
 */
export function validateToken(token: string): TokenInfo | null {
  if (isRootToken(token)) {
    return {
      token: rootToken,
      clientId: 'root',
      type: 'session',
      scopes: ['read', 'write', 'admin', 'meta', 'control'],
      tabPolicy: 'shared',
      rateLimit: 0, // unlimited
      expiresAt: null,
      createdAt: '',
      commandCount: 0,
    };
  }

  const info = tokens.get(token);
  if (!info) return null;

  // Check expiry
  if (info.expiresAt && new Date(info.expiresAt) < new Date()) {
    tokens.delete(token);
    return null;
  }

  return info;
}

/**
 * Check if a command is allowed by the token's scopes.
 * The `chain` command is special: it's allowed if the token has meta scope,
 * but each subcommand within chain must be individually scope-checked.
 */
export function checkScope(info: TokenInfo, command: string): boolean {
  if (info.clientId === 'root') return true;

  // Special case: chain is in SCOPE_META but requires that the caller
  // has scopes covering ALL subcommands. The actual subcommand check
  // happens at dispatch time, not here.
  if (command === 'chain' && info.scopes.includes('meta')) return true;

  for (const scope of info.scopes) {
    if (SCOPE_MAP[scope]?.has(command)) return true;
  }

  return false;
}

/**
 * Check if a URL is allowed by the token's domain restrictions.
 * Returns true if no domain restrictions, or if the URL matches any glob.
 */
export function checkDomain(info: TokenInfo, url: string): boolean {
  if (info.clientId === 'root') return true;
  if (!info.domains || info.domains.length === 0) return true;

  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname;

    for (const pattern of info.domains) {
      if (matchDomainGlob(hostname, pattern)) return true;
    }

    return false;
  } catch {
    return false; // Invalid URL — deny
  }
}

function matchDomainGlob(hostname: string, pattern: string): boolean {
  // Simple glob: *.example.com matches sub.example.com
  // Exact: example.com matches example.com only
  if (pattern.startsWith('*.')) {
    const suffix = pattern.slice(1); // .example.com
    return hostname.endsWith(suffix) || hostname === pattern.slice(2);
  }
  return hostname === pattern;
}

/**
 * Check rate limit for a client. Returns { allowed, retryAfterMs? }.
 */
export function checkRate(info: TokenInfo): { allowed: boolean; retryAfterMs?: number } {
  if (info.clientId === 'root') return { allowed: true };
  return checkRateLimit(info.clientId, info.rateLimit);
}

/**
 * Record that a command was executed by this token.
 */
export function recordCommand(token: string): void {
  const info = tokens.get(token);
  if (info) info.commandCount++;
}

/**
 * Revoke ALL tokens for a client ID — the session token and every setup key,
 * spent or unspent. Deleting only the first match left two holes: a spent
 * setup key (kept for idempotent re-exchange) shadowed the session token, so
 * revoke reported success while the live session survived; and an unspent
 * setup key surviving revoke let a "revoked" agent POST /connect into a
 * fresh session. Returns the number of tokens deleted (0 = nothing found).
 */
export function revokeToken(clientId: string): number {
  let deleted = 0;
  for (const [token, info] of tokens) {
    if (info.clientId === clientId) {
      tokens.delete(token); // Map tolerates delete during for...of iteration
      deleted++;
    }
  }
  if (deleted > 0) rateBuckets.delete(clientId);
  return deleted;
}

/**
 * Revoke the PENDING (unspent) setup keys for a client, leaving any live
 * session AND spent keys untouched. A re-pair always drops pending keys so a
 * superseded broad key can never be exchanged — this closes the shadow-key
 * hole (a reducing re-pair before the agent connects would otherwise leave the
 * old broad key live) without touching the spent key that #2646 keeps for
 * idempotent re-exchange on a tunnel drop. Returns the number deleted.
 */
export function revokeSetupKeys(clientId: string): number {
  let deleted = 0;
  for (const [token, info] of tokens) {
    // usesRemaining !== 0 = still exchangeable (pending). Spent keys (0) are
    // harmless: their session is either kept here or revoked on the reduce path.
    if (info.clientId === clientId && info.type === 'setup' && info.usesRemaining !== 0) {
      tokens.delete(token);
      deleted++;
    }
  }
  return deleted;
}

/** The live (non-expired) session token for a client, if any. */
export function getClientSession(clientId: string): TokenInfo | null {
  const now = new Date();
  for (const info of tokens.values()) {
    if (info.clientId !== clientId || info.type !== 'session') continue;
    if (info.expiresAt && new Date(info.expiresAt) < now) continue;
    return info;
  }
  return null;
}

/** The effective grant a re-pair is requesting, resolved to concrete values. */
export interface ResolvedGrant {
  scopes: ScopeCategory[];
  domains?: string[];
  rateLimit: number;
  tabPolicy: 'own-only' | 'shared';
}

/**
 * Does `grant` remove any capability the live `prior` session holds? Drives the
 * /pair supersede decision: a reducing re-pair revokes the old session
 * immediately (the narrowing must not wait for a reconnect that may never
 * happen); a broaden/refresh leaves it working (no outage). Fails toward
 * revocation on an unprovable domain superset — a spurious revoke costs one
 * reconnect, a missed one leaves wide access live.
 */
export function grantReducesAccess(prior: TokenInfo, grant: ResolvedGrant): boolean {
  return scopesReduced(prior.scopes, grant.scopes)
    || domainsReduced(prior.domains, grant.domains)
    || rateReduced(prior.rateLimit, grant.rateLimit)
    || tabPolicyReduced(prior.tabPolicy, grant.tabPolicy);
}

function scopesReduced(prior: ScopeCategory[], next: ScopeCategory[]): boolean {
  // Any scope the prior held that the new grant omits (also catches dropping 'control').
  return prior.some(s => !next.includes(s));
}

function domainsReduced(prior: string[] | undefined, next: string[] | undefined): boolean {
  const priorUnrestricted = !prior || prior.length === 0;
  const nextUnrestricted = !next || next.length === 0;
  if (priorUnrestricted) return !nextUnrestricted; // universe → restricted = reduce
  if (nextUnrestricted) return false;              // restricted → universe = broaden
  // Both restricted: reduced if any host the prior allowlist admits is no longer
  // admitted by the new one. Approximate over patterns — prior is covered iff
  // every prior pattern is covered by some next pattern; anything unprovable
  // counts as reduced (fail toward revocation).
  return prior!.some(p => !next!.some(n => domainGlobCovers(n, p)));
}

/** Does allowlist pattern `wide` admit every host that `narrow` admits? Mirrors
 * matchDomainGlob's suffix/exact rules. */
function domainGlobCovers(wide: string, narrow: string): boolean {
  if (wide === narrow) return true;
  const wideGlob = wide.startsWith('*.');
  if (wideGlob) {
    const wideSuffix = wide.slice(1); // ".example.com"
    const wideApex = wide.slice(2);   // "example.com"
    if (!narrow.startsWith('*.')) {
      // narrow is an exact host; covered iff the wide glob matches it.
      return narrow === wideApex || narrow.endsWith(wideSuffix);
    }
    // narrow is also a glob; its apex must fall under the wide suffix.
    const narrowApex = narrow.slice(2);
    return narrowApex === wideApex || narrowApex.endsWith(wideSuffix);
  }
  // wide is an exact host: covers only the identical host (handled by === above).
  return false;
}

function rateReduced(prior: number, next: number): boolean {
  const priorUnlimited = prior <= 0; // 0 = unlimited
  const nextUnlimited = next <= 0;
  if (priorUnlimited) return !nextUnlimited; // unlimited → capped = reduce
  if (nextUnlimited) return false;           // capped → unlimited = broaden
  return next < prior;                       // both capped: a lower cap = reduce
}

function tabPolicyReduced(prior: 'own-only' | 'shared', next: 'own-only' | 'shared'): boolean {
  return prior === 'shared' && next === 'own-only';
}

/**
 * Rotate the root token. All scoped tokens are invalidated.
 * Returns the new root token.
 */
export function rotateRoot(): string {
  rootToken = crypto.randomUUID();
  tokens.clear();
  rateBuckets.clear();
  return rootToken;
}

/**
 * List all active (non-expired) scoped tokens.
 * With includeSetup, unexchanged ("pending") setup keys are listed too —
 * they are live grants an operator must be able to see and revoke. Spent
 * keys stay hidden: they are re-exchange bookkeeping for a session that is
 * already listed.
 */
export function listTokens(opts?: { includeSetup?: boolean }): TokenInfo[] {
  const now = new Date();
  const result: TokenInfo[] = [];

  for (const [token, info] of tokens) {
    if (info.expiresAt && new Date(info.expiresAt) < now) {
      tokens.delete(token);
      continue;
    }
    if (info.type === 'session') {
      result.push(info);
    } else if (opts?.includeSetup && info.type === 'setup' && info.usesRemaining !== 0) {
      result.push(info);
    }
  }

  return result;
}

/**
 * Serialize the token registry for state file persistence.
 */
export function serializeRegistry(): TokenRegistryState {
  const agents: TokenRegistryState['agents'] = {};

  for (const info of tokens.values()) {
    if (info.type === 'session') {
      const { commandCount, ...rest } = info;
      agents[info.clientId] = rest;
    }
  }

  return { agents };
}

/**
 * Restore the token registry from persisted state file data.
 */
export function restoreRegistry(state: TokenRegistryState): void {
  tokens.clear();
  const now = new Date();

  for (const [clientId, data] of Object.entries(state.agents)) {
    // Skip expired tokens
    if (data.expiresAt && new Date(data.expiresAt) < now) continue;

    // Skip-and-log rather than throw: a hand-edited or corrupt state file must
    // not brick boot or drop every later valid session. A persisted clientId
    // 'root' would otherwise inject a token that bypasses all scope checks.
    try {
      assertValidClientId(clientId);
    } catch (err) {
      console.warn(`[browse] restoreRegistry: skipping invalid clientId ${JSON.stringify(clientId)}: ${err instanceof Error ? err.message : String(err)}`);
      continue;
    }

    tokens.set(data.token, {
      ...data,
      clientId,
      commandCount: 0,
    });
  }
}

// ─── Connect endpoint rate limiter (flood protection) ─────
//
// Global-only cap. Setup keys are 24 random bytes (unbruteforceable), so
// rate limiting here is not about preventing key guessing. It caps
// bandwidth, CPU, and log-flood damage from someone who discovered the
// ngrok URL. A legitimate pair-agent session hits /connect once, so
// 300/min is 60x that pattern and never hit accidentally. Per-IP tracking
// was considered and rejected: adds a bounded Map + LRU for defense
// already adequate at the global layer.

let connectAttempts: { ts: number }[] = [];
const CONNECT_RATE_LIMIT = 300; // attempts per minute (~5/sec average)
const CONNECT_WINDOW_MS = 60000;

export function checkConnectRateLimit(): boolean {
  const now = Date.now();
  connectAttempts = connectAttempts.filter(a => now - a.ts < CONNECT_WINDOW_MS);
  if (connectAttempts.length >= CONNECT_RATE_LIMIT) return false;
  connectAttempts.push({ ts: now });
  return true;
}

// Test-only reset.
export function __resetConnectRateLimit(): void {
  connectAttempts = [];
}

// Test-only reset. Zeroes the registry so a subsequent initRegistry call
// always succeeds. Mirrors __resetConnectRateLimit. Needed by tests that
// follow the rotateRoot() pattern — rotateRoot leaves rootToken non-empty,
// which would otherwise trip the initRegistry mismatch guard.
export function __resetRegistry(): void {
  rootToken = '';
  tokens.clear();
  rateBuckets.clear();
}

/**
 * Append-only log of tunnel-surface auth denials.
 *
 * Records every time a tunneled request is rejected by enforceTunnelPolicy
 * (root token sent over tunnel, missing scoped token, disallowed command, etc).
 * Gives operators visibility into who is actually probing their tunneled
 * daemons so the next security wave can be driven by real attack data.
 *
 * Design notes:
 * - Async via fs.promises.appendFile. NEVER appendFileSync — blocking the event
 *   loop on every denial during a flood is exactly what an attacker wants.
 *   (Prior learning: sync-audit-log-io, 10/10 confidence.)
 * - Rate-capped at 60 writes/minute globally. Excess denials are counted in
 *   memory but not written to disk — prevents disk DoS.
 * - Writes to ~/.gstack/security/attempts.jsonl, shared with the prompt-injection
 *   attempt log. File rotation is handled by the existing security pipeline.
 */
import { promises as fsp } from 'fs';
import * as path from 'path';
import * as os from 'os';
import { mkdirSecure } from './file-permissions';

const LOG_DIR = path.join(os.homedir(), '.gstack', 'security');
const LOG_PATH = path.join(LOG_DIR, 'attempts.jsonl');
const RATE_CAP = 60; // writes per minute
const WINDOW_MS = 60_000;

const writeTimestamps: number[] = [];
let droppedSinceLastWrite = 0;
let dirEnsured = false;

async function ensureDir(): Promise<void> {
  if (dirEnsured) return;
  try {
    // Sync mkdir is fine here — runs once per process at first denial. The
    // (OI)(CI) inheritance set on Windows means subsequent fsp.appendFile
    // writes pick up the owner-only ACL automatically.
    mkdirSecure(LOG_DIR);
    dirEnsured = true;
  } catch {
    // Swallow — log writes are best-effort. Failure to mkdir just means
    // subsequent appends will also fail and be caught below.
  }
}

export interface TunnelDenialEntry {
  reason: string;
  path: string;
  method: string;
  sourceIp: string;
}

export function logTunnelDenial(req: Request, url: URL, reason: string): void {
  const now = Date.now();
  // Drop stale timestamps
  while (writeTimestamps.length && writeTimestamps[0] < now - WINDOW_MS) {
    writeTimestamps.shift();
  }
  if (writeTimestamps.length >= RATE_CAP) {
    droppedSinceLastWrite += 1;
    return;
  }
  writeTimestamps.push(now);

  const sourceIp =
    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';

  const entry: Record<string, unknown> = {
    ts: new Date(now).toISOString(),
    kind: 'tunnel_auth_denial',
    reason,
    path: url.pathname,
    method: req.method,
    sourceIp,
  };
  if (droppedSinceLastWrite > 0) {
    entry.droppedSinceLastWrite = droppedSinceLastWrite;
    droppedSinceLastWrite = 0;
  }

  // Fire and forget. Never await, never block the request path.
  void (async () => {
    try {
      await ensureDir();
      await fsp.appendFile(LOG_PATH, JSON.stringify(entry) + '\n');
    } catch {
      // Swallow — log writes are best-effort. If disk is full or ACLs block
      // us, we don't want to crash the server.
    }
  })();
}

// Test-only reset. Never called in production.
export function __resetTunnelDenialLog(): void {
  writeTimestamps.length = 0;
  droppedSinceLastWrite = 0;
  dirEnsured = false;
}

/**
 * URL validation for navigation commands — blocks dangerous schemes and cloud metadata endpoints.
 * Localhost and private IPs are allowed (primary use case: QA testing local dev servers).
 */

import { fileURLToPath, pathToFileURL } from 'node:url';
import * as path from 'node:path';
import * as os from 'node:os';
import { validateReadPath } from './path-security';

export const BLOCKED_METADATA_HOSTS = new Set([
  '169.254.169.254',  // AWS/GCP/Azure instance metadata
  'fe80::1',          // IPv6 link-local — common metadata endpoint alias
  '::ffff:169.254.169.254', // IPv4-mapped IPv6 form of the metadata IP
  '::ffff:a9fe:a9fe', // Hex-encoded IPv4-mapped form (URL constructor normalizes to this)
  '::a9fe:a9fe',      // Deprecated IPv4-compatible hex form
  'metadata.google.internal', // GCP metadata
  'metadata.azure.internal',  // Azure IMDS
]);

/**
 * IPv6 prefixes to block (CIDR-style). ULA addresses cover fc00::/7 and
 * link-local addresses cover fe80::/10.
 */
const BLOCKED_IPV6_PREFIXES = ['fc', 'fd', 'fe8', 'fe9', 'fea', 'feb'];

/**
 * Check if an IPv6 address falls within a blocked prefix range.
 * Handles the full ULA range (fc00::/7) and link-local range (fe80::/10),
 * not just exact literals like fd00:: or fe80::1.
 * Only matches actual IPv6 addresses (must contain ':'), not hostnames
 * like fd.example.com or fcustomer.com.
 */
function isBlockedIpv6(addr: string): boolean {
  const normalized = addr.toLowerCase().replace(/^\[|\]$/g, '');
  // Must contain a colon to be an IPv6 address — avoids false positives on
  // hostnames like fd.example.com or fcustomer.com
  if (!normalized.includes(':')) return false;
  return BLOCKED_IPV6_PREFIXES.some(prefix => normalized.startsWith(prefix));
}

/**
 * Normalize hostname for blocklist comparison:
 * - Strip trailing dot (DNS fully-qualified notation)
 * - Strip IPv6 brackets (URL.hostname includes [] for IPv6)
 * - Resolve hex (0xA9FEA9FE) and decimal (2852039166) IP representations
 */
function normalizeHostname(hostname: string): string {
  // Strip IPv6 brackets
  let h = hostname.startsWith('[') && hostname.endsWith(']')
    ? hostname.slice(1, -1)
    : hostname;
  // Strip trailing dot
  if (h.endsWith('.')) h = h.slice(0, -1);
  return h;
}

/**
 * Check if a hostname resolves to the link-local metadata IP 169.254.169.254.
 * Catches hex (0xA9FEA9FE), decimal (2852039166), and octal (0251.0376.0251.0376) forms.
 */
function isMetadataIp(hostname: string): boolean {
  // Try to parse as a numeric IP via URL constructor — it normalizes all forms
  try {
    const probe = new URL(`http://${hostname}`);
    const normalized = probe.hostname;
    if (BLOCKED_METADATA_HOSTS.has(normalized) || isBlockedIpv6(normalized)) return true;
    // Also check after stripping trailing dot
    if (normalized.endsWith('.') && BLOCKED_METADATA_HOSTS.has(normalized.slice(0, -1))) return true;
  } catch {
    // Not a valid hostname — can't be a metadata IP
  }
  return false;
}

/**
 * Resolve a hostname to its IP addresses and check if any resolve to blocked metadata IPs.
 * Mitigates DNS rebinding: even if the hostname looks safe, the resolved IP might not be.
 *
 * Checks both A (IPv4) and AAAA (IPv6) records — an attacker can use AAAA-only DNS to
 * bypass IPv4-only checks. Each record family is tried independently; failure of one
 * (e.g. no AAAA records exist) is not treated as a rebinding risk.
 */
async function resolvesToBlockedIp(hostname: string): Promise<boolean> {
  try {
    const dns = await import('node:dns');
    const { resolve4, resolve6 } = dns.promises;

    // Check IPv4 A records
    const v4Check = resolve4(hostname).then(
      (addresses) => addresses.some(addr => BLOCKED_METADATA_HOSTS.has(addr)),
      () => false, // ENODATA / ENOTFOUND — no A records, not a risk
    );

    // Check IPv6 AAAA records — the gap that issue #668 identified
    const v6Check = resolve6(hostname).then(
      (addresses) => addresses.some(addr => {
        const normalized = addr.toLowerCase();
        return BLOCKED_METADATA_HOSTS.has(normalized) || isBlockedIpv6(normalized);
      }),
      () => false, // ENODATA / ENOTFOUND — no AAAA records, not a risk
    );

    const [v4Blocked, v6Blocked] = await Promise.all([v4Check, v6Check]);
    return v4Blocked || v6Blocked;
  } catch {
    // Unexpected error — fail open (don't block navigation on DNS infrastructure failure)
    return false;
  }
}

/**
 * Normalize non-standard file:// URLs into absolute form before the WHATWG URL parser
 * sees them. Handles cwd-relative, home-relative, and bare-segment shapes that the
 * standard parser would otherwise mis-interpret as hostnames.
 *
 *   file:///abs/path.html       → unchanged
 *   file://./<rel>              → file://<cwd>/<rel>
 *   file://~/<rel>              → file://<HOME>/<rel>
 *   file://<single-segment>/... → file://<cwd>/<single-segment>/...  (cwd-relative)
 *   file://localhost/<abs>      → unchanged
 *   file://<host-like>/...      → unchanged (caller rejects via host heuristic)
 *
 * Rejects empty (file://) and root-only (file:///) URLs — these would silently
 * trigger Chromium's directory listing, which is a different product surface.
 */
export function normalizeFileUrl(url: string): string {
  if (!url.toLowerCase().startsWith('file:')) return url;

  // Split off query + fragment BEFORE touching the path — SPAs + fixture URLs rely
  // on these. path.resolve would URL-encode `?` and `#` as `%3F`/`%23` (and
  // pathToFileURL drops them entirely), silently routing preview URLs to the
  // wrong fixture. Extract, normalize the path, reattach at the end.
  //
  // Parse order: `?` before `#` per RFC 3986 — '?' in a fragment is literal.
  // Find the FIRST `?` or `#`, whichever comes first, and take everything
  // after (including the delimiter) as the trailing segment.
  const qIdx = url.indexOf('?');
  const hIdx = url.indexOf('#');
  let delimIdx = -1;
  if (qIdx >= 0 && hIdx >= 0) delimIdx = Math.min(qIdx, hIdx);
  else if (qIdx >= 0) delimIdx = qIdx;
  else if (hIdx >= 0) delimIdx = hIdx;

  const pathPart = delimIdx >= 0 ? url.slice(0, delimIdx) : url;
  const trailing = delimIdx >= 0 ? url.slice(delimIdx) : '';

  const rest = pathPart.slice('file:'.length);

  // file:/// or longer → standard absolute; pass through unchanged (caller validates path).
  if (rest.startsWith('///')) {
    // Reject bare root-only (file:/// with nothing after)
    if (rest === '///' || rest === '////') {
      throw new Error('Invalid file URL: file:/// has no path. Use file:///<absolute-path>.');
    }
    return pathPart + trailing;
  }

  // Everything else: must start with // (we accept file://... only)
  if (!rest.startsWith('//')) {
    throw new Error(`Invalid file URL: ${url}. Use file:///<absolute-path> or file://./<rel> or file://~/<rel>.`);
  }

  const afterDoubleSlash = rest.slice(2);

  // Reject empty (file://) and trailing-slash-only (file://./ listing cwd).
  if (afterDoubleSlash === '') {
    throw new Error('Invalid file URL: file:// is empty. Use file:///<absolute-path>.');
  }
  if (afterDoubleSlash === '.' || afterDoubleSlash === './') {
    throw new Error('Invalid file URL: file://./ would list the current directory. Use file://./<filename> to render a specific file.');
  }
  if (afterDoubleSlash === '~' || afterDoubleSlash === '~/') {
    throw new Error('Invalid file URL: file://~/ would list the home directory. Use file://~/<filename> to render a specific file.');
  }

  // Home-relative: file://~/<rel>
  if (afterDoubleSlash.startsWith('~/')) {
    const rel = afterDoubleSlash.slice(2);
    const absPath = path.join(os.homedir(), rel);
    return pathToFileURL(absPath).href + trailing;
  }

  // cwd-relative with explicit ./ : file://./<rel>
  if (afterDoubleSlash.startsWith('./')) {
    const rel = afterDoubleSlash.slice(2);
    const absPath = path.resolve(process.cwd(), rel);
    return pathToFileURL(absPath).href + trailing;
  }

  // localhost host explicitly allowed: file://localhost/<abs> (pass through to standard parser).
  if (afterDoubleSlash.toLowerCase().startsWith('localhost/')) {
    return pathPart + trailing;
  }

  // Ambiguous: file://<segment>/<rest> — treat as cwd-relative ONLY if <segment> is a
  // simple path name (no dots, no colons, no backslashes, no percent-encoding, no
  // IPv6 brackets, no Windows drive letter pattern).
  const firstSlash = afterDoubleSlash.indexOf('/');
  const segment = firstSlash === -1 ? afterDoubleSlash : afterDoubleSlash.slice(0, firstSlash);

  // Reject host-like segments: dotted names (docs.v1), IPs (127.0.0.1), IPv6 ([::1]),
  // drive letters (C:), percent-encoded, or backslash paths.
  const looksLikeHost = /[.:\\%]/.test(segment) || segment.startsWith('[');
  if (looksLikeHost) {
    throw new Error(
      `Unsupported file URL host: ${segment}. Use file:///<absolute-path> for local files (network/UNC paths are not supported).`
    );
  }

  // Simple-segment cwd-relative: file://docs/page.html → cwd/docs/page.html
  const absPath = path.resolve(process.cwd(), afterDoubleSlash);
  return pathToFileURL(absPath).href + trailing;
}

/**
 * Validate a navigation URL and return a normalized version suitable for page.goto().
 *
 * Callers MUST use the return value — normalization of non-standard file:// forms
 * only takes effect at the navigation site, not at the original URL.
 *
 * Callers (keep this list current, grep before removing):
 *   - write-commands.ts:goto
 *   - meta-commands.ts:diff (both URL args)
 *   - browser-manager.ts:newTab
 *   - browser-manager.ts:restoreState
 */
export async function validateNavigationUrl(url: string): Promise<string> {
  // Normalize non-standard file:// shapes before the URL parser sees them.
  let normalized = url;
  if (url.toLowerCase().startsWith('file:')) {
    normalized = normalizeFileUrl(url);
  }

  let parsed: URL;
  try {
    parsed = new URL(normalized);
  } catch {
    throw new Error(`Invalid URL: ${url}`);
  }

  // file:// path: validate against safe-dirs and allow; otherwise defer to http(s) logic.
  if (parsed.protocol === 'file:') {
    // Reject non-empty non-localhost hosts (UNC / network paths).
    if (parsed.host !== '' && parsed.host.toLowerCase() !== 'localhost') {
      throw new Error(
        `Unsupported file URL host: ${parsed.host}. Use file:///<absolute-path> for local files.`
      );
    }

    // Convert URL → filesystem path with proper decoding (handles %20, %2F, etc.)
    // fileURLToPath strips query + hash; we reattach them after validation so SPA
    // fixture URLs like file:///tmp/app.html?route=home#login survive intact.
    let fsPath: string;
    try {
      fsPath = fileURLToPath(parsed);
    } catch (e: any) {
      throw new Error(`Invalid file URL: ${url} (${e.message})`);
    }

    // Reject path traversal after decoding — e.g. file:///tmp/safe%2F..%2Fetc/passwd
    // Note: fileURLToPath doesn't collapse .., so a literal '..' in the decoded path
    // is suspicious. path.resolve will normalize it; check the result against safe dirs.
    validateReadPath(fsPath);

    // Return the canonical file:// URL derived from the filesystem path + original
    // query + hash. This guarantees page.goto() gets a well-formed URL regardless
    // of input shape while preserving SPA route/query params.
    return pathToFileURL(fsPath).href + parsed.search + parsed.hash;
  }

  // about:blank ONLY — the canonical empty page, and the one the daemon opens its own
  // first tab on. Blocking it meant `browse newtab about:blank` failed, which is what
  // `make-pdf setup` runs as its Chromium smoke test: make-pdf reported "Chromium failed
  // to launch" against a perfectly healthy Chromium, and any browse session whose daemon
  // restarted could never recreate the blank tab it starts from.
  //
  // Deliberately not the whole `about:` scheme. about:blank has no origin, loads nothing
  // and runs nothing; about:config, about:net-internals and friends are real surfaces.
  // Exact href match, not a prefix test, so `about:blankfoo` stays blocked.
  // Compared lower-cased: the URL parser normalises the PROTOCOL but not the opaque part,
  // so `ABOUT:BLANK` parses to href `about:BLANK` and an exact === would reject it.
  if (parsed.protocol === 'about:' && parsed.href.toLowerCase() === 'about:blank') {
    return 'about:blank';
  }

  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error(
      `Blocked: scheme "${parsed.protocol}" is not allowed. Only http:, https:, file:, and about:blank URLs are permitted.`
    );
  }

  const hostname = normalizeHostname(parsed.hostname.toLowerCase());

  if (BLOCKED_METADATA_HOSTS.has(hostname) || isMetadataIp(hostname) || isBlockedIpv6(hostname)) {
    throw new Error(
      `Blocked: ${parsed.hostname} is a cloud metadata endpoint. Access is denied for security.`
    );
  }

  // DNS rebinding protection: resolve hostname and check if it points to metadata IPs.
  // Skip for loopback/private IPs — they can't be DNS-rebinded and the async DNS
  // resolution adds latency that breaks concurrent E2E tests under load.
  const isLoopback = hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1';
  const isPrivateNet = /^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)/.test(hostname);
  if (!isLoopback && !isPrivateNet && await resolvesToBlockedIp(hostname)) {
    throw new Error(
      `Blocked: ${parsed.hostname} resolves to a cloud metadata IP. Possible DNS rebinding attack.`
    );
  }

  return url;
}

