      fs.writeFileSync(stateFile, JSON.stringify(stateContent, null, 2));

      const result = await runCli(['connect'], baseEnv(stateFile));

      expect(result.code).not.toBe(0);
      expect(result.stderr).toContain('healthy daemon is already running');
      expect(result.stderr).toContain('--force-restart');
      // THE IRON RULE: the daemon process was not killed.
      expect(isProcessAlive(daemonPid)).toBe(true);
      // And the state file was not clobbered.
      expect(JSON.parse(fs.readFileSync(stateFile, 'utf-8'))).toEqual(stateContent);
    } finally {
      await daemon.close();
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('pair-agent over a live headless daemon WITHOUT --force-restart → daemon survives, notice printed, no headed relaunch', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-iron-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const daemon = await startHealthyDaemon();
    try {
      pidChild = spawn('sleep', ['60'], { stdio: 'ignore' });
      const daemonPid = pidChild.pid!;
      const stateContent = {
        pid: daemonPid,
        port: daemon.port,
        token: 'iron-rule-token',
        startedAt: new Date().toISOString(),
        serverPath: '',
        mode: 'launched' as const,
      };
      fs.writeFileSync(stateFile, JSON.stringify(stateContent, null, 2));

      // Exit code is NOT asserted: the fake daemon answers /pair with
      // non-JSON so handlePairAgent fails later — the iron rule under test
      // is everything that happens BEFORE that: no kill, no headed relaunch.
      const result = await runCli(['pair-agent'], baseEnv(stateFile));

      // The consent notice: live session named, opt-in flag named.
      expect(result.stderr).toContain('continuing against it');
      expect(result.stderr).toContain('--force-restart');
      // No headed relaunch was attempted.
      const combined = result.stdout + result.stderr;
      expect(combined).not.toContain('Opening GStack Browser');
      // THE IRON RULE: the daemon process was not killed.
      expect(isProcessAlive(daemonPid)).toBe(true);
      // And the state file was not clobbered.
      expect(JSON.parse(fs.readFileSync(stateFile, 'utf-8'))).toEqual(stateContent);
    } finally {
      await daemon.close();
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('wedged-alive daemon + plain command → busy report + nonzero exit, NO kill', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-iron-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const daemon = await startWedgedDaemon();
    try {
      pidChild = spawn('sleep', ['120'], { stdio: 'ignore' });
      const daemonPid = pidChild.pid!;
      fs.writeFileSync(stateFile, JSON.stringify({
        pid: daemonPid,
        port: daemon.port,
        token: 'iron-rule-token',
        startedAt: new Date().toISOString(),
        serverPath: '',
        mode: 'launched' as const,
      }, null, 2));

      const result = await runCli(['status'], baseEnv(stateFile));

      expect(result.code).not.toBe(0);
      expect(result.stderr).toContain('Daemon busy');
      expect(result.stderr).toContain('--force-restart');
      // Never killed, never restarted.
      expect(isProcessAlive(daemonPid)).toBe(true);
      expect(result.stderr).not.toContain('Restarting');
    } finally {
      await daemon.close();
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 45_000);

  test('wedged-alive daemon + --force-restart IS killed (explicit consent path)', async () => {
    // Unix lanes only: the consent path must boot a REAL replacement daemon
    // to answer the command, which the secretless/browserless Windows lane
    // cannot do (no Chromium install), and the teardown relies on setsid
    // process-group semantics Windows lacks. The Windows-relevant half of
    // the iron rule — busy → refusal, never an implicit kill — runs above.
    if (process.platform === 'win32') return;
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-iron-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const daemon = await startWedgedDaemon();
    try {
      pidChild = spawn('sleep', ['120'], { stdio: 'ignore' });
      const daemonPid = pidChild.pid!;
      fs.writeFileSync(stateFile, JSON.stringify({
        pid: daemonPid,
        port: daemon.port,
        token: 'iron-rule-token',
        startedAt: new Date().toISOString(),
        serverPath: '',
        mode: 'launched' as const,
      }, null, 2));

      // `status` with --force-restart: the wedged "daemon" must be killed and
      // a REAL daemon started in its place.
      const result = await runCli(['--force-restart', 'status'], baseEnv(stateFile), 60_000);

      // The wedged pid was killed — the explicit consent path.
      expect(isProcessAlive(daemonPid)).toBe(false);
      expect(result.stderr).toContain('--force-restart');
      // The replacement daemon answered the command.
      expect(result.code).toBe(0);
    } finally {
      // Kill the REAL daemon's whole PROCESS GROUP, not just its pid.
      // startServer spawns the daemon detached (setsid — its own group
      // leader), so a bare SIGKILL on the pid orphans its Chromium child,
      // which then squats memory for the REST of the suite (~100 files) —
      // enough pressure on a loaded box for the OS to kill a LATER test's
      // in-process Chromium, whose disconnect handler process.exit(1)s the
      // whole bun run mid-suite with no summary.
      try {
        const newState = JSON.parse(fs.readFileSync(stateFile, 'utf-8'));
        if (newState?.pid && isProcessAlive(newState.pid)) {
          try {
            process.kill(-newState.pid, 'SIGKILL'); // group: daemon + Chromium
          } catch {
            process.kill(newState.pid, 'SIGKILL'); // fallback: pid only
          }
        }
      } catch { /* state file gone — nothing started */ }
      await daemon.close();
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 90_000);
});

/**
 * #1781 busy-vs-dead pinning test — the "recover from a busy daemon" leg of
 * the browser-lifecycle contract, previously untested.
 *
 * Wedges a fake daemon: /health answers healthy, but the FIRST POST /command
 * hard-destroys the socket (the CLI sees ECONNRESET — exactly what a
 * single-threaded daemon under beacon load looks like). The daemon "PID"
 * is a live sleep child.
 *
 * Contract under test (cli.ts sendCommand + probeHealthWithBackoff):
 *   - CLI must NOT kill the live PID and must NOT restart the daemon
 *     (a restart drops tab/cookie state — the original crash-loop bug).
 *   - It probes /health, sees alive, and retries the SAME command against
 *     the SAME daemon instance.
 *
 * Fails on pre-#1781 code (which killed + restarted on any conn error) and
 * on any regression that reorders the busy-probe before the alive check.
 */

import { describe, test, expect, afterAll } from 'bun:test';
import { spawn, type ChildProcess } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as http from 'http';
import { isProcessAlive } from '../src/error-handling';

const BOOT_ID = `boot-${Date.now()}`;

interface FakeDaemon {
  port: number;
  commandRequests: number;
  close: () => Promise<void>;
}

/** /health healthy; first POST /command → socket destroy; then 200 + BOOT_ID. */
async function startWedgedDaemon(): Promise<FakeDaemon> {
  const state = { commandRequests: 0 };
  const server = http.createServer((req, res) => {
    if (req.url === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'healthy' }));
      return;
    }
    if (req.url === '/command' && req.method === 'POST') {
      state.commandRequests += 1;
      if (state.commandRequests === 1) {
        req.socket.destroy(); // wedged: connection dies mid-request
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end(`RECOVERED ${BOOT_ID}`);
      return;
    }
    res.writeHead(404);
    res.end();
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve());
  });
  const addr = server.address();
  if (!addr || typeof addr === 'string') throw new Error('fake daemon: bad address');
  return {
    port: addr.port,
    get commandRequests() { return state.commandRequests; },
    close: () => new Promise((r) => server.close(() => r())),
  };
}

function runCli(args: string[], env: Record<string, string>, timeoutMs = 20_000):
  Promise<{ code: number; stdout: string; stderr: string }> {
  const cliPath = path.resolve(__dirname, '../src/cli.ts');
  return new Promise((resolve) => {
    const proc = spawn('bun', ['run', cliPath, ...args], { timeout: timeoutMs, env });
    let stdout = ''; let stderr = '';
    proc.stdout.on('data', (d) => stdout += d.toString());
    proc.stderr.on('data', (d) => stderr += d.toString());
    proc.on('close', (code) => resolve({ code: code ?? 1, stdout, stderr }));
  });
}

let daemonPidChild: ChildProcess | null = null;
afterAll(() => { daemonPidChild?.kill('SIGKILL'); });

describe('#1781 busy-daemon recovery (CLI integration)', () => {
  test('retries without kill; same daemon instance, state file untouched', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-busy-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const daemon = await startWedgedDaemon();
    try {
      // A live process standing in for the daemon PID. If the CLI takes the
      // dead path it SIGTERMs this child — the aliveness assert catches it.
      daemonPidChild = spawn('sleep', ['60'], { stdio: 'ignore' });
      const daemonPid = daemonPidChild.pid!;

      const stateContent = {
        pid: daemonPid,
        port: daemon.port,
        token: 'busy-test-token',
        startedAt: new Date().toISOString(),
        serverPath: '',
        mode: 'launched' as const,
      };
      fs.writeFileSync(stateFile, JSON.stringify(stateContent, null, 2));

      const env: Record<string, string> = {};
      for (const [k, v] of Object.entries(process.env)) {
        if (v !== undefined) env[k] = v;
      }
      env.BROWSE_STATE_FILE = stateFile;

      const result = await runCli(['status'], env);

      // Recovered: retried the same command against the same daemon instance.
      expect(result.code).toBe(0);
      expect(result.stdout).toContain(`RECOVERED ${BOOT_ID}`);
      // The fork's CLI announces the busy retry on stderr; ours retries at the
      // probe layer without a message. Either is fine — the load-bearing
      // behavior is retry-without-kill, asserted below.
      expect(daemon.commandRequests).toBe(2); // wedged once, served once

      // Never killed, never restarted — tab/cookie state intact.
      expect(result.stderr).not.toContain('Restarting');
      expect(isProcessAlive(daemonPid)).toBe(true);
      expect(JSON.parse(fs.readFileSync(stateFile, 'utf-8'))).toEqual(stateContent);
    } finally {
      // Cleanup must run even when an assertion throws — otherwise a failed
      // run leaks the wedged fake daemon and the tmp dir.
      await daemon.close();
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);
});

import { describe, it, expect } from 'bun:test';
import { CDP_ALLOWLIST, lookupCdpMethod, isCdpMethodAllowed } from '../src/cdp-allowlist';

describe('CDP allowlist (T2: deny-default)', () => {
  it('every entry has all 4 required fields', () => {
    for (const entry of CDP_ALLOWLIST) {
      expect(entry.domain).toBeTruthy();
      expect(entry.method).toBeTruthy();
      expect(['tab', 'browser']).toContain(entry.scope);
      expect(['trusted', 'untrusted']).toContain(entry.output);
      expect(entry.justification).toBeTruthy();
      expect(entry.justification.length).toBeGreaterThan(20); // not a placeholder
    }
  });

  it('no duplicate (domain.method) entries', () => {
    const seen = new Set<string>();
    for (const e of CDP_ALLOWLIST) {
      const key = `${e.domain}.${e.method}`;
      expect(seen.has(key)).toBe(false);
      seen.add(key);
    }
  });

  it('lookupCdpMethod returns the entry for allowed methods', () => {
    const e = lookupCdpMethod('Accessibility.getFullAXTree');
    expect(e).not.toBeNull();
    expect(e!.scope).toBe('tab');
    expect(e!.output).toBe('untrusted');
  });

  it('isCdpMethodAllowed returns false for dangerous methods that must NOT be allowed (Codex T2)', () => {
    // Code execution surfaces — would be RCE if allowed
    expect(isCdpMethodAllowed('Runtime.evaluate')).toBe(false);
    expect(isCdpMethodAllowed('Runtime.callFunctionOn')).toBe(false);
    expect(isCdpMethodAllowed('Runtime.compileScript')).toBe(false);
    expect(isCdpMethodAllowed('Runtime.runScript')).toBe(false);
    expect(isCdpMethodAllowed('Debugger.evaluateOnCallFrame')).toBe(false);
    expect(isCdpMethodAllowed('Page.addScriptToEvaluateOnNewDocument')).toBe(false);
    expect(isCdpMethodAllowed('Page.createIsolatedWorld')).toBe(false);

    // Navigation — must use $B goto so URL blocklist applies
    expect(isCdpMethodAllowed('Page.navigate')).toBe(false);
    expect(isCdpMethodAllowed('Page.navigateToHistoryEntry')).toBe(false);

    // Exfil surfaces
    expect(isCdpMethodAllowed('Network.getResponseBody')).toBe(false);
    expect(isCdpMethodAllowed('Network.getCookies')).toBe(false);
    expect(isCdpMethodAllowed('Network.replayXHR')).toBe(false);
    expect(isCdpMethodAllowed('Network.loadNetworkResource')).toBe(false);
    expect(isCdpMethodAllowed('Storage.getCookies')).toBe(false);
    expect(isCdpMethodAllowed('Fetch.fulfillRequest')).toBe(false);

    // Browser/process-level mutators
    expect(isCdpMethodAllowed('Browser.close')).toBe(false);
    expect(isCdpMethodAllowed('Browser.crash')).toBe(false);
    expect(isCdpMethodAllowed('Target.attachToTarget')).toBe(false);
    expect(isCdpMethodAllowed('Target.createTarget')).toBe(false);
    expect(isCdpMethodAllowed('Target.setAutoAttach')).toBe(false);
    expect(isCdpMethodAllowed('Target.exposeDevToolsProtocol')).toBe(false);

    // Read-only methods we never added
    expect(isCdpMethodAllowed('Bogus.unknown')).toBe(false);
  });

  it('isCdpMethodAllowed returns true for the small read-only safe set', () => {
    expect(isCdpMethodAllowed('Accessibility.getFullAXTree')).toBe(true);
    expect(isCdpMethodAllowed('DOM.getBoxModel')).toBe(true);
    expect(isCdpMethodAllowed('Performance.getMetrics')).toBe(true);
    expect(isCdpMethodAllowed('Page.captureScreenshot')).toBe(true);
  });

  it('Emulation.setEmulatedMedia is allowed, tab-scoped, trusted (#2419)', () => {
    // Media type/feature override (prefers-color-scheme, prefers-reduced-motion,
    // prefers-contrast, forced-colors) so a11y and dark-mode CSS branches are
    // testable via $B cdp. Returns an empty result — no page content, so
    // trusted output is correct.
    expect(isCdpMethodAllowed('Emulation.setEmulatedMedia')).toBe(true);
    const e = lookupCdpMethod('Emulation.setEmulatedMedia');
    expect(e).not.toBeNull();
    expect(e!.scope).toBe('tab');
    expect(e!.output).toBe('trusted');
  });

  it('CPU + network throttling are allowed, tab-scoped, trusted (#2602)', () => {
    // Perf-measurement emulation (PR #2602 by @henbima): both constrain the
    // tab's timing/traffic, read nothing, and return empty results — same
    // posture argument as setEmulatedMedia (#2419) and setDeviceMetricsOverride.
    for (const method of ['Emulation.setCPUThrottlingRate', 'Network.emulateNetworkConditions']) {
      expect(isCdpMethodAllowed(method)).toBe(true);
      const e = lookupCdpMethod(method);
      expect(e).not.toBeNull();
      expect(e!.scope).toBe('tab');
      expect(e!.output).toBe('trusted');
      // Like setEmulatedMedia, both overrides persist on the tab until
      // cleared (rate: 1 / offline: false + defaults) — the justification
      // must say so, since callers own restoration.
      expect(e!.justification).toContain('persists on the tab until cleared');
    }
  });

  it('untrusted-output methods cover the read-everything-attacker-controlled cases', () => {
    // Anything that reads attacker-controlled strings (DOM/AX/CSS selectors)
    // should be tagged untrusted so the envelope wraps the result.
    const untrustedMethods = CDP_ALLOWLIST.filter((e) => e.output === 'untrusted').map((e) => `${e.domain}.${e.method}`);
    expect(untrustedMethods).toContain('Accessibility.getFullAXTree');
    expect(untrustedMethods).toContain('CSS.getMatchedStylesForNode');
  });
});

