import { describe, test, expect } from 'bun:test';
import { createSseEndpoint } from '../src/sse-helpers';

// Unit tests for the SSE cleanup contract introduced by D6 EXTRACT_HELPER.
//
// The pre-helper bug: /activity/stream and /inspector/events ran cleanup
// only on the `req.signal.abort` edge. If the underlying TCP died without
// firing abort (Chromium MV3 service-worker suspend, intermediate proxy
// half-close), the subscriber closure stayed in the Set capturing the
// ReadableStreamDefaultController and any payloads queued behind it.
//
// These tests pin the three cleanup edges:
//   1. abort signal → cleanup
//   2. enqueue throws (consumer gone) → cleanup
//   3. heartbeat enqueue throws → cleanup
// And the idempotency invariant: cleanup running twice is a no-op.

function makeRequest(): { req: Request; abort: () => void } {
  const controller = new AbortController();
  // Minimal Request — we only use req.signal here. URL is irrelevant.
  const req = new Request('http://localhost/test', { signal: controller.signal });
  return { req, abort: () => controller.abort() };
}

/** Pull SSE bytes from a Response stream, return decoded text. */
async function readAll(res: Response, ms: number): Promise<string> {
  if (!res.body) return '';
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let out = '';
  const deadline = Date.now() + ms;
  while (Date.now() < deadline) {
    try {
      const { value, done } = await Promise.race([
        reader.read(),
        new Promise<{ value: undefined; done: true }>((resolve) =>
          setTimeout(() => resolve({ value: undefined, done: true }), deadline - Date.now()),
        ),
      ]);
      if (done) break;
      if (value) out += decoder.decode(value, { stream: true });
    } catch {
      break;
    }
  }
  try { reader.cancel().catch(() => {}); } catch {}
  return out;
}

describe('createSseEndpoint cleanup contract', () => {
  test('1. abort signal triggers unsubscribe', async () => {
    let unsubscribed = 0;
    const { req, abort } = makeRequest();
    const res = createSseEndpoint(req, {
      subscribe: () => () => {
        unsubscribed++;
      },
      liveEventName: 'test',
      heartbeatMs: 60_000, // long enough that we don't see heartbeats in this test
    });
    // Start the stream by reading once, then abort.
    const reader = res.body!.getReader();
    // Yield to let start() run.
    await Promise.resolve();
    await Promise.resolve();
    abort();
    // Let the abort listener fire.
    await new Promise((r) => setTimeout(r, 10));
    expect(unsubscribed).toBe(1);
    reader.cancel().catch(() => {});
  });

  test('2. enqueue throw triggers unsubscribe + heartbeat clear', async () => {
    let unsubscribed = 0;
    let notify: ((entry: { msg: string }) => void) | null = null;
    const { req } = makeRequest();
    const res = createSseEndpoint<{ msg: string }>(req, {
      subscribe: (n) => {
        notify = n;
        return () => {
          unsubscribed++;
        };
      },
      liveEventName: 'test',
      heartbeatMs: 60_000,
    });
    // Cancel the reader so subsequent enqueues throw.
    const reader = res.body!.getReader();
    await Promise.resolve();
    await Promise.resolve();
    expect(notify).not.toBeNull();
    await reader.cancel(); // closes the consumer side
    // Now fire a live event — enqueue should throw → cleanup → unsubscribe.
    notify!({ msg: 'will fail to enqueue' });
    await new Promise((r) => setTimeout(r, 10));
    expect(unsubscribed).toBe(1);
  });

  test('3. cleanup is idempotent (abort then enqueue-fail)', async () => {
    let unsubscribed = 0;
    let notify: ((entry: { msg: string }) => void) | null = null;
    const { req, abort } = makeRequest();
    const res = createSseEndpoint<{ msg: string }>(req, {
      subscribe: (n) => {
        notify = n;
        return () => {
          unsubscribed++;
        };
      },
      liveEventName: 'test',
      heartbeatMs: 60_000,
    });
    const reader = res.body!.getReader();
    await Promise.resolve();
    await Promise.resolve();
    abort();
    await new Promise((r) => setTimeout(r, 10));
    // Second cleanup edge — should be a no-op.
    notify!({ msg: 'no-op' });
    await new Promise((r) => setTimeout(r, 10));
    expect(unsubscribed).toBe(1);
    reader.cancel().catch(() => {});
  });

  test('4. initialReplay events reach the client before live events', async () => {
    let notify: ((entry: { msg: string }) => void) | null = null;
    const { req } = makeRequest();
    const res = createSseEndpoint<{ msg: string }>(req, {
      initialReplay: (send) => {
        send('replay', { msg: 'first' });
      },
      subscribe: (n) => {
        notify = n;
        return () => {};
      },
      liveEventName: 'live',
      heartbeatMs: 60_000,
    });
    // Trigger one live event soon after stream starts.
    setTimeout(() => notify?.({ msg: 'second' }), 5);
    const text = await readAll(res, 50);
    expect(text).toContain('event: replay');
    expect(text).toContain('"msg":"first"');
    expect(text).toContain('event: live');
    expect(text).toContain('"msg":"second"');
    // Replay must come before live.
    expect(text.indexOf('"first"')).toBeLessThan(text.indexOf('"second"'));
  });

  test('5. initialReplay throw triggers cleanup without subscribing', async () => {
    let subscribed = 0;
    const { req } = makeRequest();
    const res = createSseEndpoint(req, {
      initialReplay: () => {
        throw new Error('replay boom');
      },
      subscribe: () => {
        subscribed++;
        return () => {};
      },
      liveEventName: 'test',
      heartbeatMs: 60_000,
    });
    // Drain — stream should close cleanly.
    const text = await readAll(res, 30);
    expect(text).toBe(''); // no events
    expect(subscribed).toBe(0); // never reached subscribe()
  });

  test('6. lone surrogates in payload string are sanitized', async () => {
    let notify: ((entry: { msg: string }) => void) | null = null;
    const { req } = makeRequest();
    const res = createSseEndpoint<{ msg: string }>(req, {
      subscribe: (n) => {
        notify = n;
        return () => {};
      },
      liveEventName: 'test',
      heartbeatMs: 60_000,
    });
    setTimeout(() => {
      // Lone high surrogate (no matching low). JSON.stringify would emit
      // \uD800 escape that breaks Claude API. Helper must strip it.
      notify?.({ msg: 'hello \uD800 world' });
    }, 5);
    const text = await readAll(res, 50);
    expect(text).toContain('event: test');
    // JSON.stringify emits U+FFFD as the literal character, not as escape.
    expect(text).toContain('�');
    // The raw lone-surrogate escape MUST NOT survive — that's the failure
    // mode that breaks the Claude API with HTTP 400.
    expect(text.toLowerCase()).not.toContain('\\ud800');
  });
});

/**
 * Unit tests for the view-only SSE session cookie module.
 *
 * Verifies the registry lifecycle (mint/validate/expire), cookie flag
 * invariants (HttpOnly, SameSite=Strict, no Secure), token entropy, and
 * that scope is implicit (the registry has no cross-endpoint footprint
 * that could be used to escalate the cookie to a scoped token).
 */

import { describe, test, expect, beforeEach } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';
import {
  mintSseSessionToken, validateSseSessionToken, extractSseCookie,
  buildSseSetCookie, SSE_COOKIE_NAME,
  __resetSseSessions,
} from '../src/sse-session-cookie';

const MODULE_SRC = fs.readFileSync(
  path.join(import.meta.dir, '../src/sse-session-cookie.ts'), 'utf-8'
);

beforeEach(() => __resetSseSessions());

describe('SSE session cookie: mint + validate', () => {
  test('mint returns a token and an expiry', () => {
    const { token, expiresAt } = mintSseSessionToken();
    expect(typeof token).toBe('string');
    expect(token.length).toBeGreaterThan(20);
    expect(expiresAt).toBeGreaterThan(Date.now());
  });

  test('mint uses 32 random bytes (256-bit entropy)', () => {
    // base64url of 32 bytes is 43 chars (no padding)
    const { token } = mintSseSessionToken();
    expect(token).toMatch(/^[A-Za-z0-9_-]{43}$/);
  });

  test('two mint calls produce different tokens', () => {
    const a = mintSseSessionToken();
    const b = mintSseSessionToken();
    expect(a.token).not.toBe(b.token);
  });

  test('validate returns true for a just-minted token', () => {
    const { token } = mintSseSessionToken();
    expect(validateSseSessionToken(token)).toBe(true);
  });

  test('validate returns false for an unknown token', () => {
    expect(validateSseSessionToken('not-a-real-token')).toBe(false);
  });

  test('validate returns false for null/undefined/empty', () => {
    expect(validateSseSessionToken(null)).toBe(false);
    expect(validateSseSessionToken(undefined)).toBe(false);
    expect(validateSseSessionToken('')).toBe(false);
  });
});

describe('SSE session cookie: TTL enforcement', () => {
  test('TTL is 30 minutes', () => {
    // Assert via source — the actual constant is module-private
    expect(MODULE_SRC).toContain('const TTL_MS = 30 * 60 * 1000');
  });

  test('a token with artificially rewound expiry is rejected', () => {
    // Mint a token, then monkey-patch Date.now to simulate 31 minutes elapsed.
    const { token, expiresAt } = mintSseSessionToken();
    const originalNow = Date.now;
    try {
      Date.now = () => expiresAt + 1;
      expect(validateSseSessionToken(token)).toBe(false);
    } finally {
      Date.now = originalNow;
    }
  });
});

describe('SSE session cookie: cookie flag invariants', () => {
  test('Set-Cookie is HttpOnly', () => {
    const { token } = mintSseSessionToken();
    expect(buildSseSetCookie(token)).toContain('HttpOnly');
  });

  test('Set-Cookie is SameSite=Strict', () => {
    const { token } = mintSseSessionToken();
    expect(buildSseSetCookie(token)).toContain('SameSite=Strict');
  });

  test('Set-Cookie includes the token value', () => {
    const { token } = mintSseSessionToken();
    expect(buildSseSetCookie(token)).toContain(`${SSE_COOKIE_NAME}=${token}`);
  });

  test('Set-Cookie Max-Age matches TTL', () => {
    const { token } = mintSseSessionToken();
    // 30 minutes = 1800 seconds
    expect(buildSseSetCookie(token)).toContain('Max-Age=1800');
  });

  test('Set-Cookie does NOT set Secure (local HTTP daemon)', () => {
    const { token } = mintSseSessionToken();
    // Adding Secure would block the browser from ever sending the cookie
    // back to a 127.0.0.1 daemon over HTTP. If gstack ever moves to HTTPS,
    // add Secure then.
    expect(buildSseSetCookie(token)).not.toContain('Secure');
  });
});

describe('SSE session cookie: extract from request', () => {
  function mockReq(cookieHeader: string | null): Request {
    const headers = new Headers();
    if (cookieHeader !== null) headers.set('cookie', cookieHeader);
    return new Request('http://127.0.0.1/activity/stream', { headers });
  }

  test('extracts the token when cookie is present', () => {
    const req = mockReq(`${SSE_COOKIE_NAME}=abc123`);
    expect(extractSseCookie(req)).toBe('abc123');
  });

  test('returns null when no cookie header', () => {
    const req = mockReq(null);
    expect(extractSseCookie(req)).toBeNull();
  });

  test('returns null when cookie header has no gstack_sse', () => {
    const req = mockReq('other=x; unrelated=y');
    expect(extractSseCookie(req)).toBeNull();
  });

  test('extracts gstack_sse from a multi-cookie header', () => {
    const req = mockReq(`other=x; ${SSE_COOKIE_NAME}=real-token; trailing=y`);
    expect(extractSseCookie(req)).toBe('real-token');
  });

  test('handles tokens with base64url padding-like chars', () => {
    // real tokens contain A-Z, a-z, 0-9, _, -
    const req = mockReq(`${SSE_COOKIE_NAME}=AbCd-_xyz`);
    expect(extractSseCookie(req)).toBe('AbCd-_xyz');
  });
});

describe('SSE session cookie: scope isolation (prior learning cookie-picker-auth-isolation)', () => {
  test('the module exposes ONLY view-only functions, no scoped-token hooks', () => {
    // This is a contract guard: if someone later makes SSE session tokens
    // valid as scoped tokens (e.g., by exporting a helper that registers
    // them in the main token registry), a leaked cookie could execute
    // /command. The module must not import from token-registry.
    expect(MODULE_SRC).not.toContain("from './token-registry'");
    expect(MODULE_SRC).not.toContain('createToken');
    expect(MODULE_SRC).not.toContain('initRegistry');
  });
});

/**
 * State file TTL security tests
 *
 * Verifies that state save includes savedAt timestamp and state load
 * warns on old state files.
 */

import { describe, test, expect } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';

const META_SRC = fs.readFileSync(path.join(import.meta.dir, '../src/meta-commands.ts'), 'utf-8');

describe('State file TTL', () => {
  test('state save includes savedAt timestamp in output', () => {
    // Verify the save code writes savedAt to the state file
    const saveBlock = META_SRC.slice(
      META_SRC.indexOf("if (action === 'save')"),
      META_SRC.indexOf("if (action === 'load')"),
    );
    expect(saveBlock).toContain('savedAt: new Date().toISOString()');
