describe('tunnel against a live daemon (HTTP only, no browser)', () => {
  test('pair → connect → revoke: verified gone, token 401s; agents lists pending keys', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-live-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const port = 20000 + Math.floor(Math.random() * 20000);
    const daemon = Bun.spawn(['bun', 'run', SERVER_ENTRY], {
      cwd: ROOT,
      env: {
        ...process.env,
        BROWSE_HEADLESS_SKIP: '1',
        BROWSE_PORT: String(port),
        BROWSE_STATE_FILE: stateFile,
        BROWSE_PARENT_PID: '0',
        BROWSE_IDLE_TIMEOUT: '600000',
      },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const baseUrl = `http://127.0.0.1:${port}`;
    try {
      const deadline = Date.now() + 15_000;
      let ready = false;
      while (Date.now() < deadline && !ready) {
        try {
          const resp = await fetch(`${baseUrl}/health`, { signal: AbortSignal.timeout(1000) });
          ready = resp.ok;
        } catch { /* not ready yet */ }
        if (!ready) await new Promise(r => setTimeout(r, 200));
      }
      expect(ready).toBe(true);
      const rootToken = (JSON.parse(fs.readFileSync(stateFile, 'utf-8')) as { token: string }).token;

      // Pair + connect a session, plus a second pending setup key.
      const pair = async () => {
        const resp = await fetch(`${baseUrl}/pair`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${rootToken}` },
          body: JSON.stringify({ clientId: 'cli-agent' }),
        });
        return (await resp.json() as { setup_key: string }).setup_key;
      };
      const key1 = await pair();
      const connectResp = await fetch(`${baseUrl}/connect`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ setup_key: key1 }),
      });
      const { token: scopedToken } = await connectResp.json() as { token: string };
      await pair(); // pending key

      // tunnel agents shows the session AND the pending key.
      const list = await runCli(['tunnel', 'agents'], baseEnv(stateFile));
      expect(list.code).toBe(0);
      expect(list.stdout).toContain('cli-agent');
      expect(list.stdout).toContain('(pending setup key)');

      // Unknown name → truthful failure with the active list.
      const miss = await runCli(['tunnel', 'revoke', 'nobody'], baseEnv(stateFile));
      expect(miss.code).toBe(1);
      expect(miss.stderr).toContain('No paired agent named "nobody"');
      expect(miss.stderr).toContain('cli-agent');

      // The real revoke: counted, verified, and the token actually dies.
      const revoke = await runCli(['tunnel', 'revoke', 'cli-agent'], baseEnv(stateFile));
      expect(revoke.code).toBe(0);
      expect(revoke.stdout).toContain('Revoked "cli-agent" (3 tokens)');
      expect(revoke.stdout).toContain('Verified: not in the active agent list.');
      const post = await fetch(`${baseUrl}/command`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${scopedToken}` },
        body: JSON.stringify({ command: 'status', args: [] }),
      });
      expect(post.status).toBe(401);

      const empty = await runCli(['tunnel', 'agents'], baseEnv(stateFile));
      expect(empty.code).toBe(0);
      expect(empty.stdout).toContain('No paired agents.');

      // Regression: handleTunnel used to trim() the name, but clientIds are
      // stored verbatim — a space-padded agent became unrevocable by the
      // documented kill switch (trimmed DELETE 404'd while the grant lived).
      const padPair = await fetch(`${baseUrl}/pair`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${rootToken}` },
        body: JSON.stringify({ clientId: ' padded' }),
      });
      expect(padPair.status).toBe(200);
      const padRevoke = await runCli(['tunnel', 'revoke', ' padded'], baseEnv(stateFile));
      expect(padRevoke.code).toBe(0);
      expect(padRevoke.stdout).toContain('Verified: not in the active agent list.');
    } finally {
      try { daemon.kill('SIGKILL'); } catch { /* already gone */ }
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 60_000);
});

describe('tunnel against a lying or unreachable daemon (stub harness)', () => {
  test('old daemon 200s the DELETE but keeps listing the agent → "Revocation incomplete", exit 1', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-skew-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    // Old daemons answer {revoked} with no tokens_deleted — this also pins
    // the "(count unknown)" print (never undefined/NaN).
    const stub = Bun.serve({
      hostname: '127.0.0.1',
      port: 0,
      fetch(req) {
        const url = new URL(req.url);
        if (req.method === 'DELETE' && url.pathname.startsWith('/token/')) {
          return Response.json({ revoked: 'mallory' });
        }
        if (url.pathname === '/agents') {
          return Response.json({
            agents: [{ clientId: 'mallory', scopes: ['read'], expiresAt: null, commandCount: 1, createdAt: '' }],
          });
        }
        return Response.json({ status: 'healthy' });
      },
    });
    try {
      writeStateFile(stateFile, process.pid, stub.port);
      const result = await runCli(['tunnel', 'revoke', 'mallory'], baseEnv(stateFile));
      expect(result.code).toBe(1);
      expect(result.stdout).toContain('count unknown');
      expect(result.stderr).toContain('Revocation incomplete: "mallory" is still listed');
    } finally {
      stub.stop(true);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('DELETE succeeds but /agents errors → "could not verify", exit 1 (never a silent success)', async () => {
    // Regression pin: a revoke whose verification read fails must NOT report
    // clean success — the whole point of the re-read is proving the deletion.
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-noverify-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const stub = Bun.serve({
      hostname: '127.0.0.1',
      port: 0,
      fetch(req) {
        const url = new URL(req.url);
        if (req.method === 'DELETE' && url.pathname.startsWith('/token/')) {
          return Response.json({ revoked: 'mallory', tokens_deleted: 1 });
        }
        if (url.pathname === '/agents') {
          return new Response('boom', { status: 500 });
        }
        return Response.json({ status: 'healthy' });
      },
    });
    try {
      writeStateFile(stateFile, process.pid, stub.port);
      const result = await runCli(['tunnel', 'revoke', 'mallory'], baseEnv(stateFile));
      expect(result.code).toBe(1);
      expect(result.stderr).toContain('Revoked, but could not verify against the agent list.');
    } finally {
      stub.stop(true);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('DELETE returns 500 → "Revoke failed" with the body error, exit 1', async () => {
    // Regression pin: a non-404 HTTP failure must surface the daemon's error,
    // not fall through to a success print.
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-500-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const stub = Bun.serve({
      hostname: '127.0.0.1',
      port: 0,
      fetch(req) {
        const url = new URL(req.url);
        if (req.method === 'DELETE' && url.pathname.startsWith('/token/')) {
          return Response.json({ error: 'registry exploded' }, { status: 500 });
        }
        return Response.json({ status: 'healthy' });
      },
    });
    try {
      writeStateFile(stateFile, process.pid, stub.port);
      const result = await runCli(['tunnel', 'revoke', 'mallory'], baseEnv(stateFile));
      expect(result.code).toBe(1);
      expect(result.stderr).toContain('Revoke failed: registry exploded');
    } finally {
      stub.stop(true);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('tunnel agents with a broken /agents → "Could not read the agent list", exit 1', async () => {
    // Regression pin: a 500 from /agents must not render as "No paired
    // agents." — an unreadable list is not an empty list.
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-agents500-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    const stub = Bun.serve({
      hostname: '127.0.0.1',
      port: 0,
      fetch(req) {
        const url = new URL(req.url);
        if (url.pathname === '/agents') {
          return new Response('boom', { status: 500 });
        }
        return Response.json({ status: 'healthy' });
      },
    });
    try {
      writeStateFile(stateFile, process.pid, stub.port);
      const result = await runCli(['tunnel', 'agents'], baseEnv(stateFile));
      expect(result.code).toBe(1);
      expect(result.stderr).toContain('Could not read the agent list');
      expect(result.stdout).not.toContain('No paired agents.');
    } finally {
      stub.stop(true);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);

  test('alive pid but unreachable port → "Could not reach daemon", exit 1 (NOT "no daemon")', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'browse-tunnel-unreach-'));
    const stateFile = path.join(tmpDir, 'browse.json');
    try {
      // Alive pid (this test process) is what routes to the fetch-failure
      // branch; a dead pid + dead port would be the exit-0 "no daemon" path.
      writeStateFile(stateFile, process.pid, await closedPort());
      const result = await runCli(['tunnel', 'revoke', 'anyone'], baseEnv(stateFile));
      expect(result.code).toBe(1);
      expect(result.stderr).toContain('Could not reach daemon');
    } finally {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  }, 30_000);
});

import { describe, it, expect } from 'bun:test';
import { validateNavigationUrl, normalizeFileUrl } from '../src/url-validation';
import * as fs from 'fs';
import * as path from 'path';
import { TEMP_DIR } from '../src/platform';

describe('validateNavigationUrl', () => {
  it('allows http URLs', async () => {
    await expect(validateNavigationUrl('http://example.com')).resolves.toBe('http://example.com');
  });

  it('allows https URLs', async () => {
    await expect(validateNavigationUrl('https://example.com/path?q=1')).resolves.toBe('https://example.com/path?q=1');
  });

  it('allows localhost', async () => {
    await expect(validateNavigationUrl('http://localhost:3000')).resolves.toBe('http://localhost:3000');
  });

  it('allows 127.0.0.1', async () => {
    await expect(validateNavigationUrl('http://127.0.0.1:8080')).resolves.toBe('http://127.0.0.1:8080');
  });

  it('allows private IPs', async () => {
    await expect(validateNavigationUrl('http://192.168.1.1')).resolves.toBe('http://192.168.1.1');
  });

  it('rejects file:// paths outside safe dirs (cwd + TEMP_DIR)', async () => {
    // file:// is accepted as a scheme now, but safe-dirs policy blocks /etc/passwd.
    await expect(validateNavigationUrl('file:///etc/passwd')).rejects.toThrow(/Path must be within/i);
  });

  it('accepts file:// for files under TEMP_DIR', async () => {
    const tmpHtml = path.join(TEMP_DIR, `browse-test-${Date.now()}.html`);
    fs.writeFileSync(tmpHtml, '<html><body>ok</body></html>');
    try {
      const result = await validateNavigationUrl(`file://${tmpHtml}`);
      // Result should be a canonical file:// URL (pathToFileURL form)
      expect(result.startsWith('file://')).toBe(true);
      expect(result.toLowerCase()).toContain('browse-test-');
    } finally {
      fs.unlinkSync(tmpHtml);
    }
  });

  it('rejects unsupported file URL host (UNC/network paths)', async () => {
    await expect(validateNavigationUrl('file://host.example.com/foo.html')).rejects.toThrow(/Unsupported file URL host/i);
  });

  // The daemon opens its own first tab on about:blank, so blocking it meant a restarted
  // daemon could never initialise — and `make-pdf setup`, whose Chromium smoke test is
  // `browse newtab about:blank`, reported "Chromium failed to launch" on a healthy browser.
  it('allows about:blank — the daemon opens its own first tab there', async () => {
    await expect(validateNavigationUrl('about:blank')).resolves.toBe('about:blank');
  });

  it('allows about:blank regardless of case, since URL parsing normalises it', async () => {
    await expect(validateNavigationUrl('ABOUT:BLANK')).resolves.toBe('about:blank');
  });

  // The allowance is about:blank EXACTLY, not the about: scheme. about:blank has no
  // origin and loads nothing; the rest of the scheme is a real surface.
  it('still blocks other about: URLs', async () => {
    await expect(validateNavigationUrl('about:config')).rejects.toThrow(/scheme.*not allowed/i);
    await expect(validateNavigationUrl('about:net-internals')).rejects.toThrow(/scheme.*not allowed/i);
  });

  it('blocks about:blankfoo — exact match, never a prefix test', async () => {
    await expect(validateNavigationUrl('about:blankfoo')).rejects.toThrow(/scheme.*not allowed/i);
  });

  it('blocks javascript: scheme', async () => {
    await expect(validateNavigationUrl('javascript:alert(1)')).rejects.toThrow(/scheme.*not allowed/i);
  });

  it('blocks data: scheme', async () => {
    await expect(validateNavigationUrl('data:text/html,<h1>hi</h1>')).rejects.toThrow(/scheme.*not allowed/i);
  });

  it('blocks AWS/GCP metadata endpoint', async () => {
    await expect(validateNavigationUrl('http://169.254.169.254/latest/meta-data/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks GCP metadata hostname', async () => {
    await expect(validateNavigationUrl('http://metadata.google.internal/computeMetadata/v1/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks Azure metadata hostname', async () => {
    await expect(validateNavigationUrl('http://metadata.azure.internal/metadata/instance')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks metadata hostname with trailing dot', async () => {
    await expect(validateNavigationUrl('http://metadata.google.internal./computeMetadata/v1/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks metadata IP in hex form', async () => {
    await expect(validateNavigationUrl('http://0xA9FEA9FE/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks metadata IP in decimal form', async () => {
    await expect(validateNavigationUrl('http://2852039166/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks metadata IP in octal form', async () => {
    await expect(validateNavigationUrl('http://0251.0376.0251.0376/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks IPv6 metadata with brackets (fd00::)', async () => {
    await expect(validateNavigationUrl('http://[fd00::]/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks IPv6 ULA fd00::1 (not just fd00::)', async () => {
    await expect(validateNavigationUrl('http://[fd00::1]/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks IPv6 ULA fd12:3456::1', async () => {
    await expect(validateNavigationUrl('http://[fd12:3456::1]/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks IPv6 ULA fc00:: (full fc00::/7 range)', async () => {
    await expect(validateNavigationUrl('http://[fc00::]/')).rejects.toThrow(/cloud metadata/i);
  });

  it('blocks direct IPv6 link-local addresses', async () => {
    await expect(validateNavigationUrl('http://[fe80::2]/')).rejects.toThrow(/cloud metadata/i);
  });

  it('does not block hostnames starting with fd (e.g. fd.example.com)', async () => {
    await expect(validateNavigationUrl('https://fd.example.com/')).resolves.toBe('https://fd.example.com/');
  });

  it('does not block hostnames starting with fc (e.g. fcustomer.com)', async () => {
    await expect(validateNavigationUrl('https://fcustomer.com/')).resolves.toBe('https://fcustomer.com/');
  });

  it('throws on malformed URLs', async () => {
    await expect(validateNavigationUrl('not-a-url')).rejects.toThrow(/Invalid URL/i);
  });
});

